ont-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_09-signed.pdf"><strong>Junta 9</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf"><strong>Junta 10</strong></a></div><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Masculino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a></div><p class="text-align-center" style="margin:0;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;padding:8px 18px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf"><strong>Unidad de Educación a Distancia y en Línea</strong></a></p></div></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>Según el art. 39 de&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf" title="Reglamento elecciones ">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a style="color:#93000b;" href="/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf" title="ausentismo de sufragio ">ausentismo de sufragio justificado.</a></p></div><p>&nbsp;</p><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf" hreflang="es"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></div><div style="margin:20px auto;max-width:800px;"><div style="border-radius:8px;height:0;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/gTP4tCSS3vU?si=0AaIwB-UVhbLFaVA" title="YouTube video player"></iframe></div></div><p>&nbsp;</p>	full_html
texto_libre	0	160	2202	es	0	<style type="text/css">/* =====================================================\r\nRESET\r\n===================================================== */\r\n*{\r\n  margin:0;\r\n  padding:0;\r\n  box-sizing:border-box;\r\n}\r\nhtml{\r\n  scroll-behavior:smooth;\r\n}\r\nbody{\r\n  font-family:\r\n    "Montserrat",\r\n    -apple-system,\r\n    BlinkMacSystemFont,\r\n    "Segoe UI",\r\n    sans-serif;\r\n  background:#ffffff;\r\n  color:#3a3a3a;\r\n  overflow-x:hidden;\r\n}\r\n/* =====================================================\r\nVARIABLES\r\n===================================================== */\r\n:root{\r\n  --primary:#93000b;\r\n  --secondary:#6e0008;\r\n  --text:#3a3a3a;\r\n  --text-soft:#6b6b6b;\r\n  --white:#ffffff;\r\n  --light-hover:#fbecec;\r\n  --border:rgba(147,0,11,.12);\r\n  --shadow:\r\n    0 10px 40px rgba(147,0,11,.08);\r\n  --radius:30px;\r\n}\r\n/* =====================================================\r\nGLOBAL\r\n===================================================== */\r\na{\r\n  text-decoration:none;\r\n  color:inherit;\r\n}\r\n.container{\r\n  width:min(1400px,92%);\r\n  margin:auto;\r\n}\r\n/* =====================================================\r\nHERO\r\n===================================================== */\r\n.hero{\r\n  position:relative;\r\n  min-height:100vh;\r\n  display:flex;\r\n  align-items:center;\r\n  overflow:hidden;\r\n  padding:120px 0 80px;\r\n}\r\n/* =====================================================\r\nIMAGE BACKGROUND\r\n===================================================== */\r\n.hero-bg{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:1;\r\n}\r\n.hero-bg img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:cover;\r\n}\r\n/* =====================================================\r\nWHITE OVERLAY\r\n===================================================== */\r\n.hero-overlay{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:2;\r\n  background:\r\n    linear-gradient(\r\n      90deg,\r\n      rgba(255,255,255,.96) 0%,\r\n      rgba(255,255,255,.92) 28%,\r\n      rgba(255,255,255,.70) 48%,\r\n      rgba(255,255,255,.20) 70%,\r\n      rgba(255,255,255,.05) 100%\r\n    );\r\n}\r\n/* =====================================================\r\nDECORATION\r\n===================================================== */\r\n.hero-decoration{\r\n  position:absolute;\r\n  left:-200px;\r\n  bottom:-220px;\r\n  width:600px;\r\n  height:600px;\r\n  border-radius:50%;\r\n  background:\r\n    radial-gradient(\r\n      circle,\r\n      rgba(147,0,11,.06),\r\n      transparent 70%\r\n    );\r\n  z-index:2;\r\n}\r\n/* =====================================================\r\nCONTENT\r\n===================================================== */\r\n.hero-content{\r\n  position:relative;\r\n  z-index:5;\r\n  max-width:700px;\r\n  animation:fadeUp 1s ease;\r\n}\r\n.hero-content h1{\r\n  font-size:clamp(4rem,7vw,7rem);\r\n  line-height:.95;\r\n  font-weight:900;\r\n  letter-spacing:-1px;\r\n  margin-bottom:35px;\r\n  color:#93000b;\r\n  text-shadow:\r\n    0 10px 40px rgba(255,255,255,.95);\r\n}\r\n.hero-content p{\r\n  max-width:620px;\r\n  font-size:1.7rem;\r\n  line-height:2;\r\n  color:#3a3a3a;\r\n  margin-bottom:45px;\r\n  font-weight:450;\r\n  text-shadow:\r\n    0 5px 30px rgba(255,255,255,.95);\r\n}\r\n/* =====================================================\r\nBUTTONS\r\n===================================================== */\r\n.hero-buttons{\r\n  display:flex;\r\n  gap:20px;\r\n  flex-wrap:wrap;\r\n}\r\n.btn{\r\n  padding:18px 34px;\r\n  border-radius:18px;\r\n  font-weight:700;\r\n  transition:.4s ease;\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:12px;\r\n  font-size:1rem;\r\n}\r\n.btn-primary{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n  box-shadow:\r\n    0 15px 35px rgba(147,0,11,.25);\r\n}\r\n.btn-primary:hover{\r\n  transform:translateY(-4px);\r\n}\r\n.btn-secondary{\r\n  background:\r\n    #fbecec;\r\n  border:\r\n    1px solid rgba(147,0,11,.15);\r\n  color:#93000b;\r\n  backdrop-filter:blur(10px);\r\n  box-shadow:\r\n    0 10px 25px rgba(0,0,0,.05);\r\n}\r\n.btn-secondary:hover{\r\n  background:white;\r\n}\r\n/* =====================================================\r\nSECTION\r\n===================================================== */\r\n.section{\r\n  padding:120px 0;\r\n}\r\n.section-title{\r\n  text-align:center;\r\n  margin-bottom:70px;\r\n}\r\n.section-title span{\r\n  color:#93000b;\r\n  font-weight:800;\r\n  letter-spacing:1px;\r\n  text-transform:uppercase;\r\n  font-size:.82rem;\r\n}\r\n.section-title h2{\r\n  font-size:clamp(2.8rem,5vw,4rem);\r\n  margin-top:16px;\r\n  color:#3a3a3a;\r\n  font-weight:900;\r\n}\r\n.section-title p{\r\n  max-width:760px;\r\n  margin:auto;\r\n  margin-top:24px;\r\n  line-height:1.9;\r\n  color:#6b6b6b;\r\n  font-size:1.5rem;\r\n}\r\n/* =====================================================\r\nTIMELINE\r\n===================================================== */\r\n.timeline-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(280px,1fr));\r\n  gap:28px;\r\n}\r\n.timeline-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:30px;\r\n  padding:35px;\r\n  transition:.4s ease;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n}\r\n.timeline-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n  box-shadow:\r\n    0 20px 40px rgba(147,0,11,.12);\r\n}\r\n.timeline-card h3{\r\n  font-size:2rem;\r\n  color:#93000b;\r\n  margin-bottom:18px;\r\n  font-weight:900;\r\n}\r\n.timeline-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.card-btn{\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:10px;\r\n  color:#93000b;\r\n  font-weight:700;\r\n}\r\n/* =====================================================\r\nDOCUMENTS\r\n===================================================== */\r\n.docs-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(320px,1fr));\r\n  gap:28px;\r\n}\r\n.doc-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:28px;\r\n  padding:35px;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n  transition:.4s ease;\r\n}\r\n.doc-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n}\r\n.doc-icon{\r\n  width:85px;\r\n  height:85px;\r\n  border-radius:24px;\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      rgba(147,0,11,.10),\r\n      rgba(147,0,11,.18)\r\n    );\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  margin-bottom:24px;\r\n  font-size:1.2rem;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.doc-card h4{\r\n  font-size:1.4rem;\r\n  margin-bottom:14px;\r\n  color:#3a3a3a;\r\n}\r\n.doc-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.doc-actions{\r\n  display:flex;\r\n  gap:14px;\r\n}\r\n.doc-btn{\r\n  flex:1;\r\n  text-align:center;\r\n  padding:14px;\r\n  border-radius:14px;\r\n  font-weight:700;\r\n  transition:.3s ease;\r\n}\r\n.view-btn{\r\n  background:#fbecec;\r\n  color:#93000b;\r\n}\r\n.download-btn{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n}\r\n.doc-btn:hover{\r\n  transform:translateY(-2px);\r\n}\r\n/* =====================================================\r\nFOOTER\r\n===================================================== */\r\nfooter{\r\n  padding:80px 0;\r\n  border-top:\r\n    1px solid rgba(147,0,11,.12);\r\n  margin-top:100px;\r\n}\r\n.footer-content{\r\n  display:flex;\r\n  justify-content:space-between;\r\n  gap:60px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-brand h3{\r\n  font-size:2rem;\r\n  margin-bottom:20px;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.footer-brand p{\r\n  max-width:500px;\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n}\r\n.footer-links{\r\n  display:flex;\r\n  gap:80px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-links h4{\r\n  margin-bottom:18px;\r\n  color:#3a3a3a;\r\n}\r\n.footer-links a{\r\n  display:block;\r\n  margin-bottom:14px;\r\n  color:#6b6b6b;\r\n  transition:.3s ease;\r\n}\r\n.footer-links a:hover{\r\n  color:#93000b;\r\n}\r\n/* =====================================================\r\nANIMATIONS\r\n===================================================== */\r\n@keyframes fadeUp{\r\n  from{\r\n    opacity:0;\r\n    transform:translateY(50px);\r\n  }\r\n  to{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n}\r\n/* =====================================================\r\nRESPONSIVE\r\n===================================================== */\r\n@media(max-width:980px){\r\n  .hero{\r\n    min-height:auto;\r\n    padding:120px 0 100px;\r\n  }\r\n  .hero-content h1{\r\n    font-size:4rem;\r\n  }\r\n  .hero-overlay{\r\n    background:\r\n      linear-gradient(\r\n        180deg,\r\n        rgba(255,255,255,.95),\r\n        rgba(255,255,255,.80)\r\n      );\r\n  }\r\n}\r\n@media(max-width:680px){\r\n  .hero-content h1{\r\n    font-size:3rem;\r\n    letter-spacing:-2px;\r\n  }\r\n  .hero-content p{\r\n    font-size:1rem;\r\n  }\r\n  .hero-buttons{\r\n    flex-direction:column;\r\n  }\r\n  .btn{\r\n    width:100%;\r\n    justify-content:center;\r\n  }\r\n}\r\n</style><!-- =====================================================\r\nHERO\r\n===================================================== --><section class="hero"><!-- IMAGE --><div class="hero-bg"><!-- CAMBIA ESTA IMAGEN --><img src="/sites/default/files/2026-05/RENDICION7%20-%20MESAS%20DE%20TRABAJO.jpg" alt="" width="3196" height="1788"></div><!-- OVERLAY --><div class="hero-overlay">&nbsp;</div><!-- DECORATION --><div class="hero-decoration">&nbsp;</div><!-- CONTENT --><div class="container"><div class="hero-content"><h1>Transparencia y Rendición de Cuentas</h1><p>Acceda de forma clara, organizada y pública a los procesos de rendición de cuentas de la Universidad Nacional de Loja.</p><div class="hero-buttons"><a class="btn btn-primary" href="#procesos">Explorar procesos → </a><a class="btn btn-secondary" href="/sites/default/files/2026-03/INFORME%20RENDICION%20CUENTAS%20UNL%202025_VP.pdf" title="Rendición de cuentas 2025">Informe 2025&nbsp;</a></div></div></div></section><!-- =====================================================\r\nTIMELINE\r\n===================================================== --><section class="section" id="procesos"><div class="container"><div class="section-title"><p><span>Histórico institucional&nbsp;</span></p><h2>Procesos de Rendición</h2><p>Consulte los procesos institucionales organizados por año y acceda rápidamente a la documentación pública.<br>&nbsp;</p></div><div class="timeline-grid"><div class="timeline-card"><h3>2025</h3><p>Rendición de cuentas 2025</p><p><a class="card-btn" href="/rendicion_cuentas/2025" title="Rendición de cuentas 2025">Ver más →</a></p></div><div class="timeline-card"><h3>2024</h3><p>Rendición de cuentas 2024</p><p><a class="card-btn" href="/rendicion_cuentas/2024" title="Rendición de cuentas 2024">Ver más →</a></p></div><div class="timeline-card"><h3>2023</h3><p>Rendición de cuentas 2023</p><p><a class="card-btn" href="/rendicion_cuentas/2023" title="Rendición de cuentas 2023">Ver más →</a></p></div><div class="timeline-card"><h3>2022</h3><p>Rendición de cuentas 2022</p><p><a class="card-btn" href="/rendicion_cuentas/2022" title="Rendición de cuentas 202 ">Ver más →</a></p></div><div class="timeline-card"><h3>2021</h3><p>Rendición de cuentas 2021</p><p><a class="card-btn" href="/rendicion_cuentas/2021" title="Rendición de cuentas 2021">Ver más →</a></p></div><div class="timeline-card"><h3>2020</h3><p>Rendición de cuentas 2020</p><p><a class="card-btn" href="/rendicion_cuentas/2020" title="Rendición de cuentas 2020">Ver más →</a></p></div></div></div></section><section class="section"><div class="container"><div class="section-title"><p><span>Documentación pública&nbsp;</span></p><h2>Documentos Destacados</h2></div><div class="docs-grid"><div class="doc-card"><div class="doc-icon">PDF</div><h4>Informe UNL 2025</h4><p>Informe institucional</p><p><a class="doc-btn download-btn" href="https://unl.edu.ec/sites/default/files/2026-03/INFORME%20RENDICION%20CUENTAS%20UNL%202025_VP.pdf">Ver</a></p></div><div class="doc-card"><div class="doc-icon">DOC</div><h4>Formulario CPCCS UNL 2025</h4><p>Registro oficial de participación ciudadana y socialización institucional.</p><p><a class="doc-btn download-btn" href="/sites/default/files/2026-04/Rendici%C3%B3n%20de%20Cuentas%20UNL%202025_0.pdf">Ver</a></p></div><div class="doc-card"><div class="doc-icon">DATA</div><h4>Presentación&nbsp;</h4><p>Presentación de deliberación pública&nbsp;</p><p><a class="doc-btn download-btn" href="/sites/default/files/2026-04/Rendici%C3%B3n%20de%20Cuentas%20UNL%202025_0.pdf">Ver</a></p></div></div></div></section><!-- =====================================================\r\nFOOTER\r\n===================================================== --><footer><div class="container footer-content"><div class="footer-brand"><h3>UNL Transparencia</h3><p>Portal institucional de acceso público para consulta, seguimiento y transparencia de los procesos de rendición de cuentas de la Universidad Nacional de Loja.</p></div><div class="footer-links"><div><h4>Portal</h4><p><a href="#">Inicio Procesos Documentos</a></p></div><div><h4>Institución</h4><p><a href="https://unl.edu.ec/">Universidad Nacional de Loja&nbsp;</a><br>&nbsp;</p></div></div></div></footer><script>\r\n/* =====================================================\r\nANIMACIÓN SUAVE HERO\r\n===================================================== */\r\nwindow.addEventListener("scroll", () => {\r\n  const scroll = window.scrollY;\r\n  const bg = document.querySelector(".hero-bg img");\r\n  bg.style.transform =\r\n    `scale(1.05) translateY(${scroll * 0.15}px)`;\r\n});\r\n</script>	full_html
