-epidemiologica/varicela" hreflang="es"><span class="field-content">Varicela</span></a><span class="field-content">&nbsp;</span></div></div></div><div class="views-row clearfix row-2" style="text-align:center;"><div class="facultad-carrera-2019 views-col col-1" style="display:inline-block;width:30%;"><div class="views-field views-field-field-imagen-de-carrera"><div class="field-content"><a href="/proyecto/2020/analisis-epidemiologico/gaceta-epidemiologica/neumonias" hreflang="es"><img class="img-responsive" src="/sites/default/files/2022-04/neumonia.jpg" alt="Neumonías" width="400" height="400" typeof="foaf:Image"></a></div></div><div class="views-field views-field-title"><a href="/proyecto/2020/analisis-epidemiologico/gaceta-epidemiologica/neumonias" hreflang="es"><span class="field-content">Neumonías</span></a><span class="field-content">&nbsp;</span></div></div><div class="facultad-carrera-2019 views-col col-2" style="display:inline-block;width:30%;"><div class="views-field views-field-field-imagen-de-carrera"><div class="field-content"><a href="/proyecto/2020/analisis-epidemiologico/gaceta-epidemiologica/covid-19" hreflang="es"><img class="img-responsive" src="/sites/default/files/2022-04/covid_19.jpg" alt="COVID 19" width="400" height="400" typeof="foaf:Image"></a></div></div><div class="views-field views-field-title"><a href="/proyecto/2020/analisis-epidemiologico/gaceta-epidemiologica/covid-19" hreflang="es"><span class="field-content">COVID 19</span></a><span class="field-content">&nbsp;</span></div></div><div class="facultad-carrera-2019 views-col col-2" style="display:inline-block;width:30%;"><div class="views-field views-field-field-imagen-de-carrera"><div class="field-content"><a href="/proyecto/2020/analisis-epidemiologico/gaceta-epidemiologica/intoxicaciones-alimentarias-bacterianas" hreflang="es"><img class="img-responsive" src="/sites/default/files/2022-04/intoxicaciones_alimentarias.jpg" alt="Intoxicaciones Alimentarias Bacterianas" width="400" heig