\r\n});\r\n\r\ndocument.addEventListener("keydown", (e)=>{\r\n\r\n    if(e.key === "Escape"){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\n</script>	full_html
