texto_libre	0	110	1334	en	0	<style type="text/css">/* =========================================\r\nPALETA OFICIAL UNL\r\n========================================= */\r\n\r\n:root{\r\n    --primary:#001F4E;\r\n    --primary-light:#003B8E;\r\n    --secondary:#0A56A8;\r\n\r\n    --bg:#f4f7fb;\r\n    --white:#ffffff;\r\n    --text:#1b1b1b;\r\n    --gray:#6f7785;\r\n    --border:#dfe7f1;\r\n\r\n    --shadow:0 10px 35px rgba(0, 31, 78, 0.10);\r\n\r\n    --radius:22px;\r\n}\r\n\r\n/* =========================================\r\nRESET\r\n========================================= */\r\n\r\n*{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\n\r\nhtml{\r\n    scroll-behavior:smooth;\r\n}\r\n\r\nbody{\r\n    font-family:'Montserrat', sans-serif;\r\n    background:var(--bg);\r\n    color:var(--text);\r\n    overflow-x:hidden;\r\n}\r\n\r\n/* =========================================\r\nOCULTAR NAVBAR INTERNO\r\nPARA NO AFECTAR EL HEADER DEL SITIO\r\n========================================= */\r\n\r\nbody > .navbar{\r\n    display:none !important;\r\n}\r\n\r\n/* =========================================\r\nHERO\r\n========================================= */\r\n\r\n.hero{\r\n    position:relative;\r\n\r\n    min-height:52vh;\r\n\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n\r\n    overflow:hidden;\r\n\r\n    padding-top:140px;\r\n    padding-bottom:70px;\r\n\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E 0%,\r\n    #002B6B 45%,\r\n    #003B8E 100%\r\n    );\r\n}\r\n\r\n.hero::before{\r\n    content:"";\r\n    position:absolute;\r\n\r\n    width:480px;\r\n    height:480px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.05);\r\n\r\n    top:-220px;\r\n    right:-120px;\r\n}\r\n\r\n.hero::after{\r\n    content:"";\r\n\r\n    position:absolute;\r\n\r\n    width:350px;\r\n    height:350px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.04);\r\n\r\n    bottom:-180px;\r\n    left:-100px;\r\n}\r\n\r\n.hero-content{\r\n    position:relative;\r\n    z-index:10;\r\n\r\n    width:90%;\r\n    max-width:1000px;\r\n\r\n    text-align:center;\r\n    color:white;\r\n}\r\n\r\n.badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n\r\n    padding:10px 18px;\r\n\r\n    background:rgba(255,255,255,0.10);\r\n\r\n    border:1px solid rgba(255,255,255,0.12);\r\n\r\n    border-radius:100px;\r\n\r\n    backdrop-filter:blur(12px);\r\n\r\n    margin-bottom:22px;\r\n\r\n    animation:fadeUp 1s ease;\r\n}\r\n\r\n.badge span{\r\n    font-size:.85rem;\r\n    font-weight:600;\r\n    letter-spacing:.3px;\r\n}\r\n\r\n.hero h2{\r\n    font-size:5.2rem;\r\n.hero .hero-content h2{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    font-size:clamp(3rem, 5vw, 4.5rem) !important;\r\n\r\n    font-weight:800 !important;\r\n\r\n    line-height:1.1 !important;\r\n\r\n    margin-bottom:20px;\r\n\r\n    color:#ffffff !important;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero .hero-content p{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:3.08rem !important;\r\n\r\n    line-height:1.9 !important;\r\n\r\n    font-weight:400 !important;\r\n\r\n    color:rgba(255,255,255,0.92) !important;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n.hero .badge span{\r\n\r\n    font-size:.9rem !important;\r\n\r\n    font-weight:600 !important;\r\n\r\n    color:white !important;\r\n\r\n}\r\n    font-weight:800;\r\n\r\n    line-height:1.1;\r\n\r\n    margin-bottom:20px;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero p{\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:1.02rem;\r\n\r\n    line-height:1.9;\r\n\r\n    opacity:.92;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n/* =========================================\r\nSECCIONES\r\n========================================= */\r\n\r\n.section{\r\n    padding:110px 0;\r\n}\r\n\r\n.container{\r\n    width:90%;\r\n    max-width:1400px;\r\n    margin:auto;\r\n}\r\n\r\n.section-title{\r\n    text-align:center;\r\n    margin-bottom:70px;\r\n}\r\n\r\n.section-title h3{\r\n    font-size:2.7rem;\r\n    color:var(--primary);\r\n    margin-bottom:18px;\r\n}\r\n\r\n.section-title p{\r\n    max-width:760px;\r\n    margin:auto;\r\n    color:var(--gray);\r\n    line-height:1.8;\r\n}\r\n\r\n/* =========================================\r\nCARDS\r\n========================================= */\r\n\r\n.cards-grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(auto-fit,minmax(340px,1fr));\r\n    gap:34px;\r\n}\r\n\r\n.card{\r\n    position:relative;\r\n    background:var(--white);\r\n    border-radius:var(--radius);\r\n    overflow:hidden;\r\n    box-shadow:var(--shadow);\r\n    transition:.4s ease;\r\n    border:1px solid rgba(0,0,0,0.03);\r\n}\r\n\r\n.card:hover{\r\n    transform:translateY(-12px);\r\n}\r\n\r\n.card-top{\r\n    position:relative;\r\n    height:220px;\r\n\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E,\r\n    #003B8E,\r\n    #0A56A8\r\n    );\r\n\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    overflow:hidden;\r\n}\r\n\r\n.card-top::before{\r\n    content:"";\r\n    position:absolute;\r\n    width:300px;\r\n    height:300px;\r\n    background:rgba(255,255,255,0.08);\r\n    border-radius:50%;\r\n    top:-100px;\r\n    right:-60px;\r\n}\r\n\r\n.card-year{\r\n    position:relative;\r\n    z-index:2;\r\n    font-size:5rem;\r\n    font-weight:800;\r\n    color:white;\r\n    letter-spacing:4px;\r\n}\r\n\r\n.card-content{\r\n    padding:34px;\r\n}\r\n\r\n.card-content h4{\r\n    font-size:1.4rem;\r\n    color:var(--primary);\r\n    margin-bottom:16px;\r\n}\r\n\r\n.card-content p{\r\n    color:var(--gray);\r\n    line-height:1.7;\r\n    margin-bottom:26px;\r\n}\r\n\r\n.card-actions{\r\n    display:flex;\r\n    gap:14px;\r\n    flex-wrap:wrap;\r\n}\r\n\r\n.btn{\r\n    flex:1;\r\n    min-width:130px;\r\n    padding:14px 18px;\r\n    border:none;\r\n    border-radius:14px;\r\n    cursor:pointer;\r\n    text-decoration:none;\r\n    font-weight:700;\r\n    transition:.3s ease;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    gap:10px;\r\n    font-family:'Montserrat', sans-serif;\r\n}\r\n\r\n.btn-primary{\r\n    background:var(--primary);\r\n    color:white;\r\n}\r\n\r\n.btn-primary:hover{\r\n    background:var(--primary-light);\r\n}\r\n\r\n.btn-secondary{\r\n    background:#eef4fb;\r\n    color:var(--primary);\r\n}\r\n\r\n.btn-secondary:hover{\r\n    background:#dfeeff;\r\n}\r\n\r\n/* =========================================\r\nMODAL PDF\r\n========================================= */\r\n\r\n.modal{\r\n    position:fixed;\r\n    inset:0;\r\n    background:rgba(0,0,0,0.78);\r\n    z-index:9999;\r\n    display:none;\r\n    align-items:center;\r\n    justify-content:center;\r\n    padding:30px;\r\n}\r\n\r\n.modal.active{\r\n    display:flex;\r\n}\r\n\r\n.modal-content{\r\n    width:100%;\r\n    max-width:1200px;\r\n    height:90vh;\r\n    background:white;\r\n    border-radius:22px;\r\n    overflow:hidden;\r\n    position:relative;\r\n    animation:zoom .35s ease;\r\n}\r\n\r\n.close-modal{\r\n    position:absolute;\r\n    top:16px;\r\n    right:16px;\r\n    width:46px;\r\n    height:46px;\r\n    border-radius:50%;\r\n    background:rgba(0,0,0,0.1);\r\n    border:none;\r\n    cursor:pointer;\r\n    font-size:1.2rem;\r\n    z-index:10;\r\n    transition:.3s;\r\n}\r\n\r\n.close-modal:hover{\r\n    background:rgba(0,0,0,0.2);\r\n}\r\n\r\n.modal iframe{\r\n    width:100%;\r\n    height:100%;\r\n    border:none;\r\n}\r\n\r\n/* =========================================\r\nFOOTER\r\n========================================= */\r\n\r\n.footer{\r\n    background:var(--primary);\r\n    padding:50px 0;\r\n    color:white;\r\n    text-align:center;\r\n}\r\n\r\n.footer p{\r\n    opacity:.85;\r\n    line-height:1.8;\r\n}\r\n\r\n/* =========================================\r\nANIMACIONES\r\n========================================= */\r\n\r\n@keyframes fadeUp{\r\n    from{\r\n        opacity:0;\r\n        transform:translateY(40px);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes zoom{\r\n    from{\r\n        opacity:0;\r\n        transform:scale(.9);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:scale(1);\r\n    }\r\n}\r\n\r\n/* =========================================\r\nRESPONSIVE\r\n========================================= */\r\n\r\n@media(max-width:992px){\r\n\r\n    .hero h2{\r\n        font-size:2.6rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:768px){\r\n\r\n    .hero{\r\n        padding-top:120px;\r\n    }\r\n\r\n    .hero h2{\r\n        font-size:2.1rem;\r\n    }\r\n\r\n    .section-title h3{\r\n        font-size:2rem;\r\n    }\r\n\r\n    .card-year{\r\n        font-size:4rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:480px){\r\n\r\n    .hero h2{\r\n        font-size:1.8rem;\r\n    }\r\n\r\n    .hero p{\r\n        font-size:.95rem;\r\n    }\r\n\r\n    .card-content{\r\n        padding:24px;\r\n    }\r\n\r\n}\r\n</style><!-- =========================================\r\nHERO\r\n========================================= --><section class="hero"><div class="hero-content"><h4 class="badge"><span>Repositorio Institucional</span></h4><h2>Planes Operativos Anuales</h2><h5>Accede a los documentos oficiales correspondientes a los Planes Operativos Anuales de la Universidad Nacional de Loja.</h5><h5>&nbsp;</h5></div></section><!-- =========================================\r\nPLANES\r\n========================================= --><section class="section" id="planes"><div class="container"><div class="section-title"><h3>Documentos Institucionales</h3><p>Explora los planes operativos anuales disponibles. Cada documento puede visualizarse directamente desde el micrositio o descargarse en formato PDF.</p></div><div class="cards-grid"><!-- 2024 --><div class="card"><div class="card-top"><div class="card-year">2024</div></div><div class="card-content"><h4>POA 2024</h4><p>&nbsp;Plan Operativo Anual 2024</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2024_mas_resolucio%CC%81n0207210001777305442.pdf" download="" title="POA 2024">Descargar</a></div></div></div><!-- 2025 --><div class="card"><div class="card-top"><div class="card-year">2025</div></div><div class="card-content"><h4>POA 2025</h4><p>&nbsp;Plan Operativo Anual 2025.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf" download="" title="POA 2025">Descargar</a></div></div></div><!-- 2026 --><div class="card"><div class="card-top"><div class="card-year">2026</div></div><div class="card-content"><h4>POA 2026</h4><p>&nbsp;Plan Operativo Anual&nbsp;2026.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf" download="" title="POA 2026">Descargar</a></div></div></div></div></div></section><!-- =========================================\r\nMODAL PDF\r\n========================================= --><div class="modal" id="pdfModal"><div class="modal-content"><button class="close-modal" id="closeModal">✕</button><iframe id="pdfViewer"></iframe></div></div><!-- =========================================\r\nFOOTER\r\n========================================= --><footer class="footer"><div class="container"><p>© 2026 Universidad Nacional de Loja<br>Micrositio institucional de planificación operativa.</p></div></footer><!-- =========================================\r\nJS\r\n========================================= --><script>\r\n\r\nconst modal = document.getElementById("pdfModal");\r\nconst pdfViewer = document.getElementById("pdfViewer");\r\nconst closeModal = document.getElementById("closeModal");\r\n\r\ndocument.querySelectorAll(".openPdf").forEach(button => {\r\n\r\n    button.addEventListener("click", () => {\r\n\r\n        const pdf = button.getAttribute("data-pdf");\r\n\r\n        pdfViewer.src = pdf;\r\n\r\n        modal.classList.add("active");\r\n\r\n        document.body.style.overflow = "hidden";\r\n\r\n    });\r\n\r\n});\r\n\r\nfunction closePdf(){\r\n\r\n    modal.classList.remove("active");\r\n\r\n    pdfViewer.src = "";\r\n\r\n    document.body.style.overflow = "auto";\r\n\r\n}\r\n\r\ncloseModal.addEventListener("click", closePdf);\r\n\r\nmodal.addEventListener("click", (e) => {\r\n\r\n    if(e.target === modal){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\ndocument.addEventListener("keydown", (e)=>{\r\n\r\n    if(e.key === "Escape"){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\n</script>	full_html
texto_libre	0	111	1335	en	0	<p><br><style type="text/css">/* BASE */\r\nbody {\r\n  margin: 0;\r\n  font-family: 'Inter', sans-serif;\r\n  background: #ffffff;\r\n  color: #111;\r\n  overflow-x: hidden;\r\n}\r\n\r\n/* FONDO */\r\n.background {\r\n  position: fixed;\r\n  width: 100%;\r\n  height: 100%;\r\n  z-index: -2;\r\n  background: radial-gradient(circle at 20% 30%, #22c55e20, transparent 40%),\r\n              radial-gradient(circle at 80% 70%, #16a34a15, transparent 40%);\r\n}\r\n\r\n/* HERO FULL IMAGE */\r\n.hero {\r\n  min-height: 80vh;\r\n  display: flex;\r\n  align-items: center;\r\n  padding: 60px 8%;\r\n  position: relative;\r\n  color: white;\r\n}\r\n\r\n.hero::before {\r\n  content: "";\r\n  position: absolute;\r\n  inset: 0;\r\n  background: url('https://unl.edu.ec/sites/default/files/2026-04/IMG_0503.jpeg') center/cover no-repeat;\r\n  z-index: -1;\r\n}\r\n\r\n.hero::after {\r\n  content: "";\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(0,0,0,0.4);\r\n  z-index: -1;\r\n}\r\n\r\n.hero h1 {\r\n  font-size: 3rem;\r\n}\r\n\r\n.hero span {\r\n  color: #22c55e;\r\n}\r\n\r\n/* PLANTA */\r\n.plant-container {\r\n  position: fixed;\r\n  left: 40px;\r\n  top: 0;\r\n  height: 100vh;\r\n  width: 80px;\r\n}\r\n\r\n.stem {\r\n  width: 6px;\r\n  background: linear-gradient(#16a34a, #22c55e);\r\n  height: 0;\r\n  margin: auto;\r\n}\r\n\r\n.leaf {\r\n  width: 22px;\r\n  height: 12px;\r\n  background: #22c55e;\r\n  border-radius: 20px;\r\n  position: absolute;\r\n  opacity: 0;\r\n  transform: scale(0);\r\n  transition: 0.5s;\r\n}\r\n\r\n.l1 { top: 150px; }\r\n.l2 { top: 350px; }\r\n.l3 { top: 550px; }\r\n.l4 { top: 750px; }\r\n\r\n/* SECCIONES */\r\n.section {\r\n  padding: 50px 8%;\r\n}\r\n\r\n/* TITULOS */\r\nh2 {\r\n  margin-bottom: 15px;\r\n}\r\n\r\n/* GRID */\r\n.grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\r\n  gap: 15px;\r\n}\r\n\r\n/* CARD */\r\n.card {\r\n  background: #f9fafb;\r\n  padding: 20px;\r\n  border-radius: 14px;\r\n  border: 1px solid #eee;\r\n}\r\n\r\n/* BOTÓN LINK */\r\n.btn {\r\n  display: inline-block;\r\n  margin-top: 10px;\r\n  padding: 8px 18px;\r\n  border-radius: 20px;\r\n  background: #16a34a;\r\n  color: white;\r\n  text-decoration: none;\r\n}\r\n\r\n/* ACCORDION */\r\n.accordion-item {\r\n  margin-bottom: 10px;\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n  border: 1px solid #eee;\r\n}\r\n\r\n.accordion-header {\r\n  padding: 15px;\r\n  cursor: pointer;\r\n  background: #f9fafb;\r\n  font-weight: 600;\r\n}\r\n\r\n.accordion-content {\r\n  max-height: 0;\r\n  overflow: hidden;\r\n  transition: 0.4s;\r\n  padding: 0 15px;\r\n}\r\n\r\n.accordion-content a {\r\n  display: block;\r\n  margin: 10px 0;\r\n}\r\n\r\n/* REVEAL */\r\n.reveal {\r\n  opacity: 0;\r\n  transform: translateY(30px);\r\n  transition: 0.6s;\r\n}\r\n\r\n.reveal.active {\r\n  opacity: 1;\r\n  transform: translateY(0);\r\n}\r\n/* ICONO + */\r\n.accordion-header {\r\n  position: relative;\r\n  padding-right: 40px;\r\n}\r\n\r\n.accordion-header::after {\r\n  content: "+";\r\n  position: absolute;\r\n  right: 15px;\r\n  top: 50%;\r\n  transform: translateY(-50%) rotate(0deg);\r\n  font-size: 20px;\r\n  font-weight: bold;\r\n  color: #16a34a;\r\n  transition: transform 0.3s ease;\r\n}\r\n\r\n/* cuando está abierto */\r\n.accordion-header.active::after {\r\n  transform: translateY(-50%) rotate(45deg);\r\n}\r\n</style></p><div class="background">&nbsp;</div><!-- PLANTA --><div class="plant-container"><div class="stem" id="stem">&nbsp;</div><div class="leaf l1" id="l1">&nbsp;</div><div class="leaf l2" id="l2">&nbsp;</div><div class="leaf l3" id="l3">&nbsp;</div><div class="leaf l4" id="l4">-d</div></div><!-- HERO --><div class="hero"><div><h1 class="text-align-center">UNL <span>SOSTENIBLE</span></h1><p class="text-align-center">Innovación, educación y compromiso con el futuro.</p></div></div><!-- POLÍTICAS --><div class="section"><h2><meta charset="UTF-8"></h2><p>La Universidad Nacional de Loja asume su compromiso con el modelo UNL Sostenible, una estrategia institucional orientada a integrar la sostenibilidad en todos sus ámbitos: académico, investigativo, de ge y vinculación con la sociedad. Este compromiso forma parte del Plan Estratégico de Desarrollo Institucional, que busca promover una universidad responsable con el entorno, que fomente la innovación, el uso eficiente de los recursos y la formación de ciudadanos comprometidos con un desarrollo equilibrado y sostenible para el sur del Ecuador y el mundo.</p><h2>&nbsp;</h2></div><!-- ACCORDION --><div class="section"><h2>Recursos institucionales</h2><p>Asegura equidad, accesibilidad y participación plena en la UNL</p><div class="accordion"><!-- POLITICAS --><div class="accordion-item"><div class="accordion-header">Políticas y planes</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/unl_politica_de_inclusion_educativa_2025.pdf" target="_blank">Política de inclusión</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/14-04-26_UNL_PLAN%20SOSTENIBIIDAD%20FINAL%20pdf.pdf" target="_blank">Plan de Gestión de Sostenibilidad</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/PROPUESTA%20POLITICA%20COMPRAS%20E%20INVERSIONES%20SOSTENIBLES%20.pdf" target="_blank">Política de Compras e Inversiones Sostenibles</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/pol%C3%ADtica_de_sostenibilidad_unl_certificacion-signed.pdf" target="_blank">Política de Sostenibilidad de la Universidad Nacional de Loja</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/resoluci%C3%B3n_so-no.03-rocs-no.8.4-07-02-2026_aprobacion_politica_de_sostenibilidad.pdf" target="_blank">Resolución Nro. SO-No.03-ROCS-No-8.4-07-04-2026</a></div></div><!-- PARTICIPACIÓN --><p>Accede a nuestras líneas de participación institucional</p></div><div class="accordion-item"><div class="accordion-header">Participación y democracia</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/Acuerdo%20SENESCYT-CZ7-2023-001-OS%20Asociacio%CC%81n%20General%20de%20Docentes%20Universitarios%20de%20Loja%20%E2%80%9CAGEDUL%E2%80%9D.pdf" target="_blank">AGEDUL</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/ASA-UNL.PDF.pdf" target="_blank">ASA</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/ESTATUTO%20FEUE%20LOJA.pdf" target="_blank">FEUE Loja</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/Sindicatos%20de%20trabajadores%20la%20Argelia_UNL.pdf" target="_blank">Sindicato La Argelia</a></div></div><!-- DOCUMENTOS --><p>Documento guía para la gestión estratégica de la UNL</p><div class="accordion-item"><div class="accordion-header">Documentos institucionales</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-10/PEDI_UNL_2024-2028_ACTUALIZADO_PND_2025-2029_VFINAL_OCS_15-10-25.pdf" target="_blank">Plan Estratégico de Desarrollo Institucional (PEDI)</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-10/Informe%20Autodiagno%CC%81stico%20RESIES%20UNL-1.pdf" target="_blank">Informe de Autodiagnóstico RESIES</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-06/2025_unl_memoria_sostenibilidad_29-05-26_1.pdf" target="_blank">Memoria de Sostenibilidad</a></div></div></div><script>\r\n// REVEAL\r\nwindow.addEventListener("scroll", () => {\r\n  document.querySelectorAll(".reveal").forEach(el => {\r\n    let top = el.getBoundingClientRect().top;\r\n    if (top < window.innerHeight - 80) {\r\n      el.classList.add("active");\r\n    }\r\n  });\r\n\r\n  // PLANTA\r\n  let scroll = window.scrollY;\r\n  let stem = document.getElementById("stem");\r\n\r\n  let growth = (scroll / document.body.scrollHeight) * window.innerHeight;\r\n  stem.style.height = growth + "px";\r\n\r\n  if (scroll > 150) showLeaf("l1");\r\n  if (scroll > 400) showLeaf("l2");\r\n  if (scroll > 800) showLeaf("l3");\r\n  if (scroll > 1200) showLeaf("l4");\r\n});\r\n\r\nfunction showLeaf(id) {\r\n  let leaf = document.getElementById(id);\r\n  leaf.style.opacity = 1;\r\n  leaf.style.transform = "scale(1)";\r\n}\r\n\r\n// ACCORDION\r\ndocument.querySelectorAll(".accordion-header").forEach(header => {\r\n  header.addEventListener("click", () => {\r\n    let content = header.nextElementSibling;\r\n\r\n    document.querySelectorAll(".accordion-content").forEach(item => {\r\n      if (item !== content) item.style.maxHeight = null;\r\n    });\r\n\r\n    content.style.maxHeight = content.scrollHeight + "px";\r\n  });\r\n});\r\n</script><!--\r\n  ==========================================================================\r\n  UNL SOSTENIBLE — Secciones nuevas: "Rankings y reconocimientos" +\r\n  "Iniciativas internacionales"\r\n  ==========================================================================\r\n  CAMBIOS EN ESTA VERSIÓN\r\n  1. Todas las medidas de texto/espaciado pasaron de rem a px.\r\n  2. Los iconos de la sección de rankings ahora representan a los 4 sistemas\r\n     de evaluación (SCImago, UI GreenMetric, THE World University Rankings,\r\n     Webometrics). Son versiones simplificadas/genéricas inspiradas en la\r\n     forma de cada símbolo (columnas, globo, insignia, red), NO reproducciones\r\n     exactas de los logotipos originales -> los logos oficiales son marca\r\n     registrada de cada organización, así que para el logo pixel-perfecto\r\n     te recomiendo descargarlo del kit de prensa/branding de cada ranking\r\n     y reemplazar el <svg> de ese icono por su <img> oficial.\r\n  3. El fondo decorativo de las tarjetas de "Iniciativas internacionales" ya\r\n     no es una hoja tipo burbuja: ahora la tarjeta verde tiene un patrón de\r\n     planta/ramificación (sostenibilidad) y la tarjeta agua tiene un patrón\r\n     de átomo/órbitas (investigación).\r\n  4. Sigue sin tocar la paleta de colores del sitio (variables --unl-verde-*,\r\n     --unl-agua-*, --unl-tierra-* al inicio del <style>).\r\n  5. Los textos marcados "[EDITAR]" siguen siendo plantilla: reemplázalos\r\n     con los datos reales de la universidad.\r\n  ==========================================================================\r\n--><section class="unl-sost-wrap" id="unl-rankings-iniciativas"><style type="text/css">#unl-rankings-iniciativas{\r\n    --unl-verde-950:#0b2b1c;\r\n    --unl-verde-800:#12472c;\r\n    --unl-verde-700:#1b5e39;\r\n    --unl-verde-600:#2c7a4b;\r\n    --unl-verde-400:#5aa878;\r\n    --unl-verde-200:#bfe0cd;\r\n    --unl-verde-100:#e4f3ea;\r\n    --unl-tierra-600:#8a6a3f;\r\n    --unl-tierra-200:#ecdfc7;\r\n    --unl-agua-600:#1f7a8c;\r\n    --unl-agua-200:#cfeef2;\r\n    --unl-texto:#16241c;\r\n    --unl-texto-suave:#4a5c52;\r\n    --unl-borde:#d8e6dc;\r\n    --unl-fondo-card:#ffffff;\r\n    --unl-radio:14px;\r\n    font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;\r\n    color: var(--unl-texto);\r\n    max-width: 1180px;\r\n    margin: 0 auto;\r\n    padding: 56px 20px;\r\n    box-sizing: border-box;\r\n  }\r\n  #unl-rankings-iniciativas *{ box-sizing: border-box; }\r\n\r\n  .unl-sost-eyebrow{\r\n    display:inline-flex; align-items:center; gap:8px;\r\n    font-size:12px; font-weight:700; letter-spacing:.08em;\r\n    text-transform:uppercase; color: var(--unl-verde-700);\r\n    background: var(--unl-verde-100);\r\n    border:1px solid var(--unl-verde-200);\r\n    padding:5px 12px; border-radius:999px; margin-bottom:14px;\r\n  }\r\n  .unl-sost-eyebrow .dot{\r\n    width:7px;height:7px;border-radius:50%;\r\n    background: var(--unl-verde-600);\r\n    animation: unlPulse 2.4s ease-in-out infinite;\r\n  }\r\n  .unl-sost-h2{\r\n    font-size: clamp(24px, 2.4vw, 34px);\r\n    font-weight: 800; line-height:1.2; margin:0 0 10px;\r\n    color: var(--unl-verde-950);\r\n  }\r\n  .unl-sost-sub{\r\n    font-size:16px; color: var(--unl-texto-suave);\r\n    max-width:62ch; line-height:1.6; margin:0 0 35px;\r\n  }\r\n\r\n  /* ============ SECCIÓN 1: RANKINGS ============ */\r\n  .unl-rank-section{ margin-bottom:72px; position:relative; }\r\n\r\n  .unl-rank-grid{\r\n    display:grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));\r\n    gap:20px;\r\n  }\r\n  .unl-rank-card{\r\n    background: var(--unl-fondo-card);\r\n    border:1px solid var(--unl-borde);\r\n    border-radius: var(--unl-radio);\r\n    padding:24px 22px;\r\n    position:relative;\r\n    overflow:hidden;\r\n    transition: transform .35s ease, box-shadow .35s ease, border-color .35s ease;\r\n  }\r\n  .unl-rank-card:hover{\r\n    transform: translateY(-4px);\r\n    box-shadow: 0 14px 28px -14px rgba(18,71,44,.25);\r\n    border-color: var(--unl-verde-400);\r\n  }\r\n  .unl-rank-card::before{\r\n    content:"";\r\n    position:absolute; inset:0 0 auto 0; height:4px;\r\n    background: linear-gradient(90deg, var(--unl-verde-600), var(--unl-agua-600));\r\n    transform-origin:left; transform:scaleX(0);\r\n    transition: transform .6s ease;\r\n  }\r\n  .unl-rank-card.unl-inview::before{ transform:scaleX(1); }\r\n\r\n  .unl-rank-icon{\r\n    width:44px;height:44px;border-radius:10px;\r\n    background: var(--unl-verde-100);\r\n    display:flex;align-items:center;justify-content:center;\r\n    margin-bottom:16px; color: var(--unl-verde-700);\r\n  }\r\n  .unl-rank-icon svg{ width:24px;height:24px; }\r\n\r\n  .unl-rank-label{\r\n    font-size:13px; color: var(--unl-texto-suave); font-weight:600;\r\n    text-transform:uppercase; letter-spacing:.03em; margin-bottom:5px;\r\n  }\r\n  .unl-rank-number{\r\n    font-size:32px; font-weight:800; color: var(--unl-verde-800);\r\n    line-height:1; display:flex; align-items:baseline; gap:5px;\r\n  }\r\n  .unl-rank-number .unl-rank-suffix{ font-size:17px; font-weight:700; color: var(--unl-verde-600); }\r\n  .unl-rank-desc{ font-size:14px; color: var(--unl-texto-suave); margin-top:9px; line-height:1.5; }\r\n  .unl-rank-tag{\r\n    display:inline-block; margin-top:14px; font-size:12px; font-weight:700;\r\n    color: var(--unl-tierra-600); background: var(--unl-tierra-200);\r\n    padding:3px 9px; border-radius:6px;\r\n  }\r\n\r\n  /* Ring de progreso circular (áreas evaluadas) */\r\n  .unl-ring-block{\r\n    margin-top:40px; padding-top:35px;\r\n    border-top:1px dashed var(--unl-borde);\r\n  }\r\n  .unl-ring-title{ font-size:16px; font-weight:700; margin:0 0 22px; color: var(--unl-verde-950); }\r\n  .unl-ring-grid{\r\n    display:grid; grid-template-columns: repeat(auto-fit, minmax(130px,1fr));\r\n    gap:20px; text-align:center;\r\n  }\r\n  .unl-ring-item{ display:flex; flex-direction:column; align-items:center; gap:10px; }\r\n  .unl-ring-svg{ width:88px; height:88px; }\r\n  .unl-ring-track{ fill:none; stroke: var(--unl-verde-100); stroke-width:8; }\r\n  .unl-ring-bar{\r\n    fill:none; stroke: var(--unl-verde-600); stroke-width:8; stroke-linecap:round;\r\n    stroke-dasharray: 251; stroke-dashoffset: 251;\r\n    transition: stroke-dashoffset 1.4s cubic-bezier(.2,.7,.2,1);\r\n  }\r\n  .unl-ring-pct{ font-size:15px; font-weight:800; fill: var(--unl-verde-800); }\r\n  .unl-ring-name{ font-size:12px; color: var(--unl-texto-suave); font-weight:600; line-height:1.3; }\r\n\r\n  /* ============ SECCIÓN 2: INICIATIVAS INTERNACIONALES ============ */\r\n  .unl-init-section{ position:relative; }\r\n\r\n  .unl-init-grid{\r\n    display:grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\r\n    gap:24px;\r\n  }\r\n  .unl-init-card{\r\n    background: linear-gradient(180deg, var(--unl-verde-950) 0%, var(--unl-verde-800) 100%);\r\n    border-radius: var(--unl-radio);\r\n    padding:28px;\r\n    color:#f2f8f4;\r\n    position:relative;\r\n    overflow:hidden;\r\n    min-height:260px;\r\n    display:flex; flex-direction:column;\r\n  }\r\n  .unl-init-card.unl-agua{\r\n    background: linear-gradient(180deg, #0c3b44 0%, #124f5c 100%);\r\n  }\r\n\r\n  /* --- Fondos decorativos temáticos --- */\r\n  .unl-init-motif{\r\n    position:absolute; right:-22px; top:-22px; width:190px; height:190px;\r\n    opacity:.16; pointer-events:none;\r\n  }\r\n  .unl-init-motif.unl-motif-atomo{ animation: unlSpin 22s linear infinite; }\r\n  .unl-init-card.unl-agua .unl-init-motif circle,\r\n  .unl-init-card.unl-agua .unl-init-motif ellipse{ stroke:#dff5f8; }\r\n  .unl-init-card:not(.unl-agua) .unl-init-motif path,\r\n  .unl-init-card:not(.unl-agua) .unl-init-motif circle{ stroke:#d9f0e2; fill:#d9f0e2; }\r\n\r\n  .unl-init-top{ display:flex; align-items:center; justify-content:space-between; margin-bottom:18px; position:relative; z-index:1; }\r\n  .unl-init-badge{\r\n    font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em;\r\n    background: rgba(255,255,255,.12); padding:5px 10px; border-radius:999px;\r\n  }\r\n  .unl-init-year{ font-size:12px; color:#cfe6d8; font-weight:600; }\r\n  .unl-init-name{ font-size:20px; font-weight:800; margin:0 0 9px; line-height:1.25; position:relative; z-index:1; }\r\n  .unl-init-desc{ font-size:15px; color:#d8ebe0; line-height:1.6; margin:0 0 19px; flex:1; position:relative; z-index:1; }\r\n\r\n  .unl-init-progress-row{ margin-top:auto; position:relative; z-index:1; }\r\n  .unl-init-progress-label{\r\n    display:flex; justify-content:space-between; font-size:12px;\r\n    color:#cfe6d8; margin-bottom:6px; font-weight:600;\r\n  }\r\n  .unl-init-bar-track{\r\n    width:100%; height:8px; border-radius:999px; background: rgba(255,255,255,.14);\r\n    overflow:hidden;\r\n  }\r\n  .unl-init-bar-fill{\r\n    height:100%; border-radius:999px;\r\n    background: linear-gradient(90deg, #7fd7a5, #b7e8c9);\r\n    width:0%; transition: width 1.6s cubic-bezier(.2,.7,.2,1);\r\n  }\r\n  .unl-agua .unl-init-bar-fill{ background: linear-gradient(90deg, #6cc9d6, #a9e4ec); }\r\n\r\n  @keyframes unlSpin{ from{ transform: rotate(0deg);} to{ transform: rotate(360deg);} }\r\n  @keyframes unlPulse{\r\n    0%,100%{ opacity:1; transform:scale(1); }\r\n    50%{ opacity:.4; transform:scale(1.3); }\r\n  }\r\n  .unl-fade-up{\r\n    opacity:0; transform: translateY(18px);\r\n    transition: opacity .7s ease, transform .7s ease;\r\n  }\r\n  .unl-fade-up.unl-inview{ opacity:1; transform:translateY(0); }\r\n\r\n  @media (prefers-reduced-motion: reduce){\r\n    #unl-rankings-iniciativas *{ animation:none !important; transition:none !important; }\r\n    .unl-fade-up{ opacity:1; transform:none; }\r\n  }\r\n\r\n  @media (max-width: 620px){\r\n    #unl-rankings-iniciativas{ padding: 40px 16px; }\r\n    .unl-rank-number{ font-size:26px; }\r\n  }\r\n</style><!-- ===================== SECCIÓN 1: RANKINGS ===================== --><div class="unl-rank-section"><p><span class="unl-sost-eyebrow">Reconocimientos</span></p><h2 class="unl-sost-h2">Rankings y reconocimientos en sostenibilidad</h2><p class="unl-sost-sub">Resultados obtenidos por la Universidad Nacional de Loja en los principales sistemas internacionales que evalúan investigación, impacto y sostenibilidad institucional.</p><div class="unl-rank-grid"><!-- Tarjeta 1: SCImago --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><path d="M3 8l9-5 9 5" stroke-linejoin="round"></path><rect height="9" width="2.4" x="4" y="9"></rect><rect height="9" width="2.4" x="9" y="9"></rect><rect height="9" width="2.4" x="14" y="9"></rect><rect height="9" width="1.6" x="19" y="9"></rect><rect height="2" width="18" x="3" y="19"></rect></svg></div><div class="unl-rank-label">SCImago Institutions Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="8">0</span></div><p class="unl-rank-desc">Entre universidades públicas del Ecuador por su impacto, la calidad y la visibilidad de la producción científica.</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 2: UI GreenMetric --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><circle cx="12" cy="12" r="8.5"></circle><path d="M4 10.5c2.5 1.2 5 1.2 8 .3s6-.3 8 1"></path><path d="M6 16c2 .8 4.2.8 6.5 0s4.8-.6 6.6.4"></path><path d="M12 3.5v17"></path></svg></div><div class="unl-rank-label">UI GreenMetric World University Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="004">0</span></div><p class="unl-rank-desc">Entre universidades públicas del Ecuador por acciones en infraestructura sostenible, energía, manejo de residuos, agua, transporte y educación ambiental.</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 3: THE World University Rankings --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><rect height="18" rx="5" width="18" x="3" y="3"></rect><path d="M8 8h3.2v8H8z" fill="currentColor" stroke="none"></path><path d="M13 8h1.4v8H13z" fill="currentColor" stroke="none"></path><path d="M15.6 8h1.4v8h-1.4z" fill="currentColor" stroke="none"></path></svg></div><div class="unl-rank-label">THE World University Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="0005">0</span><span class="unl-rank-suffix">[EDITAR]</span></div><p class="unl-rank-desc">Mejor universidad pública del Ecuador</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 4: Webometrics --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><circle cx="6" cy="6" r="2"></circle><circle cx="18" cy="6" r="2"></circle><circle cx="12" cy="12" r="2.2"></circle><circle cx="6" cy="18" r="2"></circle><circle cx="18" cy="18" r="2"></circle><path d="M7.6 7.2l3 3.4M16.4 7.2l-3 3.4M7.6 16.8l3-3.4M16.4 16.8l-3-3.4"></path></svg></div><div class="unl-rank-label">Webometrics Ranking Web of Universities</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="000">0</span><span class="unl-rank-suffix">[EDITAR]</span></div><p class="unl-rank-desc">Posición según presencia, apertura e impacto del sitio web institucional. [EDITAR con dato real]</p><p><span class="unl-rank-tag">Edición [EDITAR año]</span></p></div></div><p><!-- Áreas evaluadas: anillos de progreso -->&nbsp;</p><div class="unl-ring-block unl-fade-up"><h3 class="unl-ring-title">Desempeño por área evaluada [EDITAR con puntajes reales]</h3><div class="unl-ring-grid"><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="72" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">72%</text> </svg><span class="unl-ring-name">Entorno e</span><br><span class="unl-ring-name">infraestructura</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="58" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">58%</text> </svg><span class="unl-ring-name">Energía y</span><br><span class="unl-ring-name">cambio climático</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="65" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">65%</text> </svg><span class="unl-ring-name">Gestión de</span><br><span class="unl-ring-name">residuos</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="80" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">80%</text> </svg><span class="unl-ring-name">Uso eficiente</span><br><span class="unl-ring-name">del agua</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="61" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">61%</text> </svg><span class="unl-ring-name">Transporte</span><br><span class="unl-ring-name">sostenible</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="88" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">88%</text> </svg><span class="unl-ring-name">Educación e</span><br><span class="unl-ring-name">investigación</span></div></div></div></div><!-- ===================== SECCIÓN 2: INICIATIVAS INTERNACIONALES ===================== --><div class="unl-init-section"><p><span class="unl-sost-eyebrow">Cooperación internacional</span></p><h2 class="unl-sost-h2">Iniciativas y concursos internacionales</h2><p class="unl-sost-sub">La UNL participa actualmente en las siguientes iniciativas internacionales orientadas a fortalecer su modelo de sostenibilidad institucional. [EDITAR: reemplazar nombres, descripciones y avance real]</p><div class="unl-init-grid"><!-- Iniciativa 1: motivo de planta / ramificación --><div class="unl-init-card unl-fade-up"><svg class="unl-init-motif unl-motif-planta" aria-hidden="true" viewbox="0 0 100 100"><path d="M50 95V50" fill="none" stroke-width="2"></path><path d="M50 70C38 66 30 56 30 44" fill="none" stroke-width="2"></path><path d="M50 60C62 56 70 46 70 34" fill="none" stroke-width="2"></path><path d="M50 50C41 45 36 36 37 26" fill="none" stroke-width="2"></path><circle cx="30" cy="44" r="4"></circle><circle cx="70" cy="34" r="4"></circle><circle cx="37" cy="26" r="4"></circle><circle cx="50" cy="18" r="5"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 1</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 1]</h3><p class="unl-init-desc">[EDITAR: descripción breve — qué es la iniciativa, quién la convoca y qué compromiso concreto asumió la UNL al participar].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="45">&nbsp;</div></div></div></div><!-- Iniciativa 2: motivo de átomo / órbitas --><div class="unl-init-card unl-agua unl-fade-up"><svg class="unl-init-motif unl-motif-atomo" aria-hidden="true" fill="none" stroke-width="1.6" viewbox="0 0 100 100"><ellipse cx="50" cy="50" rx="42" ry="16"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(60 50 50)"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(120 50 50)"></ellipse><circle cx="50" cy="50" fill="currentColor" r="6" stroke="none"></circle><circle cx="92" cy="50" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="78" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="22" fill="currentColor" r="3" stroke="none"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 2</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 2]</h3><p class="unl-init-desc">[EDITAR: descripción breve — objetivo del concurso o red, alcance geográfico y en qué consiste la participación de la UNL].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="62">&nbsp;</div></div></div></div></div></div></section><script>\r\n(function(){\r\n  var root = document.getElementById('unl-rankings-iniciativas');\r\n  if(!root) return;\r\n  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\r\n\r\n  function animateCount(el){\r\n    var target = parseInt(el.getAttribute('data-target'), 10) || 0;\r\n    if(reduce){ el.textContent = target; return; }\r\n    var start = 0, dur = 1400, t0 = null;\r\n    function step(ts){\r\n      if(!t0) t0 = ts;\r\n      var p = Math.min((ts - t0) / dur, 1);\r\n      el.textContent = Math.round(start + (target - start) * p);\r\n      if(p < 1) requestAnimationFrame(step);\r\n    }\r\n    requestAnimationFrame(step);\r\n  }\r\n\r\n  function animateRing(circle){\r\n    var pct = parseFloat(circle.getAttribute('data-pct')) || 0;\r\n    var offset = 251 - (251 * pct / 100);\r\n    circle.style.strokeDashoffset = offset;\r\n  }\r\n\r\n  function animateBar(bar){\r\n    var pct = parseFloat(bar.getAttribute('data-pct')) || 0;\r\n    bar.style.width = pct + '%';\r\n    var label = bar.closest('.unl-init-progress-row').querySelector('.unl-init-pct');\r\n    if(label) label.textContent = pct + '%';\r\n  }\r\n\r\n  var io = new IntersectionObserver(function(entries){\r\n    entries.forEach(function(entry){\r\n      if(!entry.isIntersecting) return;\r\n      var el = entry.target;\r\n      el.classList.add('unl-inview');\r\n\r\n      el.querySelectorAll('.unl-rank-count').forEach(animateCount);\r\n      el.querySelectorAll('.unl-ring-bar').forEach(animateRing);\r\n      el.querySelectorAll('.unl-init-bar-fill').forEach(animateBar);\r\n\r\n      io.unobserve(el);\r\n    });\r\n  }, { threshold: .3 });\r\n\r\n  root.querySelectorAll('.unl-fade-up, .unl-rank-card').forEach(function(el){\r\n    io.observe(el);\r\n  });\r\n})();\r\n</script>	full_html
texto_libre	0	111	1336	en	0	<p><br><style type="text/css">/* BASE */\r\nbody {\r\n  margin: 0;\r\n  font-family: 'Inter', sans-serif;\r\n  background: #ffffff;\r\n  color: #111;\r\n  overflow-x: hidden;\r\n}\r\n\r\n/* FONDO */\r\n.background {\r\n  position: fixed;\r\n  width: 100%;\r\n  height: 100%;\r\n  z-index: -2;\r\n  background: radial-gradient(circle at 20% 30%, #22c55e20, transparent 40%),\r\n              radial-gradient(circle at 80% 70%, #16a34a15, transparent 40%);\r\n}\r\n\r\n/* HERO FULL IMAGE */\r\n.hero {\r\n  min-height: 80vh;\r\n  display: flex;\r\n  align-items: center;\r\n  padding: 60px 8%;\r\n  position: relative;\r\n  color: white;\r\n}\r\n\r\n.hero::before {\r\n  content: "";\r\n  position: absolute;\r\n  inset: 0;\r\n  background: url('https://unl.edu.ec/sites/default/files/2026-04/IMG_0503.jpeg') center/cover no-repeat;\r\n  z-index: -1;\r\n}\r\n\r\n.hero::after {\r\n  content: "";\r\n  position: absolute;\r\n  inset: 0;\r\n  background: rgba(0,0,0,0.4);\r\n  z-index: -1;\r\n}\r\n\r\n.hero h1 {\r\n  font-size: 3rem;\r\n}\r\n\r\n.hero span {\r\n  color: #22c55e;\r\n}\r\n\r\n/* PLANTA */\r\n.plant-container {\r\n  position: fixed;\r\n  left: 40px;\r\n  top: 0;\r\n  height: 100vh;\r\n  width: 80px;\r\n}\r\n\r\n.stem {\r\n  width: 6px;\r\n  background: linear-gradient(#16a34a, #22c55e);\r\n  height: 0;\r\n  margin: auto;\r\n}\r\n\r\n.leaf {\r\n  width: 22px;\r\n  height: 12px;\r\n  background: #22c55e;\r\n  border-radius: 20px;\r\n  position: absolute;\r\n  opacity: 0;\r\n  transform: scale(0);\r\n  transition: 0.5s;\r\n}\r\n\r\n.l1 { top: 150px; }\r\n.l2 { top: 350px; }\r\n.l3 { top: 550px; }\r\n.l4 { top: 750px; }\r\n\r\n/* SECCIONES */\r\n.section {\r\n  padding: 50px 8%;\r\n}\r\n\r\n/* TITULOS */\r\nh2 {\r\n  margin-bottom: 15px;\r\n}\r\n\r\n/* GRID */\r\n.grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\r\n  gap: 15px;\r\n}\r\n\r\n/* CARD */\r\n.card {\r\n  background: #f9fafb;\r\n  padding: 20px;\r\n  border-radius: 14px;\r\n  border: 1px solid #eee;\r\n}\r\n\r\n/* BOTÓN LINK */\r\n.btn {\r\n  display: inline-block;\r\n  margin-top: 10px;\r\n  padding: 8px 18px;\r\n  border-radius: 20px;\r\n  background: #16a34a;\r\n  color: white;\r\n  text-decoration: none;\r\n}\r\n\r\n/* ACCORDION */\r\n.accordion-item {\r\n  margin-bottom: 10px;\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n  border: 1px solid #eee;\r\n}\r\n\r\n.accordion-header {\r\n  padding: 15px;\r\n  cursor: pointer;\r\n  background: #f9fafb;\r\n  font-weight: 600;\r\n}\r\n\r\n.accordion-content {\r\n  max-height: 0;\r\n  overflow: hidden;\r\n  transition: 0.4s;\r\n  padding: 0 15px;\r\n}\r\n\r\n.accordion-content a {\r\n  display: block;\r\n  margin: 10px 0;\r\n}\r\n\r\n/* REVEAL */\r\n.reveal {\r\n  opacity: 0;\r\n  transform: translateY(30px);\r\n  transition: 0.6s;\r\n}\r\n\r\n.reveal.active {\r\n  opacity: 1;\r\n  transform: translateY(0);\r\n}\r\n/* ICONO + */\r\n.accordion-header {\r\n  position: relative;\r\n  padding-right: 40px;\r\n}\r\n\r\n.accordion-header::after {\r\n  content: "+";\r\n  position: absolute;\r\n  right: 15px;\r\n  top: 50%;\r\n  transform: translateY(-50%) rotate(0deg);\r\n  font-size: 20px;\r\n  font-weight: bold;\r\n  color: #16a34a;\r\n  transition: transform 0.3s ease;\r\n}\r\n\r\n/* cuando está abierto */\r\n.accordion-header.active::after {\r\n  transform: translateY(-50%) rotate(45deg);\r\n}\r\n</style></p><div class="background">&nbsp;</div><!-- PLANTA --><div class="plant-container"><div class="stem" id="stem">&nbsp;</div><div class="leaf l1" id="l1">&nbsp;</div><div class="leaf l2" id="l2">&nbsp;</div><div class="leaf l3" id="l3">&nbsp;</div><div class="leaf l4" id="l4">-d</div></div><!-- HERO --><div class="hero"><div><h1 class="text-align-center">UNL <span>SOSTENIBLE</span></h1><p class="text-align-center">Innovación, educación y compromiso con el futuro.</p></div></div><!-- POLÍTICAS --><div class="section"><h2><meta charset="UTF-8"></h2><p>La Universidad Nacional de Loja asume su compromiso con el modelo UNL Sostenible, una estrategia institucional orientada a integrar la sostenibilidad en todos sus ámbitos: académico, investigativo, de ge y vinculación con la sociedad. Este compromiso forma parte del Plan Estratégico de Desarrollo Institucional, que busca promover una universidad responsable con el entorno, que fomente la innovación, el uso eficiente de los recursos y la formación de ciudadanos comprometidos con un desarrollo equilibrado y sostenible para el sur del Ecuador y el mundo.</p><h2>&nbsp;</h2></div><!-- ACCORDION --><div class="section"><h2>Recursos institucionales</h2><p>Asegura equidad, accesibilidad y participación plena en la UNL</p><div class="accordion"><!-- POLITICAS --><div class="accordion-item"><div class="accordion-header">Políticas y planes</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/unl_politica_de_inclusion_educativa_2025.pdf" target="_blank">Política de inclusión</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/14-04-26_UNL_PLAN%20SOSTENIBIIDAD%20FINAL%20pdf.pdf" target="_blank">Plan de Gestión de Sostenibilidad</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/PROPUESTA%20POLITICA%20COMPRAS%20E%20INVERSIONES%20SOSTENIBLES%20.pdf" target="_blank">Política de Compras e Inversiones Sostenibles</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/pol%C3%ADtica_de_sostenibilidad_unl_certificacion-signed.pdf" target="_blank">Política de Sostenibilidad de la Universidad Nacional de Loja</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-04/resoluci%C3%B3n_so-no.03-rocs-no.8.4-07-02-2026_aprobacion_politica_de_sostenibilidad.pdf" target="_blank">Resolución Nro. SO-No.03-ROCS-No-8.4-07-04-2026</a></div></div><!-- PARTICIPACIÓN --><p>Accede a nuestras líneas de participación institucional</p></div><div class="accordion-item"><div class="accordion-header">Participación y democracia</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/Acuerdo%20SENESCYT-CZ7-2023-001-OS%20Asociacio%CC%81n%20General%20de%20Docentes%20Universitarios%20de%20Loja%20%E2%80%9CAGEDUL%E2%80%9D.pdf" target="_blank">AGEDUL</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/ASA-UNL.PDF.pdf" target="_blank">ASA</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/ESTATUTO%20FEUE%20LOJA.pdf" target="_blank">FEUE Loja</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-11/Sindicatos%20de%20trabajadores%20la%20Argelia_UNL.pdf" target="_blank">Sindicato La Argelia</a></div></div><!-- DOCUMENTOS --><p>Documento guía para la gestión estratégica de la UNL</p><div class="accordion-item"><div class="accordion-header">Documentos institucionales</div><div class="accordion-content"><a class="btn" href="https://unl.edu.ec/sites/default/files/2025-10/PEDI_UNL_2024-2028_ACTUALIZADO_PND_2025-2029_VFINAL_OCS_15-10-25.pdf" target="_blank">Plan Estratégico de Desarrollo Institucional (PEDI)</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2025-10/Informe%20Autodiagno%CC%81stico%20RESIES%20UNL-1.pdf" target="_blank">Informe de Autodiagnóstico RESIES</a> <a class="btn" href="https://unl.edu.ec/sites/default/files/2026-06/2025_unl_memoria_sostenibilidad_29-05-26_1.pdf" target="_blank">Memoria de Sostenibilidad</a></div></div></div><script>\r\n// REVEAL\r\nwindow.addEventListener("scroll", () => {\r\n  document.querySelectorAll(".reveal").forEach(el => {\r\n    let top = el.getBoundingClientRect().top;\r\n    if (top < window.innerHeight - 80) {\r\n      el.classList.add("active");\r\n    }\r\n  });\r\n\r\n  // PLANTA\r\n  let scroll = window.scrollY;\r\n  let stem = document.getElementById("stem");\r\n\r\n  let growth = (scroll / document.body.scrollHeight) * window.innerHeight;\r\n  stem.style.height = growth + "px";\r\n\r\n  if (scroll > 150) showLeaf("l1");\r\n  if (scroll > 400) showLeaf("l2");\r\n  if (scroll > 800) showLeaf("l3");\r\n  if (scroll > 1200) showLeaf("l4");\r\n});\r\n\r\nfunction showLeaf(id) {\r\n  let leaf = document.getElementById(id);\r\n  leaf.style.opacity = 1;\r\n  leaf.style.transform = "scale(1)";\r\n}\r\n\r\n// ACCORDION\r\ndocument.querySelectorAll(".accordion-header").forEach(header => {\r\n  header.addEventListener("click", () => {\r\n    let content = header.nextElementSibling;\r\n\r\n    document.querySelectorAll(".accordion-content").forEach(item => {\r\n      if (item !== content) item.style.maxHeight = null;\r\n    });\r\n\r\n    content.style.maxHeight = content.scrollHeight + "px";\r\n  });\r\n});\r\n</script><!--\r\n  ==========================================================================\r\n  UNL SOSTENIBLE — Secciones nuevas: "Rankings y reconocimientos" +\r\n  "Iniciativas internacionales"\r\n  ==========================================================================\r\n  CAMBIOS EN ESTA VERSIÓN\r\n  1. Todas las medidas de texto/espaciado pasaron de rem a px.\r\n  2. Los iconos de la sección de rankings ahora representan a los 4 sistemas\r\n     de evaluación (SCImago, UI GreenMetric, THE World University Rankings,\r\n     Webometrics). Son versiones simplificadas/genéricas inspiradas en la\r\n     forma de cada símbolo (columnas, globo, insignia, red), NO reproducciones\r\n     exactas de los logotipos originales -> los logos oficiales son marca\r\n     registrada de cada organización, así que para el logo pixel-perfecto\r\n     te recomiendo descargarlo del kit de prensa/branding de cada ranking\r\n     y reemplazar el <svg> de ese icono por su <img> oficial.\r\n  3. El fondo decorativo de las tarjetas de "Iniciativas internacionales" ya\r\n     no es una hoja tipo burbuja: ahora la tarjeta verde tiene un patrón de\r\n     planta/ramificación (sostenibilidad) y la tarjeta agua tiene un patrón\r\n     de átomo/órbitas (investigación).\r\n  4. Sigue sin tocar la paleta de colores del sitio (variables --unl-verde-*,\r\n     --unl-agua-*, --unl-tierra-* al inicio del <style>).\r\n  5. Los textos marcados "[EDITAR]" siguen siendo plantilla: reemplázalos\r\n     con los datos reales de la universidad.\r\n  ==========================================================================\r\n--><section class="unl-sost-wrap" id="unl-rankings-iniciativas"><style type="text/css">#unl-rankings-iniciativas{\r\n    --unl-verde-950:#0b2b1c;\r\n    --unl-verde-800:#12472c;\r\n    --unl-verde-700:#1b5e39;\r\n    --unl-verde-600:#2c7a4b;\r\n    --unl-verde-400:#5aa878;\r\n    --unl-verde-200:#bfe0cd;\r\n    --unl-verde-100:#e4f3ea;\r\n    --unl-tierra-600:#8a6a3f;\r\n    --unl-tierra-200:#ecdfc7;\r\n    --unl-agua-600:#1f7a8c;\r\n    --unl-agua-200:#cfeef2;\r\n    --unl-texto:#16241c;\r\n    --unl-texto-suave:#4a5c52;\r\n    --unl-borde:#d8e6dc;\r\n    --unl-fondo-card:#ffffff;\r\n    --unl-radio:14px;\r\n    font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;\r\n    color: var(--unl-texto);\r\n    max-width: 1180px;\r\n    margin: 0 auto;\r\n    padding: 56px 20px;\r\n    box-sizing: border-box;\r\n  }\r\n  #unl-rankings-iniciativas *{ box-sizing: border-box; }\r\n\r\n  .unl-sost-eyebrow{\r\n    display:inline-flex; align-items:center; gap:8px;\r\n    font-size:12px; font-weight:700; letter-spacing:.08em;\r\n    text-transform:uppercase; color: var(--unl-verde-700);\r\n    background: var(--unl-verde-100);\r\n    border:1px solid var(--unl-verde-200);\r\n    padding:5px 12px; border-radius:999px; margin-bottom:14px;\r\n  }\r\n  .unl-sost-eyebrow .dot{\r\n    width:7px;height:7px;border-radius:50%;\r\n    background: var(--unl-verde-600);\r\n    animation: unlPulse 2.4s ease-in-out infinite;\r\n  }\r\n  .unl-sost-h2{\r\n    font-size: clamp(24px, 2.4vw, 34px);\r\n    font-weight: 800; line-height:1.2; margin:0 0 10px;\r\n    color: var(--unl-verde-950);\r\n  }\r\n  .unl-sost-sub{\r\n    font-size:16px; color: var(--unl-texto-suave);\r\n    max-width:62ch; line-height:1.6; margin:0 0 35px;\r\n  }\r\n\r\n  /* ============ SECCIÓN 1: RANKINGS ============ */\r\n  .unl-rank-section{ margin-bottom:72px; position:relative; }\r\n\r\n  .unl-rank-grid{\r\n    display:grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));\r\n    gap:20px;\r\n  }\r\n  .unl-rank-card{\r\n    background: var(--unl-fondo-card);\r\n    border:1px solid var(--unl-borde);\r\n    border-radius: var(--unl-radio);\r\n    padding:24px 22px;\r\n    position:relative;\r\n    overflow:hidden;\r\n    transition: transform .35s ease, box-shadow .35s ease, border-color .35s ease;\r\n  }\r\n  .unl-rank-card:hover{\r\n    transform: translateY(-4px);\r\n    box-shadow: 0 14px 28px -14px rgba(18,71,44,.25);\r\n    border-color: var(--unl-verde-400);\r\n  }\r\n  .unl-rank-card::before{\r\n    content:"";\r\n    position:absolute; inset:0 0 auto 0; height:4px;\r\n    background: linear-gradient(90deg, var(--unl-verde-600), var(--unl-agua-600));\r\n    transform-origin:left; transform:scaleX(0);\r\n    transition: transform .6s ease;\r\n  }\r\n  .unl-rank-card.unl-inview::before{ transform:scaleX(1); }\r\n\r\n  .unl-rank-icon{\r\n    width:44px;height:44px;border-radius:10px;\r\n    background: var(--unl-verde-100);\r\n    display:flex;align-items:center;justify-content:center;\r\n    margin-bottom:16px; color: var(--unl-verde-700);\r\n  }\r\n  .unl-rank-icon svg{ width:24px;height:24px; }\r\n\r\n  .unl-rank-label{\r\n    font-size:13px; color: var(--unl-texto-suave); font-weight:600;\r\n    text-transform:uppercase; letter-spacing:.03em; margin-bottom:5px;\r\n  }\r\n  .unl-rank-number{\r\n    font-size:32px; font-weight:800; color: var(--unl-verde-800);\r\n    line-height:1; display:flex; align-items:baseline; gap:5px;\r\n  }\r\n  .unl-rank-number .unl-rank-suffix{ font-size:17px; font-weight:700; color: var(--unl-verde-600); }\r\n  .unl-rank-desc{ font-size:14px; color: var(--unl-texto-suave); margin-top:9px; line-height:1.5; }\r\n  .unl-rank-tag{\r\n    display:inline-block; margin-top:14px; font-size:12px; font-weight:700;\r\n    color: var(--unl-tierra-600); background: var(--unl-tierra-200);\r\n    padding:3px 9px; border-radius:6px;\r\n  }\r\n\r\n  /* Ring de progreso circular (áreas evaluadas) */\r\n  .unl-ring-block{\r\n    margin-top:40px; padding-top:35px;\r\n    border-top:1px dashed var(--unl-borde);\r\n  }\r\n  .unl-ring-title{ font-size:16px; font-weight:700; margin:0 0 22px; color: var(--unl-verde-950); }\r\n  .unl-ring-grid{\r\n    display:grid; grid-template-columns: repeat(auto-fit, minmax(130px,1fr));\r\n    gap:20px; text-align:center;\r\n  }\r\n  .unl-ring-item{ display:flex; flex-direction:column; align-items:center; gap:10px; }\r\n  .unl-ring-svg{ width:88px; height:88px; }\r\n  .unl-ring-track{ fill:none; stroke: var(--unl-verde-100); stroke-width:8; }\r\n  .unl-ring-bar{\r\n    fill:none; stroke: var(--unl-verde-600); stroke-width:8; stroke-linecap:round;\r\n    stroke-dasharray: 251; stroke-dashoffset: 251;\r\n    transition: stroke-dashoffset 1.4s cubic-bezier(.2,.7,.2,1);\r\n  }\r\n  .unl-ring-pct{ font-size:15px; font-weight:800; fill: var(--unl-verde-800); }\r\n  .unl-ring-name{ font-size:12px; color: var(--unl-texto-suave); font-weight:600; line-height:1.3; }\r\n\r\n  /* ============ SECCIÓN 2: INICIATIVAS INTERNACIONALES ============ */\r\n  .unl-init-section{ position:relative; }\r\n\r\n  .unl-init-grid{\r\n    display:grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\r\n    gap:24px;\r\n  }\r\n  .unl-init-card{\r\n    background: linear-gradient(180deg, var(--unl-verde-950) 0%, var(--unl-verde-800) 100%);\r\n    border-radius: var(--unl-radio);\r\n    padding:28px;\r\n    color:#f2f8f4;\r\n    position:relative;\r\n    overflow:hidden;\r\n    min-height:260px;\r\n    display:flex; flex-direction:column;\r\n  }\r\n  .unl-init-card.unl-agua{\r\n    background: linear-gradient(180deg, #0c3b44 0%, #124f5c 100%);\r\n  }\r\n\r\n  /* --- Fondos decorativos temáticos --- */\r\n  .unl-init-motif{\r\n    position:absolute; right:-22px; top:-22px; width:190px; height:190px;\r\n    opacity:.16; pointer-events:none;\r\n  }\r\n  .unl-init-motif.unl-motif-atomo{ animation: unlSpin 22s linear infinite; }\r\n  .unl-init-card.unl-agua .unl-init-motif circle,\r\n  .unl-init-card.unl-agua .unl-init-motif ellipse{ stroke:#dff5f8; }\r\n  .unl-init-card:not(.unl-agua) .unl-init-motif path,\r\n  .unl-init-card:not(.unl-agua) .unl-init-motif circle{ stroke:#d9f0e2; fill:#d9f0e2; }\r\n\r\n  .unl-init-top{ display:flex; align-items:center; justify-content:space-between; margin-bottom:18px; position:relative; z-index:1; }\r\n  .unl-init-badge{\r\n    font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em;\r\n    background: rgba(255,255,255,.12); padding:5px 10px; border-radius:999px;\r\n  }\r\n  .unl-init-year{ font-size:12px; color:#cfe6d8; font-weight:600; }\r\n  .unl-init-name{ font-size:20px; font-weight:800; margin:0 0 9px; line-height:1.25; position:relative; z-index:1; }\r\n  .unl-init-desc{ font-size:15px; color:#d8ebe0; line-height:1.6; margin:0 0 19px; flex:1; position:relative; z-index:1; }\r\n\r\n  .unl-init-progress-row{ margin-top:auto; position:relative; z-index:1; }\r\n  .unl-init-progress-label{\r\n    display:flex; justify-content:space-between; font-size:12px;\r\n    color:#cfe6d8; margin-bottom:6px; font-weight:600;\r\n  }\r\n  .unl-init-bar-track{\r\n    width:100%; height:8px; border-radius:999px; background: rgba(255,255,255,.14);\r\n    overflow:hidden;\r\n  }\r\n  .unl-init-bar-fill{\r\n    height:100%; border-radius:999px;\r\n    background: linear-gradient(90deg, #7fd7a5, #b7e8c9);\r\n    width:0%; transition: width 1.6s cubic-bezier(.2,.7,.2,1);\r\n  }\r\n  .unl-agua .unl-init-bar-fill{ background: linear-gradient(90deg, #6cc9d6, #a9e4ec); }\r\n\r\n  @keyframes unlSpin{ from{ transform: rotate(0deg);} to{ transform: rotate(360deg);} }\r\n  @keyframes unlPulse{\r\n    0%,100%{ opacity:1; transform:scale(1); }\r\n    50%{ opacity:.4; transform:scale(1.3); }\r\n  }\r\n  .unl-fade-up{\r\n    opacity:0; transform: translateY(18px);\r\n    transition: opacity .7s ease, transform .7s ease;\r\n  }\r\n  .unl-fade-up.unl-inview{ opacity:1; transform:translateY(0); }\r\n\r\n  @media (prefers-reduced-motion: reduce){\r\n    #unl-rankings-iniciativas *{ animation:none !important; transition:none !important; }\r\n    .unl-fade-up{ opacity:1; transform:none; }\r\n  }\r\n\r\n  @media (max-width: 620px){\r\n    #unl-rankings-iniciativas{ padding: 40px 16px; }\r\n    .unl-rank-number{ font-size:26px; }\r\n  }\r\n</style><!-- ===================== SECCIÓN 1: RANKINGS ===================== --><div class="unl-rank-section"><p><span class="unl-sost-eyebrow">Reconocimientos</span></p><h2 class="unl-sost-h2">Rankings y reconocimientos en sostenibilidad</h2><p class="unl-sost-sub">Resultados obtenidos por la Universidad Nacional de Loja en los principales sistemas internacionales que evalúan investigación, impacto y sostenibilidad institucional.</p><div class="unl-rank-grid"><!-- Tarjeta 1: SCImago --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><path d="M3 8l9-5 9 5" stroke-linejoin="round"></path><rect height="9" width="2.4" x="4" y="9"></rect><rect height="9" width="2.4" x="9" y="9"></rect><rect height="9" width="2.4" x="14" y="9"></rect><rect height="9" width="1.6" x="19" y="9"></rect><rect height="2" width="18" x="3" y="19"></rect></svg></div><div class="unl-rank-label">SCImago Institutions Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="8">0</span></div><p class="unl-rank-desc">Entre universidades públicas del Ecuador por su impacto, la calidad y la visibilidad de la producción científica.</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 2: UI GreenMetric --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><circle cx="12" cy="12" r="8.5"></circle><path d="M4 10.5c2.5 1.2 5 1.2 8 .3s6-.3 8 1"></path><path d="M6 16c2 .8 4.2.8 6.5 0s4.8-.6 6.6.4"></path><path d="M12 3.5v17"></path></svg></div><div class="unl-rank-label">UI GreenMetric World University Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="004">0</span></div><p class="unl-rank-desc">Entre universidades públicas del Ecuador por acciones en infraestructura sostenible, energía, manejo de residuos, agua, transporte y educación ambiental.</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 3: THE World University Rankings --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><rect height="18" rx="5" width="18" x="3" y="3"></rect><path d="M8 8h3.2v8H8z" fill="currentColor" stroke="none"></path><path d="M13 8h1.4v8H13z" fill="currentColor" stroke="none"></path><path d="M15.6 8h1.4v8h-1.4z" fill="currentColor" stroke="none"></path></svg></div><div class="unl-rank-label">THE World University Rankings</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="0005">0</span><span class="unl-rank-suffix">[EDITAR]</span></div><p class="unl-rank-desc">Mejor universidad pública del Ecuador</p><p><span class="unl-rank-tag">Edición 2025</span></p></div><!-- Tarjeta 4: Webometrics --><div class="unl-rank-card unl-fade-up"><div class="unl-rank-icon" aria-hidden="true"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 24 24"><circle cx="6" cy="6" r="2"></circle><circle cx="18" cy="6" r="2"></circle><circle cx="12" cy="12" r="2.2"></circle><circle cx="6" cy="18" r="2"></circle><circle cx="18" cy="18" r="2"></circle><path d="M7.6 7.2l3 3.4M16.4 7.2l-3 3.4M7.6 16.8l3-3.4M16.4 16.8l-3-3.4"></path></svg></div><div class="unl-rank-label">Webometrics Ranking Web of Universities</div><div class="unl-rank-number"><span class="unl-rank-count" data-target="000">0</span><span class="unl-rank-suffix">[EDITAR]</span></div><p class="unl-rank-desc">Posición según presencia, apertura e impacto del sitio web institucional. [EDITAR con dato real]</p><p><span class="unl-rank-tag">Edición [EDITAR año]</span></p></div></div><p><!-- Áreas evaluadas: anillos de progreso -->&nbsp;</p><div class="unl-ring-block unl-fade-up"><h3 class="unl-ring-title">Desempeño por área evaluada [EDITAR con puntajes reales]</h3><div class="unl-ring-grid"><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="72" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">72%</text> </svg><span class="unl-ring-name">Entorno e</span><br><span class="unl-ring-name">infraestructura</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="58" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">58%</text> </svg><span class="unl-ring-name">Energía y</span><br><span class="unl-ring-name">cambio climático</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="65" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">65%</text> </svg><span class="unl-ring-name">Gestión de</span><br><span class="unl-ring-name">residuos</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="80" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">80%</text> </svg><span class="unl-ring-name">Uso eficiente</span><br><span class="unl-ring-name">del agua</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="61" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">61%</text> </svg><span class="unl-ring-name">Transporte</span><br><span class="unl-ring-name">sostenible</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="88" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">88%</text> </svg><span class="unl-ring-name">Educación e</span><br><span class="unl-ring-name">investigación</span></div></div></div></div><!-- ===================== SECCIÓN 2: INICIATIVAS INTERNACIONALES ===================== --><div class="unl-init-section"><p><span class="unl-sost-eyebrow">Cooperación internacional</span></p><h2 class="unl-sost-h2">Iniciativas y concursos internacionales</h2><p class="unl-sost-sub">La UNL participa actualmente en las siguientes iniciativas internacionales orientadas a fortalecer su modelo de sostenibilidad institucional. [EDITAR: reemplazar nombres, descripciones y avance real]</p><div class="unl-init-grid"><!-- Iniciativa 1: motivo de planta / ramificación --><div class="unl-init-card unl-fade-up"><svg class="unl-init-motif unl-motif-planta" aria-hidden="true" viewbox="0 0 100 100"><path d="M50 95V50" fill="none" stroke-width="2"></path><path d="M50 70C38 66 30 56 30 44" fill="none" stroke-width="2"></path><path d="M50 60C62 56 70 46 70 34" fill="none" stroke-width="2"></path><path d="M50 50C41 45 36 36 37 26" fill="none" stroke-width="2"></path><circle cx="30" cy="44" r="4"></circle><circle cx="70" cy="34" r="4"></circle><circle cx="37" cy="26" r="4"></circle><circle cx="50" cy="18" r="5"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 1</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 1]</h3><p class="unl-init-desc">[EDITAR: descripción breve — qué es la iniciativa, quién la convoca y qué compromiso concreto asumió la UNL al participar].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="45">&nbsp;</div></div></div></div><!-- Iniciativa 2: motivo de átomo / órbitas --><div class="unl-init-card unl-agua unl-fade-up"><svg class="unl-init-motif unl-motif-atomo" aria-hidden="true" fill="none" stroke-width="1.6" viewbox="0 0 100 100"><ellipse cx="50" cy="50" rx="42" ry="16"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(60 50 50)"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(120 50 50)"></ellipse><circle cx="50" cy="50" fill="currentColor" r="6" stroke="none"></circle><circle cx="92" cy="50" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="78" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="22" fill="currentColor" r="3" stroke="none"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 2</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 2]</h3><p class="unl-init-desc">[EDITAR: descripción breve — objetivo del concurso o red, alcance geográfico y en qué consiste la participación de la UNL].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="62">&nbsp;</div></div></div></div></div></div></section><script>\r\n(function(){\r\n  var root = document.getElementById('unl-rankings-iniciativas');\r\n  if(!root) return;\r\n  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\r\n\r\n  function animateCount(el){\r\n    var target = parseInt(el.getAttribute('data-target'), 10) || 0;\r\n    if(reduce){ el.textContent = target; return; }\r\n    var start = 0, dur = 1400, t0 = null;\r\n    function step(ts){\r\n      if(!t0) t0 = ts;\r\n      var p = Math.min((ts - t0) / dur, 1);\r\n      el.textContent = Math.round(start + (target - start) * p);\r\n      if(p < 1) requestAnimationFrame(step);\r\n    }\r\n    requestAnimationFrame(step);\r\n  }\r\n\r\n  function animateRing(circle){\r\n    var pct = parseFloat(circle.getAttribute('data-pct')) || 0;\r\n    var offset = 251 - (251 * pct / 100);\r\n    circle.style.strokeDashoffset = offset;\r\n  }\r\n\r\n  function animateBar(bar){\r\n    var pct = parseFloat(bar.getAttribute('data-pct')) || 0;\r\n    bar.style.width = pct + '%';\r\n    var label = bar.closest('.unl-init-progress-row').querySelector('.unl-init-pct');\r\n    if(label) label.textContent = pct + '%';\r\n  }\r\n\r\n  var io = new IntersectionObserver(function(entries){\r\n    entries.forEach(function(entry){\r\n      if(!entry.isIntersecting) return;\r\n      var el = entry.target;\r\n      el.classList.add('unl-inview');\r\n\r\n      el.querySelectorAll('.unl-rank-count').forEach(animateCount);\r\n      el.querySelectorAll('.unl-ring-bar').forEach(animateRing);\r\n      el.querySelectorAll('.unl-init-bar-fill').forEach(animateBar);\r\n\r\n      io.unobserve(el);\r\n    });\r\n  }, { threshold: .3 });\r\n\r\n  root.querySelectorAll('.unl-fade-up, .unl-rank-card').forEach(function(el){\r\n    io.observe(el);\r\n  });\r\n})();\r\n</script>	full_html
texto_libre	0	110	1339	en	0	<style type="text/css">/* =========================================\r\nPALETA OFICIAL UNL\r\n========================================= */\r\n/* =========================================\r\nRESET\r\n========================================= */\r\n*{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\nhtml{\r\n    scroll-behavior:smooth;\r\n}\r\nbody{\r\n    font-family:'Montserrat', sans-serif;\r\n    background:var(--bg);\r\n    color:var(--text);\r\n    overflow-x:hidden;\r\n}\r\n/* =========================================\r\nOCULTAR NAVBAR INTERNO\r\nPARA NO AFECTAR EL HEADER DEL SITIO\r\n========================================= */\r\nbody > .navbar{\r\n    display:none !important;\r\n}\r\n/* =========================================\r\nHERO\r\n========================================= */\r\n.hero{\r\n    position:relative;\r\n    min-height:52vh;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    overflow:hidden;\r\n    padding-top:140px;\r\n    padding-bottom:70px;\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E 0%,\r\n    #002B6B 45%,\r\n    #003B8E 100%\r\n    );\r\n}\r\n.hero::before{\r\n    content:"";\r\n    position:absolute;\r\n    width:480px;\r\n    height:480px;\r\n    border-radius:50%;\r\n    background:rgba(255,255,255,0.05);\r\n    top:-220px;\r\n    right:-120px;\r\n}\r\n.hero::after{\r\n    content:"";\r\n    position:absolute;\r\n    width:350px;\r\n    height:350px;\r\n    border-radius:50%;\r\n    background:rgba(255,255,255,0.04);\r\n    bottom:-180px;\r\n    left:-100px;\r\n}\r\n.hero-content{\r\n    position:relative;\r\n    z-index:10;\r\n    width:90%;\r\n    max-width:1000px;\r\n    text-align:center;\r\n    color:white;\r\n}\r\n.badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:10px 18px;\r\n    background:rgba(255,255,255,0.10);\r\n    border:1px solid rgba(255,255,255,0.12);\r\n    border-radius:100px;\r\n    backdrop-filter:blur(12px);\r\n    margin-bottom:22px;\r\n    animation:fadeUp 1s ease;\r\n}\r\n.badge span{\r\n    font-size:.85rem;\r\n    font-weight:600;\r\n    letter-spacing:.3px;\r\n}\r\n.hero h2{\r\n    font-size:5.2rem;\r\n.hero .hero-content h2{\r\n    font-family:'Montserrat', sans-serif !important;\r\n    font-size:clamp(3rem, 5vw, 4.5rem) !important;\r\n    font-weight:800 !important;\r\n    line-height:1.1 !important;\r\n    margin-bottom:20px;\r\n    color:#ffffff !important;\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n.hero .hero-content p{\r\n    font-family:'Montserrat', sans-serif !important;\r\n    max-width:760px;\r\n    margin:auto;\r\n    font-size:3.08rem !important;\r\n    line-height:1.9 !important;\r\n    font-weight:400 !important;\r\n    color:rgba(255,255,255,0.92) !important;\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n.hero .badge span{\r\n    font-size:.9rem !important;\r\n    font-weight:600 !important;\r\n    color:white !important;\r\n}\r\n    font-weight:800;\r\n    line-height:1.1;\r\n    margin-bottom:20px;\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n.hero p{\r\n    max-width:760px;\r\n    margin:auto;\r\n    font-size:1.02rem;\r\n    line-height:1.9;\r\n    opacity:.92;\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n/* =========================================\r\nSECCIONES\r\n========================================= */\r\n.section{\r\n    padding:110px 0;\r\n}\r\n.container{\r\n    width:90%;\r\n    max-width:1400px;\r\n    margin:auto;\r\n}\r\n.section-title{\r\n    text-align:center;\r\n    margin-bottom:70px;\r\n}\r\n.section-title h3{\r\n    font-size:2.7rem;\r\n    color:var(--primary);\r\n    margin-bottom:18px;\r\n}\r\n.section-title p{\r\n    max-width:760px;\r\n    margin:auto;\r\n    color:var(--gray);\r\n    line-height:1.8;\r\n}\r\n/* =========================================\r\nCARDS\r\n========================================= */\r\n.cards-grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(auto-fit,minmax(340px,1fr));\r\n    gap:34px;\r\n}\r\n.card{\r\n    position:relative;\r\n    background:var(--white);\r\n    border-radius:var(--radius);\r\n    overflow:hidden;\r\n    box-shadow:var(--shadow);\r\n    transition:.4s ease;\r\n    border:1px solid rgba(0,0,0,0.03);\r\n}\r\n.card:hover{\r\n    transform:translateY(-12px);\r\n}\r\n.card-top{\r\n    position:relative;\r\n    height:220px;\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E,\r\n    #003B8E,\r\n    #0A56A8\r\n    );\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    overflow:hidden;\r\n}\r\n.card-top::before{\r\n    content:"";\r\n    position:absolute;\r\n    width:300px;\r\n    height:300px;\r\n    background:rgba(255,255,255,0.08);\r\n    border-radius:50%;\r\n    top:-100px;\r\n    right:-60px;\r\n}\r\n.card-year{\r\n    position:relative;\r\n    z-index:2;\r\n    font-size:5rem;\r\n    font-weight:800;\r\n    color:white;\r\n    letter-spacing:4px;\r\n}\r\n.card-content{\r\n    padding:34px;\r\n}\r\n.card-content h4{\r\n    font-size:1.4rem;\r\n    color:var(--primary);\r\n    margin-bottom:16px;\r\n}\r\n.card-content p{\r\n    color:var(--gray);\r\n    line-height:1.7;\r\n    margin-bottom:26px;\r\n}\r\n.card-actions{\r\n    display:flex;\r\n    gap:14px;\r\n    flex-wrap:wrap;\r\n}\r\n.btn{\r\n    flex:1;\r\n    min-width:130px;\r\n    padding:14px 18px;\r\n    border:none;\r\n    border-radius:14px;\r\n    cursor:pointer;\r\n    text-decoration:none;\r\n    font-weight:700;\r\n    transition:.3s ease;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    gap:10px;\r\n    font-family:'Montserrat', sans-serif;\r\n}\r\n.btn-primary{\r\n    background:var(--primary);\r\n    color:white;\r\n}\r\n.btn-primary:hover{\r\n    background:var(--primary-light);\r\n}\r\n.btn-secondary{\r\n    background:#eef4fb;\r\n    color:var(--primary);\r\n}\r\n.btn-secondary:hover{\r\n    background:#dfeeff;\r\n}\r\n/* =========================================\r\nMODAL PDF\r\n========================================= */\r\n.modal{\r\n    position:fixed;\r\n    inset:0;\r\n    background:rgba(0,0,0,0.78);\r\n    z-index:9999;\r\n    display:none;\r\n    align-items:center;\r\n    justify-content:center;\r\n    padding:30px;\r\n}\r\n.modal.active{\r\n    display:flex;\r\n}\r\n.modal-content{\r\n    width:100%;\r\n    max-width:1200px;\r\n    height:90vh;\r\n    background:white;\r\n    border-radius:22px;\r\n    overflow:hidden;\r\n    position:relative;\r\n    animation:zoom .35s ease;\r\n}\r\n.close-modal{\r\n    position:absolute;\r\n    top:16px;\r\n    right:16px;\r\n    width:46px;\r\n    height:46px;\r\n    border-radius:50%;\r\n    background:rgba(0,0,0,0.1);\r\n    border:none;\r\n    cursor:pointer;\r\n    font-size:1.2rem;\r\n    z-index:10;\r\n    transition:.3s;\r\n}\r\n.close-modal:hover{\r\n    background:rgba(0,0,0,0.2);\r\n}\r\n.modal iframe{\r\n    width:100%;\r\n    height:100%;\r\n    border:none;\r\n}\r\n/* =========================================\r\nFOOTER\r\n========================================= */\r\n.footer{\r\n    background:var(--primary);\r\n    padding:50px 0;\r\n    color:white;\r\n    text-align:center;\r\n}\r\n.footer p{\r\n    opacity:.85;\r\n    line-height:1.8;\r\n}\r\n/* =========================================\r\nANIMACIONES\r\n========================================= */\r\n@keyframes fadeUp{\r\n    from{\r\n        opacity:0;\r\n        transform:translateY(40px);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:translateY(0);\r\n    }\r\n}\r\n@keyframes zoom{\r\n    from{\r\n        opacity:0;\r\n        transform:scale(.9);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:scale(1);\r\n    }\r\n}\r\n/* =========================================\r\nRESPONSIVE\r\n========================================= */\r\n@media(max-width:992px){\r\n    .hero h2{\r\n        font-size:2.6rem;\r\n    }\r\n}\r\n@media(max-width:768px){\r\n    .hero{\r\n        padding-top:120px;\r\n    }\r\n    .hero h2{\r\n        font-size:2.1rem;\r\n    }\r\n    .section-title h3{\r\n        font-size:2rem;\r\n    }\r\n    .card-year{\r\n        font-size:4rem;\r\n    }\r\n}\r\n@media(max-width:480px){\r\n    .hero h2{\r\n        font-size:1.8rem;\r\n    }\r\n    .hero p{\r\n        font-size:.95rem;\r\n    }\r\n    .card-content{\r\n        padding:24px;\r\n    }\r\n}\r\n</style><!-- =========================================\r\nHERO\r\n========================================= --><section class="hero"><div class="hero-content"><h4 class="badge"><span>Repositorio Institucional</span></h4><h2>Planes Operativos Anuales</h2><h5>Accede a los documentos oficiales correspondientes a los Planes Operativos Anuales de la Universidad Nacional de Loja.</h5><h5>&nbsp;</h5></div></section><!-- =========================================\r\nPLANES\r\n========================================= --><section class="section" id="planes"><div class="container"><div class="section-title"><h3>Documentos Institucionales</h3><p>Explora los planes operativos anuales disponibles. Cada documento puede visualizarse directamente desde el micrositio o descargarse en formato PDF.</p></div><div class="cards-grid"><!-- 2024 --><div class="card"><div class="card-top"><div class="card-year">2024</div></div><div class="card-content"><h4>POA 2024</h4><p>&nbsp;Plan Operativo Anual 2024</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2024_mas_resolucio%CC%81n0207210001777305442.pdf" download="" title="POA 2024">Descargar</a></div></div></div><!-- 2025 --><div class="card"><div class="card-top"><div class="card-year">2025</div></div><div class="card-content"><h4>POA 2025</h4><p>&nbsp;Plan Operativo Anual 2025.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf" download="" title="POA 2025">Descargar</a></div></div></div><!-- 2026 --><div class="card"><div class="card-top"><div class="card-year">2026</div></div><div class="card-content"><h4>POA 2026</h4><p>&nbsp;Plan Operativo Anual&nbsp;2026.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf" download="" title="POA 2026">Descargar</a></div></div></div></div></div></section><!-- =========================================\r\nMODAL PDF\r\n========================================= --><div class="modal" id="pdfModal"><div class="modal-content"><button class="close-modal" id="closeModal">✕</button><iframe id="pdfViewer"></iframe></div></div><!-- =========================================\r\nFOOTER\r\n========================================= --><footer class="footer"><div class="container"><p>© 2026 Universidad Nacional de Loja<br>Micrositio institucional de planificación operativa.</p></div></footer><!-- =========================================\r\nJS\r\n========================================= --><script>\r\nconst modal = document.getElementById("pdfModal");\r\nconst pdfViewer = document.getElementById("pdfViewer");\r\nconst closeModal = document.getElementById("closeModal");\r\ndocument.querySelectorAll(".openPdf").forEach(button => {\r\n    button.addEventListener("click", () => {\r\n        const pdf = button.getAttribute("data-pdf");\r\n        pdfViewer.src = pdf;\r\n        modal.classList.add("active");\r\n        document.body.style.overflow = "hidden";\r\n    });\r\n});\r\nfunction closePdf(){\r\n    modal.classList.remove("active");\r\n    pdfViewer.src = "";\r\n    document.body.style.overflow = "auto";\r\n}\r\ncloseModal.addEventListener("click", closePdf);\r\nmodal.addEventListener("click", (e) => {\r\n    if(e.target === modal){\r\n        closePdf();\r\n    }\r\n});\r\ndocument.addEventListener("keydown", (e)=>{\r\n    if(e.key === "Escape"){\r\n        closePdf();\r\n    }\r\n});\r\n</script>	full_html
texto_libre	0	113	1341	en	0	<table class="table"><tbody><tr><td><h3><a href="https://lookerstudio.google.com/u/0/reporting/2c880b6f-a4e8-4ded-bcd6-d4769bdd5dbd/page/UbxCD"><strong>COOPERACIÓN INTERNACIONAL EN CIFRAS</strong>&nbsp;</a></h3><p>&nbsp;</p></td><td>&nbsp;</td></tr></tbody></table><p>REVISA LAS CIFRAS DE IMPACTO DE NUESTRA ACCIÓN.</p><table class="table"><tbody><tr><td><h3><strong>INFORMACIÓN &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</strong></h3><p>&nbsp;</p><p><strong>&nbsp;Dirección:</strong><br>&nbsp;Bloque 108, Universidad Nacional de Loja.</p><p><strong>Horario de atención:</strong><br>08h00 a 13h00 | 15h00 a 18h00</p><p><strong>Teléfono:</strong><br>(07) 999999</p><p><strong>Mail:</strong><br>cooperacion@unl.edu.ec</p><p><img src="/sites/default/files/inline-images/Captura%20de%20pantalla%202023-03-30%20a%20la%28s%29%2012.19.18_0.png" data-align="left" data-entity-uuid="37b447b3-bd44-4e21-8147-72cc20a3bf2d" data-entity-type="file" alt="Facebook" width="23" height="22"><a href="https://www.facebook.com/BecaseIntercambiosUNL"><strong>Cooperación Internacional UNL</strong></a>&nbsp;</p><p>&nbsp;</p><p><img src="/sites/default/files/inline-images/Captura%20de%20pantalla%202023-07-06%20a%20la%28s%29%2010.01.06.png" data-align="left" data-entity-uuid="5401d6c1-9dc7-49e7-bab6-58457de5fd2f" data-entity-type="file" alt="IG" width="22" height="21"><a href="https://www.instagram.com/cooperacion_internacional_unl/"><strong>Cooperación Internacional UNL</strong></a></p></td><td>&nbsp;</td></tr></tbody></table><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title></title><p>&nbsp;</p><h1>Intercambios estudiantiles</h1><p><iframe allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" height="315" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/3Bby8KfIXL0?si=tK0C78GMu-iARG08" title="YouTube video player" width="560"></iframe></p><p>&nbsp;</p><p>&nbsp;</p><p><a href="https://unl.edu.ec/sites/default/files/2022-05/Intercambio_UNL.pdf"><span><strong>CONOCE LA FICHA INFORMATIVA&nbsp;</strong></span></a></p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>	full_html
texto_libre	0	124	1817	es	0	<style type="text/css">/* =========================================\r\n       1. ESTILOS BASE Y CONTENEDOR PRINCIPAL\r\n       ========================================= */\r\n\r\n    .di-bloque {\r\n      font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\r\n      line-height: 1.6;\r\n      margin: 0 auto;\r\n      max-width: 1200px;\r\n      width: 100%;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 10px 30px rgba(8, 31, 73, 0.08);\r\n      background-color: #ffffff;\r\n    }\r\n\r\n    /* =========================================\r\n       2. CABECERA (HERO)\r\n       ========================================= */\r\n    .di-bloque__hero {\r\n      background-color: #0c2342;\r\n      color: #ffffff;\r\n      padding: 64px 32px;\r\n      text-align: center;\r\n      border-bottom: 5px solid #BF0811;\r\n    }\r\n\r\n    .di-bloque__titulo {\r\n      font-size: 40px;\r\n      font-weight: 800;\r\n      margin: 0 0 16px 0;\r\n      color: #ffffff;\r\n      letter-spacing: -0.5px;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .di-bloque__descripcion {\r\n      max-width: 800px;\r\n      margin: 0 auto;\r\n      font-size: 18px;\r\n      color: rgba(255, 255, 255, 0.85);\r\n      font-weight: 300;\r\n    }\r\n\r\n    /* =========================================\r\n       3. SEPARADORES DE SECCIÓN\r\n       ========================================= */\r\n    .di-divisor {\r\n      display: flex;\r\n      align-items: center;\r\n      color: #081f49;\r\n      font-size: 14px;\r\n      font-weight: 700;\r\n      text-transform: uppercase;\r\n      letter-spacing: 2px;\r\n      margin: 48px 32px 16px 32px;\r\n    }\r\n\r\n    .di-divisor::before,\r\n    .di-divisor::after {\r\n      content: "";\r\n      flex: 1;\r\n      border-bottom: 1px solid rgba(8, 31, 73, 0.15);\r\n    }\r\n\r\n    .di-divisor::before { margin-right: 24px; }\r\n    .di-divisor::after { margin-left: 24px; }\r\n\r\n    /* =========================================\r\n       4. ESTRUCTURA DE ESTADÍSTICAS (MÓVIL PRIMERO)\r\n       ========================================= */\r\n    .di-bloque__stats {\r\n      padding: 32px 32px 48px 32px;\r\n      display: grid;\r\n      grid-template-columns: 1fr; /* 1 columna por defecto en móviles */\r\n      gap: 40px;\r\n    }\r\n\r\n    .di-stat {\r\n      text-align: center;\r\n      position: relative;\r\n      padding: 0 16px;\r\n    }\r\n\r\n    .di-stat__numero {\r\n      display: block;\r\n      font-size: 56px;\r\n      font-weight: 800;\r\n      color: #081f49;\r\n      line-height: 1;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .di-stat__etiqueta {\r\n      display: block;\r\n      font-size: 14px;\r\n      font-weight: 700;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n      color: #666666;\r\n    }\r\n\r\n    /* =========================================\r\n       5. ADAPTACIÓN A PANTALLAS GRANDES (DESKTOP)\r\n       ========================================= */\r\n    @media (min-width: 768px) {\r\n      /* Pasa a 4 columnas */\r\n      .di-bloque__stats--4cols {\r\n        grid-template-columns: repeat(4, 1fr);\r\n      }\r\n\r\n      /* Agrega los divisores verticales solo en desktop y no al último elemento */\r\n      .di-stat:not(:last-child)::after {\r\n        content: "";\r\n        position: absolute;\r\n        right: -20px;\r\n        top: 15%;\r\n        height: 70%;\r\n        width: 1px;\r\n        background-color: #081f49;\r\n        opacity: 0.15;\r\n      }\r\n    }\r\n</style><div class="di-bloque"><!-- Cabecera de Presentación --><div class="di-bloque__hero"><h2 class="di-bloque__titulo">Investigación UNL</h2><p class="di-bloque__descripcion">Impulsamos la producción científica, planificando y apoyando la generación de conocimiento científico y la innovación tecnológica.</p></div><!-- SECCIÓN 1: Estructura --><div class="di-divisor">Estructura de Investigación</div><!-- Nota: Cambié los rem del style en línea a px (24px y 64px) --><div class="di-bloque__stats di-bloque__stats--4cols" style="padding-bottom:64px;padding-top:24px;"><div class="di-stat"><span class="di-stat__numero">11</span> <a class="di-stat__etiqueta" href="https://unl.edu.ec/investigacion/lineas-investigacion" rel="noopener noreferrer" target="_blank">Líneas de Investigación</a></div><div class="di-stat"><span class="di-stat__numero">9</span> <a class="di-stat__etiqueta" href="https://unl.edu.ec/investigacion/centros-laboratorios-de-investigacion" rel="noopener noreferrer" target="_blank">Centros de Investigación</a></div><div class="di-stat"><span class="di-stat__numero">23</span> <a class="di-stat__etiqueta" href="https://unl.edu.ec/investigacion/grupos-investigacion" rel="noopener noreferrer" target="_blank">Grupos de Investigación</a></div><div class="di-stat"><span class="di-stat__numero">2.677+</span> <span class="di-stat__etiqueta">Artículos en revistas académicas</span></div></div><!-- SECCIÓN 2: PERIODO ACTUAL --><div class="di-divisor">Proyectos de Investigación 2025 - 2026</div><div class="di-bloque__stats di-bloque__stats--4cols"><div class="di-stat"><span class="di-stat__numero">58</span> <span class="di-stat__etiqueta">Proyectos de convocatoria</span></div><div class="di-stat"><span class="di-stat__numero">13</span> <span class="di-stat__etiqueta">Proyectos cofinanciados</span></div><div class="di-stat"><span class="di-stat__numero">8</span> <span class="di-stat__etiqueta">Proyectos de interés institucional</span></div><div class="di-stat"><span class="di-stat__numero">12</span> <span class="di-stat__etiqueta">Proyectos de investigación doctoral</span></div></div></div>	full_html
texto_libre	0	160	2110	es	0	<style type="text/css">/* =====================================================\r\nRESET\r\n===================================================== */\r\n*{\r\n  margin:0;\r\n  padding:0;\r\n  box-sizing:border-box;\r\n}\r\nhtml{\r\n  scroll-behavior:smooth;\r\n}\r\nbody{\r\n  font-family:\r\n    "Montserrat",\r\n    -apple-system,\r\n    BlinkMacSystemFont,\r\n    "Segoe UI",\r\n    sans-serif;\r\n  background:#ffffff;\r\n  color:#3a3a3a;\r\n  overflow-x:hidden;\r\n}\r\n/* =====================================================\r\nVARIABLES\r\n===================================================== */\r\n:root{\r\n  --primary:#93000b;\r\n  --secondary:#6e0008;\r\n  --text:#3a3a3a;\r\n  --text-soft:#6b6b6b;\r\n  --white:#ffffff;\r\n  --light-hover:#fbecec;\r\n  --border:rgba(147,0,11,.12);\r\n  --shadow:\r\n    0 10px 40px rgba(147,0,11,.08);\r\n  --radius:30px;\r\n}\r\n/* =====================================================\r\nGLOBAL\r\n===================================================== */\r\na{\r\n  text-decoration:none;\r\n  color:inherit;\r\n}\r\n.container{\r\n  width:min(1400px,92%);\r\n  margin:auto;\r\n}\r\n/* =====================================================\r\nHERO\r\n===================================================== */\r\n.hero{\r\n  position:relative;\r\n  min-height:100vh;\r\n  display:flex;\r\n  align-items:center;\r\n  overflow:hidden;\r\n  padding:120px 0 80px;\r\n}\r\n/* =====================================================\r\nIMAGE BACKGROUND\r\n===================================================== */\r\n.hero-bg{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:1;\r\n}\r\n.hero-bg img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:cover;\r\n}\r\n/* =====================================================\r\nWHITE OVERLAY\r\n===================================================== */\r\n.hero-overlay{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:2;\r\n  background:\r\n    linear-gradient(\r\n      90deg,\r\n      rgba(255,255,255,.96) 0%,\r\n      rgba(255,255,255,.92) 28%,\r\n      rgba(255,255,255,.70) 48%,\r\n      rgba(255,255,255,.20) 70%,\r\n      rgba(255,255,255,.05) 100%\r\n    );\r\n}\r\n/* =====================================================\r\nDECORATION\r\n===================================================== */\r\n.hero-decoration{\r\n  position:absolute;\r\n  left:-200px;\r\n  bottom:-220px;\r\n  width:600px;\r\n  height:600px;\r\n  border-radius:50%;\r\n  background:\r\n    radial-gradient(\r\n      circle,\r\n      rgba(147,0,11,.06),\r\n      transparent 70%\r\n    );\r\n  z-index:2;\r\n}\r\n/* =====================================================\r\nCONTENT\r\n===================================================== */\r\n.hero-content{\r\n  position:relative;\r\n  z-index:5;\r\n  max-width:700px;\r\n  animation:fadeUp 1s ease;\r\n}\r\n.hero-content h1{\r\n  font-size:clamp(4rem,7vw,7rem);\r\n  line-height:.95;\r\n  font-weight:900;\r\n  letter-spacing:-1px;\r\n  margin-bottom:35px;\r\n  color:#93000b;\r\n  text-shadow:\r\n    0 10px 40px rgba(255,255,255,.95);\r\n}\r\n.hero-content p{\r\n  max-width:620px;\r\n  font-size:1.7rem;\r\n  line-height:2;\r\n  color:#3a3a3a;\r\n  margin-bottom:45px;\r\n  font-weight:450;\r\n  text-shadow:\r\n    0 5px 30px rgba(255,255,255,.95);\r\n}\r\n/* =====================================================\r\nBUTTONS\r\n===================================================== */\r\n.hero-buttons{\r\n  display:flex;\r\n  gap:20px;\r\n  flex-wrap:wrap;\r\n}\r\n.btn{\r\n  padding:18px 34px;\r\n  border-radius:18px;\r\n  font-weight:700;\r\n  transition:.4s ease;\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:12px;\r\n  font-size:1rem;\r\n}\r\n.btn-primary{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n  box-shadow:\r\n    0 15px 35px rgba(147,0,11,.25);\r\n}\r\n.btn-primary:hover{\r\n  transform:translateY(-4px);\r\n}\r\n.btn-secondary{\r\n  background:\r\n    #fbecec;\r\n  border:\r\n    1px solid rgba(147,0,11,.15);\r\n  color:#93000b;\r\n  backdrop-filter:blur(10px);\r\n  box-shadow:\r\n    0 10px 25px rgba(0,0,0,.05);\r\n}\r\n.btn-secondary:hover{\r\n  background:white;\r\n}\r\n/* =====================================================\r\nSECTION\r\n===================================================== */\r\n.section{\r\n  padding:120px 0;\r\n}\r\n.section-title{\r\n  text-align:center;\r\n  margin-bottom:70px;\r\n}\r\n.section-title span{\r\n  color:#93000b;\r\n  font-weight:800;\r\n  letter-spacing:1px;\r\n  text-transform:uppercase;\r\n  font-size:.82rem;\r\n}\r\n.section-title h2{\r\n  font-size:clamp(2.8rem,5vw,4rem);\r\n  margin-top:16px;\r\n  color:#3a3a3a;\r\n  font-weight:900;\r\n}\r\n.section-title p{\r\n  max-width:760px;\r\n  margin:auto;\r\n  margin-top:24px;\r\n  line-height:1.9;\r\n  color:#6b6b6b;\r\n  font-size:1.5rem;\r\n}\r\n/* =====================================================\r\nTIMELINE\r\n===================================================== */\r\n.timeline-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(280px,1fr));\r\n  gap:28px;\r\n}\r\n.timeline-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:30px;\r\n  padding:35px;\r\n  transition:.4s ease;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n}\r\n.timeline-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n  box-shadow:\r\n    0 20px 40px rgba(147,0,11,.12);\r\n}\r\n.timeline-card h3{\r\n  font-size:2rem;\r\n  color:#93000b;\r\n  margin-bottom:18px;\r\n  font-weight:900;\r\n}\r\n.timeline-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.card-btn{\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:10px;\r\n  color:#93000b;\r\n  font-weight:700;\r\n}\r\n/* =====================================================\r\nDOCUMENTS\r\n===================================================== */\r\n.docs-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(320px,1fr));\r\n  gap:28px;\r\n}\r\n.doc-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:28px;\r\n  padding:35px;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n  transition:.4s ease;\r\n}\r\n.doc-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n}\r\n.doc-icon{\r\n  width:85px;\r\n  height:85px;\r\n  border-radius:24px;\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      rgba(147,0,11,.10),\r\n      rgba(147,0,11,.18)\r\n    );\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  margin-bottom:24px;\r\n  font-size:1.2rem;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.doc-card h4{\r\n  font-size:1.4rem;\r\n  margin-bottom:14px;\r\n  color:#3a3a3a;\r\n}\r\n.doc-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.doc-actions{\r\n  display:flex;\r\n  gap:14px;\r\n}\r\n.doc-btn{\r\n  flex:1;\r\n  text-align:center;\r\n  padding:14px;\r\n  border-radius:14px;\r\n  font-weight:700;\r\n  transition:.3s ease;\r\n}\r\n.view-btn{\r\n  background:#fbecec;\r\n  color:#93000b;\r\n}\r\n.download-btn{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n}\r\n.doc-btn:hover{\r\n  transform:translateY(-2px);\r\n}\r\n/* =====================================================\r\nFOOTER\r\n===================================================== */\r\nfooter{\r\n  padding:80px 0;\r\n  border-top:\r\n    1px solid rgba(147,0,11,.12);\r\n  margin-top:100px;\r\n}\r\n.footer-content{\r\n  display:flex;\r\n  justify-content:space-between;\r\n  gap:60px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-brand h3{\r\n  font-size:2rem;\r\n  margin-bottom:20px;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.footer-brand p{\r\n  max-width:500px;\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n}\r\n.footer-links{\r\n  display:flex;\r\n  gap:80px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-links h4{\r\n  margin-bottom:18px;\r\n  color:#3a3a3a;\r\n}\r\n.footer-links a{\r\n  display:block;\r\n  margin-bottom:14px;\r\n  color:#6b6b6b;\r\n  transition:.3s ease;\r\n}\r\n.footer-links a:hover{\r\n  color:#93000b;\r\n}\r\n/* =====================================================\r\nANIMATIONS\r\n===================================================== */\r\n@keyframes fadeUp{\r\n  from{\r\n    opacity:0;\r\n    transform:translateY(50px);\r\n  }\r\n  to{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n}\r\n/* =====================================================\r\nRESPONSIVE\r\n===================================================== */\r\n@media(max-width:980px){\r\n  .hero{\r\n    min-height:auto;\r\n    padding:120px 0 100px;\r\n  }\r\n  .hero-content h1{\r\n    font-size:4rem;\r\n  }\r\n  .hero-overlay{\r\n    background:\r\n      linear-gradient(\r\n        180deg,\r\n        rgba(255,255,255,.95),\r\n        rgba(255,255,255,.80)\r\n      );\r\n  }\r\n}\r\n@media(max-width:680px){\r\n  .hero-content h1{\r\n    font-size:3rem;\r\n    letter-spacing:-2px;\r\n  }\r\n  .hero-content p{\r\n    font-size:1rem;\r\n  }\r\n  .hero-buttons{\r\n    flex-direction:column;\r\n  }\r\n  .btn{\r\n    width:100%;\r\n    justify-content:center;\r\n  }\r\n}\r\n</style><!-- =====================================================\r\nHERO\r\n===================================================== --><section class="hero"><!-- IMAGE --><div class="hero-bg"><!-- CAMBIA ESTA IMAGEN --><img src="https://unl.edu.ec/sites/default/files/2026-05/RENDICION7%20-%20MESAS%20DE%20TRABAJO.jpg" alt="" width="3196" height="1788"></div><!-- OVERLAY --><div class="hero-overlay">&nbsp;</div><!-- DECORATION --><div class="hero-decoration">&nbsp;</div><!-- CONTENT --><div class="container"><div class="hero-content"><h1>Transparencia y Rendición de Cuentas</h1><p>Acceda de forma clara, organizada y pública a los procesos de rendición de cuentas de la Universidad Nacional de Loja.</p><div class="hero-buttons"><a class="btn btn-primary" href="#procesos">Explorar procesos → </a><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-03/INFORME%20RENDICION%20CUENTAS%20UNL%202025_VP.pdf" title="Rendición de cuentas 2025">Informe 2025&nbsp;</a></div></div></div></section><!-- =====================================================\r\nTIMELINE\r\n===================================================== --><section class="section" id="procesos"><div class="container"><div class="section-title"><p><span>Histórico institucional&nbsp;</span></p><h2>Procesos de Rendición</h2><p>Consulte los procesos institucionales organizados por año y acceda rápidamente a la documentación pública.<br>&nbsp;</p></div><div class="timeline-grid"><div class="timeline-card"><h3>2025</h3><p>Rendición de cuentas 2025</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2025" title="Rendición de cuentas 2025">Ver más →</a></p></div><div class="timeline-card"><h3>2024</h3><p>Rendición de cuentas 2024</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2024" title="Rendición de cuentas 2024">Ver más →</a></p></div><div class="timeline-card"><h3>2023</h3><p>Rendición de cuentas 2023</p><p><a class="card-btn" href="http://172.190.19.169/rendicion_cuentas/2023" title="Rendición de cuentas 2023">Ver más →</a></p></div><div class="timeline-card"><h3>2022</h3><p>Rendición de cuentas 2022</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2022" title="Rendición de cuentas 202 ">Ver más →</a></p></div><div class="timeline-card"><h3>2021</h3><p>Rendición de cuentas 2021</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2021" title="Rendición de cuentas 2021">Ver más →</a></p></div><div class="timeline-card"><h3>2020</h3><p>Rendición de cuentas 2020</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2020" title="Rendición de cuentas 2020">Ver más →</a></p></div></div></div></section><section class="section"><div class="container"><div class="section-title"><p><span>Documentación pública&nbsp;</span></p><h2>Documentos Destacados</h2></div><div class="docs-grid"><div class="doc-card"><div class="doc-icon">PDF</div><h4>Informe UNL 2025</h4><p>Informe institucional</p><p><a class="doc-btn download-btn" href="https://unl.edu.ec/sites/default/files/2026-03/INFORME%20RENDICION%20CUENTAS%20UNL%202025_VP.pdf">Ver</a></p></div><div class="doc-card"><div class="doc-icon">DOC</div><h4>Formulario CPCCS UNL 2025</h4><p>Registro oficial de participación ciudadana y socialización institucional.</p><p><a class="doc-btn download-btn" href="https://unl.edu.ec/sites/default/files/2026-04/Rendici%C3%B3n%20de%20Cuentas%20UNL%202025_0.pdf">Ver</a></p></div><div class="doc-card"><div class="doc-icon">DATA</div><h4>Presentación&nbsp;</h4><p>Presentación de deliberación pública&nbsp;</p><p><a class="doc-btn download-btn" href="https://unl.edu.ec/sites/default/files/2026-04/Rendici%C3%B3n%20de%20Cuentas%20UNL%202025_0.pdf">Ver</a></p></div></div></div></section><!-- =====================================================\r\nFOOTER\r\n===================================================== --><footer><div class="container footer-content"><div class="footer-brand"><h3>UNL Transparencia</h3><p>Portal institucional de acceso público para consulta, seguimiento y transparencia de los procesos de rendición de cuentas de la Universidad Nacional de Loja.</p></div><div class="footer-links"><div><h4>Portal</h4><p><a href="#">Inicio Procesos Documentos</a></p></div><div><h4>Institución</h4><p><a href="https://unl.edu.ec/">Universidad Nacional de Loja&nbsp;</a><br>&nbsp;</p></div></div></div></footer><script>\r\n/* =====================================================\r\nANIMACIÓN SUAVE HERO\r\n===================================================== */\r\nwindow.addEventListener("scroll", () => {\r\n  const scroll = window.scrollY;\r\n  const bg = document.querySelector(".hero-bg img");\r\n  bg.style.transform =\r\n    `scale(1.05) translateY(${scroll * 0.15}px)`;\r\n});\r\n</script>	full_html
texto_libre	0	110	1342	en	0	<section class="hero"><div class="hero-content"><h4 class="badge"><span>Repositorio Institucional</span></h4><h2>Planes Operativos Anuales</h2><h5>Accede a los documentos oficiales correspondientes a los Planes Operativos Anuales de la Universidad Nacional de Loja.</h5><h5>&nbsp;</h5></div></section><!-- =========================================\r\nPLANES\r\n========================================= --><section class="section" id="planes"><div class="container"><div class="section-title"><h3>Documentos Institucionales</h3><p>Explora los planes operativos anuales disponibles. Cada documento puede visualizarse directamente desde el micrositio o descargarse en formato PDF.</p></div><div class="cards-grid"><!-- 2024 --><div class="card"><div class="card-top"><div class="card-year">2024</div></div><div class="card-content"><h4>POA 2024</h4><p>&nbsp;Plan Operativo Anual 2024</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2024_mas_resolucio%CC%81n0207210001777305442.pdf" download="" title="POA 2024">Descargar</a></div></div></div><!-- 2025 --><div class="card"><div class="card-top"><div class="card-year">2025</div></div><div class="card-content"><h4>POA 2025</h4><p>&nbsp;Plan Operativo Anual 2025.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf" download="" title="POA 2025">Descargar</a></div></div></div><!-- 2026 --><div class="card"><div class="card-top"><div class="card-year">2026</div></div><div class="card-content"><h4>POA 2026</h4><p>&nbsp;Plan Operativo Anual&nbsp;2026.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf" download="" title="POA 2026">Descargar</a></div></div></div></div></div></section><!-- =========================================\r\nMODAL PDF\r\n========================================= --><div class="modal" id="pdfModal"><div class="modal-content"><button class="close-modal" id="closeModal">✕</button><iframe id="pdfViewer"></iframe></div></div><!-- =========================================\r\nFOOTER\r\n========================================= --><footer class="footer"><div class="container"><p>© 2026 Universidad Nacional de Loja<br>Micrositio institucional de planificación operativa.</p></div></footer><!-- =========================================\r\nJS\r\n========================================= --><script>\r\n\r\nconst modal = document.getElementById("pdfModal");\r\nconst pdfViewer = document.getElementById("pdfViewer");\r\nconst closeModal = document.getElementById("closeModal");\r\n\r\ndocument.querySelectorAll(".openPdf").forEach(button => {\r\n\r\n    button.addEventListener("click", () => {\r\n\r\n        const pdf = button.getAttribute("data-pdf");\r\n\r\n        pdfViewer.src = pdf;\r\n\r\n        modal.classList.add("active");\r\n\r\n        document.body.style.overflow = "hidden";\r\n\r\n    });\r\n\r\n});\r\n\r\nfunction closePdf(){\r\n\r\n    modal.classList.remove("active");\r\n\r\n    pdfViewer.src = "";\r\n\r\n    document.body.style.overflow = "auto";\r\n\r\n}\r\n\r\ncloseModal.addEventListener("click", closePdf);\r\n\r\nmodal.addEventListener("click", (e) => {\r\n\r\n    if(e.target === modal){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\ndocument.addEventListener("keydown", (e)=>{\r\n\r\n    if(e.key === "Escape"){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\n</script>	full_html
texto_libre	0	110	1343	en	0	<style type="text/css">/* =========================================\r\nPALETA OFICIAL UNL\r\n========================================= */\r\n\r\n:root{\r\n    --primary:#001F4E;\r\n    --primary-light:#003B8E;\r\n    --secondary:#0A56A8;\r\n\r\n    --bg:#f4f7fb;\r\n    --white:#ffffff;\r\n    --text:#1b1b1b;\r\n    --gray:#6f7785;\r\n    --border:#dfe7f1;\r\n\r\n    --shadow:0 10px 35px rgba(0, 31, 78, 0.10);\r\n\r\n    --radius:22px;\r\n}\r\n\r\n/* =========================================\r\nRESET\r\n========================================= */\r\n\r\n*{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\n\r\nhtml{\r\n    scroll-behavior:smooth;\r\n}\r\n\r\nbody{\r\n    font-family:'Montserrat', sans-serif;\r\n    background:var(--bg);\r\n    color:var(--text);\r\n    overflow-x:hidden;\r\n}\r\n\r\n/* =========================================\r\nOCULTAR NAVBAR INTERNO\r\nPARA NO AFECTAR EL HEADER DEL SITIO\r\n========================================= */\r\n\r\nbody > .navbar{\r\n    display:none !important;\r\n}\r\n\r\n/* =========================================\r\nHERO\r\n========================================= */\r\n\r\n.hero{\r\n    position:relative;\r\n\r\n    min-height:52vh;\r\n\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n\r\n    overflow:hidden;\r\n\r\n    padding-top:140px;\r\n    padding-bottom:70px;\r\n\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E 0%,\r\n    #002B6B 45%,\r\n    #003B8E 100%\r\n    );\r\n}\r\n\r\n.hero::before{\r\n    content:"";\r\n    position:absolute;\r\n\r\n    width:480px;\r\n    height:480px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.05);\r\n\r\n    top:-220px;\r\n    right:-120px;\r\n}\r\n\r\n.hero::after{\r\n    content:"";\r\n\r\n    position:absolute;\r\n\r\n    width:350px;\r\n    height:350px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.04);\r\n\r\n    bottom:-180px;\r\n    left:-100px;\r\n}\r\n\r\n.hero-content{\r\n    position:relative;\r\n    z-index:10;\r\n\r\n    width:90%;\r\n    max-width:1000px;\r\n\r\n    text-align:center;\r\n    color:white;\r\n}\r\n\r\n.badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n\r\n    padding:10px 18px;\r\n\r\n    background:rgba(255,255,255,0.10);\r\n\r\n    border:1px solid rgba(255,255,255,0.12);\r\n\r\n    border-radius:100px;\r\n\r\n    backdrop-filter:blur(12px);\r\n\r\n    margin-bottom:22px;\r\n\r\n    animation:fadeUp 1s ease;\r\n}\r\n\r\n.badge span{\r\n    font-size:.85rem;\r\n    font-weight:600;\r\n    letter-spacing:.3px;\r\n}\r\n\r\n.hero h2{\r\n    font-size:5.2rem;\r\n.hero .hero-content h2{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    font-size:clamp(3rem, 5vw, 4.5rem) !important;\r\n\r\n    font-weight:800 !important;\r\n\r\n    line-height:1.1 !important;\r\n\r\n    margin-bottom:20px;\r\n\r\n    color:#ffffff !important;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero .hero-content p{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:3.08rem !important;\r\n\r\n    line-height:1.9 !important;\r\n\r\n    font-weight:400 !important;\r\n\r\n    color:rgba(255,255,255,0.92) !important;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n.hero .badge span{\r\n\r\n    font-size:.9rem !important;\r\n\r\n    font-weight:600 !important;\r\n\r\n    color:white !important;\r\n\r\n}\r\n    font-weight:800;\r\n\r\n    line-height:1.1;\r\n\r\n    margin-bottom:20px;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero p{\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:1.02rem;\r\n\r\n    line-height:1.9;\r\n\r\n    opacity:.92;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n/* =========================================\r\nSECCIONES\r\n========================================= */\r\n\r\n.section{\r\n    padding:110px 0;\r\n}\r\n\r\n.container{\r\n    width:90%;\r\n    max-width:1400px;\r\n    margin:auto;\r\n}\r\n\r\n.section-title{\r\n    text-align:center;\r\n    margin-bottom:70px;\r\n}\r\n\r\n.section-title h3{\r\n    font-size:2.7rem;\r\n    color:var(--primary);\r\n    margin-bottom:18px;\r\n}\r\n\r\n.section-title p{\r\n    max-width:760px;\r\n    margin:auto;\r\n    color:var(--gray);\r\n    line-height:1.8;\r\n}\r\n\r\n/* =========================================\r\nCARDS\r\n========================================= */\r\n\r\n.cards-grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(auto-fit,minmax(340px,1fr));\r\n    gap:34px;\r\n}\r\n\r\n.card{\r\n    position:relative;\r\n    background:var(--white);\r\n    border-radius:var(--radius);\r\n    overflow:hidden;\r\n    box-shadow:var(--shadow);\r\n    transition:.4s ease;\r\n    border:1px solid rgba(0,0,0,0.03);\r\n}\r\n\r\n.card:hover{\r\n    transform:translateY(-12px);\r\n}\r\n\r\n.card-top{\r\n    position:relative;\r\n    height:220px;\r\n\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E,\r\n    #003B8E,\r\n    #0A56A8\r\n    );\r\n\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    overflow:hidden;\r\n}\r\n\r\n.card-top::before{\r\n    content:"";\r\n    position:absolute;\r\n    width:300px;\r\n    height:300px;\r\n    background:rgba(255,255,255,0.08);\r\n    border-radius:50%;\r\n    top:-100px;\r\n    right:-60px;\r\n}\r\n\r\n.card-year{\r\n    position:relative;\r\n    z-index:2;\r\n    font-size:5rem;\r\n    font-weight:800;\r\n    color:white;\r\n    letter-spacing:4px;\r\n}\r\n\r\n.card-content{\r\n    padding:34px;\r\n}\r\n\r\n.card-content h4{\r\n    font-size:1.4rem;\r\n    color:var(--primary);\r\n    margin-bottom:16px;\r\n}\r\n\r\n.card-content p{\r\n    color:var(--gray);\r\n    line-height:1.7;\r\n    margin-bottom:26px;\r\n}\r\n\r\n.card-actions{\r\n    display:flex;\r\n    gap:14px;\r\n    flex-wrap:wrap;\r\n}\r\n\r\n.btn{\r\n    flex:1;\r\n    min-width:130px;\r\n    padding:14px 18px;\r\n    border:none;\r\n    border-radius:14px;\r\n    cursor:pointer;\r\n    text-decoration:none;\r\n    font-weight:700;\r\n    transition:.3s ease;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    gap:10px;\r\n    font-family:'Montserrat', sans-serif;\r\n}\r\n\r\n.btn-primary{\r\n    background:var(--primary);\r\n    color:white;\r\n}\r\n\r\n.btn-primary:hover{\r\n    background:var(--primary-light);\r\n}\r\n\r\n.btn-secondary{\r\n    background:#eef4fb;\r\n    color:var(--primary);\r\n}\r\n\r\n.btn-secondary:hover{\r\n    background:#dfeeff;\r\n}\r\n\r\n/* =========================================\r\nMODAL PDF\r\n========================================= */\r\n\r\n.modal{\r\n    position:fixed;\r\n    inset:0;\r\n    background:rgba(0,0,0,0.78);\r\n    z-index:9999;\r\n    display:none;\r\n    align-items:center;\r\n    justify-content:center;\r\n    padding:30px;\r\n}\r\n\r\n.modal.active{\r\n    display:flex;\r\n}\r\n\r\n.modal-content{\r\n    width:100%;\r\n    max-width:1200px;\r\n    height:90vh;\r\n    background:white;\r\n    border-radius:22px;\r\n    overflow:hidden;\r\n    position:relative;\r\n    animation:zoom .35s ease;\r\n}\r\n\r\n.close-modal{\r\n    position:absolute;\r\n    top:16px;\r\n    right:16px;\r\n    width:46px;\r\n    height:46px;\r\n    border-radius:50%;\r\n    background:rgba(0,0,0,0.1);\r\n    border:none;\r\n    cursor:pointer;\r\n    font-size:1.2rem;\r\n    z-index:10;\r\n    transition:.3s;\r\n}\r\n\r\n.close-modal:hover{\r\n    background:rgba(0,0,0,0.2);\r\n}\r\n\r\n.modal iframe{\r\n    width:100%;\r\n    height:100%;\r\n    border:none;\r\n}\r\n\r\n/* =========================================\r\nFOOTER\r\n========================================= */\r\n\r\n.footer{\r\n    background:var(--primary);\r\n    padding:50px 0;\r\n    color:white;\r\n    text-align:center;\r\n}\r\n\r\n.footer p{\r\n    opacity:.85;\r\n    line-height:1.8;\r\n}\r\n\r\n/* =========================================\r\nANIMACIONES\r\n========================================= */\r\n\r\n@keyframes fadeUp{\r\n    from{\r\n        opacity:0;\r\n        transform:translateY(40px);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes zoom{\r\n    from{\r\n        opacity:0;\r\n        transform:scale(.9);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:scale(1);\r\n    }\r\n}\r\n\r\n/* =========================================\r\nRESPONSIVE\r\n========================================= */\r\n\r\n@media(max-width:992px){\r\n\r\n    .hero h2{\r\n        font-size:2.6rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:768px){\r\n\r\n    .hero{\r\n        padding-top:120px;\r\n    }\r\n\r\n    .hero h2{\r\n        font-size:2.1rem;\r\n    }\r\n\r\n    .section-title h3{\r\n        font-size:2rem;\r\n    }\r\n\r\n    .card-year{\r\n        font-size:4rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:480px){\r\n\r\n    .hero h2{\r\n        font-size:1.8rem;\r\n    }\r\n\r\n    .hero p{\r\n        font-size:.95rem;\r\n    }\r\n\r\n    .card-content{\r\n        padding:24px;\r\n    }\r\n\r\n}\r\n</style><!-- =========================================\r\nHERO\r\n========================================= --><section class="hero"><div class="hero-content"><h4 class="badge"><span>Repositorio Institucional</span></h4><h2>Planes Operativos Anuales</h2><h5>Accede a los documentos oficiales correspondientes a los Planes Operativos Anuales de la Universidad Nacional de Loja.</h5><h5>&nbsp;</h5></div></section><!-- =========================================\r\nPLANES\r\n========================================= --><section class="section" id="planes"><div class="container"><div class="section-title"><h3>Documentos Institucionales</h3><p>Explora los planes operativos anuales disponibles. Cada documento puede visualizarse directamente desde el micrositio o descargarse en formato PDF.</p></div><div class="cards-grid"><!-- 2024 --><div class="card"><div class="card-top"><div class="card-year">2024</div></div><div class="card-content"><h4>POA 2024</h4><p>&nbsp;Plan Operativo Anual 2024</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2024_mas_resolucio%CC%81n0207210001777305442.pdf" download="" title="POA 2024">Descargar</a></div></div></div><!-- 2025 --><div class="card"><div class="card-top"><div class="card-year">2025</div></div><div class="card-content"><h4>POA 2025</h4><p>&nbsp;Plan Operativo Anual 2025.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf" download="" title="POA 2025">Descargar</a></div></div></div><!-- 2026 --><div class="card"><div class="card-top"><div class="card-year">2026</div></div><div class="card-content"><h4>POA 2026</h4><p>&nbsp;Plan Operativo Anual&nbsp;2026.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf" download="" title="POA 2026">Descargar</a></div></div></div></div></div></section><!-- =========================================\r\nMODAL PDF\r\n========================================= --><div class="modal" id="pdfModal"><div class="modal-content"><button class="close-modal" id="closeModal">✕</button><iframe id="pdfViewer"></iframe></div></div><!-- =========================================\r\nFOOTER\r\n========================================= --><footer class="footer"><div class="container"><p>© 2026 Universidad Nacional de Loja<br>Micrositio institucional de planificación operativa.</p></div></footer><!-- =========================================\r\nJS\r\n========================================= --><script>\r\n\r\nconst modal = document.getElementById("pdfModal");\r\nconst pdfViewer = document.getElementById("pdfViewer");\r\nconst closeModal = document.getElementById("closeModal");\r\n\r\ndocument.querySelectorAll(".openPdf").forEach(button => {\r\n\r\n    button.addEventListener("click", () => {\r\n\r\n        const pdf = button.getAttribute("data-pdf");\r\n\r\n        pdfViewer.src = pdf;\r\n\r\n        modal.classList.add("active");\r\n\r\n        document.body.style.overflow = "hidden";\r\n\r\n    });\r\n\r\n});\r\n\r\nfunction closePdf(){\r\n\r\n    modal.classList.remove("active");\r\n\r\n    pdfViewer.src = "";\r\n\r\n    document.body.style.overflow = "auto";\r\n\r\n}\r\n\r\ncloseModal.addEventListener("click", closePdf);\r\n\r\nmodal.addEventListener("click", (e) => {\r\n\r\n    if(e.target === modal){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\ndocument.addEventListener("keydown", (e)=>{\r\n\r\n    if(e.key === "Escape"){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\n</script>	full_html
texto_libre	0	110	1344	en	0	<style type="text/css">/* =========================================\r\nPALETA OFICIAL UNL\r\n========================================= */\r\n\r\n:root{\r\n    --primary:#001F4E;\r\n    --primary-light:#003B8E;\r\n    --secondary:#0A56A8;\r\n\r\n    --bg:#f4f7fb;\r\n    --white:#ffffff;\r\n    --text:#1b1b1b;\r\n    --gray:#6f7785;\r\n    --border:#dfe7f1;\r\n\r\n    --shadow:0 10px 35px rgba(0, 31, 78, 0.10);\r\n\r\n    --radius:22px;\r\n}\r\n\r\n/* =========================================\r\nRESET\r\n========================================= */\r\n\r\n*{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\n\r\nhtml{\r\n    scroll-behavior:smooth;\r\n}\r\n\r\nbody{\r\n    font-family:'Montserrat', sans-serif;\r\n    background:var(--bg);\r\n    color:var(--text);\r\n    overflow-x:hidden;\r\n}\r\n\r\n/* =========================================\r\nOCULTAR NAVBAR INTERNO\r\nPARA NO AFECTAR EL HEADER DEL SITIO\r\n========================================= */\r\n\r\nbody > .navbar{\r\n    display:none !important;\r\n}\r\n\r\n/* =========================================\r\nHERO\r\n========================================= */\r\n\r\n.hero{\r\n    position:relative;\r\n\r\n    min-height:52vh;\r\n\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n\r\n    overflow:hidden;\r\n\r\n    padding-top:140px;\r\n    padding-bottom:70px;\r\n\r\n    background:\r\n    linear-gradient(\r\n    135deg,\r\n    #001F4E 0%,\r\n    #002B6B 45%,\r\n    #003B8E 100%\r\n    );\r\n}\r\n\r\n.hero::before{\r\n    content:"";\r\n    position:absolute;\r\n\r\n    width:480px;\r\n    height:480px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.05);\r\n\r\n    top:-220px;\r\n    right:-120px;\r\n}\r\n\r\n.hero::after{\r\n    content:"";\r\n\r\n    position:absolute;\r\n\r\n    width:350px;\r\n    height:350px;\r\n\r\n    border-radius:50%;\r\n\r\n    background:rgba(255,255,255,0.04);\r\n\r\n    bottom:-180px;\r\n    left:-100px;\r\n}\r\n\r\n.hero-content{\r\n    position:relative;\r\n    z-index:10;\r\n\r\n    width:90%;\r\n    max-width:1000px;\r\n\r\n    text-align:center;\r\n    color:white;\r\n}\r\n\r\n.badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n\r\n    padding:10px 18px;\r\n\r\n    background:rgba(255,255,255,0.10);\r\n\r\n    border:1px solid rgba(255,255,255,0.12);\r\n\r\n    border-radius:100px;\r\n\r\n    backdrop-filter:blur(12px);\r\n\r\n    margin-bottom:22px;\r\n\r\n    animation:fadeUp 1s ease;\r\n}\r\n\r\n.badge span{\r\n    font-size:.85rem;\r\n    font-weight:600;\r\n    letter-spacing:.3px;\r\n}\r\n\r\n.hero h2{\r\n    font-size:5.2rem;\r\n.hero .hero-content h2{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    font-size:clamp(3rem, 5vw, 4.5rem) !important;\r\n\r\n    font-weight:800 !important;\r\n\r\n    line-height:1.1 !important;\r\n\r\n    margin-bottom:20px;\r\n\r\n    color:#ffffff !important;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero .hero-content p{\r\n\r\n    font-family:'Montserrat', sans-serif !important;\r\n\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:3.08rem !important;\r\n\r\n    line-height:1.9 !important;\r\n\r\n    font-weight:400 !important;\r\n\r\n    color:rgba(255,255,255,0.92) !important;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n.hero .badge span{\r\n\r\n    font-size:.9rem !important;\r\n\r\n    font-weight:600 !important;\r\n\r\n    color:white !important;\r\n\r\n}\r\n    font-weight:800;\r\n\r\n    line-height:1.1;\r\n\r\n    margin-bottom:20px;\r\n\r\n    animation:fadeUp 1.1s ease;\r\n}\r\n\r\n.hero p{\r\n    max-width:760px;\r\n\r\n    margin:auto;\r\n\r\n    font-size:1.02rem;\r\n\r\n    line-height:1.9;\r\n\r\n    opacity:.92;\r\n\r\n    animation:fadeUp 1.2s ease;\r\n}\r\n\r\n/* =========================================\r\nSECCIONES\r\n========================================= */\r\n\r\n.section{\r\