\n}\r\n\r\n.btn{\r\n    flex:1;\r\n    min-width:130px;\r\n    padding:14px 18px;\r\n    border:none;\r\n    border-radius:14px;\r\n    cursor:pointer;\r\n    text-decoration:none;\r\n    font-weight:700;\r\n    transition:.3s ease;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    gap:10px;\r\n    font-family:'Montserrat', sans-serif;\r\n}\r\n\r\n.btn-primary{\r\n    background:var(--primary);\r\n    color:white;\r\n}\r\n\r\n.btn-primary:hover{\r\n    background:var(--primary-light);\r\n}\r\n\r\n.btn-secondary{\r\n    background:#eef4fb;\r\n    color:var(--primary);\r\n}\r\n\r\n.btn-secondary:hover{\r\n    background:#dfeeff;\r\n}\r\n\r\n/* =========================================\r\nMODAL PDF\r\n========================================= */\r\n\r\n.modal{\r\n    position:fixed;\r\n    inset:0;\r\n    background:rgba(0,0,0,0.78);\r\n    z-index:9999;\r\n    display:none;\r\n    align-items:center;\r\n    justify-content:center;\r\n    padding:30px;\r\n}\r\n\r\n.modal.active{\r\n    display:flex;\r\n}\r\n\r\n.modal-content{\r\n    width:100%;\r\n    max-width:1200px;\r\n    height:90vh;\r\n    background:white;\r\n    border-radius:22px;\r\n    overflow:hidden;\r\n    position:relative;\r\n    animation:zoom .35s ease;\r\n}\r\n\r\n.close-modal{\r\n    position:absolute;\r\n    top:16px;\r\n    right:16px;\r\n    width:46px;\r\n    height:46px;\r\n    border-radius:50%;\r\n    background:rgba(0,0,0,0.1);\r\n    border:none;\r\n    cursor:pointer;\r\n    font-size:1.2rem;\r\n    z-index:10;\r\n    transition:.3s;\r\n}\r\n\r\n.close-modal:hover{\r\n    background:rgba(0,0,0,0.2);\r\n}\r\n\r\n.modal iframe{\r\n    width:100%;\r\n    height:100%;\r\n    border:none;\r\n}\r\n\r\n/* =========================================\r\nFOOTER\r\n========================================= */\r\n\r\n.footer{\r\n    background:var(--primary);\r\n    padding:50px 0;\r\n    color:white;\r\n    text-align:center;\r\n}\r\n\r\n.footer p{\r\n    opacity:.85;\r\n    line-height:1.8;\r\n}\r\n\r\n/* =========================================\r\nANIMACIONES\r\n========================================= */\r\n\r\n@keyframes fadeUp{\r\n    from{\r\n        opacity:0;\r\n        transform:translateY(40px);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:translateY(0);\r\n    }\r\n}\r\n\r\n@keyframes zoom{\r\n    from{\r\n        opacity:0;\r\n        transform:scale(.9);\r\n    }\r\n    to{\r\n        opacity:1;\r\n        transform:scale(1);\r\n    }\r\n}\r\n\r\n/* =========================================\r\nRESPONSIVE\r\n========================================= */\r\n\r\n@media(max-width:992px){\r\n\r\n    .hero h2{\r\n        font-size:2.6rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:768px){\r\n\r\n    .hero{\r\n        padding-top:120px;\r\n    }\r\n\r\n    .hero h2{\r\n        font-size:2.1rem;\r\n    }\r\n\r\n    .section-title h3{\r\n        font-size:2rem;\r\n    }\r\n\r\n    .card-year{\r\n        font-size:4rem;\r\n    }\r\n\r\n}\r\n\r\n@media(max-width:480px){\r\n\r\n    .hero h2{\r\n        font-size:1.8rem;\r\n    }\r\n\r\n    .hero p{\r\n        font-size:.95rem;\r\n    }\r\n\r\n    .card-content{\r\n        padding:24px;\r\n    }\r\n\r\n}\r\n</style><!-- =========================================\r\nHERO\r\n========================================= --><section class="hero"><div class="hero-content"><h4 class="badge"><span>Repositorio Institucional</span></h4><h2>Planes Operativos Anuales</h2><h5>Accede a los documentos oficiales correspondientes a los Planes Operativos Anuales de la Universidad Nacional de Loja.</h5><h5>&nbsp;</h5></div></section><!-- =========================================\r\nPLANES\r\n========================================= --><section class="section" id="planes"><div class="container"><div class="section-title"><h3>Documentos Institucionales</h3><p>Explora los planes operativos anuales disponibles. Cada documento puede visualizarse directamente desde el micrositio o descargarse en formato PDF.</p></div><div class="cards-grid"><!-- 2024 --><div class="card"><div class="card-top"><div class="card-year">2024</div></div><div class="card-content"><h4>POA 2024</h4><p>&nbsp;Plan Operativo Anual 2024</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2024_mas_resolucio%CC%81n0207210001777305442.pdf" download="" title="POA 2024">Descargar</a></div></div></div><!-- 2025 --><div class="card"><div class="card-top"><div class="card-year">2025</div></div><div class="card-content"><h4>POA 2025</h4><p>&nbsp;Plan Operativo Anual 2025.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa_2025_mas_resolucio%CC%81n0046180001777305442.pdf" download="" title="POA 2025">Descargar</a></div></div></div><!-- 2026 --><div class="card"><div class="card-top"><div class="card-year">2026</div></div><div class="card-content"><h4>POA 2026</h4><p>&nbsp;Plan Operativo Anual&nbsp;2026.</p><div class="card-actions"><button class="btn btn-primary openPdf" data-pdf="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf">Visualizar</button><a class="btn btn-secondary" href="https://unl.edu.ec/sites/default/files/2026-05/poa-2026_mas_resolucion-aprobacio%CC%81n0405566001777305441.pdf" download="" title="POA 2026">Descargar</a></div></div></div></div></div></section><!-- =========================================\r\nMODAL PDF\r\n========================================= --><div class="modal" id="pdfModal"><div class="modal-content"><button class="close-modal" id="closeModal">✕</button><iframe id="pdfViewer"></iframe></div></div><!-- =========================================\r\nFOOTER\r\n========================================= --><footer class="footer"><div class="container"><p>© 2026 Universidad Nacional de Loja<br>Micrositio institucional de planificación operativa.</p></div></footer><!-- =========================================\r\nJS\r\n========================================= --><script>\r\n\r\nconst modal = document.getElementById("pdfModal");\r\nconst pdfViewer = document.getElementById("pdfViewer");\r\nconst closeModal = document.getElementById("closeModal");\r\n\r\ndocument.querySelectorAll(".openPdf").forEach(button => {\r\n\r\n    button.addEventListener("click", () => {\r\n\r\n        const pdf = button.getAttribute("data-pdf");\r\n\r\n        pdfViewer.src = pdf;\r\n\r\n        modal.classList.add("active");\r\n\r\n        document.body.style.overflow = "hidden";\r\n\r\n    });\r\n\r\n});\r\n\r\nfunction closePdf(){\r\n\r\n    modal.classList.remove("active");\r\n\r\n    pdfViewer.src = "";\r\n\r\n    document.body.style.overflow = "auto";\r\n\r\n}\r\n\r\ncloseModal.addEventListener("click", closePdf);\r\n\r\nmodal.addEventListener("click", (e) => {\r\n\r\n    if(e.target === modal){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\ndocument.addEventListener("keydown", (e)=>{\r\n\r\n    if(e.key === "Escape"){\r\n\r\n        closePdf();\r\n\r\n    }\r\n\r\n});\r\n\r\n</script>	full_html
texto_libre	0	106	1345	en	0	<p class="text-align-justify">La Dirección de Relaciones de Cooperación Internacional, anexa al Rectorado, es la encargada de guiar el proceso de internacionalización integral, además de&nbsp;centralizar todo el manejo y funciones de cooperación internacional y de asistencia técnica que se encuentren en otras unidades académicas o administrativas y constituirse en el punto de enlace obligatorio de la Universidad Nacional de Loja (UNL) en sus relaciones internacionales.</p><p>&nbsp;&nbsp;</p><img src="/sites/default/files/inline-images/WhatsApp%20Image%202023-05-22%20at%2016.19.32.jpeg" data-align="center" data-entity-uuid="fa6584e7-e76b-4d57-91c5-27e1a2ff071c" data-entity-type="file" alt="cooperación"><p>&nbsp;</p>	full_html
texto_libre	0	100	1346	en	0	<p class="text-align-justify">El Órgano Colegiado Superior (OCS), es el máximo órgano de gobierno de la Universidad Nacional de Loja, encargado de&nbsp;<strong>aprobar políticas, planes, estrategias y objetivos que consoliden y fortalezcan la institucionalidad</strong>, de conformidad a los lineamientos del órgano rector de la política pública de educación superior. Sus resoluciones son ejecutables para toda la institución.</p><p class="text-align-justify">Las obligaciones del OCS son cumplir y hacer&nbsp; cumplir la Constitución de la&nbsp; República&nbsp; del&nbsp; Ecuador,&nbsp; la&nbsp; Ley Orgánica de Educación Superior, su Reglamento, las Resoluciones del Consejo de Educación Superior, las Resoluciones del Órgano Colegiado Superior, las directrices o normativa expedida&nbsp; por el&nbsp;órgano rector de la&nbsp; política pública de educación superior, el presente Estatuto, los reglamentos internos de la Institución, y demás disposiciones legales.</p><img src="/sites/default/files/inline-images/DIR00735_optimized_700.jpg" data-entity-uuid="042ab32d-e403-417d-86fb-3cbfec005c88" data-entity-type="file" width="1893" height="1262"><p class="text-align-justify"><strong>NÓMINA DE REPRESENTANTES DOCENTES TITULARES ANTE EL ÓRGANO COLEGIADO SUPERIOR DE LA UNIVERSIDAD NACIONAL DE LOJA, PERÍODO SEPTIEMBRE 2025 - SEPTIEMBRE 2027.</strong></p><table class="table MsoTableGrid" style="border-collapse:collapse;border-style:none;mso-border-alt:solid windowtext .5pt;mso-padding-alt:0cm 5.4pt 0cm 5.4pt;mso-table-layout-alt:fixed;mso-yfti-tbllook:1184;width:0px;" border="1" cellpadding="0" cellspacing="0"><tbody><tr style="height:26.6pt;mso-yfti-firstrow:yes;mso-yfti-irow:0;"><td style="border-color:windowtext;border-width:1.0pt;height:26.6pt;mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt;width:94.6pt;" rowspan="2" width="119"><p class="text-align-center MsoNormal" style="line-height:normal;margin-bottom:.0001pt;tab-stops:452.25pt;"><b style="ms