texto_libre	0	125	1758	es	0	<style type="text/css">/* ============================================================\r\n   CONVOCATORIAS DE PROYECTOS — UNL\r\n   -----------------------------------------------------------\r\n   ============================================================ */\r\n:root {\r\n  --unl-navy:        #0c2342;\r\n  --unl-azul:        #004C7B;\r\n  --unl-verde:       #4F8E3A;\r\n  --unl-verde-texto: #247A1E;\r\n  --unl-rojo:        #BF0811;\r\n  --unl-blanco:      #ffffff;\r\n\r\n  --cvp-tinta:       #211915;\r\n  --cvp-tinta-soft:  #3f4a5a;\r\n  --cvp-mute:        #6b7686;\r\n  --cvp-rule:        #e4e7ec;\r\n  --cvp-azul-glow:   rgba(0, 76, 123, 0.06);\r\n  --cvp-verde-glow:  rgba(79, 142, 58, 0.10);\r\n  --cvp-shadow:      0 1px 3px rgba(15, 23, 42, 0.05);\r\n  --cvp-shadow-h:    0 12px 28px -10px rgba(15, 23, 42, 0.18);\r\n}\r\n\r\n.cvp * { box-sizing: border-box; margin: 0; padding: 0; }\r\n\r\n.cvp {\r\n  font-family: 'Montserrat', system-ui, sans-serif;\r\n  color: var(--cvp-tinta);\r\n  line-height: 1.55;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\n.cvp-wrap { width: 100%; margin: 0 auto; padding: 8px 0 32px; }\r\n\r\n/* ============================================================\r\n   BLOQUE 1 — CONVOCATORIA VIGENTE \r\n   ============================================================ */\r\n.cvp-vigente {\r\n  position: relative;\r\n  background: var(--unl-blanco);\r\n  border: 1px solid var(--cvp-rule);\r\n  border-left: 4px solid var(--unl-rojo);\r\n  border-radius: 12px;\r\n  padding: 22px 24px;\r\n  margin-bottom: 32px;\r\n  box-shadow: var(--cvp-shadow);\r\n  overflow: hidden;\r\n}\r\n\r\n.cvp-eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-size: 11px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--unl-azul);\r\n  margin-bottom: 12px;\r\n}\r\n.cvp-eyebrow::before {\r\n  content: '';\r\n  display: inline-block;\r\n  width: 20px;\r\n  height: 2px;\r\n  background: var(--unl-azul);\r\n}\r\n\r\n.cvp-vigente-head {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 14px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 8px;\r\n}\r\n.cvp-vigente-titulo {\r\n  font-size: 26px;\r\n  font-weight: 700;\r\n  color: var(--unl-azul);\r\n  line-height: 1.2;\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n\r\n.cvp-badge-estado {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-size: 11px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.06em;\r\n  text-transform: uppercase;\r\n  color: var(--unl-blanco);\r\n  background: var(--unl-verde-texto);\r\n  padding: 6px 12px;\r\n  border-radius: 20px;\r\n  white-space: nowrap;\r\n  flex-shrink: 0;\r\n}\r\n.cvp-badge-estado::before {\r\n  content: '';\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: var(--unl-blanco);\r\n  animation: cvp-pulse 2s ease-in-out infinite;\r\n}\r\n@keyframes cvp-pulse {\r\n  0%, 100% { opacity: 1; }\r\n  50%      { opacity: 0.4; }\r\n}\r\n\r\n.cvp-vigente-bajada {\r\n  font-size: 14.5px;\r\n  color: var(--cvp-tinta-soft);\r\n  margin-bottom: 18px;\r\n  max-width: 620px;\r\n}\r\n\r\n.cvp-vigente-meta {\r\n  display: flex;\r\n  gap: 24px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 20px;\r\n  padding: 14px 16px;\r\n  background: var(--cvp-azul-glow);\r\n  border-radius: 8px;\r\n}\r\n.cvp-meta-item {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 10px;\r\n  min-width: 0;\r\n}\r\n.cvp-meta-item svg {\r\n  width: 18px;\r\n  height: 18px;\r\n  color: var(--unl-verde-texto);\r\n  flex-shrink: 0;\r\n  margin-top: 2px;\r\n}\r\n.cvp-meta-label {\r\n  display: block;\r\n  font-size: 10.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.06em;\r\n  text-transform: uppercase;\r\n  color: var(--cvp-mute);\r\n  margin-bottom: 2px;\r\n}\r\n.cvp-meta-valor {\r\n  font-size: 13.5px;\r\n  font-weight: 600;\r\n  color: var(--cvp-tinta);\r\n}\r\n\r\n.cvp-vigente-acciones {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 20px;\r\n  flex-wrap: wrap;\r\n}\r\n.cvp-cta, .cvp-cta:link,.cvp-cta:visited,.cvp-cta:active  {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-family: inherit;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  color: var(--unl-blanco);\r\n  background: var(--unl-azul);\r\n  text-decoration: none;\r\n  border-radius: 8px;\r\n  padding: 12px 20px;\r\n  transition: background 0.2s, gap 0.2s;\r\n}\r\n.cvp-cta:hover {\r\n  background: #013a5e;\r\n  gap: 12px;\r\n  color: var(--unl-blanco);\r\n  text-decoration: none;\r\n}\r\n.cvp-cta:focus-visible {\r\n  outline: 2px solid var(--unl-azul);\r\n  outline-offset: 3px;\r\n}\r\n.cvp-cta svg { width: 16px; height: 16px; }\r\n\r\n/* ============================================================\r\n   BLOQUE 2 — CONVOCATORIAS ANTERIORES (archivo histórico)\r\n   ============================================================ */\r\n.cvp-seccion-historico { margin-top: 8px; }\r\n\r\n.cvp-seccion-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 12px;\r\n  margin-bottom: 16px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid var(--cvp-rule);\r\n  flex-wrap: wrap;\r\n}\r\n.cvp-seccion-titulo {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--unl-azul);\r\n}\r\n.cvp-seccion-hint {\r\n  font-size: 12.5px;\r\n  color: var(--cvp-mute);\r\n}\r\n\r\n.cvp-historico-grid {\r\n  display: grid;\r\n  /* auto-fill para que las cards NO se estiren si quedan pocas */\r\n  grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr));\r\n  gap: 14px;\r\n}\r\n\r\n/* Card de convocatoria histórica: DIV con único <a> en el h3. */\r\n.cvp-hist-card {\r\n  position: relative;\r\n  background: var(--unl-blanco);\r\n  border: 1px solid var(--cvp-rule);\r\n  border-radius: 10px;\r\n  padding: 16px 18px;\r\n  transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;\r\n  min-width: 0;\r\n}\r\n.cvp-hist-card:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: var(--cvp-shadow-h);\r\n  border-color: rgba(0, 76, 123, 0.25);\r\n}\r\n\r\n/* Estado "Cerrada": gris sobrio */\r\n.cvp-hist-estado {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 5px;\r\n  font-size: 10px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--cvp-mute);\r\n  margin-bottom: 8px;\r\n}\r\n.cvp-hist-estado::before {\r\n  content: '';\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: var(--cvp-mute);\r\n}\r\n\r\n.cvp-hist-titulo {\r\n  font-size: 18px;\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  margin-bottom: 4px;\r\n}\r\n.cvp-hist-titulo a {\r\n  color: var(--unl-azul);\r\n  text-decoration: none;\r\n  transition: color 0.2s;\r\n}\r\n.cvp-hist-titulo a:hover {\r\n  color: var(--unl-verde-texto);\r\n  text-decoration: underline;\r\n}\r\n.cvp-hist-titulo a:focus-visible {\r\n  outline: 2px solid var(--unl-azul);\r\n  outline-offset: 2px;\r\n  border-radius: 2px;\r\n}\r\n/* Stretched link para ampliar hit-area de la card sin usar <a> envolvente */\r\n.cvp-hist-titulo a::after {\r\n  content: '';\r\n  position: absolute;\r\n  inset: 0;\r\n  z-index: 1;\r\n}\r\n\r\n.cvp-hist-sub {\r\n  font-size: 12.5px;\r\n  color: var(--cvp-tinta-soft);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 5px;\r\n}\r\n.cvp-hist-sub svg {\r\n  width: 12px;\r\n  height: 12px;\r\n  color: var(--cvp-mute);\r\n}\r\n\r\n/* ============================================================\r\n   RESPONSIVE\r\n   ============================================================ */\r\n@media (max-width: 900px) {\r\n  .cvp-vigente-titulo { font-size: 22px; }\r\n  .cvp-historico-grid { grid-template-columns: repeat(2, 1fr); }\r\n}\r\n\r\n@media (max-width: 520px) {\r\n  .cvp-vigente { padding: 18px 16px; }\r\n  .cvp-vigente-head { flex-direction: column; gap: 10px; }\r\n  .cvp-vigente-titulo { font-size: 20px; }\r\n  .cvp-vigente-meta { flex-direction: column; gap: 12px; padding: 12px 14px; }\r\n  .cvp-vigente-acciones { flex-direction: column; align-items: stretch; gap: 12px; }\r\n  .cvp-cta { width: 100%; justify-content: center; padding: 13px 18px; }\r\n  .cvp-historico-grid { grid-template-columns: 1fr; gap: 12px; }\r\n  .cvp-hist-card { padding: 14px 16px; }\r\n}\r\n</style><div class="simula-drupal"><h1 class="demo-h1">Convocatorias de Proyectos</h1><div class="cvp"><div class="cvp-wrap"><!-- ============== BLOQUE 1: CONVOCATORIA VIGENTE 2026 ============== --><div class="cvp-vigente"><p><span class="cvp-eyebrow">Convocatoria abierta a docentes-investigadores</span></p><div class="cvp-vigente-head"><h2 class="cvp-vigente-titulo">Convocatoria 2026&nbsp;</h2><p><span class="cvp-badge-estado">Abierta</span></p></div><p class="cvp-vigente-bajada">Presenta tu propuesta de investigación para acceder a financiamiento institucional UNL. Bases, duración y cronograma disponibles.</p><div class="cvp-vigente-meta"><div class="cvp-meta-item"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"> <rect height="18" rx="2" ry="2" width="18" x="3" y="4"></rect> <line x1="16" x2="16" y1="2" y2="6"></line> <line x1="8" x2="8" y1="2" y2="6"></line> <line x1="3" x2="21" y1="10" y2="10"></line> </svg><div><span class="cvp-meta-label">Apertura</span> <span class="cvp-meta-valor">29 de julio de 2026</span></div></div><div class="cvp-meta-item"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"> <circle cx="12" cy="12" r="10"></circle> <polyline points="12 6 12 12 16 14"></polyline> </svg><div><span class="cvp-meta-label">Cierre postulaciones</span> <span class="cvp-meta-valor">04 de octubre de 2026</span></div></div><div class="cvp-meta-item"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"> <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path> <polyline points="14 2 14 8 20 8"></polyline> </svg><div><span class="cvp-meta-label">Periodo de ejecución</span> <span class="cvp-meta-valor">2027 — 2029</span></div></div></div><div class="cvp-vigente-acciones"><a class="cvp-cta" href="https://unl.edu.ec/investigacion/convocatorias/2026" rel="noopener" target="_blank">Ver bases y postular&nbsp;<svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" viewbox="0 0 24 24"> <line x1="5" x2="19" y1="12" y2="12"></line> <polyline points="12 5 19 12 12 19"></polyline> </svg></a></div></div><!-- ============== BLOQUE 2: CONVOCATORIAS ANTERIORES ============== --><section class="cvp-seccion-historico"><div class="cvp-seccion-head"><h2 class="cvp-seccion-titulo">Convocatorias anteriores</h2><p><span class="cvp-seccion-hint">Consulta proyectos financiados en cada edición</span></p></div><div class="cvp-historico-grid"><div class="cvp-hist-card"><p><span class="cvp-hist-estado">Cerrada</span></p><h3 class="cvp-hist-titulo"><a href="/investigacion/proyectos-investigacion/convocatorias/2024">Convocatoria 2024</a></h3><p><span class="cvp-hist-sub"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>Ver información</span></p></div><div class="cvp-hist-card"><p><span class="cvp-hist-estado">Cerrada</span></p><h3 class="cvp-hist-titulo"><a href="/investigacion/proyectos-investigacion/convocatorias/2022">Convocatoria 2022</a></h3><p><span class="cvp-hist-sub"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>Ver información</span></p></div><div class="cvp-hist-card"><p><span class="cvp-hist-estado">Cerrada</span></p><h3 class="cvp-hist-titulo"><a href="/investigacion/proyectos-investigacion/convocatorias/2021">Convocatoria 2021</a></h3><p><span class="cvp-hist-sub"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>Ver información</span></p></div><div class="cvp-hist-card"><p><span class="cvp-hist-estado">Cerrada</span></p><h3 class="cvp-hist-titulo"><a href="/investigacion/proyectos-investigacion/convocatorias/2018">Convocatoria 2018</a></h3><p><span class="cvp-hist-sub"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>Ver información</span></p></div></div></section></div></div></div>	full_html
texto_libre	0	106	1354	en	0	<div class="drci-micrositio"><style>\r\n.drci-micrositio *{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\n\r\n.drci-micrositio{\r\n    font-family:'Montserrat', sans-serif;\r\n    background:#f4f7fb !important;\r\n    color:#1b1b1b;\r\n    overflow-x:hidden;\r\n}\r\n\r\n.drci-micrositio > .navbar{\r\n    display:none !important;\r\n}\r\n\r\n/* =========================================\r\n   HERO\r\n========================================= */\r\n\r\n.drci-micrositio .hero{\r\n    position:relative;\r\n    min-height:42vh;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    overflow:hidden;\r\n    padding:140px 0 70px;\r\n\r\n    background:linear-gradient(\r\n        135deg,\r\n        #001F4E 0%,\r\n        #002B6B 45%,\r\n        #003B8E 100%\r\n    ) !important;\r\n}\r\n\r\n.drci-micrositio .hero::before{\r\n    content:"";\r\n    position:absolute;\r\n    width:480px;\r\n    height:480px;\r\n    border-radius:50%;\r\n    background:rgba(255,255,255,0.05) !important;\r\n    top:-220px;\r\n    right:-120px;\r\n}\r\n\r\n.drci-micrositio .hero::after{\r\n    content:"";\r\n    position:absolute;\r\n    width:350px;\r\n    height:350px;\r\n    border-radius:50%;\r\n    background:rgba(255,255,255,0.04) !important;\r\n    bottom:-180px;\r\n    left:-100px;\r\n}\r\n\r\n.drci-micrositio .hero-content{\r\n    position:relative;\r\n    z-index:10;\r\n    width:90%;\r\n    max-width:900px;\r\n    text-align:center;\r\n    color:white;\r\n}\r\n\r\n.drci-micrositio .badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:10px 18px;\r\n    background:rgba(255,255,255,0.10) !important;\r\n    border:1px solid rgba(255,255,255,0.12);\r\n    border-radius:100px;\r\n    backdrop-filter:blur(12px);\r\n    margin-bottom:22px;\r\n}\r\n\r\n.drci-micrositio .badge span{\r\n    font-size:.9rem !important;\r\n    font-weight:600 !important;\r\n    color:white !important;\r\n    letter-spacing:.3px;\r\n}\r\n\r\n.drci-micrositio .hero-content h2{\r\n    font-family:'Montserrat', sans-serif !important;\r\n    font-size:clamp(2.2rem, 4vw, 3.4rem) !important;\r\n    font-weight:800 !important;\r\n    line-height:1.2 !important;\r\n    color:#ffffff !important;\r\n}\r\n\r\n/* =========================================\r\n   CONTENIDO\r\n========================================= */\r\n\r\n.drci-micrositio .section{\r\n    padding:90px 0;\r\n}\r\n\r\n.drci-micrositio .container{\r\n    width:90%;\r\n    max-width:1200px;\r\n    margin:auto;\r\n}\r\n\r\n.drci-micrositio .content-card{\r\n    background:#ffffff !important;\r\n    border-radius:22px;\r\n    box-shadow:0 10px 35px rgba(0, 31, 78, 0.10);\r\n    overflow:hidden;\r\n    border:1px solid rgba(0,0,0,0.03);\r\n    display:grid;\r\n    grid-template-columns:1.1fr .9fr;\r\n    align-items:stretch;\r\n}\r\n\r\n.drci-micrositio .content-text{\r\n    padding:54px;\r\n    display:flex;\r\n    align-items:center;\r\n}\r\n\r\n.drci-micrositio .content-text p{\r\n    color:#3a3a3a;\r\n    line-height:1.9;\r\n    font-size:1.05rem;\r\n    text-align:justify;\r\n}\r\n\r\n.drci-micrositio .content-image{\r\n    position:relative;\r\n    min-height:340px;\r\n}\r\n\r\n.drci-micrositio .content-image img{\r\n    width:100%;\r\n    height:100%;\r\n    object-fit:cover;\r\n    display:block;\r\n}\r\n\r\n/* =========================================\r\n   RESPONSIVE\r\n========================================= */\r\n\r\n@media(max-width:900px){\r\n    .drci-micrositio .content-card{\r\n        grid-template-columns:1fr;\r\n    }\r\n    .drci-micrositio .content-image{\r\n        min-height:260px;\r\n        order:-1;\r\n    }\r\n    .drci-micrositio .content-text{\r\n        padding:34px;\r\n    }\r\n}\r\n\r\n@media(max-width:480px){\r\n    .drci-micrositio .hero{\r\n        padding:120px 0 50px;\r\n    }\r\n    .drci-micrositio .hero-content h2{\r\n        font-size:1.9rem !important;\r\n    