g" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="80" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">80%</text> </svg><span class="unl-ring-name">Uso eficiente</span><br><span class="unl-ring-name">del agua</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="61" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">61%</text> </svg><span class="unl-ring-name">Transporte</span><br><span class="unl-ring-name">sostenible</span></div><div class="unl-ring-item"><svg class="unl-ring-svg" viewbox="0 0 100 100"><circle class="unl-ring-track" cx="50" cy="50" r="40"></circle><circle class="unl-ring-bar" cx="50" cy="50" data-pct="88" r="40" transform="rotate(-90 50 50)"></circle><text class="unl-ring-pct" text-anchor="middle" x="50" y="55">88%</text> </svg><span class="unl-ring-name">Educación e</span><br><span class="unl-ring-name">investigación</span></div></div></div></div><!-- ===================== SECCIÓN 2: INICIATIVAS INTERNACIONALES ===================== --><div class="unl-init-section"><p><span class="unl-sost-eyebrow">Cooperación internacional</span></p><h2 class="unl-sost-h2">Iniciativas y concursos internacionales</h2><p class="unl-sost-sub">La UNL participa actualmente en las siguientes iniciativas internacionales orientadas a fortalecer su modelo de sostenibilidad institucional. [EDITAR: reemplazar nombres, descripciones y avance real]</p><div class="unl-init-grid"><!-- Iniciativa 1: motivo de planta / ramificación --><div class="unl-init-card unl-fade-up"><svg class="unl-init-motif unl-motif-planta" aria-hidden="true" viewbox="0 0 100 100"><path d="M50 95V50" fill="none" stroke-width="2"></path><path d="M50 70C38 66 30 56 30 44" fill="none" stroke-width="2"></path><path d="M50 60C62 56 70 46 70 34" fill="none" stroke-width="2"></path><path d="M50 50C41 45 36 36 37 26" fill="none" stroke-width="2"></path><circle cx="30" cy="44" r="4"></circle><circle cx="70" cy="34" r="4"></circle><circle cx="37" cy="26" r="4"></circle><circle cx="50" cy="18" r="5"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 1</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 1]</h3><p class="unl-init-desc">[EDITAR: descripción breve — qué es la iniciativa, quién la convoca y qué compromiso concreto asumió la UNL al participar].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="45">&nbsp;</div></div></div></div><!-- Iniciativa 2: motivo de átomo / órbitas --><div class="unl-init-card unl-agua unl-fade-up"><svg class="unl-init-motif unl-motif-atomo" aria-hidden="true" fill="none" stroke-width="1.6" viewbox="0 0 100 100"><ellipse cx="50" cy="50" rx="42" ry="16"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(60 50 50)"></ellipse><ellipse cx="50" cy="50" rx="42" ry="16" transform="rotate(120 50 50)"></ellipse><circle cx="50" cy="50" fill="currentColor" r="6" stroke="none"></circle><circle cx="92" cy="50" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="78" fill="currentColor" r="3" stroke="none"></circle><circle cx="26" cy="22" fill="currentColor" r="3" stroke="none"></circle></svg><div class="unl-init-top"><span class="unl-init-badge">Iniciativa 2</span> <span class="unl-init-year">[EDITAR año inicio]</span></div><h3 class="unl-init-name">[EDITAR: nombre de la iniciativa internacional 2]</h3><p class="unl-init-desc">[EDITAR: descripción breve — objetivo del concurso o red, alcance geográfico y en qué consiste la participación de la UNL].</p><div class="unl-init-progress-row"><div class="unl-init-progress-label"><span>Avance del compromiso</span><span class="unl-init-pct">0%</span></div><div class="unl-init-bar-track"><div class="unl-init-bar-fill" data-pct="62">&nbsp;</div></div></div></div></div></div></section><script>\r\n(function(){\r\n  var root = document.getElementById('unl-rankings-iniciativas');\r\n  if(!root) return;\r\n  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\r\n  function animateCount(el){\r\n    var target = parseInt(el.getAttribute('data-target'), 10) || 0;\r\n    if(reduce){ el.textContent = target; return; }\r\n    var start = 0, dur = 1400, t0 = null;\r\n    function step(ts){\r\n      if(!t0) t0 = ts;\r\n      var p = Math.min((ts - t0) / dur, 1);\r\n      el.textContent = Math.round(start + (target - start) * p);\r\n      if(p < 1) requestAnimationFrame(step);\r\n    }\r\n    requestAnimationFrame(step);\r\n  }\r\n  function animateRing(circle){\r\n    var pct = parseFloat(circle.getAttribute('data-pct')) || 0;\r\n    var offset = 251 - (251 * pct / 100);\r\n    circle.style.strokeDashoffset = offset;\r\n  }\r\n  function animateBar(bar){\r\n    var pct = parseFloat(bar.getAttribute('data-pct')) || 0;\r\n    bar.style.width = pct + '%';\r\n    var label = bar.closest('.unl-init-progress-row').querySelector('.unl-init-pct');\r\n    if(label) label.textContent = pct + '%';\r\n  }\r\n  var io = new IntersectionObserver(function(entries){\r\n    entries.forEach(function(entry){\r\n      if(!entry.isIntersecting) return;\r\n      var el = entry.target;\r\n      el.classList.add('unl-inview');\r\n      el.querySelectorAll('.unl-rank-count').forEach(animateCount);\r\n      el.querySelectorAll('.unl-ring-bar').forEach(animateRing);\r\n      el.querySelectorAll('.unl-init-bar-fill').forEach(animateBar);\r\n      io.unobserve(el);\r\n    });\r\n  }, { threshold: .3 });\r\n  root.querySelectorAll('.unl-fade-up, .unl-rank-card').forEach(function(el){\r\n    io.observe(el);\r\n  });\r\n})();\r\n</script>	full_html
texto_libre	0	116	1421	en	0	<style type="text/css">\r\n  /* Contenedor principal de la sección */\r\n  .unl-showcase-box {\r\n    max-width: 900px;\r\n    margin: 3rem auto;\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);\r\n    overflow: hidden;\r\n    border: 1px solid #eaeaea;\r\n    font-family: 'Inter', Arial, sans-serif;\r\n  }\r\n\r\n  /* Cabecera con título y botón */\r\n  .unl-showcase-header {\r\n    padding: 2.5rem 2rem;\r\n    text-align: center;\r\n    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);\r\n    border-bottom: 1px solid #dee2e6;\r\n  }\r\n\r\n  .unl-showcase-header h3 {\r\n    margin: 0 0 15px 0;\r\n    color: #93000b; /* Rojo institucional */\r\n    font-size: 1.8rem;\r\n    font-weight: 800;\r\n    text-transform: uppercase;\r\n    letter-spacing: 0.5px;\r\n  }\r\n\r\n  /* Diseño del botón de Looker Studio */\r\n  .unl-btn-dashboard {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 10px;\r\n    background: #93000b;\r\n    color: #ffffff !important;\r\n    padding: 12px 28px;\r\n    border-radius: 30px;\r\n    text-decoration: none;\r\n    font-weight: 600;\r\n    font-size: 1rem;\r\n    transition: all 0.3s ease;\r\n    box-shadow: 0 4px 15px rgba(147, 0, 11, 0.25);\r\n  }\r\n\r\n  .unl-btn-dashboard:hover {\r\n    background: #7a0009; /* Rojo más oscuro al pasar el cursor */\r\n    transform: translateY(-3px);\r\n    box-shadow: 0 6px 20px rgba(147, 0, 11, 0.4);\r\n    text-decoration: none;\r\n  }\r\n\r\n  .unl-btn-dashboard svg {\r\n    width: 20px;\r\n    height: 20px;\r\n    stroke: currentColor;\r\n  }\r\n\r\n  /* Contenedor responsivo para el video de YouTube (Relación 16:9) */\r\n  .unl-video-responsive {\r\n    position: relative;\r\n    padding-bottom: 56.25%; /* Proporción exacta de 16:9 */\r\n    height: 0;\r\n    overflow: hidden;\r\n    background: #000000;\r\n  }\r\n\r\n  .unl-video-responsive iframe {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    border: 0;\r\n  }\r\n</style><div class="unl-showcase-box"><!-- CABECERA Y BOTÓN --><div class="unl-showcase-header"><h3>Intercambios Virtuales</h3><!-- Icono de Dashboard SVG --><a class="unl-btn-dashboard" href="https://lookerstudio.google.com/u/0/reporting/2c880b6f-a4e8-4ded-bcd6-d4769bdd5dbd/page/UbxCD" target="_blank" title="Abrir reporte interactivo"><svg viewbox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="3" y1="9" x2="21" y2="9"></line><line x1="9" y1="21" x2="9" y2="9"></line></svg></a><p><a class="unl-btn-dashboard" href="https://lookerstudio.google.com/u/0/reporting/2c880b6f-a4e8-4ded-bcd6-d4769bdd5dbd/page/UbxCD" target="_blank" title="Abrir reporte interactivo">Ver Dashboard Interactivo&nbsp;</a></p></div><!-- VIDEO YOUTUBE RESPONSIVO --><div class="unl-video-responsive"><iframe src="https://www.youtube.com/embed/a9XViE3Ayc8?si=sD6zEXQiwkayKCef&amp;controls=0" title="YouTube video player" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen=""></iframe></div></div>	full_html
