r"><a href="mailto:maria.e.ordonez@unl.edu.ec"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">maria.e.ordonez@unl.edu.ec</span></a></p></td></tr><tr><td style="border-color:black;padding:0.1px;width:170px;"><ul><li style="margin-bottom:11px;" data-list-item-id="e6afd44c4a2a3fd24d171244396890439"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Beverly Fabiana Aguilera Enriquez</span></li></ul></td><td style="border-color:black;padding:0.1px;width:132px;"><p class="text-align-center"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">UNL</span></p></td><td style="border-color:black;padding:0.1px;width:132px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Estudiante de Medicina</span></td><td style="border-color:black;padding:0.1px;width:208px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Manejo de hojas de cálculo</span></td><td style="border-color:black;padding:0.1px;width:265px;"><p class="text-align-center"><a href="mailto:beverly.aguilera@unl.edu.ec"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">beverly.aguilera@unl.edu.ec</span></a></p></td></tr><tr><td style="border-color:black;padding:0.1px;width:170px;"><ul><li style="margin-bottom:11px;" data-list-item-id="e851083aa2a29ee8030a1a84ff7184985"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Daniela Lisbeth Pinta Contento</span></li></ul></td><td style="border-color:black;padding:0.1px;width:132px;"><p class="text-align-center"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">UNL</span></p></td><td style="border-color:black;padding:0.1px;width:132px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Estudiante de Medicina</span></td><td style="border-color:black;padding:0.1px;width:208px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Manejo de hojas de cálculo</span></td><td style="border-color:black;padding:0.1px;width:265px;"><p class="text-align-center"><a href="mailto:daniela.pinta@unl.edu.ec"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">daniela.pinta@unl.edu.ec</span></a></p></td></tr><tr><td style="border-color:black;padding:0.1px;width:170px;"><ul><li style="margin-bottom:11px;" data-list-item-id="e320c4fc702bd18cf11e136370b948979"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Max González Merizalde</span></li></ul></td><td style="border-color:black;padding:0.1px;width:132px;"><p class="text-align-center"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">CAPRUJ</span></p></td><td style="border-color:black;padding:0.1px;width:132px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Magíster en Salud Pública.</span></td><td style="border-color:black;padding:0.1px;width:208px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Salud Pública.</span></td><td style="border-color:black;padding:0.1px;width:265px;"><p class="text-align-center"><a href="mailto:max.vgonzalez@gmail.com"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">max.vgonzalez@gmail.com</span></a></p></td></tr><tr><td style="border-color:black;padding:0.1px;width:170px;"><ul><li style="margin-bottom:11px;" data-list-item-id="e8f4d0e02e2df61b05269a8d0ee9d876b"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Gina Cueva Tutillo</span></li></ul></td><td style="border-color:black;padding:0.1px;width:132px;"><p class="text-align-center"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">MSP</span></p></td><td style="border-color:black;padding:0.1px;width:132px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Magister en Gerencia de Salud.</span></td><td style="border-color:black;padding:0.1px;width:208px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">Vigilancia Epidemiológica.</span></td><td style="border-color:black;padding:0.1px;width:265px;"><p class="text-align-center"><a href="mailto:ginacuevatutillo@gmail.com"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:10.0pt;line-height:normal;">ginacuevatutillo@gmail.com</span></a></p></td></tr></tbody></table>	full_html
texto_libre	0	157	1651	en	0	<style type="text/css">*{margin:0;padding:0;box-sizing:border-box;}\r\n:root{\r\n  --navy:#1A2E4A;\r\n  --navy2:#F0F4F8;\r\n  --gold:#B08800;\r\n  --gold2:#8A6A00;\r\n  --white:#1A2E4A;\r\n  --muted:#637082;\r\n  --border:rgba(160,120,0,0.20);\r\n}\r\nhtml,body{background:#F5F7FA;color:#1A2E4A;font-family:'Inter',sans-serif;overflow-x:hidden;scroll-behavior:smooth;}\r\n\r\n/* ── CANVAS PARTÍCULAS ─── */\r\n#particles{position:fixed;inset:0;z-index:0;pointer-events:none;}\r\n\r\n/* ── ORB GLOWS ─── */\r\n.orb{position:fixed;border-radius:50%;pointer-events:none;z-index:1;}\r\n.orb1{width:700px;height:700px;background:radial-gradient(circle,rgba(176,136,0,.09),transparent 68%);top:-160px;right:-140px;}\r\n.orb2{width:560px;height:560px;background:radial-gradient(circle,rgba(176,136,0,.06),transparent 68%);bottom:-140px;left:-140px;}\r\n\r\n/* ── DIAGONAL LINES BG ─── */\r\n.diag{position:fixed;inset:0;z-index:0;pointer-events:none;\r\n  background-image:repeating-linear-gradient(\r\n    -55deg,\r\n    transparent,\r\n    transparent 40px,\r\n    rgba(160,120,0,.045) 40px,\r\n    rgba(160,120,0,.045) 41px\r\n  );\r\n}\r\n\r\n/* ── NAVBAR ─── */\r\n.nav{position:sticky;top:0;z-index:100;display:flex;justify-content:space-between;align-items:center;padding:18px 48px;border-bottom:1px solid var(--border);background:rgba(245,247,250,.93);backdrop-filter:blur(24px);}\r\n.nav-logo{font-size:11px;font-weight:800;letter-spacing:5px;text-transform:uppercase;color:#B08800;}\r\n.nav-links{display:flex;gap:28px;}\r\n.nav-links a{color:#637082;text-decoration:none;font-size:13px;font-weight:600;letter-spacing:.5px;transition:.2s;}\r\n.nav-links a:hover{color:#1A2E4A;}\r\n.nav-cta{background:#B08800;color:#FFFFFF;font-size:12px;font-weight:800;padding:10px 22px;border-radius:7px;text-decoration:none;letter-spacing:.5px;transition:.2s;}\r\n.nav-cta:hover{background:#8A6A00;transform:translateY(-1px);}\r\n\r\n/* ── HERO ─── */\r\n.hero{position:relative;z-index:10;display:grid;grid-template-columns:1fr 1fr;min-height:calc(100vh - 65px);max-width:1300px;margin:0 auto;padding:72px 48px;gap:40px;}\r\n.hero-left{display:flex;flex-direction:column;justify-content:center;padding-right:32px;}\r\n\r\n.tag{display:inline-flex;align-items:center;gap:8px;background:#FFF6CC;border:1px solid rgba(160,120,0,.25);border-radius:5px;padding:8px 14px;font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#B08800;margin-bottom:28px;width:fit-content;}\r\n.tag-dot{width:6px;height:6px;background:#B08800;border-radius:50%;animation:blink 1.5s ease-in-out infinite;}\r\n@keyframes blink{0%,100%{opacity:1;}50%{opacity:.2;}}\r\n\r\n.eyebrow{font-size:13px;font-weight:600;color:#637082;letter-spacing:1px;margin-bottom:10px;text-transform:uppercase;}\r\nh1{font-family:'Playfair Display',serif;font-size:clamp(44px,5.6vw,78px);font-weight:700;line-height:1.03;margin-bottom:10px;}\r\nh1 em{font-style:italic;color:#B08800;}\r\n.year-badge{display:inline-block;background:#B08800;color:#FFFFFF;font-family:'Inter',sans-serif;font-size:clamp(26px,3.6vw,50px);font-weight:900;padding:4px 20px;border-radius:7px;margin-bottom:28px;letter-spacing:-1px;}\r\n\r\n.desc{font-size:16px;line-height:1.78;color:#637082;max-width:500px;margin-bottom:38px;}\r\n.desc strong{color:#1A2E4A;font-weight:700;}\r\n\r\n.btn-row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:44px;}\r\n.btn-gold{background:#B08800;color:var(--navy);font-size:14px;font-weight:800;padding:17px 30px;border-radius:9px;text-decoration:none;letter-spacing:.3px;transition:.25s;display:inline-flex;align-items:center;gap:8px;}\r\n.btn-gold:hover{background:#8A6A00;transform:translateY(-3px);box-shadow:0 12px 36px rgba(160,120,0,.20);}\r\n.btn-outline{background:transparent;color:#1A2E4A;font-size:14px;font-weight:600;padding:17px 30px;border-radius:9px;text-decoration:none;border:1px solid rgba(26,46,74,.22);transition:.25s;display:inline-flex;align-items:center;gap:8px;}\r\n.btn-outline:hover{border-color:#B08800;color:#B08800;transform:translateY(-3px);}\r\n\r\n.dates{display:flex;gap:12px;flex-wrap:wrap;}\r\n.date-item{display:flex;flex-direction:column;gap:4px;padding:14px 18px;background:#FFFFFF;border:1px solid rgba(160,120,0,.18);border-radius:9px;transition:.2s;}\r\n.date-item:hover{background:#FFF6CC;}\r\n.date-label{font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#B08800;}\r\n.date-value{font-size:15px;font-weight:700;color:#1A2E4A;}\r\n\r\n/* ── HERO IMAGEN ─── */\r\n.hero-right{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;}\r\n.img-frame{position:relative;width:100%;max-width:460px;}\r\n.img-accent{position:absolute;top:-18px;right:-18px;width:100%;height:100%;background:#B08800;border-radius:16px;opacity:.08;}\r\n.img-accent2{position:absolute;bottom:-12px;left:-12px;width:60%;height:60%;border:1px solid rgba(160,120,0,.25);border-radius:12px;}\r\n.img-photo{width:100%;border-radius:14px;overflow:hidden;position:relative;z-index:2;background:#D0D8E4;aspect-ratio:3/4;}\r\n/* FOTO MÁS CLARA: sin grayscale, brightness alto, overlay muy suave */\r\n.img-photo img{\r\n  width:100%;height:100%;object-fit:cover;object-position:center top;display:block;\r\n  filter:brightness(1.15) contrast(1.05) saturate(0.25);\r\n  transition:transform 6s ease;\r\n}\r\n.img-photo:hover img{transform:scale(1.03);}\r\n/* overlay solo abajo, muy tenue para no tapar la cara */\r\n.img-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(26,46,74,.72) 0%,rgba(26,46,74,.08) 45%,transparent 70%);border-radius:14px;}\r\n.img-caption{position:absolute;bottom:0;left:0;right:0;padding:28px;z-index:3;}\r\n.cap-label{font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#F5C518;margin-bottom:4px;}\r\n.cap-sub{font-size:14px;font-weight:700;color:#FFFFFF;}\r\n\r\n/* borde brillante animado en la foto */\r\n.img-photo::after{\r\n  content:'';position:absolute;inset:0;border-radius:14px;z-index:4;pointer-events:none;\r\n  border:1px solid rgba(160,120,0,.28);\r\n  animation:borderPulse 3s ease-in-out infinite;\r\n}\r\n@keyframes borderPulse{0%,100%{border-color:rgba(160,120,0,.28);}50%{border-color:rgba(160,120,0,.55);}}\r\n\r\n/* ── PREMIOS ─── */\r\n.prizes{background:#ECEEF2;border-top:1px solid rgba(160,120,0,.15);border-bottom:1px solid rgba(160,120,0,.15);padding:60px 48px;position:relative;z-index:10;}\r\n.prizes-inner{max-width:1300px;margin:0 auto;}\r\n.section-header{display:flex;align-items:center;gap:14px;margin-bottom:32px;}\r\n.section-header h2{font-size:13px;font-weight:800;letter-spacing:4px;text-transform:uppercase;color:#B08800;white-space:nowrap;}\r\n.h-line{flex:1;height:1px;background:rgba(160,120,0,.20);}\r\n.prizes-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;}\r\n.prize-card{background:#FFFFFF;border:1px solid rgba(160,120,0,.18);border-radius:14px;padding:28px;position:relative;overflow:hidden;transition:.25s;}\r\n.prize-card:hover{transform:translateY(-4px);border-color:rgba(160,120,0,.4);}\r\n.prize-card.first{border-color:#B08800;}\r\n.prize-card.first::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:#B08800;}\r\n.prize-bg-num{position:absolute;top:-8px;right:12px;font-size:88px;font-weight:900;color:rgba(160,120,0,.08);line-height:1;user-select:none;pointer-events:none;}\r\n.p-rank{font-size:10px;font-weight:800;letter-spacing:3px;text-transform:uppercase;color:#B08800;margin-bottom:10px;}\r\n.p-amount{font-size:38px;font-weight:900;color:#1A2E4A;letter-spacing:-1px;margin-bottom:4px;}\r\n.p-amount span{font-size:14px;font-weight:400;color:#637082;}\r\n.p-items{list-style:none;margin-top:16px;}\r\n.p-items li{font-size:13px;color:#637082;padding:6px 0;border-bottom:1px solid rgba(26,46,74,.07);display:flex;gap:8px;align-items:flex-start;line-height:1.5;}\r\n.p-items li:last-child{border-bottom:none;}\r\n.p-items li::before{content:"·";color:#B08800;font-weight:900;flex-shrink:0;}\r\n\r\n/* ── INFO BAR ─── */\r\n.infobar{max-width:1300px;margin:0 auto;padding:36px 48px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;position:relative;z-index:10;}\r\n.info-item{display:flex;align-items:center;gap:14px;}\r\n.info-icon{width:42px;height:42px;background:#FFF6CC;border:1px solid rgba(160,120,0,.22);border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;}\r\n.info-label{font-size:10px;color:#637082;font-weight:700;letter-spacing:2px;text-transform:uppercase;}\r\n.info-value{font-size:14px;font-weight:700;color:#1A2E4A;margin-top:2px;}\r\n.sep{width:1px;height:44px;background:rgba(160,120,0,.18);}\r\n\r\n/* ── FOOTER ─── */\r\n.org-bar{display:flex;justify-content:center;align-items:center;gap:16px;padding:28px 48px 44px;border-top:1px solid rgba(160,120,0,.15);position:relative;z-index:10;background:#F5F7FA;}\r\n.org-pill{display:flex;align-items:center;gap:10px;padding:10px 20px;background:#FFFFFF;border:1px solid rgba(160,120,0,.18);border-radius:9px;transition:.2s;}\r\n.org-pill:hover{border-color:#B08800;}\r\n.org-logo{width:32px;height:32px;background:#FFF6CC;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:8px;font-weight:900;color:#8A6A00;letter-spacing:1px;}\r\n.org-name{font-size:12px;font-weight:600;color:#637082;}\r\n\r\n/* ── FADE IN ─── */\r\n.fade-up{opacity:0;transform:translateY(28px);transition:opacity .85s cubic-bezier(.2,.8,.2,1),transform .85s cubic-bezier(.2,.8,.2,1);}\r\n.fade-up.in{opacity:1;transform:translateY(0);}\r\n\r\n/* ── SECCIONES GENERALES ─── */\r\n.section{position:relative;z-index:10;padding:64px 48px;}\r\n.section-inner{max-width:1300px;margin:0 auto;}\r\n.section.alt{background:#ECEEF2;}\r\n.section-title{font-size:13px;font-weight:800;letter-spacing:4px;text-transform:uppercase;color:#B08800;margin-bottom:28px;display:flex;align-items:center;gap:12px;}\r\n.section-title::after{content:'';flex:1;height:1px;background:rgba(160,120,0,.20);}\r\n\r\n/* ── PARTICIPANTES ─── */\r\n.part-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;}\r\n.part-card{background:#FFFFFF;border:1px solid rgba(160,120,0,.18);border-radius:12px;padding:24px 28px;display:flex;gap:16px;align-items:flex-start;}\r\n.part-icon{width:40px;height:40px;background:#FFF6CC;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;}\r\n.part-text{font-size:15px;color:#3A4E62;line-height:1.65;}\r\n\r\n/* ── MODALIDAD ─── */\r\n.modal-list{display:flex;flex-direction:column;gap:14px;}\r\n.modal-item{background:#FFFFFF;border:1px solid rgba(160,120,0,.15);border-radius:12px;padding:20px 24px;display:flex;gap:18px;align-items:flex-start;}\r\n.modal-num{width:36px;height:36px;background:#B08800;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:900;color:#FFFFFF;flex-shrink:0;}\r\n.modal-body{}\r\n.modal-label{font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#B08800;margin-bottom:4px;}\r\n.modal-desc{font-size:15px;color:#3A4E62;line-height:1.6;}\r\n.modal-item.highlight{border-color:#B08800;background:#FFFBF0;}\r\n\r\n/* ── TEMÁTICAS ─── */\r\n.temas-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;}\r\n.tema-item{background:#FFFFFF;border:1px solid rgba(160,120,0,.15);border-radius:10px;padding:16px 20px;display:flex;gap:14px;align-items:center;transition:.2s;}\r\n.tema-item:hover{border-color:#B08800;background:#FFFBF0;transform:translateX(4px);}\r\n.tema-n{font-size:12px;font-weight:800;color:#B08800;min-width:22px;}\r\n.tema-txt{font-size:14px;color:#3A4E62;line-height:1.5;}\r\n\r\n/* ── DESCARGA / CONTACTO ─── */\r\n.bottom-row{display:grid;grid-template-columns:1fr 1fr;gap:20px;}\r\n.download-card{background:#1A2E4A;border-radius:14px;padding:36px;display:flex;flex-direction:column;gap:16px;}\r\n.download-card h3{font-size:18px;font-weight:800;color:#FFFFFF;line-height:1.3;}\r\n.download-card p{font-size:14px;color:rgba(255,255,255,.65);line-height:1.6;}\r\n.download-btn{display:inline-flex;align-items:center;gap:10px;background:#B08800;color:#FFFFFF;font-size:14px;font-weight:800;padding:15px 26px;border-radius:9px;text-decoration:none;width:fit-content;transition:.2s;}\r\n.download-btn:hover{background:#8A6A00;transform:translateY(-2px);}\r\n.contact-card{background:#FFFFFF;border:1px solid rgba(160,120,0,.18);border-radius:14px;padding:36px;display:flex;flex-direction:column;gap:16px;}\r\n.contact-card h3{font-size:18px;font-weight:800;color:#1A2E4A;}\r\n.contact-card p{font-size:14px;color:#637082;line-height:1.6;}\r\n.contact-email{display:inline-flex;align-items:center;gap:10px;background:#FFF6CC;border:1px solid rgba(160,120,0,.25);color:#8A6A00;font-size:14px;font-weight:700;padding:14px 22px;border-radius:9px;text-decoration:none;width:fit-content;transition:.2s;}\r\n.contact-email:hover{background:#FFF0A0;border-color:#B08800;}\r\n\r\n@media(max-width:900px){\r\n  .part-grid,.temas-grid,.bottom-row{grid-template-columns:1fr;}\r\n  .section{padding:44px 28px;}\r\n}\r\n/* ── RESPONSIVE ─── */\r\n@media(max-width:1060px){\r\n  .hero{grid-template-columns:1fr;padding:52px 28px;}\r\n  .hero-left{padding-right:0;}\r\n  .hero-right{align-items:flex-start;}\r\n  .img-frame{max-width:380px;}\r\n  .prizes-grid{grid-template-columns:1fr;}\r\n  .prizes{padding:44px 28px;}\r\n  .infobar{padding:28px;}\r\n}\r\n@media(max-width:700px){\r\n  .nav{padding:14px 20px;}\r\n  .nav-links,.nav-cta{display:none;}\r\n  .infobar{flex-direction:column;align-items:flex-start;}\r\n  .sep{display:none;}\r\n  .org-bar{flex-direction:column;padding:24px 20px 36px;}\r\n}\r\n</style><!-- BACKGROUNDS --><p><canvas id="particles"></canvas></p><div class="diag">Inscripciones abiertas</div><!-- HERO --><section class="hero" id="que-es"><div class="hero-left"><div class="eyebrow fade-up">I Concurso Nacional Interuniversitario de Oratoria</div><h1 class="fade-up">Tribuna<br><em>por la Paz</em></h1><div class="year-badge fade-up">2026</div><p class="desc fade-up">La voz de una generación llamada a construir un mundo mejor.<br><strong>Estudiantes de todas las universidades del Ecuador</strong> en cualquier modalidad de tercer nivel.</p><div class="btn-row fade-up"><a class="btn-gold" href="https://forms.gle/GrEpz2rL5ETHRy2s7">INSCRIBIRME AHORA →</a> <a class="btn-outline" href="#premios">Ver premios</a></div><div class="dates fade-up"><div class="date-item"><span class="date-label">Inscripciones</span> <span class="date-value">Hasta 18 sep</span></div><div class="date-item"><span class="date-label">Semifinal</span> <span class="date-value">29 sep 2026</span></div><div class="date-item"><span class="date-label">Final</span> <span class="date-value">30 sep 2026</span></div></div></div><div class="hero-right fade-up" id="heroRight"><div class="img-frame"><div class="img-accent">&nbsp;</div><div class="img-accent2">&nbsp;</div><div class="img-photo"><img src="https://unl.edu.ec/sites/default/files/2026-06/Tribuna.jpg" alt="Oradora en el escenario" id="heroImg" onerror="this.parentElement.style.background=&apos;#13243A&apos;"><div class="img-overlay">&nbsp;</div><div class="img-caption"><div class="cap-label">Loja · Ecuador</div><div class="cap-sub">Universidad Nacional de Loja</div></div></div></div></div></section><!-- PREMIOS --><section class="prizes" id="premios"><div class="prizes-inner"><div class="section-header"><p><span style="color:#B08800;font-size:20px;">★</span></p><h2>Premios</h2><div class="h-line">&nbsp;</div></div><div class="prizes-grid"><div class="prize-card first fade-up"><div class="prize-bg-num">1</div><div class="p-rank">Primer lugar</div><div class="p-amount">$1.000 <span>USD</span></div><ul class="p-items"><li data-list-item-id="eb9582cfd8271be4621330ae79a6e5e82">Beca cursos educación continua — UNL</li><li data-list-item-id="eff776c3b771d74b79bb48069396a6120">Colección Obras completas de Benjamín Carrión</li><li data-list-item-id="e126fa3415e942521f98a3f0c21ca4262">Medalla y diploma</li></ul></div><div class="prize-card fade-up"><div class="prize-bg-num">2</div><div class="p-rank">Segundo lugar</div><div class="p-amount">$600 <span>USD</span></div><ul class="p-items"><li data-list-item-id="ef280a643adb4790d89eda6cf73e21b14">Beca completa — Escuela de Formación Política (CAJE)</li><li data-list-item-id="e0aac08c7718fc5d2653188a85b5fa4e0">Colección Obras completas de Benjamín Carrión</li><li data-list-item-id="ea77d4576edcff0958e818db1a910a6a5">Medalla y diploma</li></ul></div><div class="prize-card fade-up"><div class="prize-bg-num">3</div><div class="p-rank">Tercer lugar</div><div class="p-amount">$400 <span>USD</span></div><ul class="p-items"><li data-list-item-id="e04ecd46b6cb8b0d62f1ebe77b7f784e8">Beca matrícula — "¿Cómo Hablar en Público?" (CCE Núcleo Loja)</li><li data-list-item-id="e3bf93d73775e4aad8f8bdfd6a9773ce3">Colección Obras completas de Benjamín Carrión</li><li data-list-item-id="ed06f1c9feb9dd29921f30e8e7cdda173">Medalla y diploma</li></ul></div></div></div></section><!-- INFO BAR --><div class="infobar"><div class="info-item"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path> <circle cx="9" cy="7" r="4"></circle> <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path> <path d="M16 3.13a4 4 0 0 1 0 7.75"></path> </svg><div><div class="info-label">¿Quiénes participan?</div><div class="info-value">Estudiantes universitarios de todo Ecuador</div></div></div><div class="sep">&nbsp;</div><div class="info-item"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <rect height="18" rx="2" ry="2" width="18" x="3" y="4"></rect> <line x1="16" x2="16" y1="2" y2="6"></line> <line x1="8" x2="8" y1="2" y2="6"></line> <line x1="3" x2="21" y1="10" y2="10"></line> </svg><div><div class="info-label">Cierre inscripciones</div><div class="info-value">18 de septiembre de 2026</div></div></div><div class="sep">&nbsp;</div><div class="info-item"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <path d="M21 10c0 7-9 13-9 13S3 17 3 10a9 9 0 0 1 18 0z"></path> <circle cx="12" cy="10" r="3"></circle> </svg><div><div class="info-label">Lugar del evento</div><div class="info-value">Loja, Ecuador</div></div></div><div class="sep">&nbsp;</div><div class="info-item"><svg fill="#B08800" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon> </svg><div><div class="info-label">Premio total</div><div class="info-value">$5.000 USD en premios</div></div></div></div><!-- PARTICIPANTES --><section class="section" id="que-es"><div class="section-inner"><div class="section-title">¿Quiénes pueden participar?</div><div class="part-grid"><div class="part-card fade-up"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <path d="M22 10v6M2 10l10-5 10 5-10 5z"></path> <path d="M6 12v5c0 2 2 3 6 3s6-1 6-3v-5"></path> </svg><p class="part-text">Estudiantes de <strong>todas las universidades del Ecuador</strong> que cursen estudios de tercer nivel en cualquier modalidad.</p></div><div class="part-card fade-up"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <line x1="3" x2="21" y1="22" y2="22"></line> <line x1="6" x2="6" y1="18" y2="11"></line> <line x1="10" x2="10" y1="18" y2="11"></line> <line x1="14" x2="14" y1="18" y2="11"></line> <line x1="18" x2="18" y1="18" y2="11"></line> <polygon points="12 2 20 7 4 7"></polygon> </svg><p class="part-text">Cada universidad podrá inscribir hasta <strong>dos representantes</strong> debidamente acreditados.</p></div></div></div></section><!-- MODALIDAD --><section class="section alt" id="modalidad"><div class="section-inner"><div class="section-title">Modalidad del concurso</div><div class="modal-list"><div class="modal-item fade-up"><div class="modal-num">1</div><div class="modal-body"><div class="modal-label">Semifinal</div><div class="modal-desc">Los participantes presentarán un discurso sobre uno de los temas propuestos en las bases.</div></div></div><div class="modal-item fade-up"><div class="modal-num">2</div><div class="modal-body"><div class="modal-label">Final</div><div class="modal-desc">Los finalistas expondrán un discurso improvisado sobre un tema de actualidad nacional o internacional asignado por sorteo.</div></div></div><div class="modal-item highlight fade-up"><svg fill="none" height="20" stroke="#B08800" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"> <circle cx="12" cy="12" r="10"></circle> <polyline points="12 6 12 12 16 14"></polyline> </svg><div class="modal-body"><div class="modal-label">Tiempo de intervención</div><div class="modal-desc">Entre <strong>4 y 5 minutos</strong> por participante.</div></div></div></div></div></section><!-- TEMÁTICAS --><section class="section" id="tematicas"><div class="section-inner"><div class="section-title">Temáticas</div><div class="temas-grid"><div class="tema-item fade-up"><span class="tema-n">01</span><span class="tema-txt">La paz como responsabilidad de la ONU en el siglo XXI</span></div><div class="tema-item fade-up"><span class="tema-n">02</span><span class="tema-txt">Paz, soberanía y el derecho a la autodeterminación de los pueblos</span></div><div class="tema-item fade-up"><span class="tema-n">03</span><span class="tema-txt">Educación, paz y no violencia</span></div><div class="tema-item fade-up"><span class="tema-n">04</span><span class="tema-txt">La juventud por la paz en el mundo</span></div><div class="tema-item fade-up"><span class="tema-n">05</span><span class="tema-txt">Paz y justicia social</span></div><div class="tema-item fade-up"><span class="tema-n">06</span><span class="tema-txt">Hegemonía política mundial y genocidio</span></div><div class="tema-item fade-up"><span class="tema-n">07</span><span class="tema-txt">Diversidad cultural y convivencia pacífica en un mundo globalizado</span></div><div class="tema-item fade-up"><span class="tema-n">08</span><span class="tema-txt">Cultura de paz frente a la violencia global contemporánea</span></div><div class="tema-item fade-up"><span class="tema-n">09</span><span class="tema-txt">Desarrollo sostenible como camino hacia la paz duradera</span></div><div class="tema-item fade-up"><span class="tema-n">10</span><span class="tema-txt">Liderazgo moral y democracia para un mundo sin violencia</span></div></div></div></section><!-- DESCARGA Y CONTACTO --><section class="section alt" id="inscripciones"><div class="section-inner"><div class="bottom-row"><div class="download-card fade-up"><h3>Descarga las bases del concurso</h3><p>Consulta los requisitos, criterios de evaluación y demás disposiciones oficiales del concurso.</p><p><a class="download-btn" href="https://unl.edu.ec/sites/default/files/2026-06/BASESORATORIA.pdf">⬇ Descargar PDF</a></p></div><div class="contact-card fade-up"><h3>Más información</h3><p>¿Tienes dudas sobre el proceso de inscripción o las bases del concurso? Escríbenos y te responderemos a la brevedad.</p><p><a class="contact-email" href="mailto:arte.cultura@unl.edu.ec">✉ arte.cultura@unl.edu.ec</a></p></div></div></div></section><!-- ORGANIZADORES --><footer class="org-bar"><div class="org-pill"><img style="object-fit:contain;" src="https://unl.edu.ec/sites/default/files/2026-04/CCE.png" alt="CCE Benjamín Carrión" width="NaN" height="32"> <span class="org-name">CCE Benjamín Carrión</span></div><div class="org-pill"><img style="object-fit:contain;" src="https://unl.edu.ec/sites/default/files/2026-03/ESCUDO%20UNL%202025-12.png" alt="Universidad Nacional de Loja" width="NaN" height="32"><span class="org-name">Universidad Nacional de Loja</span></div></footer><script>\r\n(function(){\r\n\r\n  /* ── PARTÍCULAS ── */\r\n  const canvas = document.getElementById('particles');\r\n  const ctx = canvas.getContext('2d');\r\n  let W, H, pts = [];\r\n\r\n  function resize(){\r\n    W = canvas.width = window.innerWidth;\r\n    H = canvas.height = window.innerHeight;\r\n  }\r\n  resize();\r\n  window.addEventListener('resize', resize);\r\n\r\n  for(let i=0;i<55;i++){\r\n    pts.push({\r\n      x: Math.random()*window.innerWidth,\r\n      y: Math.random()*window.innerHeight,\r\n      r: Math.random()*1.4+0.3,\r\n      vx:(Math.random()-.5)*0.18,\r\n      vy:(Math.random()-.5)*0.18,\r\n      o: Math.random()*0.5+0.15\r\n    });\r\n  }\r\n\r\n  function drawParticles(){\r\n    ctx.clearRect(0,0,W,H);\r\n    pts.forEach(p=>{\r\n      ctx.beginPath();\r\n      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);\r\n      ctx.fillStyle=`rgba(160,120,0,${p.o * 0.5})`;\r\n      ctx.fill();\r\n      p.x+=p.vx; p.y+=p.vy;\r\n      if(p.x<0) p.x=W; if(p.x>W) p.x=0;\r\n      if(p.y<0) p.y=H; if(p.y>H) p.y=0;\r\n    });\r\n    requestAnimationFrame(drawParticles);\r\n  }\r\n  drawParticles();\r\n\r\n  /* ── PARALLAX SUAVE EN SCROLL ── */\r\n  const heroImg = document.getElementById('heroImg');\r\n  window.addEventListener('scroll', ()=>{\r\n    const s = window.scrollY;\r\n    if(heroImg) heroImg.style.transform = `translateY(${s*0.12}px) scale(1.05)`;\r\n  }, {passive:true});\r\n\r\n  /* ── FADE-UP OBSERVER ── */\r\n  const els = document.querySelectorAll('.fade-up');\r\n  const obs = new IntersectionObserver(entries=>{\r\n    entries.forEach((e,i)=>{\r\n      if(e.isIntersecting){\r\n        setTimeout(()=>e.target.classList.add('in'), i*80);\r\n        obs.unobserve(e.target);\r\n      }\r\n    });\r\n  },{threshold:.12});\r\n  els.forEach(el=>obs.observe(el));\r\n\r\n})();\r\n</script>	full_html
texto_libre	0	156	1695	es	0	<p>&nbsp;<img src="/sites/default/files/inline-images/Web-3.jpg" data-align="left" data-entity-uuid="d8d61238-f178-4d37-af99-47c75802060c" data-entity-type="file" alt="web 3" width="439" height="168"></p><table class="table" style="width:927px;" border="0" cellpadding="1" cellspacing="1"><tbody><tr><td class="text-align-justify" style="width:453px;"><p>En la Universidad Nacional de Loja, el arte no es solo una actividad: ¡es nuestra esencia! Desde mediados del siglo XX, hemos tejido una identidad cultural vibrante que hoy, más que nunca, se renueva con fuerza, creatividad y una visión hacia el futuro.</p><h4><strong>Un Legado que se Transforma</strong></h4><p>Gracias al impulso de la Coordinación de Vinculación con la Sociedad, la cultura se ha convertido en nuestro eje estratégico. No solo mantenemos viva la tradición de nuestros coros y grupos de teatro pioneros, sino que hemos potenciado cada rincón artístico con:</p><ul><li data-list-item-id="e95e009bad26bfdd8e6081897f36ca767"><strong>Nuevos horizontes:</strong> Revitalización de agrupaciones artísticas con vestuario e instrumentos de primer nivel.</li><li data-list-item-id="e87137b67c4ee152910e612b5fc1429fb"><strong>Espacios vivos:</strong> Creación de escenarios y laboratorios donde la comunidad universitaria es la verdadera protagonista.</li><li data-list-item-id="e897392c1af87aef957c1bc281e627a7f"><strong>Identidad local: </strong>Un ecosistema donde la música, la danza y las artes&nbsp;visuales dialogan directamente con la ciudadanía.</li></ul></td><td style="width:481px;"><img src="/sites/default/files/inline-images/Web-2.jpg" data-align="center" data-entity-uuid="8f6b83db-8ab9-4017-8eb8-a44460885e99" data-entity-type="file" alt="fvev" width="464" height="391"><p>&nbsp;</p></td></tr></tbody></table><img src="/sites/default/files/inline-images/Web4.jpg" data-align="center" data-entity-uuid="8aeec09b-2eac-444e-a327-985177de7c05" data-entity-type="file" alt="web 4" width="2078" height="472"><h3 class="text-align-center" data-path-to-node="8"><strong>Un Hito Histórico: "Pablo Palacio: un hombre sin rostro"</strong></h3><p data-path-to-node="9">Nuestra capacidad creativa alcanzó un nuevo nivel con el estreno de esta obra teatral magistral. ¡Un espectáculo de gran envergadura que puso a prueba nuestro talento!</p><ul data-path-to-node="10"><li data-list-item-id="e90ecba2a301b39cb6c173e887a0d097d"><p data-path-to-node="10,0,0"><b data-index-in-node="0" data-path-to-node="10,0,0"><strong>250 Artistas en Escena:</strong></b> Una producción masiva que unió a estudiantes, docentes y administrativos.</p></li><li data-list-item-id="ebb67fc0980faeace3a626d7987028c77"><p data-path-to-node="10,1,0"><b data-index-in-node="0" data-path-to-node="10,1,0"><strong>Estética Vanguardista:</strong></b> Una propuesta surrealista dirigida por el docente <b data-index-in-node="73" data-path-to-node="10,1,0"><strong>Paúl Chimbo Torres</strong></b>.</p></li><li data-list-item-id="ed88e908f43554bc77dedb81bf9372ec0"><p data-path-to-node="10,2,0"><b data-index-in-node="0" data-path-to-node="10,2,0"><strong>4 Actos de Pura Magia:</strong></b> Un recorrido profundo por la vida del célebre escritor lojano que conmovió a toda la ciudad.</p></li></ul><p>&nbsp;</p><p>&nbsp;</p><table class="table" style="width:880px;" border="0" cellpadding="1" cellspacing="1"><tbody><tr><td style="width:492px;"><img src="/sites/default/files/inline-images/Web5K.jpg" data-align="center" data-entity-uuid="dc9b3974-f016-4a4b-b2ff-240609b4397e" data-entity-type="file" alt="WEB 5K" width="560" height="472"><p class="text-align-justify">&nbsp;</p></td><td style="width:373px;"><h3 class="text-align-justify">5K UNL Actívate</h3><p class="text-align-justify">La cuarta edición de la 5K UNL Actívate volvió a demostrar que el deporte también une a la comunidad universitaria. Desde su inicio en 2022, esta carrera organizada por la Carrera de Actividad Física y Deporte sigue creciendo y, este 2025, reunió a cerca de 3 mil participantes, consolidándose como uno de los eventos deportivos más grandes de la UNL.</p><p class="text-align-justify">Deporte, comunidad y espíritu UNL en cada kilómetro.</p></td></tr></tbody></table><p>&nbsp;</p><p>&nbsp;</p><table class="table seccion-interna" style="width:100%;" border="0" cellpadding="0" cellspacing="0"><tbody><tr><td class="izquierda" style="width:311px;"><h3><strong>INFORMACIÓN</strong></h3><p><strong>Dirección:</strong><br>Coordinación de Vinculación con la Sociedad, Bloque 83, Piso 2, Universidad Nacional de Loja.</p><p><strong>Horario de atención:</strong><br>08h00 a 13h00 | 15h00 a 18h00</p><p><strong>Teléfono:</strong><br>(072) 546 808</p><p><strong>Mail:</strong><br><mail>vinculacion.sociedad@unl.edu.ec</mail></p></td><td class="derecha" style="width:954px;"><img src="/sites/default/files/inline-images/Web-frase.jpg" data-entity-uuid="5f53cf76-01b8-4f21-9f57-06a61ab62d45" data-entity-type="file" alt="web frase"></td></tr></tbody></table>	full_html
texto_libre	0	149	1709	es	0	<img src="/sites/default/files/inline-images/7093825.jpg" data-align="center" data-entity-uuid="3d5d3098-ab68-4123-9269-c0db48c3a20d" data-entity-type="file" alt="Vinculación collage" width="873" height="491"><p class="text-align-justify">&nbsp;</p><p data-end="387" data-start="78">La Vinculación con la Sociedad de la Universidad Nacional de Loja (UNL) conecta el conocimiento académico y científico con las necesidades reales de la comunidad. Trabajamos junto a la sociedad para aportar soluciones, impulsar la innovación y contribuir al desarrollo sostenible de la región sur del Ecuador.</p><p data-end="794" data-start="389">Lo hacemos a través de procesos formativos, experiencias prácticas de nuestros estudiantes y proyectos con enfoque social e innovador, que se complementan con acciones culturales, trabajo en red, relacionamiento y apoyo a graduados, y la transferencia y divulgación de conocimientos. Estas iniciativas se desarrollan de manera articulada y flexible, en coherencia con la naturaleza de la UNL y el ejercicio de su autonomía responsable.</p><h3 class="text-align-justify"><br>Nuestras líneas operativas:</h3><ul><li data-list-item-id="eab7871e3b0f1b8116e116325a196276d">Educación continua</li><li data-list-item-id="e92bed87f9750df1ad8a2cbdfd840d687">Prácticas preprofesionales</li><li data-list-item-id="ef2249d561a04ab851b3297829336c4bd">Proyectos de vinculación de servicios comunitarios o sociales, de innovación y de servicios especializados</li><li data-list-item-id="e6f512846b7379407a1333c0f1ddec34a">Redes académicas</li><li data-list-item-id="e3a7c8512f81b5c20857d6b83b49a330e">Alumni</li><li data-list-item-id="e67f2c68920b582d8aed12d421261ae14">Arte y cultura</li><li data-list-item-id="e8df0975eeb066e50b7350217da7b26e0">Transferencia y divulgación de conocimientos</li><li data-list-item-id="e4c921d2e66ab4fbad45f8e379205792d">Otras determinadas por la institución en correspondencia con su naturaleza y en ejercicio de su autonomía responsable</li></ul><p>&nbsp;</p><table class="table" style="width:100%;" border="0" cellpadding="0" cellspacing="0"><tbody><tr><td style="padding:5px;white-space:nowrap;width:32%;"><a href="/innovat" id="" rel="noreferrer noopener" target="_blank" title=""><img src="/sites/default/files/inline-images/innovaT_Mesa%20de%20trabajo%201-02.png" data-align="center" data-entity-uuid="f269e20b-f4e0-42e1-bacb-64fc08922adc" data-entity-type="file" alt="InnovaT"></a></td><td style="padding:5px;white-space:nowrap;width:1%;">&nbsp;</td><td style="padding:5px;white-space:nowrap;width:32%;"><a href="https://unl.edu.ec/consultorio-juridico"><img src="/sites/default/files/inline-images/Consultorio.png" data-align="center" data-entity-uuid="db1a115a-2db9-40df-9a8d-eb4ac55887b2" data-entity-type="file" alt="Vinculación 2"></a></td><td style="padding:5px;white-space:nowrap;width:1%;">&nbsp;</td><td style="padding:5px;white-space:nowrap;width:32%;"><a href="/hospital-veterinario" rel="noreferrer noopener"><img src="/sites/default/files/inline-images/hospital%20veterinario.png" data-align="center" data-entity-uuid="943f4a13-4b12-41b7-88fd-f18c55410239" data-entity-type="file" alt="Vinculación 2"></a></td></tr><tr><td class="text-align-center noticia_leer_mas" style="color:#FFF;"><strong>INNOVA-T</strong></td><td class="text-align-center">&nbsp;</td><td class="text-align-center noticia_leer_mas" style="color:#FFF;"><a href="https://unl.edu.ec/consultorio-juridico"><strong>CONSULTORIO</strong> <strong>JURÍDICO</strong></a></td><td class="text-align-center">&nbsp;</td><td class="text-align-center noticia_leer_mas" style="color:#FFF;"><strong>HOSPITAL</strong> <strong>VETERINARIO</strong></td></tr></tbody></table><p>&nbsp;</p><p><strong>Contáctenos</strong><br><strong>Email: </strong>vinculacion.sociedad@unl.edu.ec<br><strong>Atención:</strong> Lunes a viernes<br><strong>Horario: </strong>08:00 a 13:00 | 15:00 a 18:00</p><p>&nbsp;</p><img src="/sites/default/files/inline-images/MEMBRETADA%20UNL_Mesa%20de%20trabajo%201%20copia_3.png" data-align="center" data-entity-uuid="a13abe64-c345-448f-8e54-a1af797b4809" data-entity-type="file" alt="hhhh" width="338" height="52">	full_html
texto_libre	0	141	1724	es	0	<div class="topbar">&nbsp;</div><section class="hero"><div class="hero-inner"><h1>Repositorio de <span>Buena Gobernanza</span><br>e Innovación Pública</h1><p class="hero-desc">Espacio académico que reúne los principales debates, enfoques y herramientas sobre buena gobernanza, anclados a la innovación pública. Organizado en tres ejes temáticos: gobernanza colaborativa, e-governance y gobernanza en red.</p><div class="hero-acciones"><a class="btn-verde" href="#ejes"><svg fill="none" height="16" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20" width="16"><path d="M10 2v16M2 10h16"></path></svg>Explorar ejes temáticos </a><a class="btn-outline-blanco" href="#recursos"><svg fill="none" height="16" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20" width="16"><rect height="14" rx="2" width="12" x="4" y="3"></rect><path d="M7 8h6M7 11h6M7 14h4"></path></svg>Ver documentos</a></div></div></section><!-- STATS BAR --><div class="stats-bar"><div class="stats-inner"><div class="stat-item"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5z"></path><path d="M2 17l10 5 10-5M2 12l10 5 10-5"></path></svg><div><span class="stat-num">3</span> Ejes temáticos</div></div><div class="stat-item"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg><div><span class="stat-num">6+</span> Subtemas de investigación</div></div><div class="stat-item"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><line x1="12" x2="12" y1="8" y2="12"></line><line x1="12" x2="12.01" y1="16" y2="16"></line></svg><div><span class="stat-num">3</span> Tipos de recursos por sección</div></div><div class="stat-item"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 00-3-3.87"></path><path d="M16 3.13a4 4 0 010 7.75"></path></svg><div><span class="stat-num">UNL</span> Dirección de Investigación</div></div></div></div><!-- DESCRIPCIÓN GENERAL --><section class="section" id="descripcion"><div class="section-inner"><div class="section-label"><svg fill="none" stroke="currentColor" stroke-width="1.8" viewbox="0 0 16 16"><circle cx="8" cy="8" r="6"></circle><path d="M8 5v3l2 1.5"></path></svg>Sobre el repositorio</div><div class="divider">&nbsp;</div><h2 class="section-title">Ecosistema de gobernanza: los tres ejes</h2><p class="section-body">Este repositorio reúne los principales debates y enfoques sobre buena gobernanza, anclados a la innovación pública, organizados en tres ejes temáticos. El primero corresponde a la <strong>gobernanza colaborativa</strong>, centrada en las relaciones Estado–sociedad mediante procesos de participación, transparencia y construcción colectiva de políticas públicas. El segundo aborda la <strong>e-governance</strong>, entendida como la incorporación de tecnologías, datos abiertos y mecanismos de gobierno abierto para fortalecer la transparencia y la interacción gobierno–ciudadanía. El tercero se enfoca en la <strong>gobernanza en red</strong>, destacando la articulación entre múltiples actores, escalas e instituciones para comprender las nuevas formas de gobernar frente a problemas complejos.</p><!-- EJES CARDS --><div class="ejes-grid" id="ejes"><div class="eje-card azul"><div class="eje-icon azul"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><circle cx="12" cy="12" r="3"></circle><path d="M12 3c-1.2 5.4-5 9-9 9a9 9 0 0018 0c-4 0-7.8-3.6-9-9z"></path></svg></div><h3>Gobernanza Colaborativa</h3><p>Relaciones Estado–sociedad, participación, transparencia, cohesión social y construcción colectiva de políticas públicas.</p></div><div class="eje-card verde"><div class="eje-icon verde"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><rect height="14" rx="2" width="20" x="2" y="3"></rect><path d="M8 21h8M12 17v4"></path></svg></div><h3>E-Governance</h3><p>Tecnologías digitales, datos abiertos, gobierno abierto y mecanismos de interacción transparente entre Estado y ciudadanía.</p></div><div class="eje-card indigo"><div class="eje-icon indigo"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><circle cx="5" cy="12" r="2"></circle><circle cx="19" cy="5" r="2"></circle><circle cx="19" cy="19" r="2"></circle><path d="M7 12h10M17 7l-10 3.5M17 17L7 13.5"></path></svg></div><h3>Gobernanza en Red</h3><p>Articulación entre múltiples actores, escalas e instituciones para responder a problemas complejos de gobernanza.</p></div></div></div></section><!-- EJE 1: GOBERNANZA COLABORATIVA --><section class="section section-alt"><div class="section-inner"><div class="eje-title-bar"><div class="eje-num azul">1</div><h2>Gobernanza Colaborativa</h2></div><p class="section-body" style="margin:16px 0 0;">En las nuevas formas de gobernar, el Estado ha buscado superar los modelos estrictamente gerenciales en el diseño de políticas públicas, promoviendo arreglos colaborativos entre actores públicos y privados. Estos espacios de deliberación reúnen agencias gubernamentales, actores sociales y organizaciones del mercado con el propósito de participar conjuntamente en los procesos de toma de decisiones (Ansell y Gash, 2008).</p><!-- PARTICIPACIÓN CIUDADANA --><div class="subtema"><div class="subtema-header"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 00-3-3.87"></path><path d="M16 3.13a4 4 0 010 7.75"></path></svg><h3>Participación Ciudadana</h3></div><div class="subtema-body"><p>La participación es un mecanismo fundamental para la construcción de procesos de cooperación y deliberación entre actores públicos, privados y sociales. La literatura ha buscado relacionar la participación con el desempeño estatal, considerando que no solo fortalece los procesos democráticos, sino también las capacidades sociales orientadas a generar mecanismos de regulación, control y fiscalización social (Mayntz 2005). Este espacio reúne documentos, guías y formación destinada a fortalecer los procesos participativos, capacidades locales y liderazgos.</p><div class="recurso-btns"><a class="btn-recurso btn-doc" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M13 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7l-3-5z"></path><path d="M13 2v5h5"></path></svg>Documentos </a><a class="btn-recurso btn-kit" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><rect height="11" rx="2" width="16" x="2" y="7"></rect><path d="M7 7V5a3 3 0 016 0v2"></path></svg>Kit de Herramientas </a><a class="btn-recurso btn-form" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M12 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V8l-4-4z"></path><path d="M12 2v6h6"></path></svg>Formación</a></div></div></div><!-- TRANSPARENCIA Y BUENAS PRÁCTICAS --><div class="subtema"><div class="subtema-header"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg><h3>Transparencia y Buenas Prácticas</h3></div><div class="subtema-body"><p>La transparencia y las buenas prácticas gubernamentales se han consolidado como recursos fundamentales de la gobernanza para fortalecer la confianza institucional y la legitimidad democrática. Las buenas prácticas estatales aportan ventajas asociadas a la lucha contra la corrupción, promoviendo mayores niveles de credibilidad institucional, rendición de cuentas y fortalecimiento de la relación entre ciudadanía y Estado (García-Morales 2016). En este espacio encontrará herramientas dedicadas a fortalecer la transparencia de gobiernos nacionales y subnacionales.</p><div class="recurso-btns"><a class="btn-recurso btn-doc" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M13 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7l-3-5z"></path><path d="M13 2v5h5"></path></svg>Documentos </a><a class="btn-recurso btn-kit" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><rect height="11" rx="2" width="16" x="2" y="7"></rect><path d="M7 7V5a3 3 0 016 0v2"></path></svg>Kit de Herramientas </a><a class="btn-recurso btn-form" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M12 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V8l-4-4z"></path><path d="M12 2v6h6"></path></svg>Formación</a></div></div></div><!-- COHESIÓN SOCIAL --><div class="subtema"><div class="subtema-header"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"></path></svg><h3>Cohesión Social</h3></div><div class="subtema-body"><p>La cohesión social, entendida como el conjunto de procesos y vínculos sociales en los que el capital social, la acción colectiva y las redes sociales fortalecen espacios de deliberación y cooperación (Sorj y Martuccelli 2008), constituye un eje relevante dentro de la gobernanza colaborativa. Desde los enfoques promovidos por la CEPAL, se relaciona con la generación de conocimiento, el fortalecimiento del desarrollo social y la reducción de desigualdades. Este espacio presenta documentos, guías y formación orientados a fortalecer la cohesión social a partir de la inclusión, el capital social y las normas que aportan a la acción colectiva.</p><div class="recurso-btns"><a class="btn-recurso btn-doc" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M13 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7l-3-5z"></path><path d="M13 2v5h5"></path></svg>Documentos </a><a class="btn-recurso btn-kit" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><rect height="11" rx="2" width="16" x="2" y="7"></rect><path d="M7 7V5a3 3 0 016 0v2"></path></svg>Kit de Herramientas </a><a class="btn-recurso btn-form" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M12 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V8l-4-4z"></path><path d="M12 2v6h6"></path></svg>Formación</a></div></div></div></div></section><!-- EJE 2: E-GOVERNANCE --><section class="section" id="recursos"><div class="section-inner"><div class="eje-title-bar"><div class="eje-num verde">2</div><h2>E-Governance</h2></div><p class="section-body" style="margin:16px 0 0;">La <em>e-governance</em> surge como una evolución del <em>e-government</em>, orientada a incorporar a la ciudadanía en los procesos de toma de decisiones, transparencia y rendición de cuentas (Greenberg y Newell 2012). Este modelo de gobernanza, basado en el uso de tecnologías de la información y la comunicación, busca implementar iniciativas de apertura gubernamental bajo estándares que promuevan el involucramiento ciudadano y fortalezcan la interacción Estado–sociedad.</p><!-- TRANSPARENCIA Y DATOS ABIERTOS --><div class="subtema"><div class="subtema-header" style="background-color:#e8f5e9;"><svg style="color:var(--verde-principal);" fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><circle cx="11" cy="11" r="8"></circle><path d="M21 21l-4.35-4.35"></path></svg><h3>Transparencia y Datos Abiertos</h3></div><div class="subtema-body"><p>Con el impulso de la Alianza de Gobierno Abierto (Open Government Partnership), la transparencia y los datos abiertos se consolidaron como ejes centrales de transformación en los distintos niveles de gobierno. Los datos abiertos amplían las posibilidades de acceso a la información pública y fortalecen los mecanismos de control social y <em>accountability</em> vertical, permitiendo que la ciudadanía supervise, evalúe y participe activamente en los procesos gubernamentales. En este espacio encontrará documentos, kit de herramientas y formación que fomentan el uso de tecnologías asociadas a la <em>e-governance</em>.</p><div class="recurso-btns"><a class="btn-recurso btn-doc" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M13 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7l-3-5z"></path><path d="M13 2v5h5"></path></svg>Documentos </a><a class="btn-recurso btn-kit" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><rect height="11" rx="2" width="16" x="2" y="7"></rect><path d="M7 7V5a3 3 0 016 0v2"></path></svg>Kit de Herramientas </a><a class="btn-recurso btn-form" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M12 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V8l-4-4z"></path><path d="M12 2v6h6"></path></svg>Formación</a></div></div></div></div></section><!-- EJE 3: GOBERNANZA EN RED --><section class="section section-alt"><div class="section-inner"><div class="eje-title-bar"><div class="eje-num indigo">3</div><h2>Gobernanza en Red</h2></div><p class="section-body" style="margin:16px 0 0;">La gobernanza en red busca generar impactos positivos en la gestión y la toma de decisiones (Sorensen y Torfing 2007), aportando información, conocimiento e interacción entre diferentes actores para responder a problemas complejos. Coordina y coopera entre actores a partir de su interdependencia o autonomía (Rhodes 1996), permitiendo responder a políticas como las violencias de género desde un enfoque sistémico y multinivel.</p><!-- VIOLENCIAS DE GÉNERO Y GOBERNANZA EN RED --><div class="subtema"><div class="subtema-header" style="background-color:#ede7f6;"><svg style="color:#5c6bc0;" fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 24 24"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="M9 9c0-1.657 1.343-3 3-3s3 1.343 3 3-1.343 3-3 3v3M12 18.01l.01-.011"></path></svg><h3>Violencias de Género y Gobernanza en Red</h3></div><div class="subtema-body"><p>La gobernanza en red ofrece un marco analítico clave para abordar fenómenos complejos como las violencias de género, permitiendo la coordinación entre múltiples actores —instituciones públicas, organizaciones sociales, organismos internacionales y comunidades— bajo principios de interdependencia y cooperación. Este enfoque facilita el diseño de respuestas integrales, articuladas desde distintas escalas de gobierno, para enfrentar problemas que requieren acción colectiva sostenida.</p><div class="recurso-btns"><a class="btn-recurso btn-doc" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M13 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V7l-3-5z"></path><path d="M13 2v5h5"></path></svg>Documentos </a><a class="btn-recurso btn-kit" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><rect height="11" rx="2" width="16" x="2" y="7"></rect><path d="M7 7V5a3 3 0 016 0v2"></path></svg>Kit de Herramientas </a><a class="btn-recurso btn-form" href="#"><svg fill="none" stroke="currentColor" stroke-width="2" viewbox="0 0 20 20"><path d="M12 2H6a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V8l-4-4z"></path><path d="M12 2v6h6"></path></svg>Formación</a></div></div></div></div></section>	full_html
texto_libre	0	131	1746	es	0	<div style="background-color:#f9f9f9;border-radius:8px;box-shadow:0 4px 8px rgba(0, 0, 0, 0.1);margin:20px 0;padding:20px;"><p>La Universidad Nacional de Loja, mediante las líneas de investigación y los proyectos que en ellas se ejecutan, forma parte de 17 redes y alianzas de investigación en las que participan docentes, investigadores y estudiantes.</p><style type="text/css">/* Comentario: Estilo para resaltar al pasar el mouse */\r\n  .resaltado:hover {\r\n    background-color: #cce5ff; /* Comentario: Cambia el color de fondo a un azul claro */\r\n    border-radius: 8px;        /* Comentario: Aplica un borde redondeado */\r\n    padding: 10px;             /* Comentario: Añade un padding para dar más espacio */\r\n    transition: background-color 0.3s ease; /* Comentario: Añade una transición suave */\r\n  }\r\n</style><div style="background-color:#ffffff;border-radius:8px;border:1px solid #ddd;margin-top:10px;padding:15px;"><!-- Comentario: Aplicación de la clase 'resaltado' al <summary> --><details><summary class="resaltado"><strong>Redes de investigación en las que participan docentes de la Universidad Nacional de Loja:</strong></summary><hr><p><img src="/sites/default/files/inline-images/RedBio_0.png" data-align="right" data-entity-uuid="a7684fae-11f7-4292-adf7-5b64b07fb025" data-entity-type="file" alt="redbio" width="269" height="91"><a href="http://inabio.biodiversidad.gob.ec/">LA RED NACIONAL DE INVESTIGACIÓN SOBRE LA DIVERSIDAD BIOLÓGICA DEL ECUADOR&nbsp;</a></p><ul><li data-list-item-id="e649beeb14b323192cf16206d37b1cf9b">Ing. Nikolay Aguirre</li><li data-list-item-id="e624a3fc389ea491a0014867629f2ad35">Ing. Zhofre Aguirre</li><li data-list-item-id="ee647a1975b9d0777e62b25a5540ad1d8">Ing. Nelson Jaramillo</li><li data-list-item-id="ef5be349a4e21e852687734d490c080ae">Ing. Johana Muñoz</li><li data-list-item-id="e4d66b6092c17443b54ce740fa38bcb28">Ing. Juan Maita</li></ul><hr><p><img src="/sites/default/files/inline-images/aeeree.png" data-align="right" data-entity-uuid="948eefbc-c318-4260-be13-9a9aeeda849c" data-entity-type="file" alt="aeeree" width="112" height="112"><a href="https://aeeree.org/">ASOCIACIÓN ECUATORIANADE ENERGÍAS RENOVABLES Y EFICIENCIA ENERGÉTICA (AEE-REE)</a></p><ul><li data-list-item-id="ef20a260ac8a47fe4be02b945bd045848">Ing. Carlos Gustavo Samaniego</li><li data-list-item-id="e4b870760c2b890c538af2a9573e0b914">Ing. Juan Carlos Solano</li><li data-list-item-id="e6defc21932d1096533049f3d4c898b2f">Ing. Pablo Fernando Ordóñez</li><li data-list-item-id="e971efcadf667194a9c6b49f17c78a218">Ing. Jorge Luis Maldonado</li></ul><hr><p><img src="/sites/default/files/inline-images/RedEcuatoriana.png" data-align="right" data-entity-uuid="3adaba5e-3856-4d7a-81d9-fdb6ffc941e4" data-entity-type="file" alt="RedEcuatoriana" width="224" height="53"><a href="https://regap.iaen.edu.ec/" rel="noopener" target="_blank" title="RED ECUATORIANA DE GOBIERNO Y ADMINISTRACIÓN PÚBLICA (REGAP)">RED ECUATORIANA DE GOBIERNO Y ADMINISTRACIÓN PÚBLICA (REGAP)</a></p><ul><li data-list-item-id="e24618b62f3fd0fa736a37edf92a1287b"><p class="text-align-justify">Ing. José Rodrigo Maldonado.</p></li></ul><hr><p><img src="/sites/default/files/inline-images/Relieve.png" data-align="right" data-entity-uuid="880f3521-f74a-4b60-9821-0b9238c49083" data-entity-type="file" alt="Relieve" width="142" height="62"></p><p><a href="https://redrelieve.com">RED LATINOAMERICANA DE INVESTIGACIÓN EN ENERGÍA Y VEHÍCULOS (RELIEVE)</a></p><ul><li data-list-item-id="e92c873a4d5d4f75c77f754d0cb3b9c1a">Ing. Jairo Darío Castillo Calderón.</li></ul><hr><p><img src="/sites/default/files/inline-images/LOGO-REDU.png" data-align="right" data-entity-uuid="cef9e9c4-95f8-4d2e-bc5a-28b11bb85f85" data-entity-type="file" alt="Redu" width="128" height="75"></p><p><a href="https://redu.edu.ec/">RED ECUATORIANA DE UNIVERSIDADES Y ESCUELAS POLITÉCNICAS PARA LA INVESTIGACIÓN Y POSGRADOS - REDU</a></p><ul><li data-list-item-id="e6b27e69f21a7a06d4ed55abbd