texto_libre	0	132	1505	en	0	<div class="drci-micrositio"><style>\r\n.drci-micrositio *{\r\n    margin:0;\r\n    padding:0;\r\n    box-sizing:border-box;\r\n}\r\n\r\n.drci-micrositio{\r\n    font-family:'Montserrat', sans-serif;\r\n    color:#1b1b1b;\r\n}\r\n\r\n.drci-micrositio a{\r\n    color:#93000b;\r\n    text-decoration:none;\r\n}\r\n\r\n.drci-micrositio .drci-texto p{\r\n    color:#3a3a3a;\r\n    line-height:1.9;\r\n    font-size:1.05rem;\r\n    text-align:justify;\r\n    margin-bottom:30px;\r\n}\r\n\r\n/* =========================================\r\n   ENLACES PRINCIPALES\r\n========================================= */\r\n\r\n.drci-micrositio .drci-enlaces{\r\n    display:grid;\r\n    grid-template-columns:repeat(auto-fit,minmax(180px,1fr));\r\n    gap:18px;\r\n    margin-bottom:26px;\r\n}\r\n\r\n.drci-micrositio .drci-enlace-card{\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    text-align:center;\r\n    background:#ffffff;\r\n    border:1px solid #dfe7f1;\r\n    border-top:4px solid #93000b;\r\n    border-radius:12px;\r\n    padding:24px 16px;\r\n    color:#93000b;\r\n    font-weight:700;\r\n    line-height:1.4;\r\n    transition:.3s ease;\r\n}\r\n\r\n.drci-micrositio .drci-enlace-card:hover{\r\n    border-color:#93000b;\r\n    background:#fbecec;\r\n    transform:translateY(-4px);\r\n}\r\n\r\n/* =========================================\r\n   REPORTE (botón destacado)\r\n========================================= */\r\n\r\n.drci-micrositio .drci-btn-reporte{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:14px 22px;\r\n    background:#93000b;\r\n    color:#ffffff;\r\n    font-weight:700;\r\n    border-radius:10px;\r\n    transition:.3s ease;\r\n}\r\n\r\n.drci-micrositio .drci-btn-reporte:hover{\r\n    background:#6e0008;\r\n    color:#ffffff;\r\n}\r\n\r\n/* =========================================\r\n   RESPONSIVE\r\n========================================= */\r\n\r\n@media(max-wi