und:#f9fafb;\r\n    border:1px solid #eee;\r\n    border-left:4px solid #93000b;\r\n    border-radius:0 10px 10px 0;\r\n    padding:18px 20px;\r\n}\r\n\r\n.drci-micrositio .drci-red-logo{\r\n    flex-shrink:0;\r\n    width:80px;\r\n    height:60px;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    background:#ffffff;\r\n    border-radius:8px;\r\n    border:1px solid #eee;\r\n    overflow:hidden;\r\n}\r\n\r\n.drci-micrositio .drci-red-logo img{\r\n    max-width:100%;\r\n    max-height:100%;\r\n    object-fit:contain;\r\n}\r\n\r\n.drci-micrositio .drci-red-info{\r\n    flex:1;\r\n}\r\n\r\n.drci-micrositio .drci-red-info a{\r\n    display:block;\r\n    font-weight:700;\r\n    font-size:.98rem;\r\n    line-height:1.4;\r\n    margin-bottom:10px;\r\n}\r\n\r\n.drci-micrositio .drci-red-investigadores{\r\n    display:flex;\r\n    flex-wrap:wrap;\r\n    gap:8px;\r\n}\r\n\r\n.drci-micrositio .drci-inv-chip{\r\n    background:#ffffff;\r\n    border:1px solid #dfe7f1;\r\n    border-radius:999px;\r\n    padding:4px 12px;\r\n    font-size:.82rem;\r\n    color:#3a3a3a;\r\n}\r\n\r\n@media(max-width:560px){\r\n    .drci-micrositio .drci-red-card{\r\n        flex-direction:column;\r\n        align-items:center;\r\n        text-align:center;\r\n    }\r\n}\r\n\r\n/* =========================================\r\n   TABLA DE ALIANZAS (2 columnas)\r\n========================================= */\r\n\r\n.drci-micrositio .drci-alianzas{\r\n    display:grid;\r\n    grid-template-columns:repeat(auto-fit,minmax(280px,1fr));\r\n    gap:24px;\r\n    margin-bottom:26px;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col{\r\n    background:#ffffff;\r\n    border:1px solid #dfe7f1;\r\n    border-top:4px solid #93000b;\r\n    border-radius:12px;\r\n    padding:22px;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col h4{\r\n    color:#93000b;\r\n    font-size:1rem;\r\n    text-align:center;\r\n    margin-bottom:14px;\r\n    padding-bottom:12px;\r\n    border-bottom:1px solid #eee;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col ul{\r\n    list-style:none;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col li{\r\n    color:#3a3a3a;\r\n    line-height:1.6;\r\n    font-size:.9rem;\r\n    padding:6px 0 6px 16px;\r\n    position:relative;\r\n    border-bottom:1px solid #f5f5f5;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col li:last-child{\r\n    border-bottom:none;\r\n}\r\n\r\n.drci-micrositio .drci-alianza-col li::before{\r\n    content:"";\r\n    position:absolute;\r\n    left:0;\r\n    top:14px;\r\n    width:5px;\r\n    height:5px;\r\n    border-radius:50%;\r\n    background:#93000b;\r\n}\r\n\r\n/* =========================================\r\n   BOTÓN FINAL\r\n========================================= */\r\n\r\n.drci-micrositio .drci-btn-conoce{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:14px 22px;\r\n    background:#93000b;\r\n    color:#ffffff;\r\n    font-weight:700;\r\n    border-radius:10px;\r\n    transition:.3s ease;\r\n}\r\n\r\n.drci-micrositio .drci-btn-conoce:hover{\r\n    background:#6e0008;\r\n    color:#ffffff;\r\n}\r\n</style><div class="drci-texto"><p>La Universidad Nacional de Loja, mediante las líneas de investigación y los proyectos que en ellas se ejecutan, forma parte de 17 redes y alianzas de investigación en las que participan docentes, investigadores y estudiantes.</p></div><!-- ACORDEÓN DE REDES --><details class="drci-acordeon-redes"><summary>Redes de investigación en las que participan docentes de la UNL</summary><div class="drci-redes-lista"><div class="drci-red-card"><div class="drci-red-logo"><img src="/sites/default/files/inline-images/RedBio_0.png" alt="RedBio"></div><div class="drci-red-info"><p><a href="http://inabio.biodiversidad.gob.ec/" target="_blank" rel="noopener">Red Nacional de Investigación sobre la Diversidad Biológica del Ecuador</a></p><div class="drci-red-investigadores"><span class="drci-inv-chip">Ing. Nikolay Aguirre</span> <span class="drci-inv-chip">