texto_libre	0	129	1507	en	0	<style type="text/css">:root {\r\n    --unl-navy:        #4a0006;\r\n    --unl-azul:        #93000b;\r\n    --unl-verde:       #b3444f;\r\n    --unl-verde-texto: #93000b;\r\n    --unl-rojo:        #BF0811;\r\n    --unl-negro:       #211915;\r\n    --unl-blanco:      #ffffff;\r\n    --gi-tinta:        #211915;\r\n    --gi-tinta-soft:   #3f4a5a;\r\n    --gi-mute:         #6b7686;\r\n    --gi-rule:         #e4e7ec;\r\n    --gi-azul-glow:    rgba(147, 0, 11, 0.06);\r\n    --gi-verde-glow:   rgba(147, 0, 11, 0.10);\r\n    --gi-shadow:       0 1px 3px rgba(15, 23, 42, 0.05);\r\n    --gi-shadow-h:     0 12px 28px -10px rgba(15, 23, 42, 0.18);\r\n}\r\n        .gited-unl * { box-sizing: border-box; margin: 0; padding: 0; }\r\n        .gited-unl {\r\n            font-family: 'Montserrat', system-ui, sans-serif;\r\n            color: var(--gi-tinta);\r\n            line-height: 1.55;\r\n            -webkit-font-smoothing: antialiased;\r\n        }\r\n        .gited-wrap { width: 100%; margin: 0 auto; padding: 16px 0 48px; }\r\n        /* ====== ENCABEZADO ====== */\r\n        .gited-banner {\r\n            position: relative;\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 16px 20px;\r\n            background: var(--gi-azul-glow);\r\n            border-left: 4px solid var(--unl-azul);\r\n            border-radius: 8px;\r\n            margin-bottom: 18px;\r\n        }\r\n        .gited-banner::after {\r\n            content: '';\r\n            position: absolute;\r\n            left: 20px; bottom: -1px;\r\n            width: 60px; height: 3px;\r\n            background: var(--unl-rojo);\r\n            border-radius: 2px;\r\n        }\r\n        .gited-banner h2 {\r\n            font-size: 16px;\r\n            font-weight: 600;\r\n            color: var(--unl-azul);\r\n        }\r\n        .gited-stats {\r\n            margin-left: auto;\r\n            font-size: 13px;\r\n            font-weight: 700;\r\n            color: var(--unl-verde-texto);\r\n            white-space: nowrap;\r\n        }\r\n        /* ====== BARRA DE BÚSQUEDA ====== */\r\n        .gited-search {\r\n            position: relative;\r\n            margin-bottom: 22px;\r\n            padding: 14px;\r\n            background: var(--unl-blanco);\r\n            border: 1px solid var(--gi-rule);\r\n            border-radius: 10px;\r\n            box-shadow: var(--gi-shadow);\r\n        }\r\n        .gited-search label {\r\n            display: block;\r\n            font-size: 11px;\r\n            font-weight: 700;\r\n            letter-spacing: 0.06em;\r\n            text-transform: uppercase;\r\n            color: var(--gi-mute);\r\n            margin-bottom: 5px;\r\n        }\r\n        .gited-input-wrap {\r\n            position: relative;\r\n            display: block;\r\n        }\r\n        .gited-input {\r\n            width: 100%;\r\n            font-family: inherit;\r\n            font-size: 14px;\r\n            color: var(--gi-tinta);\r\n            background: var(--unl-blanco);\r\n            border: 1px solid var(--gi-rule);\r\n            border-radius: 8px;\r\n            padding: 10px 12px 10px 40px;\r\n            transition: border-color 0.2s, box-shadow 0.2s;\r\n        }\r\n        .gited-input:focus {\r\n            outline: none;\r\n            border-color: var(--unl-azul);\r\n            box-shadow: 0 0 0 3px var(--gi-azul-glow);\r\n        }\r\n        .gited-input-icon {\r\n            position: absolute;\r\n            left: 12px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            width: 18px; height: 18px;\r\n            color: var(--gi-mute);\r\n            pointer-events: none;\r\n        }\r\n        .gited-input-hint {\r\n            font-size: 12px;\r\n            color: var(--gi-mute);\r\n            margin-top: 6px;\r\n        }\r\n        /* ====== GRID ====== */\r\n        .gited-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));\r\n            gap: 18px;\r\n            align-items: stretch;\r\n            margin-bottom: 22px;\r\n        }\r\n        /* ====== CARD ======\r\n           Ahora es \r\n<div>\r\n     (no <a>) — CKEditor no la reescribe. */\r\n            .gited-card {\r\n                position: relative;\r\n                display: flex;\r\n                flex-direction: column;\r\n                height: 100%;\r\n                background: var(--unl-blanco);\r\n                border: 1px solid var(--gi-rule);\r\n                border-radius: 12px;\r\n                box-shadow: var(--gi-shadow);\r\n                overflow: hidden;\r\n                min-width: 0;\r\n                color: inherit;\r\n                transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;\r\n            }\r\n            .gited-card:hover {\r\n                transform: translateY(-3px);\r\n                box-shadow: var(--gi-shadow-h);\r\n                border-color: rgba(0, 76, 123, 0.25);\r\n            }\r\n            .gited-card:hover .gited-img img { transform: scale(1.05); }\r\n            /* === Imagen === */\r\n            .gited-img {\r\n                position: relative;\r\n                width: 100%;\r\n                aspect-ratio: 16 / 10;\r\n                overflow: hidden;\r\n                background: var(--gi-azul-glow);\r\n            }\r\n            .gited-img img {\r\n                width: 100%;\r\n                height: 100%;\r\n                object-fit: cover;\r\n                object-position: top;\r\n                display: block;\r\n                transition: transform 0.5s ease;\r\n            }\r\n            /* === Placeholder grupos sin foto === */\r\n            .gited-placeholder {\r\n                position: absolute;\r\n                inset: 0;\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: center;\r\n                background: linear-gradient(135deg, var(--unl-azul) 0%, var(--unl-navy) 100%);\r\n                color: var(--unl-blanco);\r\n                font-size: clamp(28px, 5vw, 42px);\r\n                font-weight: 700;\r\n                letter-spacing: 0.04em;\r\n                text-align: center;\r\n                padding: 16px;\r\n            }\r\n            .gited-placeholder::before {\r\n                content: '';\r\n                position: absolute;\r\n                inset: 0;\r\n                background-image:\r\n                    radial-gradient(circle at 80% 20%, rgba(255,255,255,0.08) 0%, transparent 50%),\r\n                    radial-gradient(circle at 20% 80%, rgba(255,255,255,0.05) 0%, transparent 50%);\r\n            }\r\n            .gited-placeholder span { position: relative; z-index: 1; }\r\n            /* Badge de siglas */\r\n            .gited-siglas {\r\n                position: absolute;\r\n                top: 12px;\r\n                left: 12px;\r\n                z-index: 2;\r\n                display: inline-flex;\r\n                align-items: center;\r\n                font-size: 11px;\r\n                font-weight: 700;\r\n                letter-spacing: 0.06em;\r\n                color: var(--unl-blanco);\r\n                background: var(--unl-verde-texto);\r\n                padding: 4px 10px;\r\n                border-radius: 16px;\r\n                box-shadow: 0 2px 6px rgba(0,0,0,0.18);\r\n            }\r\n            /* === Cuerpo === */\r\n            .gited-card-body {\r\n                padding: 16px 16px 18px;\r\n                flex: 1;\r\n                display: flex;\r\n                flex-direction: column;\r\n            }\r\n            /* El nombre del grupo: contiene el único <a> de la card */\r\n            .gited-name {\r\n                font-size: 14.5px;\r\n                font-weight: 600;\r\n                line-height: 1.35;\r\n                margin-bottom: 10px;\r\n            }\r\n            .gited-name a {\r\n                color: var(--unl-azul);\r\n                text-decoration: none;\r\n                display: -webkit-box;\r\n                -webkit-line-clamp: 3;\r\n                -webkit-box-orient: vertical;\r\n                overflow: hidden;\r\n                transition: color 0.2s;\r\n            }\r\n            .gited-name a:hover {\r\n                color: var(--unl-verde-texto);\r\n                text-decoration: underline;\r\n            }\r\n            .gited-name a:focus-visible {\r\n                outline: 2px solid var(--unl-azul);\r\n                outline-offset: 2px;\r\n                border-radius: 2px;\r\n            }\r\n            /* Director con ícono */\r\n            .gited-director {\r\n                display: flex;\r\n                align-items: flex-start;\r\n                gap: 7px;\r\n                font-size: 12.5px;\r\n                color: var(--gi-tinta-soft);\r\n                line-height: 1.3;\r\n                margin-top: auto;\r\n            }\r\n            .gited-director svg {\r\n                width: 14px;\r\n                height: 14px;\r\n                color: var(--unl-verde-texto);\r\n                flex-shrink: 0;\r\n                margin-top: 1px;\r\n            }\r\n            .gited-director strong {\r\n                display: block;\r\n                font-size: 10.5px;\r\n                letter-spacing: 0.06em;\r\n                text-transform: uppercase;\r\n                font-weight: 600;\r\n                color: var(--gi-mute);\r\n                margin-bottom: 1px;\r\n            }\r\n            .gited-director-info { flex: 1; min-width: 0; }\r\n            .gited-director-name {\r\n                color: var(--gi-tinta);\r\n                font-weight: 500;\r\n            }\r\n            /* ====== BOTÓN "CARGAR MÁS" ====== */\r\n            .gited-loadmore-wrap { text-align: center; margin-top: 6px; }\r\n            .gited-loadmore {\r\n     