span class="gited-siglas">NEURONAS</span></p><div class="gited-placeholder"><span>NEURONAS</span></div></div><div class="gited-card-body"><h3 class="gited-name"><a href="https://unl.edu.ec/investigacion/grupos-investigacion/neuronas">Laboratorio de Pedagogías, Tecnologías Emergentes y STEAM</a></h3><div class="gited-director"><svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewbox="0 0 24 24"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg><div class="gited-director-info"><strong>Director</strong> <span class="gited-director-name">Fanny Soraya Zuñiga Tinizaray</span></div></div></div></div></div><div class="gited-empty" hidden="" id="gited-empty"><strong>No se encontraron grupos</strong> con esa búsqueda.<br>Prueba con otras palabras (nombre completo, siglas o director).</div><div class="gited-loadmore-wrap"><button class="gited-loadmore" id="gited-loadmore" type="button">Cargar más grupos <svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" viewBox="0 0 24 24"><path d="M12 5v14M19 12l-7 7-7-7"></path></svg></button></div></div></div><script>\r\n        (function () {\r\n            'use strict';\r\n            const PROYECTOS_POR_PAGINA = 8;\r\n            const ESPERA_ANTES_DE_FILTRAR_MS = 120;\r\n            const MAX_CARACTERES_BUSQUEDA = 80;\r\n            const inputBusqueda = document.getElementById('gited-q');\r\n            const contenedorTarjetas = document.getElementById('gited-grid');\r\n            const etiquetaContador = document.getElementById('gited-stats');\r\n            const mensajeSinResultados = document.getElementById('gited-empty');\r\n            const botonCargarMas = document.getElementById('gited-loadmore');\r\n            if (!contenedorTarjetas) return;\r\n            const tarjetas = Array.from(contenedorTarjetas.querySelectorAll('.js-gited-card'))\r\n                .map(elemento => ({\r\n                    elemento: elemento,\r\n                    textoBuscable: (elemento.dataset.search || '').toLowerCase()\r\n                }));\r\n            let cantidadVisible = 0;\r\n            let tarjetasCoincidentes = [];\r\n            function quitarAcentosYMinusculas(texto) {\r\n                return String(texto)\r\n                    .normalize('NFD')\r\n                    .replace(/[\\u0300-\\u036f]/g, '')\r\n                    .toLowerCase()\r\n                    .trim();\r\n            }\r\n            function ejecutarTrasPausaEnTecleo(funcion, milisegundos) {\r\n                let temporizador = 0;\r\n                return function () {\r\n                    clearTimeout(temporizador);\r\n                    temporizador = setTimeout(funcion, milisegundos);\r\n                };\r\n            }\r\n            function filtrarTarjetasSegunBusqueda() {\r\n                const valorIngresado = inputBusqueda\r\n                    ? String(inputBusqueda.value || '').slice(0, MAX_CARACTERES_BUSQUEDA)\r\n                    : '';\r\n                const textoBuscado = quitarAcentosYMinusculas(valorIngresado);\r\n                tarjetasCoincidentes = tarjetas.filter(tarjeta => {\r\n                    return !textoBuscado || tarjeta.textoBuscable.includes(textoBuscado);\r\n                });\r\n                cantidadVisible = Math.min(PROYECTOS_POR_PAGINA, tarjetasCoincidentes.length);\r\n                actualizarLoQueSeVeEnPantalla();\r\n            }\r\n            function actualizarLoQueSeVeEnPantalla() {\r\n                const tarjetasQueDebenVerse = new Set(\r\n                    tarjetasCoincidentes.slice(0, cantidadVisible).map(t => t.elemento)\r\n                );\r\n                tarjetas.forEach(tarjeta => {\r\n                    if (tarjetasQueDebenVerse.has(tarjeta.elemento)) {\r\n                        tarjeta.elemento.removeAttribute('hidden');\r\n                    } else {\r\n                        tarjeta.elemento.setAttribute('hidden', '');\r\n                    }\r\n                });\r\n                actualizarContador();\r\n                actualizarMensajeSinResultados();\r\n                actualizarBotonCargarMas();\r\n            }\r\n            function actualizarContador() {\r\n                if (!etiquetaContador) return;\r\n                const total = tarjetas.length;\r\n                const coincidencias = tarjetasCoincidentes.length;\r\n                if (coincidencias === total) {\r\n                    etiquetaContador.textContent = total + (total === 1 ? ' grupo' : ' grupos');\r\n                } else {\r\n                    etiquetaContador.textContent = coincidencias + ' de ' + total + ' grupos';\r\n                }\r\n            }\r\n            function actualizarMensajeSinResultados() {\r\n                if (!mensajeSinResultados) return;\r\n                if (tarjetasCoincidentes.length === 0) {\r\n                    mensajeSinResultados.removeAttribute('hidden');\r\n                } else {\r\n                    mensajeSinResultados.setAttribute('hidden', '');\r\n                }\r\n            }\r\n            function actualizarBotonCargarMas() {\r\n                if (!botonCargarMas) return;\r\n                const quedanOcultas = cantidadVisible < tarjetasCoincidentes.length;\r\n                if (quedanOcultas) {\r\n                    botonCargarMas.removeAttribute('hidden');\r\n                } else {\r\n                    botonCargarMas.setAttribute('hidden', '');\r\n                }\r\n            }\r\n            const filtrarConPausa = ejecutarTrasPausaEnTecleo(\r\n                filtrarTarjetasSegunBusqueda,\r\n                ESPERA_ANTES_DE_FILTRAR_MS\r\n            );\r\n            if (inputBusqueda) {\r\n                inputBusqueda.addEventListener('input', function () {\r\n                    if (inputBusqueda.value.length > MAX_CARACTERES_BUSQUEDA) {\r\n                        inputBusqueda.value = inputBusqueda.value.slice(0, MAX_CARACTERES_BUSQUEDA);\r\n                    }\r\n                    filtrarConPausa();\r\n                });\r\n            }\r\n            if (botonCargarMas) {\r\n                botonCargarMas.addEventListener('click', function () {\r\n                    cantidadVisible = Math.min(\r\n                        cantidadVisible + PROYECTOS_POR_PAGINA,\r\n                        tarjetasCoincidentes.length\r\n                    );\r\n                    actualizarLoQueSeVeEnPantalla();\r\n                });\r\n            }\r\n            filtrarTarjetasSegunBusqueda();\r\n        })();\r\n        </script>	full_html
texto_libre	0	129	1508	en	0	<style type="text/css">:root {\r\n            --unl-navy:        #0c2342;\r\n            --unl-azul:        #004C7B;\r\n            --unl-verde:       #4F8E3A;\r\n            --unl-verde-texto: #247A1E;\r\n            --unl-rojo:        #BF0811;\r\n            --unl-negro:       #211915;\r\n            --unl-blanco:      #ffffff;\r\n\r\n            --gi-tinta:        #211915;\r\n            --gi-tinta-soft:   #3f4a5a;\r\n            --gi-mute:         #6b7686;\r\n            --gi-rule:         #e4e7ec;\r\n            --gi-azul-glow:    rgba(0, 76, 123, 0.06);\r\n            --gi-verde-glow:   rgba(79, 142, 58, 0.10);\r\n            --gi-shadow:       0 1px 3px rgba(15, 23, 42, 0.05);\r\n            --gi-shadow-h:     0 12px 28px -10px rgba(15, 23, 42, 0.18);\r\n        }\r\n\r\n        .gited-unl * { box-sizing: border-box; margin: 0; padding: 0; }\r\n\r\n        .gited-unl {\r\n            font-family: 'Montserrat', system-ui, sans-serif;\r\n            color: var(--gi-tinta);\r\n            line-height: 1.55;\r\n            -webkit-font-smoothing: antialiased;\r\n        }\r\n\r\n        .gited-wrap { width: 100%; margin: 0 auto; padding: 16px 0 48px; }\r\n\r\n        /* ====== ENCABEZADO ====== */\r\n        .gited-banner {\r\n            position: relative;\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 16px 20px;\r\n            background: var(--gi-azul-glow);\r\n            border-left: 4px solid var(--unl-azul);\r\n            border-radius: 8px;\r\n            margin-bottom: 18px;\r\n        }\r\n        .gited-banner::after {\r\n            content: '';\r\n            position: absolute;\r\n            left: 20px; bottom: -1px;\r\n            width: 60px; height: 3px;\r\n            background: var(--unl-rojo);\r\n            border-radius: 2px;\r\n        }\r\n        .gited-banner h2 {\r\n            font-size: 16px;\r\n            font-weight: 600;\r\n            color: var(--unl-azul);\r\n        }\r\n        .gited-stats {\r\n            margin-left: auto;\r\n            font-size: 13px;\r\n            font-weight: 700;\r\n            color: var(--unl-verde-texto);\r\n            white-space: nowrap;\r\n        }\r\n\r\n        /* ====== BARRA DE BÚSQUEDA ====== */\r\n        .gited-search {\r\n            position: relative;\r\n            margin-bottom: 22px;\r\n            padding: 14px;\r\n            background: var(--unl-blanco);\r\n            border: 1px solid var(--gi-rule);\r\n            border-radius: 10px;\r\n            box-shadow: var(--gi-shadow);\r\n        }\r\n        .gited-search label {\r\n            display: block;\r\n            font-size: 11px;\r\n            font-weight: 700;\r\n            letter-spacing: 0.06em;\r\n            text-transform: uppercase;\r\n            color: var(--gi-mute);\r\n            margin-bottom: 5px;\r\n        }\r\n        .gited-input-wrap {\r\n            position: relative;\r\n            display: block;\r\n        }\r\n        .gited-input {\r\n            width: 100%;\r\n            font-family: inherit;\r\n            font-size: 14px;\r\n            color: var(--gi-tinta);\r\n            background: var(--unl-blanco);\r\n            border: 1px solid var(--gi-rule);\r\n            border-radius: 8px;\r\n            padding: 10px 12px 10px 40px;\r\n            transition: border-color 0.2s, box-shadow 0.2s;\r\n        }\r\n        .gited-input:focus {\r\n            outline: none;\r\n            border-color: var(--unl-azul);\r\n            box-shadow: 0 0 0 3px var(--gi-azul-glow);\r\n        }\r\n        .gited-input-icon {\r\n            position: absolute;\r\n            left: 12px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            width: 18px; height: 18px;\r\n            color: var(--gi-mute);\r\n            pointer-events: none;\r\n        }\r\n        .gited-input-hint {\r\n            font-size: 12px;\r\n            color: var(--gi-mute);\r\n            margin-top: 6px;\r\n        }\r\n\r\n        /* ====== GRID ====== */\r\n        .gited-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));\r\n            gap: 18px;\r\n            align-items: stretch;\r\n            margin-bottom: 22px;\r\n        }\r\n\r\n        /* ====== CARD ======\r\n           Ahora es <div> (no <a>) — CKEditor no la reescribe. */\r\n        .gited-card {\r\n            position: relative;\r\n            display: flex;\r\n            flex-direction: column;\r\n            height: 100%;\r\n            background: var(--unl-blanco);\r\n            border: 1px solid var(--gi-rule);\r\n            border-radius: 12px;\r\n            box-shadow: var(--gi-shadow);\r\n            overflow: hidden;\r\n            min-width: 0;\r\n            color: inherit;\r\n            transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;\r\n        }\r\n        .gited-card:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: var(--gi-shadow-h);\r\n            border-color: rgba(0, 76, 123, 0.25);\r\n        }\r\n        .gited-card:hover .gited-img img { transform: scale(1.05); }\r\n\r\n        /* === Imagen === */\r\n        .gited-img {\r\n            position: relative;\r\n            width: 100%;\r\n            aspect-ratio: 16 / 10;\r\n            overflow: hidden;\r\n            background: var(--gi-azul-glow);\r\n        }\r\n        .gited-img img {\r\n            width: 100%;\r\n            height: 100%;\r\n            object-fit: cover;\r\n            object-position: top;\r\n            display: block;\r\n            transition: transform 0.5s ease;\r\n        }\r\n\r\n        /* === Placeholder grupos sin foto === */\r\n        .gited-placeholder {\r\n            position: absolute;\r\n            inset: 0;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            background: linear-gradient(135deg, var(--unl-azul) 0%, var(--unl-navy) 100%);\r\n            color: var(--unl-blanco);\r\n            font-size: clamp(28px, 5vw, 42px);\r\n            font-weight: 700;\r\n            letter-spacing: 0.04em;\r\n            text-align: center;\r\n            padding: 16px;\r\n        }\r\n        .gited-placeholder::before {\r\n            content: '';\r\n            position: absolute;\r\n            inset: 0;\r\n            background-image:\r\n                radial-gradient(circle at 80% 20%, rgba(255,255,255,0.08) 0%, transparent 50%),\r\n                radial-gradient(circle at 20% 80%, rgba(255,255,255,0.05) 0%, transparent 50%);\r\n        }\r\n        .gited-placeholder span { position: relative; z-index: 1; }\r\n\r\n        /* Badge de siglas */\r\n        .gited-siglas {\r\n            position: absolute;\r\n            top: 12px;\r\n            left: 12px;\r\n            z-index: 2;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            font-size: 11px;\r\n            font-weight: 700;\r\n            letter-spacing: 0.06em;\r\n            color: var(--unl-blanco);\r\n            background: var(--unl-verde-texto);\r\n            padding: 4px 10px;\r\n            border-radius: 16px;\r\n            box-shadow: 0 2px 6px rgba(0,0,0,0.18);\r\n        }\r\n\r\n        /* === Cuerpo === */\r\n        .gited-card-body {\r\n            padding: 16px 16px 18px;\r\n            flex: 1;\r\n            display: flex;\r\n            flex-direction: column;\r\n        }\r\n\r\n        /* El nombre del grupo: contiene el único <a> de la card */\r\n        .gited-name {\r\n            font-size: 14.5px;\r\n            font-weight: 600;\r\n            line-height: 1.35;\r\n            margin-bottom: 10px;\r\n        }\r\n        .gited-name a {\r\n            color: var(--unl-azul);\r\n            text-decoration: none;\r\n            display: -webkit-box;\r\n            -webkit-line-clamp: 3;\r\n            -webkit-box-orient: vertical;\r\n            overflow: hidden;\r\n            transition: color 0.2s;\r\n        }\r\n        .gited-name a:hover {\r\n            color: var(--unl-verde-texto);\r\n            text-decoration: underline;\r\n        }\r\n        .gited-name a:focus-visible {\r\n            outline: 2px solid var(--unl-azul);\r\n            outline-offset: 2px;\r\n            border-radius: 2px;\r\n        }\r\n\r\n        /* Director con ícono */\r\n        .gited-director {\r\n            display: flex;\r\n            align-items: flex-start;\r\n            gap: 7px;\r\n            font-size: 12.5px;\r\n            color: var(--gi-tinta-soft);\r\n            line-height: 1.3;\r\n            margin-top: auto;\r\n        }\r\n        .gited-director svg {\r\n            width: 14px;\r\n            height: 14px;\r\n            color: var(--unl-verde-texto);\r\n            flex-shrink: 0;\r\n            margin-top: 1px;\r\n        }\r\n        .gited-director strong {\r\n            display: block;\r\n            font-size: 10.5px;\r\n            letter-spacing: 0.06em;\r\n            text-transform: uppercase;\r\n            font-weight: 600;\r\n            color: var(--gi-mute);\r\n            margin-bottom: 1px;\r\n        }\r\n        .gited-director-info { flex: 1; min-width: 0; }\r\n        .gited-director-name {\r\n            color: var(--gi-tinta);\r\n            font-weight: 500;\r\n        }\r\n\r\n        /* ====== BOTÓN "CARGAR MÁS" ====== */\r\n        .gited-loadmore-wrap { text-align: center; margin-top: 6px; }\r\n        .gited-loadmore {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            font-family: inherit;\r\n            font-size: 14px;\r\n            font-weight: 600;\r\n            color: var(--unl-blanco);\r\n            background: var(--unl-azul);\r\n            border: none;\r\n            border-radius: 8px;\r\n            padding: 11px 22px;\r\n            cursor: pointer;\r\n            transition: background 0.2s, gap 0.2s;\r\n        }\r\n        .gited-loadmore:hover { background: #013a5e; gap: 12px; }\r\n        .gited-loadmore:focus-visible { outline: 2px solid var(--unl-azul); outline-offset: 3px; }\r\n        .gited-loadmore[hidden] { display: none; }\r\n        .gited-loadmore svg { width: 16px; height: 16px; }\r\n\r\n        /* ====== ESTADO VACÍO ====== */\r\n        .gited-empty {\r\n            text-align: center;\r\n            padding: 40px 20px;\r\n            color: var(--gi-mute);\r\n            font-size: 14px;\r\n            background: var(--unl-blanco);\r\n            border: 1px dashed var(--gi-rule);\r\n            border-radius: 10px;\r\n        }\r\n        .gited-empty[hidden] { display: none; }\r\n        .gited-empty strong { color: var(--unl-azul); font-weight: 700; }\r\n\r\n        .gited-card[hidden] { display: none; }\r\n\r\n        /* ============================================================\r\n           RESPONSIVE\r\n           ============================================================ */\r\n        @media (max-width: 900px) {\r\n            .gited-grid {\r\n                grid-template-columns: repeat(2, 1fr);\r\n                gap: 14px;\r\n            }\r\n            .gited-card-body { padding: 14px 14px 16px; }\r\n            .gited-name { font-size: 14px; }\r\n        }\r\n\r\n        @media (max-width: 520px) {\r\n            .gited-wrap { padding: 12px 0 32px; }\r\n            .gited-banner {\r\n                flex-direction: column;\r\n                align-items: flex-start;\r\n                gap: 6px;\r\n                padding: 14px 16px;\r\n            }\r\n            .gited-banner h2 { font-size: 15px; }\r\n            .gited-stats { margin-left: 0; }\r\n            .gited-search { padding: 12px; }\r\n            .gited-input { font-size: 16px; }\r\n            .gited-input-hint { font-size: 11.5px; }\r\n            .gited-grid {\r\n                grid-template-