y Soraya Zuñiga Tinizaray</span></div></div></div></div></div><div class="gited-empty" hidden="" id="gited-empty"><strong>No se encontraron grupos</strong> con esa búsqueda.<br>Prueba con otras palabras (nombre completo, siglas o director).</div><div class="gited-loadmore-wrap"><button class="gited-loadmore" id="gited-loadmore" type="button">Cargar más grupos <svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" viewBox="0 0 24 24"><path d="M12 5v14M19 12l-7 7-7-7"></path></svg></button></div></div></div><script>\r\n    (function () {\r\n        'use strict';\r\n\r\n        const PROYECTOS_POR_PAGINA = 8;\r\n        const ESPERA_ANTES_DE_FILTRAR_MS = 120;\r\n        const MAX_CARACTERES_BUSQUEDA = 80;\r\n\r\n        const inputBusqueda = document.getElementById('gited-q');\r\n        const contenedorTarjetas = document.getElementById('gited-grid');\r\n        const etiquetaContador = document.getElementById('gited-stats');\r\n        const mensajeSinResultados = document.getElementById('gited-empty');\r\n        const botonCargarMas = document.getElementById('gited-loadmore');\r\n\r\n        if (!contenedorTarjetas) return;\r\n\r\n        const tarjetas = Array.from(contenedorTarjetas.querySelectorAll('.js-gited-card'))\r\n            .map(elemento => ({\r\n                elemento: elemento,\r\n                textoBuscable: (elemento.dataset.search || '').toLowerCase()\r\n            }));\r\n\r\n        let cantidadVisible = 0;\r\n        let tarjetasCoincidentes = [];\r\n\r\n        function quitarAcentosYMinusculas(texto) {\r\n            return String(texto)\r\n                .normalize('NFD')\r\n                .replace(/[\\u0300-\\u036f]/g, '')\r\n                .toLowerCase()\r\n                .trim();\r\n        }\r\n\r\n        function ejecutarTrasPausaEnTecleo(funcion, milisegundos) {\r\n            let temporizador = 0;\r\n            return function () {\r\n                clearTimeout(temporizador);\r\n                temporizador = setTimeout(funcion, milisegundos);\r\n            };\r\n        }\r\n\r\n        function filtrarTarjetasSegunBusqueda() {\r\n            const valorIngresado = inputBusqueda\r\n                ? String(inputBusqueda.value || '').slice(0, MAX_CARACTERES_BUSQUEDA)\r\n                : '';\r\n            const textoBuscado = quitarAcentosYMinusculas(valorIngresado);\r\n\r\n            tarjetasCoincidentes = tarjetas.filter(tarjeta => {\r\n                return !textoBuscado || tarjeta.textoBuscable.includes(textoBuscado);\r\n            });\r\n\r\n            cantidadVisible = Math.min(PROYECTOS_POR_PAGINA, tarjetasCoincidentes.length);\r\n            actualizarLoQueSeVeEnPantalla();\r\n        }\r\n\r\n        function actualizarLoQueSeVeEnPantalla() {\r\n            const tarjetasQueDebenVerse = new Set(\r\n                tarjetasCoincidentes.slice(0, cantidadVisible).map(t => t.elemento)\r\n            );\r\n\r\n            tarjetas.forEach(tarjeta => {\r\n                if (tarjetasQueDebenVerse.has(tarjeta.elemento)) {\r\n                    tarjeta.elemento.removeAttribute('hidden');\r\n                } else {\r\n                    tarjeta.elemento.setAttribute('hidden', '');\r\n                }\r\n            });\r\n\r\n            actualizarContador();\r\n            actualizarMensajeSinResultados();\r\n            actualizarBotonCargarMas();\r\n        }\r\n\r\n        function actualizarContador() {\r\n            if (!etiquetaContador) return;\r\n\r\n            const total = tarjetas.length;\r\n            const coincidencias = tarjetasCoincidentes.length;\r\n\r\n            if (coincidencias === total) {\r\n                etiquetaContador.textContent = total + (total === 1 ? ' grupo' : ' grupos');\r\n            } else {\r\n                etiquetaContador.textContent = coincidencias + ' de ' + total + ' grupos';\r\n            }\r\n        }\r\n\r\n        function actualizarMensajeSinResultados() {\r\n            if (!mensajeSinResultados) return;\r\n\r\n            if (tarjetasCoincidentes.length === 0) {\r\n                mensajeSinResultados.removeAttribute('hidden');\r\n            } else {\r\n                mensajeSinResultados.setAttribute('hidden', '');\r\n            }\r\n        }\r\n\r\n        function actualizarBotonCargarMas() {\r\n            if (!botonCargarMas) return;\r\n\r\n            const quedanOcultas = cantidadVisible < tarjetasCoincidentes.length;\r\n            if (quedanOcultas) {\r\n                botonCargarMas.removeAttribute('hidden');\r\n            } else {\r\n                botonCargarMas.setAttribute('hidden', '');\r\n            }\r\n        }\r\n\r\n        const filtrarConPausa = ejecutarTrasPausaEnTecleo(\r\n            filtrarTarjetasSegunBusqueda,\r\n            ESPERA_ANTES_DE_FILTRAR_MS\r\n        );\r\n\r\n        if (inputBusqueda) {\r\n            inputBusqueda.addEventListener('input', function () {\r\n                if (inputBusqueda.value.length > MAX_CARACTERES_BUSQUEDA) {\r\n                    inputBusqueda.value = inputBusqueda.value.slice(0, MAX_CARACTERES_BUSQUEDA);\r\n                }\r\n                filtrarConPausa();\r\n            });\r\n        }\r\n\r\n        if (botonCargarMas) {\r\n            botonCargarMas.addEventListener('click', function () {\r\n                cantidadVisible = Math.min(\r\n                    cantidadVisible + PROYECTOS_POR_PAGINA,\r\n                    tarjetasCoincidentes.length\r\n                );\r\n                actualizarLoQueSeVeEnPantalla();\r\n            });\r\n        }\r\n\r\n        filtrarTarjetasSegunBusqueda();\r\n    })();\r\n    </script>	full_html
texto_libre	0	150	1641	en	0	<p>&nbsp;</p><table class="table" style="width:100%;" border="0" cellpadding="6" cellspacing="6"><tbody><tr><td class="text-align-justify" style="width:375px;">Los programas y proyectos de vinculación con la sociedad de la Universidad Nacional de Loja (UNL) se caracterizan por su pertinencia social y académica. Estos se articulan de manera coherente con los dominios académicos y las líneas de investigación institucionales, y se desarrollan en los ámbitos de servicios comunitarios y sociales, innovación y servicios especializados. Su planificación, ejecución y seguimiento están orientados y coordinados por la Coordinación de Vinculación con la Sociedad.</td><td style="width:1px;">&nbsp;</td><td style="width:556px;"><img src="/sites/default/files/inline-images/505388691_1137621005079080_6719966560439682319_n_0.jpg" data-entity-uuid="e48e8762-1670-4bf2-9f18-e50543c18358" data-entity-type="file" alt="robot vinculacion" width="489" height="275"></td></tr></tbody></table><p>&nbsp;</p><h3 class="text-align-justify"><strong>Áreas de intervención:</strong></h3><ul><li data-list-item-id="e774e8b906c6b0986a82ca2a92ca0fc9f">Salud integral y bienestar humano</li><li data-list-item-id="e8dd2002a71ef473d5b8a680c40f2d939">Gestión jurídica, social, administrativa, financiera, inclusión y emprendimiento</li><li data-list-item-id="e2308e0e128b0d0ac62332beb4454a0de">Desarrollo agropecuario sostenible y salud animal</li><li data-list-item-id="e2e8f6ddcb356b9910e9541120926ae45">Ambiente y cambio climático</li><li data-list-item-id="ee735add857aa06aa6cb9e5ecec8c6a78">Educación, pedagogía y didáctica</li><li data-list-item-id="e4a6a9babf97c44c511441d5e322663c1">Arte, cultura, comunicación y recreación</li><li data-list-item-id="ebb61a05f0f0c78445abf228fc22c5234">Industria, innovación y desarrollo tecnológico</li><li data-list-item-id="e32f35f563e379a91aaeb8849c3306b7e">Gestión sostenible de la energía</li><li data-list-item-id="eb549fb1a3f9bb335a7bd1dfedf17c78a">Manejo Sostenible de los recursos minerales y geológico-ambientales</li></ul><hr><h3 class="text-align-justify" style="line-height:1.38;"><strong>¿Cómo proponer un proyecto de vinculación?</strong></h3><p data-end="609" data-start="189">Los proyectos de Vinculación con la Sociedad se elaboran en coherencia con el proyecto curricular de cada carrera y se alinean con sus campos específicos de conocimiento. Estas iniciativas están orientadas a dar respuesta a problemáticas reales o a satisfacer necesidades de la sociedad, priorizando, siempre que sea posible, la atención a personas o grupos en situación de vulnerabilidad y promoviendo un enfoque de igualdad, de acuerdo con la naturaleza de cada carrera o programa.&nbsp;Asimismo, los resultados de investigación no solo se comparten con la sociedad, sino que pueden dar origen a nuevos proyectos de vinculación. De igual manera, las experiencias y resultados de estos proyectos pueden convertirse en insumos valiosos para el desarrollo de futuras investigaciones, fortaleciendo así la integración entre docencia, investigación y vinculación.</p><p data-end="609" data-start="189">Con el propósito de unificar criterios y facilitar la formulación de los proyectos de Vinculación con la Sociedad, la Universidad Nacional de Loja pone a disposición un <strong data-end="393" data-start="358">formato&nbsp;</strong>y una<strong data-end="393" data-start="358">&nbsp;guía metodológica</strong> que orientan el diseño, desarrollo y seguimiento de las propuestas. Esta herramienta busca simplificar el proceso de elaboración de proyectos y fortalecer su gestión y control por parte de la función de Vinculación.</p><p data-end="935" data-start="611">La guía establece el uso de la metodología de marco lógico, una herramienta práctica que permite organizar de manera clara las ideas del proyecto, desde su planificación hasta su evaluación. Gracias a esta metodología, se facilita la conceptualización, ejecución y comunicación de los elementos clave de cada iniciativa.</p><p data-end="1869" data-start="1795">📩 Para más información, escríbenos a: <a data-end="1867" data-start="1836" rel="noopener"><strong data-end="1869" data-start="1834">vinculacion.sociedad@unl.edu.ec</strong></a></p><hr><h3><a href="https://datastudio.google.com/u/0/reporting/0f500b7d-8a50-4173-a1de-1ddab911225e/page/p_hlpjzslzuc" title="Dashboard PROYECTOS"><strong>Proyectos de Vinculación en cifras</strong></a>&nbsp;</h3><p><font color="#000000" face="Montserrat, sans-serif"><span style="font-size:14px;white-space:pre-wrap;">REVISA LAS CIFRAS DE IMPACTO DE NUESTRA ACCIÓN.</span></font></p><hr><img src="/sites/default/files/inline-images/MEMBRETADA%20UNL_Mesa%20de%20trabajo%201%20copia_3.png" data-align="center" data-entity-uuid="a13abe64-c345-448f-8e54-a1af797b4809" data-entity-type="file" alt="hhhh" width="338" height="52"><h3><strong>Formatos</strong></h3>	full_html
texto_libre	0	154	1699	es	0	<h4 class="text-align-center">&nbsp;</h4><p class="text-align-justify">Desde la <strong>Coordinación de Vinculación con la Sociedad</strong>, el conocimiento universitario deja de ser un activo estático para convertirse en un motor de cambio social mediante procesos estratégicos de transferencia. Esta labor se materializa en la organización de eventos científicos:&nbsp;<b data-index-in-node="258" data-path-to-node="0"><strong>congresos, seminarios, jornadas científicas, etcétera;</strong></b>&nbsp;espacios diseñados para democratizar los hallazgos académicos y fomentar el diálogo con sectores productivos y comunitarios. Al sacar la investigación de las aulas y exponerla en estos foros de divulgación, la UNL asegura que la innovación científica se traduzca en soluciones prácticas, fortaleciendo el tejido social y garantizando que el saber académico responda a las necesidades reales del entorno.</p><p class="text-align-center">&nbsp;</p><table class="table"><tbody><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/sic2024"><img src="/sites/default/files/inline-images/SIC_0.jpg" data-align="center" data-entity-uuid="5092722b-133e-4871-a83a-2d7f2c55360f" data-entity-type="file" alt="SIC" width="241" height="136"></a><p class="text-align-center"><a href="https://unl.edu.ec/sic2024" title="SIC"><strong>III Simposio de Investigación Científica: Ciencia para un futuro sostenible</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/cienf2025" title="CIENF web"><img src="/sites/default/files/inline-images/Logo%20Congreso%20Enfermeri%CC%81a_0.png" data-align="center" data-entity-uuid="49964352-7c3e-4ae0-aaa8-2e8f27bb6282" data-entity-type="file" alt="enf" width="296" height="137"></a><p class="text-align-center"><a href="https://unl.edu.ec/cienf2025" title="CIENF"><strong>Congreso Internacional de Enfermería: Cuidado, Innovación e Investigación en el ámbito Familiar y Comunitario</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/cicafise" title="cicafise"><img src="/sites/default/files/inline-images/CICAFISE.jpg" data-align="center" data-entity-uuid="ebc29feb-9da7-4c7a-bafa-6ddc9e9a56e7" data-entity-type="file" alt="CICAFISE" width="337" height="98"></a><p class="text-align-center"><a href="https://unl.edu.ec/cicafise" title="cicafise web"><strong>I Congreso Internacional de Investigación en Contabilidad, Auditoría y Finanzas: Innovación y Sostenibilidad Empresarial</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><img src="/sites/default/files/inline-images/Odontologi%CC%81a.jpg" data-align="center" data-entity-uuid="2bada46c-4b0e-4519-a87d-eefd61d8c4aa" data-entity-type="file" alt="Odonto" width="332" height="54"><p class="text-align-center"><strong>I Jornadas Científicas Internacionales de la Carrera de Odontología UNL</strong></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/ciedl" title="rde3r23"><img src="/sites/default/files/inline-images/CIEDL.jpg" data-align="center" data-entity-uuid="0cdbc4c4-2eee-4e77-ba42-1daf886ef481" data-entity-type="file" alt="CIEDL" width="324" height="83"></a><p class="text-align-center"><a href="https://unl.edu.ec/ciedl" title="efded"><strong>II Congreso Internacional de Educación a Distancia y en Línea: Experiencias y perspectivas</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/relas2024" title="er3"><img src="/sites/default/files/inline-images/RELAS_0.jpg" data-align="center" data-entity-uuid="a6916f0b-be12-4741-89d1-0125f942ee9e" data-entity-type="file" alt="RELAS" width="224" height="127"></a><p class="text-align-center"><a href="https://unl.edu.ec/relas2024" title="relas"><strong>XIV Reunión Latinoamericana de Scarabaeoidología (RELAS) 2024</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/cigecop2024" title="4f4f4"><img src="/sites/default/files/inline-images/CIGECOP.jpg" data-align="center" data-entity-uuid="8233e280-9531-4ac9-8f6e-00398a6dc5c9" data-entity-type="file" alt="CIGECOP" width="276" height="88"></a><p class="text-align-center"><a href="https://unl.edu.ec/cigecop2024" title="r4r4r"><strong>Primer Congreso Internacional de Gestión y Contratación Pública. Desafíos y perspectivas 2024</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://www.unl.edu.ec/elesl/2021" title="lidi"><img src="/sites/default/files/inline-images/LIDI_0.png" data-align="center" data-entity-uuid="88a60028-0fd1-4655-a1ce-5bb31582125d" data-entity-type="file" alt="LIDI" width="329" height="102"></a><p class="text-align-center"><a href="https://www.unl.edu.ec/elesl/2021" title="lidi"><strong>I Congreso Nacional de Enseñanza de Lenguas Extranjeras y Lenguas Segundas:</strong></a></p><p class="text-align-center"><a href="https://www.unl.edu.ec/elesl/2021" title="lidi"><strong>Investigación, Experiencias y Perspectivas durante y pospandemia</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://unl.edu.ec/cerp/2021" title="cerp img"><img src="/sites/default/files/inline-images/CERP.jpg" data-align="center" data-entity-uuid="310a4f90-d7eb-4f21-b2c9-e3b1539b4fd5" data-entity-type="file" alt="cerp" width="238" height="163"></a><p class="text-align-center"><a href="https://unl.edu.ec/cerp/2021" title="cerp"><strong>II Congreso Ecuatoriano de Restauración del Paisaje</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr><tr><td nowrap="nowrap"><a href="https://www.unl.edu.ec/joim2026" title="f4f4f"><img src="/sites/default/files/inline-images/JOIM_0.jpg" data-align="center" data-entity-uuid="2e299acf-d8ba-4dcc-85ea-6b9696afff31" data-entity-type="file" alt="JOIM" width="291" height="199"></a><p class="text-align-center"><a href="https://www.unl.edu.ec/joim2026" title="4f4f"><strong>Jornadas de Investigación Musical</strong></a></p><p class="text-align-center">&nbsp;</p></td></tr></tbody></table>	full_html
