: 24px; }\r\n\r\n    /* =========================================\r\n       4. ESTRUCTURA DE ESTADÍSTICAS (MÓVIL PRIMERO)\r\n       ========================================= */\r\n    .di-bloque__stats {\r\n      padding: 32px 32px 48px 32px;\r\n      display: grid;\r\n      grid-template-columns: 1fr; /* 1 columna por defecto en móviles */\r\n      gap: 40px;\r\n    }\r\n\r\n    .di-stat {\r\n      text-align: center;\r\n      position: relative;\r\n      padding: 0 16px;\r\n    }\r\n\r\n    .di-stat__numero {\r\n      display: block;\r\n      font-size: 56px;\r\n      font-weight: 800;\r\n      color: #081f49;\r\n      line-height: 1;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .di-stat__etiqueta {\r\n      display: block;\r\n      font-size: 14px;\r\n      font-weight: 700;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n      color: #666666;\r\n    }\r\n\r\n    /* =========================================\r\n       5. ADAPTACIÓN A PANTALLAS GRANDES (DESKTOP)\r\n       ========================================= */\r\n    @media (min-width: 768px) {\r\n      /* Pasa a 4 columnas */\r\n      .di-bloque__stats--4cols {\r\n        grid-template-columns: repeat(4, 1fr);\r\n      }\r\n\r\n      /* Agrega los divisores verticales solo en desktop y no al último elemento */\r\n      .di-stat:not(:last-child)::after {\r\n        content: "";\r\n        position: absolute;\r\n        right: -20px;\r\n        top: 15%;\r\n        height: 70%;\r\n        width: 1px;\r\n        background-color: #081f49;\r\n        opacity: 0.15;\r\n      }\r\n    }\r\n</style><div class="di-bloque"><!-- Cabecera de Presentación --><div class="di-bloque__hero"><h2 class="di-bloque__titulo">Investigación UNL</h2><p class="di-bloque__descripcion">Impulsamos la producción científica, planificando y apoyando la generación de conocimiento científico y la innovación tecnológica.</p></div><!-- SECCIÓN 1: Estructura --><div class="di-divisor">Estructura de Investigación</div>