d-image"><div class="field-content"><a href="/cite" hreflang="es"><img src="/sites/default/files/inline-images/LAPP_1.jpg" alt="Laboratorio de Administración y Políticas Públicas (LAPP)" width="657" height="429"></a></div></div><div class="views-field views-field-title"><a href="/laap" hreflang="es"><span class="field-content">Laboratorio de Administración y Políticas Públicas (LAPP)</span></a></div></div><div class="facultad-carrera views-col col-2" style="width:50%;"><div class="views-field views-field-field-image"><div class="field-content"><a href="/investigacion/centro-investigacion-innovacion-tecnologica" hreflang="es"><img src="/sites/default/files/inline-images/I2TEC.jpg" data-entity-uuid="078d109e-8567-420b-b722-a3646022e7b8" data-entity-type="file" alt="I2TEC"></a></div></div><div class="views-field views-field-title"><a href="/investigacion/centro-investigacion-innovacion-tecnologica" hreflang="es"><span class="field-content">Centro de Investigación, Innovación y Tecnología I2TEC&nbsp;</span></a></div></div></div><div class="views-row clearfix row-4"><div class="facultad-carrera views-col col-1" style="width:50%;"><div class="views-field views-field-field-image"><div class="field-content"><div class="views-field views-field-field-image"><div class="field-content"><a href="/investigacion/centro-investigacion-desarrollo-innovacion-nutricion-animal" hreflang="es"><img src="/sites/default/files/inline-images/CIDiNA.jpeg" data-entity-uuid="65a5d28a-90d1-45ef-b96b-f0b28f8ee719" data-entity-type="file" alt="Cidina"></a></div></div><div class="views-field views-field-title"><a href="/investigacion/centro-investigacion-desarrollo-innovacion-nutricion-animal" hreflang="es"><span class="field-content">Centro de Investigación, Desarrollo e Innovación en Nutrición Animal (CIDiNA)</span></a></div></div></div></div></div></div>	full_html
texto_libre	0	126	1755	es	0	<style type="text/css">:root {\r\n            --ink: #0a1f3d;\r\n            --ink-soft: #1e3a5f;\r\n            --ink-mute: #5a6b85;\r\n            --bg: #ffffff;\r\n            --bg-card: #fcfcfc;\r\n\r\n            --accent: #4F8E3A;\r\n            --accent-light: #648F39;\r\n            --accent-text: #247A1E;\r\n            --accent-glow: rgba(79, 142, 58, 0.08);\r\n            --accent-soft: rgba(79, 142, 58, 0.20);\r\n            --accent-soft-2: rgba(79, 142, 58, 0.25);\r\n\r\n            --rule: #e4e7ec;\r\n            --rule-soft: #f1f3f5;\r\n            --shadow-sm: 0 2px 8px rgba(15, 23, 42, 0.06), 0 1px 2px rgba(15, 23, 42, 0.04);\r\n            --shadow-lg: 0 28px 56px -12px rgba(15, 23, 42, 0.18), 0 8px 16px rgba(15, 23, 42, 0.08);\r\n        }\r\n\r\n        .lineas-unl * {\r\n            box-sizing: border-box;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n\r\n        .lineas-unl {\r\n            font-family: 'Montserrat', system-ui, sans-serif;\r\n          \r\n            color: var(--ink);\r\n            line-height: 1.55;\r\n            -webkit-font-smoothing: antialiased;\r\n        }\r\n\r\n         .lineas-unl .lineas-wrap {\r\n            width: 100%;\r\n            margin: 0 auto;\r\n            padding: 16px 0 48px;\r\n        }\r\n\r\n        /* ====== HEADER ====== */\r\n        .lineas-unl .page-header {\r\n            margin-bottom: 56px;\r\n            max-width: 820px;\r\n        }\r\n\r\n        .lineas-unl .eyebrow {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            font-size: 12px;\r\n            font-weight: 600;\r\n            letter-spacing: 0.14em;\r\n            text-transform: uppercase;\r\n            color: var(--accent-text);\r\n            margin-bottom: 24px;\r\n        }\r\n\r\n        .lineas-unl .eyebrow::before {\r\n            content: '';\r\n            width: 28px;\r\n            height: 1px;\r\n            background: var(--accent);\r\n        }\r\n\r\n        .lineas-unl .page-title {\r\n            font-family: 'Montserrat', Georgia, serif;\r\n            font-size: clamp(36px, 4.5vw, 56px);\r\n            font-weight: 700;\r\n            line-height: 1.05;\r\n            letter-spacing: -0.02em;\r\n            color: var(--ink);\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .lineas-unl .page-title em {\r\n            font-style: italic;\r\n            font-weight: 400;\r\n            color: var(--accent-text);\r\n        }\r\n\r\n        .lineas-unl .page-lead {\r\n            font-size: 14px;\r\n            text-align: justify;\r\n            color: var(--ink-mute);\r\n            max-width: 880px;\r\n            margin-bottom: 14px;\r\n        }\r\n\r\n        .lineas-unl .page-intro {\r\n            font-size: 14px;\r\n            color: var(--ink-mute);\r\n            margin-top: 16px;\r\n            margin-bottom: 16px;\r\n            max-width: 720px;\r\n        }\r\n\r\n        /* ====== GRID ====== */\r\n        .lineas-unl .lines-grid {\r\n            display: grid;\r\n            width: 100%;\r\n            /* min(390px, 100%) evita el desborde si el contenedor fuera más\r\n               angosto que 390px*/\r\n            grid-template-columns: repeat(auto-fit, minmax(min(390px, 100%), 1fr));\r\n            gap: 24px;\r\n            /* FIX UX: 'start' evita que toda la fila iguale su altura\r\n               a la card expandida. Cada card crece de forma independiente. */\r\n            align-items: start;\r\n        }\r\n\r\n        /* ====== CARD ====== */\r\n        .lineas-unl .line-card {\r\n            background: var(--bg-card);\r\n            border-radius: 14px;\r\n            position: relative;\r\n            border: 1px solid #eaecf0;\r\n            box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04), 0 1px 2px rgba(15, 23, 42, 0.03);\r\n            transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),\r\n                box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1),\r\n                border-color 0.3s ease;\r\n            display: flex;\r\n            flex-direction: column;\r\n            overflow: hidden;\r\n            /* Permite que la card se encoja dentro del grid (evita desbordes\r\n               por el min-width:auto que traen por defecto los items de grid). */\r\n            min-width: 0;\r\n        }\r\n\r\n        /* Contenido de la card */\r\n        .lineas-unl .card-clickable {\r\n            display: flex;\r\n            flex-direction: column;\r\n            padding: 26px;\r\n        }\r\n\r\n        /* Radio oculto que controla el estado abierto/cerrado por card.\r\n           Al compartir name="linea-acordeon", solo UNA card queda abierta a la vez. */\r\n        .lineas-unl .card-toggle {\r\n            position: absolute;\r\n            opacity: 0;\r\n            width: 1px;\r\n            height: 1px;\r\n            pointer-events: none;\r\n        }\r\n\r\n        .lineas-unl .line-card::before {\r\n            content: '';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            bottom: 0;\r\n            width: 3px;\r\n            background: var(--accent);\r\n            transform: scaleY(0.3);\r\n            transform-origin: top;\r\n            transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);\r\n        }\r\n\r\n        .lineas-unl .line-card:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: var(--shadow-lg);\r\n            border-color: var(--accent-soft);\r\n        }\r\n\r\n        .lineas-unl .line-card:hover::before {\r\n            transform: scaleY(1);\r\n        }\r\n\r\n        /* Estado expandido: cuando el radio de esta card está marcado */\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .card-bar-trigger,\r\n        .lineas-unl .line-card:has(.card-toggle:checked)::before {\r\n            transform: scaleY(1);\r\n        }\r\n\r\n        .lineas-unl .line-card:has(.card-toggle:checked) {\r\n            box-shadow: var(--shadow-lg);\r\n            border-color: var(--accent-soft-2);\r\n        }\r\n\r\n        /* card header */\r\n        .lineas-unl .card-head {\r\n            display: flex;\r\n            align-items: flex-start;\r\n            justify-content: space-between;\r\n            gap: 16px;\r\n            margin-bottom: 22px;\r\n        }\r\n\r\n        .lineas-unl .card-icon {\r\n            width: 44px;\r\n            height: 44px;\r\n            border-radius: 10px;\r\n            background: var(--accent-glow);\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: var(--accent-text);\r\n            flex-shrink: 0;\r\n            transition: background 0.3s ease, color 0.3s ease;\r\n        }\r\n\r\n        .lineas-unl .line-card:hover .card-icon,\r\n        .lineas-unl .line-card:has(.card-toggle:checked) .card-icon {\r\n            background: var(--accent);\r\n            color: #ffffff;\r\n        }\r\n\r\n        .lineas-unl .card-icon svg {\r\n            width: 22px;\r\n            height: 22px;\r\n            stroke-width: 1.8;\r\n        }\r\n\r\n        .lineas-unl .card-number {\r\n            font-family: 'Montserrat', serif;\r\n            font-size: 10px;\r\n            font-weight: 500;\r\n            color: var(--ink-mute);\r\n            letter-spacing: 0.05em;\r\n            font-feature-settings: 'tnum';\r\n            padding-top: 8px;\r\n            margin-top: 8px;\r\n        }\r\n\r\n        .lineas-unl .card-title {\r\n            font-family: 'Montserrat', serif;\r\n            font-size: 16px;\r\n            font-weight: 600;\r\n            line-height: 1.3;\r\n            letter-spacing: -0.01em;\r\n            color: var(--ink);\r\n            margin-bottom: 16px;\r\n        }\r\n\r\n        /* ====== DESCRIPCIÓN COLAPSABLE ======*/\r\n        .lineas-unl .card-desc-wrap {\r\n            position: relative;\r\n            display: grid;\r\n            grid-template-rows: 0fr;\r\n            transition: grid-template-rows 0.55s cubic-bezier(0.16, 1, 0.3, 1);\r\n        }\r\n\r\n        .lineas-unl .card-desc {\r\n            font-size: 14px;\r\n            color: var(--ink-soft);\r\n            line-height: 1.6;\r\n            overflow: hidden;\r\n            min-height: 0;\r\n           \r\n            max-height: 96px;\r\n            transition: max-height 0.55s cubic-bezier(0.16, 1, 0.3, 1);\r\n            position: relative;\r\n        }\r\n\r\n  \r\n        .lineas-unl .card-desc-wrap::after {\r\n            content: '';\r\n            position: absolute;\r\n            bottom: 0;\r\n            left: 0;\r\n            right: 0;\r\n            height: 48px;\r\n            background: linear-gradient(to bottom, transparent, var(--bg-card) 85%);\r\n            pointer-events: none;\r\n            transition: opacity 0.4s ease;\r\n        }\r\n\r\n        /* Expandido */\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .card-desc-wrap {\r\n            grid-template-rows: 1fr;\r\n        }\r\n\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .card-desc {\r\n            max-height: 1200px;\r\n        }\r\n\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .card-desc-wrap::after {\r\n            opacity: 0;\r\n        }\r\n\r\n        /* ====== BOTÓN LEER MÁS / MOSTRAR MENOS ======\r\n           Son <label> que apuntan a los radios. El "abrir" apunta a este radio;\r\n           el "cerrar" apunta a un radio neutro común que desmarca todo. */\r\n        .lineas-unl .read-more-btn {\r\n            background: none;\r\n            border: none;\r\n            padding: 14px 0 0;\r\n            font-family: 'Montserrat', sans-serif;\r\n            font-size: 14px;\r\n            font-weight: 600;\r\n            color: var(--accent-text);\r\n            cursor: pointer;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            transition: gap 0.25s ease, color 0.25s ease;\r\n            width: 100%;\r\n            justify-content: flex-start;\r\n            position: relative;\r\n        }\r\n\r\n        .lineas-unl .read-more-btn:hover {\r\n            gap: 12px;\r\n            color: var(--accent);\r\n        }\r\n\r\n        .lineas-unl .read-more-btn svg {\r\n            width: 14px;\r\n            height: 14px;\r\n            transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);\r\n        }\r\n\r\n        /* La flecha rota cuando la card está expandida */\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .read-more-btn svg {\r\n            transform: rotate(180deg);\r\n        }\r\n\r\n        /* Alterna los botones (labels) según el estado de la card */\r\n        .lineas-unl .label-open { display: inline-flex; }\r\n        .lineas-unl .label-close { display: none; }\r\n\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .label-open { display: none; }\r\n        .lineas-unl .card-toggle:checked ~ .card-clickable .label-close { display: inline-flex; }\r\n\r\n    \r\n        .lineas-unl .read-more-btn:focus-visible {\r\n            outline: 2px solid var(--accent);\r\n            outline-offset: 3px;\r\n            border-radius: 4px;\r\n        }\r\n\r\n        /* badge */\r\n        .lineas-unl .linea-badge {\r\n            position: absolute;\r\n            top: 26px;\r\n            right: 28px;\r\n            font-size: 10px;\r\n            font-weight: 600;\r\n            color: var(--accent-text);\r\n            text-transform: uppercase;\r\n            letter-spacing: 0.1em;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 5px;\r\n            \r\n            z-index: 1;\r\n        }\r\n\r\n        .lineas-unl .linea-badge::before {\r\n            content: '';\r\n            width: 6px;\r\n            height: 6px;\r\n            border-radius: 50%;\r\n            background: var(--accent);\r\n        }\r\n\r\n        /* responsive: por debajo de 720px, 1 sola columna garantizada */\r\n        @media (max-width: 720px) {\r\n            .lineas-unl .lineas-wrap {\r\n                padding: 12px 0 40px;\r\n            }\r\n\r\n            .lineas-unl .lines-grid {\r\n                grid-template-columns: 1fr;\r\n            }\r\n\r\n            .lineas-unl .card-clickable {\r\n                padding: 24px;\r\n            }\r\n        }\r\n\r\n        \r\n        @media (prefers-reduced-motion: no-preference) {\r\n            .lineas-unl .line-card {\r\n                opacity: 0;\r\n                transform: translateY(12px);\r\n                animation: rise 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;\r\n                /* Escalonado con variable, sin 11 reglas :nth-child */\r\n                animation-delay: calc(var(--i, 0) * 0.05s);\r\n            }\r\n\r\n            @keyframes rise {\r\n                to {\r\n                    opacity: 1;\r\n                    transform: translateY(0);\r\n                }\r\n            }\r\n        }\r\n</style><div class="lineas-unl"><div class="lineas-wrap"><p><input class="card-toggle" hidden="" id="linea-cerrar" name="linea-acordeon" type="radio"></p><p class="page-lead">La investigación académico-científica es una labor creativa, sistemática, rigurosa, sistémica, epistemológica y metodológicamente fundamentada, que está orientada a producir conocimiento, a desarrollar tecnología y a innovar en los diferentes campos científicos con el fin de solucionar problemas de la realidad.</p><p class="page-lead">La investigación se planifica en correspondencia con las políticas y objetivos institucionales, los dominios académicos, el código de ética y las líneas de investigación; se ejecuta con la participación de docentes, técnicos, estudiantes y grupos de investigación a través de programas y proyectos, en escenarios como estaciones científicas, centros y laboratorios de investigación y otros a nivel interno y externo.</p><p class="page-lead">En este marco, las líneas de investigación institucionales que se presentan a continuación, son ejes temáticos que direccionan programas y proyectos hacia la producción de conocimiento y la potenciación de saberes ancestrales, como base para la innovación y transferencia.</p><p class="page-intro">A continuación, se describen las 11 líneas de investigación institucionales:</p><div class="lines-grid"><!-- LÍNEA 1 --><article class="line-card" style="--i:1;"><p><input class="card-toggle" id="linea-1" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M2 9.5a5.5 5.5 0 0 1 9.591-3.676.56.56 0 0 0 .818 0A5.49 5.49 0 0 1 22 9.5c0 2.29-1.5 4-3 5.5l-5.492 5.313a2 2 0 0 1-3 .019L5 15c-1.5-1.5-3-3.2-3-5.5"></path><path d="M3.22 13H9.5l.5-1 2 4.5 2-7 1.5 3.5h5.27"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Salud integral para el desarrollo sostenible de la región sur</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir, a través de la investigación, al desarrollo de la salud integral a través de la promoción, identificación de factores determinantes que afectan a la salud de la población, prevención, curación y rehabilitación de las principales enfermedades transmisibles, no transmisibles, emergencias y desastres en las personas, familias y comunidades de la Región Sur del Ecuador, incorporando la perspectiva de género, equidad e interculturalidad, discapacidad y movilidad humana en todos los procesos.</p></div><p><label class="read-more-btn label-open" for="linea-1" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 2 --><article class="line-card" style="--i:2;"><p><input class="card-toggle" id="linea-2" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Conversión, transporte y gestión de la energía</h2><div class="card-desc-wrap"><p class="card-desc">Promover la investigación en el desarrollo de proyectos de energía limpia, renovable, que sea una base de un desarrollo social sostenible y que al mismo tiempo sea amigable con el ambiente.</p></div><p><label class="read-more-btn label-open" for="linea-2" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 3 --><article class="line-card" style="--i:3;"><p><input class="card-toggle" id="linea-3" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M12 20v2"></path><path d="M12 2v2"></path><path d="M17 20v2"></path><path d="M17 2v2"></path><path d="M2 12h2"></path><path d="M2 17h2"></path><path d="M2 7h2"></path><path d="M20 12h2"></path><path d="M20 17h2"></path><path d="M20 7h2"></path><path d="M7 20v2"></path><path d="M7 2v2"></path><rect height="16" rx="2" width="16" x="4" y="4"></rect><rect height="8" rx="1" width="8" x="8" y="8"></rect></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Industria, innovación y desarrollo tecnológico</h2><div class="card-desc-wrap"><p class="card-desc">Desarrollar conocimiento, tecnología e innovación a través de la planeación, ejecución y evaluación de proyectos que se enfocan en el análisis de los sistemas modernos de telecomunicaciones; lo que resultará en producciones científicas enfocadas a elevar la calidad de vida de las personas y mejorar el ambiente, tomando como enfoque de las telecomunicaciones como un servicio básico y el derecho al acceso de las mismas.</p></div><p><label class="read-more-btn label-open" for="linea-3" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 4 --><article class="line-card" style="--i:4;"><p><input class="card-toggle" id="linea-4" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="m8 3 4 8 5-5 5 15H2L8 3z"></path><path d="M4.14 15.08c2.62-1.57 5.24-1.43 7.86.42 2.74 1.94 5.49 2 8.23.19"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Aprovechamiento de los recursos minerales, geológicos y ambientales.</h2><div class="card-desc-wrap"><p class="card-desc">Realizar investigación científica pertinente para la generación de conocimientos innovadores en los distintos campos de las Ciencias Geológicas, Ciencias del Suelo, Minería y otros campos afines, así como el desarrollo de la infraestructura analítica y de nuevas tecnologías de servicio en el ámbito de las ciencias de la tierra.</p></div><p><label class="read-more-btn label-open" for="linea-4" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 5 --><article class="line-card" style="--i:5;"><p><input class="card-toggle" id="linea-5" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M18 21a8 8 0 0 0-16 0"></path><circle cx="10" cy="8" r="5"></circle><path d="M22 20c0-3.37-2-6.5-4-8a5 5 0 0 0-.45-8.3"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Agentes, procesos, saberes e innovación en la educación</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir a la generación de nuevos conocimientos sobre la realidad y problemáticas relevantes de la educación en el Ecuador y coadyuvar al correcto planeamiento de las alternativas que mejoren la calidad de los procesos y sus resultados.</p></div><p><label class="read-more-btn label-open" for="linea-5" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 6 --><article class="line-card" style="--i:6;"><p><input class="card-toggle" id="linea-6" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M12 22a1 1 0 0 1 0-20 10 9 0 0 1 10 9 5 5 0 0 1-5 5h-2.25a1.75 1.75 0 0 0-1.4 2.8l.3.4a1.75 1.75 0 0 1-1.4 2.8z"></path><circle cx="13.5" cy="6.5" fill="currentColor" r=".5"></circle><circle cx="17.5" cy="10.5" fill="currentColor" r=".5"></circle><circle cx="6.5" cy="12.5" fill="currentColor" r=".5"></circle><circle cx="8.5" cy="7.5" fill="currentColor" r=".5"></circle></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Arte, culturas y sociedad</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir a la generación de nuevos conocimientos sobre los distintos campos artísticos en la Región Sur del Ecuador, en sus diferentes manifestaciones, y al desarrollo de propuestas innovadoras en lo simbólico y estético.</p></div><p><label class="read-more-btn label-open" for="linea-6" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 7 --><article class="line-card" style="--i:7;"><p><input class="card-toggle" id="linea-7" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M4.9 16.1C1 12.2 1 5.8 4.9 1.9"></path><path d="M7.8 4.7a6.14 6.14 0 0 0-.8 7.5"></path><circle cx="12" cy="9" r="2"></circle><path d="M16.2 4.8c2 2 2.26 5.11.8 7.47"></path><path d="M19.1 1.9a9.96 9.96 0 0 1 0 14.1"></path><path d="M9.5 18h5"></path><path d="m8 22 4-11 4 11"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Procesos, entornos, saberes, y tecnologías de la comunicación</h2><div class="card-desc-wrap"><p class="card-desc">Impulsar investigaciones en el ámbito de la Comunicación para la generación de conocimientos y a la vez dar respuestas a las problemáticas a través de alternativas viables que faciliten los procesos con resultados de calidad sostenibles en el tiempo.</p></div><p><label class="read-more-btn label-open" for="linea-7" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 8 --><article class="line-card" style="--i:8;"><p><input class="card-toggle" id="linea-8" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M12 3v18"></path><path d="m19 8 3 8a5 5 0 0 1-6 0zV7"></path><path d="M3 7h1a17 17 0 0 0 8-2 17 17 0 0 0 8 2h1"></path><path d="m5 8 3 8a5 5 0 0 1-6 0zV7"></path><path d="M7 21h10"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Estudios sociales, jurídicos y del comportamiento</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir a la solución de los problemas sociales, jurídicos y del comportamiento que obstaculizan el desarrollo sostenible e integral y las relaciones armónicas entre los miembros de la población del área de influencia de la universidad, con el fin de buscar un desarrollo humano más incluyente, integral y humanista, acorde con los principios y valores que promueve la Universidad.</p></div><p><label class="read-more-btn label-open" for="linea-8" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 9 --><article class="line-card" style="--i:9;"><p><input class="card-toggle" id="linea-9" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M16 7h6v6"></path><path d="m22 7-8.5 8.5-5-5L2 17"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Economía, administración y desarrollo</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir a la generación de conocimientos que aporten soluciones de los problemas en los ámbitos económicos, administrativos y de desarrollo que afectan a la población del área de influencia de la Universidad, con el fin de ofrecer resultados que lleven a los responsables de la política pública y del sector privado a promover el desarrollo sostenible.</p></div><p><label class="read-more-btn label-open" for="linea-9" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 10 --><article class="line-card" style="--i:10;"><p><input class="card-toggle" id="linea-10" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M2 22 16 8"></path><path d="M3.47 12.53 5 11l1.53 1.53a3.5 3.5 0 0 1 0 4.94L5 19l-1.53-1.53a3.5 3.5 0 0 1 0-4.94Z"></path><path d="M7.47 8.53 9 7l1.53 1.53a3.5 3.5 0 0 1 0 4.94L9 15l-1.53-1.53a3.5 3.5 0 0 1 0-4.94Z"></path><path d="M11.47 4.53 13 3l1.53 1.53a3.5 3.5 0 0 1 0 4.94L13 11l-1.53-1.53a3.5 3.5 0 0 1 0-4.94Z"></path><path d="M20 2h2v2a4 4 0 0 1-4 4h-2V6a4 4 0 0 1 4-4Z"></path><path d="M11.47 17.47 13 19l-1.53 1.53a3.5 3.5 0 0 1-4.94 0L5 19l1.53-1.53a3.5 3.5 0 0 1 4.94 0Z"></path><path d="M15.47 13.47 17 15l-1.53 1.53a3.5 3.5 0 0 1-4.94 0L9 15l1.53-1.53a3.5 3.5 0 0 1 4.94 0Z"></path><path d="M19.47 9.47 21 11l-1.53 1.53a3.5 3.5 0 0 1-4.94 0L13 11l1.53-1.53a3.5 3.5 0 0 1 4.94 0Z"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Sistemas agropecuarios sostenibles para la soberanía alimentaria</h2><div class="card-desc-wrap"><p class="card-desc">Contribuir a la generación de conocimiento científico-técnico en el campo agropecuario y del uso y aprovechamiento sostenible de los recursos para la producción, que garanticen la provisión de alimentos para la población nacional y la exportación.</p></div><p><label class="read-more-btn label-open" for="linea-10" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article><!-- LÍNEA 11 --><article class="line-card" style="--i:11;"><p><input class="card-toggle" id="linea-11" name="linea-acordeon" type="radio"> <span class="linea-badge">Activa</span></p><div class="card-clickable"><div class="card-head"><div class="card-icon"><svg fill="none" stroke="currentColor" viewbox="0 0 24 24"><path d="M14 9.536V7a4 4 0 0 1 4-4h1.5a.5.5 0 0 1 .5.5V5a4 4 0 0 1-4 4 4 4 0 0 0-4 4c0 2 1 3 1 5a5 5 0 0 1-1 3"></path><path d="M4 9a5 5 0 0 1 8 4 5 5 0 0 1-8-4"></path><path d="M5 21h14"></path></svg></div><p><span class="card-number">Línea de investigación</span></p></div><h2 class="card-title">Aprovechamiento de los recursos de la biodiversidad y cambio climático.</h2><div class="card-desc-wrap"><p class="card-desc">Generar información científica-técnica que permita disponer de insumos necesarios para el aprovechamiento y conservación de la biodiversidad de bosques y sistemas económico-productivos y conservación de ecosistemas frágiles, y a la vez entender los fenómenos relacionados con el cambio climático.</p></div><p><label class="read-more-btn label-open" for="linea-11" role="button" tabindex="0"><span>Leer más</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg> </label><label class="read-more-btn label-close" for="linea-cerrar" role="button" tabindex="0"><span>Mostrar menos</span>&nbsp;<svg fill="none" stroke="currentColor" stroke-width="2.5" viewbox="0 0 24 24"> <polyline points="6 9 12 15 18 9"></polyline> </svg></label></p></div></article></div></div></div>	full_html
texto_libre	0	121	1766	es	0	<p class="text-align-justify" style="margin-bottom:13px;"><span style="color:#4f81bd;font-family:Calibri,sans-serif;font-size:13pt;line-height:115%;"><strong>&nbsp;</strong></span></p><img src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-30%20at%201.11.23%20PM_0.jpeg" data-align="center" data-entity-uuid="0364e2e1-25b4-4838-a9ae-a37add7beee5" data-entity-type="file" alt="ERASMUS" width="642" height="281"><p style="margin-bottom:13px;">&nbsp;</p><p class="text-align-justify" style="margin-bottom:11px;margin-top:32px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Proyecto Erasmus+ KA171 (2024–2027)</strong></span></p><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Este proyecto se enmarca en la acción clave KA171 del Programa Erasmus+, orientada a promover la movilidad internacional entre universidades de la Unión Europea y países no asociados al programa. En este contexto, la UNL y la Universidad de Córdoba consolidan su cooperación institucional a través de un proyecto que fortalece la internacionalización de la educación superior, permitiendo intercambios académicos de alto impacto y fomentando la movilidad del personal docente y administrativo en el periodo 2024-2027.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e07aab9153ebbc07155a4ef0459a08ea2"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Tipo de Proyecto: Erasmus+ KA171 – Movilidad con terceros países no asociados al Programa (región América Latina).</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e4eea7f6f5b59d773cc8aaaa35da66943"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Coordinador: Universidad de Córdoba – ECORDOBA01</span></p></li><li style="margin-bottom:13px;" data-list-item-id="ee2be7477effebe6409d5902b6173ff9c"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">País socio: Ecuador – UNL (Universidad Nacional de Loja)</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e5a96480a6279769c03884d0a7b61b1a4"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Duración: Desde 2024 hasta el 31 de julio de 2027</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e10430b45e3bf828e4106b74cb5a276fc"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Código del proyecto: 2024-1-ES01-KA171-HED-000220737</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Tipología y número de movilidades concedidas</strong></span></p><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Las movilidades se circunscriben a los campos de Ciencias de la Educación y de Ciencias Naturales, Matemáticas y Estadística, de acuerdo con el acuerdo interinstitucional suscrito. Esto asegura que las actividades propuestas por los beneficiarios se alineen con las fortalezas académicas compartidas entre ambas universidades y potencien la cooperación interdisciplinaria en dichas áreas.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e9911a4a183fc18c42968eda3e34e5c6a"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Tipo de movilidad: Personal de la UNL hacia la UCO</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e53c7a50011bd9b5952b18fb04c78d6da"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Duración: 5 días de actividad + 2 días de viaje (formato 5+2d)</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Áreas temáticas habilitadas para movilidad</strong></span></p><ul><li style="margin-bottom:13px;" data-list-item-id="ecd7c660ab84566bf5cffe8899bd4c74e"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">0111 – Ciencias de la Educación</span></p></li></ul><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">El personal postulante debe contar con vínculo contractual con la UNL y demostrar competencias alineadas con las actividades académicas o formativas que llevará a cabo en la UCO. Además de los documentos requeridos, se valora positivamente la experiencia previa en cooperación internacional, el manejo de lenguas extranjeras y la motivación institucional por fortalecer los lazos con universidades europeas.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e533b1e9da824d4504a6bed57ccb0f244"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">0588 – Ciencias Naturales, Matemáticas y Estadística</span></p></li><li style="margin-bottom:13px;" data-list-item-id="ea15a8b724d75f958b186f1fde77d24f5"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Programas interdisciplinarios vinculados a estas áreas</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Requisitos del participante</strong></span></p><ul><li style="margin-bottom:13px;" data-list-item-id="ebac01bd2cd6cd2235e7d44cfc300429d"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Tener relación contractual vigente con la UNL.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">La UNL deberá implementar una convocatoria &nbsp;y coordinar con la UCO la nominación del personal seleccionado. El proceso incluye la elaboración y firma de acuerdos de movilidad, la planificación logística del viaje y la preparación documental y académica para garantizar el cumplimiento del programa de movilidad.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e775f30bc896b5f17e14bc3b364e60fb6"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Presentar: carta de motivación, CV actualizado, plan de movilidad preliminar, copia de pasaporte.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e3af6576b1c1692daabf8ee1d853cef33"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Nivel de idioma recomendado: B2 en español o inglés.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="eb3e5a369c8472e67efc482be742e9bc2"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Área de movilidad alineada con el IIA.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Procedimiento y documentos clave</strong></span></p><ul><li style="margin-bottom:13px;" data-list-item-id="ebec26da88f1e32efa908f99b89bc1bcf"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Convocatoria interna.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="ec801290bf4feb33d8945eab3ddd39012"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Evaluación y selección por comisión designada.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Ambas universidades tienen un rol complementario en la implementación del proyecto. La UNL debe garantizar la preparación, acompañamiento y reconocimiento de la movilidad, mientras que la UCO facilita la acogida, entrega del apoyo económico y emisión del certificado de participación. La cooperación fluida entre ambas instituciones es clave para el éxito del proceso.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e980f460f012be0bc177b2a4aeb4b2b10"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Nominación formal a UCO.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e4382670959f461d828ece1a238107828"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Coordinación con departamento anfitrión en UCO.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:13px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Para resolver dudas o facilitar el proceso logístico y académico, los participantes deben comunicarse con la Oficina de Relaciones Internacionales de la UCO. Este contacto proporciona apoyo directo en temas relacionados con visados, alojamiento, seguros, actividades académicas y trámites administrativos, asegurando una experiencia de movilidad exitosa.</span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e6da97bfca5314f73371ae3162bce6042"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Firma de Mobility Agreement y Grant Agreement.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="eecdd51dc25a6e5eea7a6349f087d5d9c"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Gestión de visa, seguro, viaje y alojamiento.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Responsabilidades institucionales</strong></span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e878344930069f54eb209fd9a67cbd202"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">UNL: convocatoria, selección, preparación y reconocimiento institucional.</span></p></li><li style="margin-bottom:13px;" data-list-item-id="e0d920a1986c0a955360bca5fb3599735"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">UCO: carta de invitación, gestión logística, pago del apoyo y emisión del certificado de estancia.</span></p></li></ul><p class="text-align-justify" style="margin-bottom:11px;margin-top:13px;"><span style="color:#4f81bd;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>Contacto clave en UCO</strong></span></p><ul><li style="margin-bottom:13px;" data-list-item-id="e5136bbc1b8d5f355f9216701e7084b96"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Oficina de Relaciones Internacionales – Erasmus+ KA171</span></p></li><li style="margin-bottom:13px;" data-list-item-id="ed4d75ac7b6fb2bd7b13bb68d40b58208"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Correo: erasmus.icm@uco.es</span></p></li><li style="margin-bottom:13px;" data-list-item-id="ec4c776822c2fbd84734102b087359fa8"><p class="text-align-justify"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">Web: </span><a href="https://www.uco.es/internacional"><span style="color:blue;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;tab-stops:list 36.0pt;" lang="EN-US">https://www.uco.es/internacional</span></a></p></li></ul><p class="text-align-center" style="margin-bottom:13px;"><span style="color:#2e75b6;font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;" lang="EN-US"><strong>CONVOCATORIA</strong></span></p><p style="margin-bottom:11px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">La convocatoria está dirigida a los docentes de las siguientes áreas:</span><br><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">•&nbsp;&nbsp; &nbsp;Ciencias de la Educación</span><br><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">•&nbsp;&nbsp; &nbsp;Ciencias Naturales</span><br><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">•&nbsp;&nbsp; &nbsp;Matemáticas y estadística</span></p><p class="text-align-justify" style="margin-bottom:11px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Fecha máxima de postulación: 31 marzo de 2026</span></p><p style="margin-bottom:11px;"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">La visita podrá efectuarse dentro del primer trimestre del año 2027.</span><br><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">Los docentes interesados deberán completar el formulario de postulación dentro del siguiente enlace:</span><br><a href="https://docs.google.com/forms/d/e/1FAIpQLScDiayxf-o9mPpXHbCGiEOKWgPR52uZVlBwVRXn2xvDWWls-w/viewform?usp=send_form" title="Convocatoria"><span style="font-family:&quot;Arial&quot;,sans-serif;font-size:12.0pt;line-height:normal;">https://docs.google.com/forms/d/e/1FAIpQLScDiayxf-o9mPpXHbCGiEOKWgPR52uZVlBwVRXn2xvDWWls-w/viewform?usp=send_form</span></a></p><p style="margin-bottom:13px;">&nbsp;</p>	full_html
texto_libre	0	101	1816	es	0	<p>.unl-content { font-family: inherit; } .unl-content p { line-height: 1.7; margin-bottom: 1.25rem; } .unl-content hr { border: none; border-top: 1px solid #ddd; margin: 2rem 0; } .unl-content .unl-block { background: #f4f4f4; border-left: 4px solid #c0392b; padding: 1.5rem 2rem; margin: 1.5rem 0; border-radius: 4px; } .unl-content .unl-block h4 { color: #c0392b; text-transform: uppercase; letter-spacing: 1px; font-size: 1.1rem; margin-top: 0; margin-bottom: 0.75rem; } .unl-content .unl-block p { margin-bottom: 0; color: #333; } .unl-valores h4 { color: #c0392b; text-transform: uppercase; letter-spacing: 1px; font-size: 1.1rem; margin: 2rem 0 1rem; } .unl-valores p { margin-bottom: 1rem; } .unl-himno-titulo { color: #c0392b; text-transform: uppercase; letter-spacing: 1px; font-size: 1.1rem; text-align: center; margin: 2.5rem 0 1.5rem; } .unl-himno-creditos { text-align: center; color: #666; font-size: 0.9rem; margin-bottom: 0.25rem; } .unl-himno-letra { max-width: 600px; margin: 2rem auto 0; text-align: center; } .unl-himno-letra .coro { font-weight: bold; color: #c0392b; text-transform: uppercase; margin-bottom: 0.5rem; } .unl-himno-letra .estrofa-num { font-weight: bold; color: #c0392b; margin: 1.5rem 0 0.5rem; } .unl-himno-letra p { margin: 0; line-height: 1.8; } .unl-audio-player { display: flex; align-items: center; gap: 1rem; padding: 0.75rem 1.5rem; background: #f4f4f4; border-radius: 50px; max-width: 480px; margin: 1.5rem auto; } .unl-audio-player__play { flex-shrink: 0; width: 48px; height: 48px; border-radius: 50%; background: #c0392b; border: none; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: background 0.2s ease; } .unl-audio-player__play:hover { background: #a93226; } .unl-audio-player__play svg { width: 18px; height: 18px; fill: #fff; } .unl-audio-player__waveform { flex: 1; display: flex; align-items: center; gap: 2px; height: 32px; } .unl-audio-player__bar { flex: 1; min-width: 2px; max-width: 3px; background: #cfcfcf; border-radius: 2px; transition: background 0.2s ease; } .unl-audio-player.is-playing .unl-audio-player__bar { animation: unl-wave 0.9s ease-in-out infinite; animation-delay: calc(var(--i) * 0.03s); } @keyframes unl-wave { 0%, 100% { transform: scaleY(0.4); } 50% { transform: scaleY(1); } } .unl-audio-player__time { flex-shrink: 0; font-size: 0.85rem; color: #666; min-width: 40px; text-align: right; }&nbsp;</p><p class="text-align-justify">Somos una institución de educación superior laica, autónoma, de derecho público, con personería jurídica y sin fines de lucro;&nbsp;de alta calidad académica y humanística.&nbsp;Ofrecemos&nbsp;formación en la modalidad presencial y a distancia, promoviendo a&nbsp;través de&nbsp;la investigación científico-técnica,&nbsp;los problemas del entorno&nbsp;con calidad, pertinencia y equidad.&nbsp;</p><p class="text-align-justify">Coadyuvamos&nbsp;al desarrollo sustentable de la región y del país, interactuando con la comunidad&nbsp;por medio de propuestas alternativas a los problemas nacionales y&nbsp;con responsabilidad social; reconociendo y promoviendo la diversidad cultural y étnica y la sabiduría popular. Nos&nbsp;apoyamos en los&nbsp;avances científicos y tecnológicos&nbsp;en procura de mejorar la calidad de vida del pueblo ecuatoriano.</p><hr><p><img src="/sites/default/files/inline-images/UNL%20pano%203.jpg" data-entity-uuid="26a590b4-adff-42b7-9a96-321fee8bde39" data-entity-type="file" alt="unl pano">&nbsp;</p><hr><h4>Misión</h4><p class="text-align-justify">Somos la primera universidad pública de la Región Sur del Ecuador que forma integralmente profesionales e investigadores; genera, innova y divulga conocimiento científico, tecnológico, artístico y literario; desarrolla pensamiento crítico; respeta y valora la diversidad, las culturas y saberes, integrando en la sociedad el avance científico para contribuir al desarrollo sostenible del país y del mundo con calidad, pertinencia y gestión inteligente.</p><h4>Visión</h4><p class="text-align-justify">La UNL es la universidad pública sostenible del Ecuador que lidera y transforma la academia contribuyendo al desarrollo humano.</p><h4>Valores Institucionales</h4><p><strong>El accionar</strong> de la gestión institucional se sustenta en la internalización y puesta en práctica de los siguientes valores:</p><p><strong>Responsabilidad</strong> de toda la comunidad universitaria para actuar con respeto y tomar decisiones en pro de nuestra alma mater.</p><p><strong>Solidaridad</strong> entre todos los integrantes de la UNL para buscar el bien común, la igualdad y la fraternidad.</p><p><strong>Pluralismo</strong> para ejercer con autonomía responsable la libertad de pensamiento, opinión, cátedra y asociación.</p><p><strong>Pertenencia</strong> de la comunidad universitaria hacia la trayectoria e incidencia histórica de la Universidad Nacional de Loja, su posicionamiento, prestigio y trascendencia, lo que se refleja en la satisfacción y valoración social del Alma Máter.</p><p><strong>Honestidad</strong> en el actuar conforme a nuestros pensamientos y sentimientos, siendo consecuentes con nuestras acciones.</p><h4>Himno Universidad Nacional de Loja</h4><p>0:00&nbsp;</p><p><strong>Letra</strong>: Dr. Benjamín Ruiz y Gómez</p><p><strong>Música</strong>: Maestro Segundo Puertas Moreno</p><p><strong>Fecha de creación</strong>: 8 de diciembre de 1945</p><p>Coro</p><p>Gloria Loja, por siempre cantemos</p><p>Con acento de voz inmortal</p><p>Fuimos grandes y hoy más lo seremos</p><p>Con el triunfo de nuestro ideal.</p><p>I</p><p>Al calor de un brillante pasado</p><p>Que dio a Loja, blasón de talento,</p><p>De hidalguía, de fe y sentimiento,</p><p>Nueva vida queremos vivir.</p><p>II</p><p>La inquietud cultural vigoriza</p><p>La conciencia de un pueblo escogido</p><p>Que si acaso parece dormido</p><p>Hoy despierta a un glorioso existir.</p><p>(function () { const wrapper = document.getElementById('unl-himno-player'); const audio = document.getElementById('unl-himno-audio'); const playBtn = wrapper.querySelector('.unl-audio-player__play'); const waveform = document.getElementById('unl-himno-waveform'); const timeEl = document.getElementById('unl-himno-time'); const playIcon = '&lt;svg viewBox="0 0 24 24"&gt;&lt;path d="M8 5v14l11-7z"/&gt;&lt;/svg&gt;'; const pauseIcon = '&lt;svg viewBox="0 0 24 24"&gt;&lt;path d="M6 5h4v14H6zm8 0h4v14h-4z"/&gt;&lt;/svg&gt;'; const barCount = 40; for (let i = 0; i &lt; barCount; i++) { const bar = document.createElement('span'); bar.className = 'unl-audio-player__bar'; bar.style.height = (30 + Math.random() * 70) + '%'; bar.style.setProperty('--i', i); waveform.appendChild(bar); } function formatTime(s) { const m = Math.floor(s / 60); const sec = Math.floor(s % 60).toString().padStart(2, '0'); return m + ':' + sec; } playBtn.addEventListener('click', function () { if (audio.paused) { audio.play(); } else { audio.pause(); } }); audio.addEventListener('play', function () { wrapper.classList.add('is-playing'); playBtn.innerHTML = pauseIcon; }); audio.addEventListener('pause', function () { wrapper.classList.remove('is-playing'); playBtn.innerHTML = playIcon; }); audio.addEventListener('timeupdate', function () { timeEl.textContent = formatTime(audio.currentTime); }); })();</p>	full_html
texto_libre	0	135	1737	es	0	<div style="background-color:#f9f9f9;border-radius:8px;box-shadow:0 4px 8px rgba(0, 0, 0, 0.1);margin:20px 0;padding:20px;"><h3 class="text-align-justify"><strong>Primer encuentro regional de caficultura sostenible</strong></h3><p class="text-align-justify">Del 23 al 25 de julio de 2025, la Universidad Nacional de Loja fue sede del Primer Encuentro Regional de Caficultura Sostenible, un espacio que reunió a caficultores, academia, empresas y entidades públicas para fortalecer la cadena del café en el sur del Ecuador. El encuentro promovió la recuperación de semillas de alta calidad, la articulación de la investigación con las necesidades del territorio y el impulso de políticas que prioricen al sector cafetalero. Se desarrolló en el Aula Magna de la Facultad Agropecuaria y contempló conferencias y mesas de diálogo orientadas a soluciones concretas.</p><img src="/sites/default/files/inline-images/Primer%20encuentro%20regional%20de%20caficultura%20sostenible.jpg" data-align="center" data-entity-uuid="5c7a47f1-29c2-4cb7-801c-2dd14871dcd3" data-entity-type="file" alt="Primer encuentro regional de caficultura sostenible"><p>&nbsp;</p><div style="background-color:#000;height:0;max-width:100%;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="border-radius:8px;height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen="" frameborder="0" src="https://www.youtube.com/embed/CXgra95ryco?si=AUV7qPCT-sAy3HyI"></iframe></div><div class="text-align-justify" style="color:#333;font-family:Arial, sans-serif;margin-top:20px;"><a href="https://www.unl.edu.ec/sites/default/files/archivo/2025-07/Primer%20encuentro%20Regional%20de%20caficultura%20Sostenible%2007%20JULIO%20FINAL-signed.pdf" title="Agenda del primer encuentro regional de caficultura sostenible">Agenda del Primer encuentro regional de caficultura sostenible</a></div></div>	full_html
