texto_libre	0	160	2111	es	0	<style type="text/css">/* =====================================================\r\nRESET\r\n===================================================== */\r\n*{\r\n  margin:0;\r\n  padding:0;\r\n  box-sizing:border-box;\r\n}\r\nhtml{\r\n  scroll-behavior:smooth;\r\n}\r\nbody{\r\n  font-family:\r\n    "Montserrat",\r\n    -apple-system,\r\n    BlinkMacSystemFont,\r\n    "Segoe UI",\r\n    sans-serif;\r\n  background:#ffffff;\r\n  color:#3a3a3a;\r\n  overflow-x:hidden;\r\n}\r\n/* =====================================================\r\nVARIABLES\r\n===================================================== */\r\n:root{\r\n  --primary:#93000b;\r\n  --secondary:#6e0008;\r\n  --text:#3a3a3a;\r\n  --text-soft:#6b6b6b;\r\n  --white:#ffffff;\r\n  --light-hover:#fbecec;\r\n  --border:rgba(147,0,11,.12);\r\n  --shadow:\r\n    0 10px 40px rgba(147,0,11,.08);\r\n  --radius:30px;\r\n}\r\n/* =====================================================\r\nGLOBAL\r\n===================================================== */\r\na{\r\n  text-decoration:none;\r\n  color:inherit;\r\n}\r\n.container{\r\n  width:min(1400px,92%);\r\n  margin:auto;\r\n}\r\n/* =====================================================\r\nHERO\r\n===================================================== */\r\n.hero{\r\n  position:relative;\r\n  min-height:100vh;\r\n  display:flex;\r\n  align-items:center;\r\n  overflow:hidden;\r\n  padding:120px 0 80px;\r\n}\r\n/* =====================================================\r\nIMAGE BACKGROUND\r\n===================================================== */\r\n.hero-bg{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:1;\r\n}\r\n.hero-bg img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:cover;\r\n}\r\n/* =====================================================\r\nWHITE OVERLAY\r\n===================================================== */\r\n.hero-overlay{\r\n  position:absolute;\r\n  inset:0;\r\n  z-index:2;\r\n  background:\r\n    linear-gradient(\r\n      90deg,\r\n      rgba(255,255,255,.96) 0%,\r\n      rgba(255,255,255,.92) 28%,\r\n      rgba(255,255,255,.70) 48%,\r\n      rgba(255,255,255,.20) 70%,\r\n      rgba(255,255,255,.05) 100%\r\n    );\r\n}\r\n/* =====================================================\r\nDECORATION\r\n===================================================== */\r\n.hero-decoration{\r\n  position:absolute;\r\n  left:-200px;\r\n  bottom:-220px;\r\n  width:600px;\r\n  height:600px;\r\n  border-radius:50%;\r\n  background:\r\n    radial-gradient(\r\n      circle,\r\n      rgba(147,0,11,.06),\r\n      transparent 70%\r\n    );\r\n  z-index:2;\r\n}\r\n/* =====================================================\r\nCONTENT\r\n===================================================== */\r\n.hero-content{\r\n  position:relative;\r\n  z-index:5;\r\n  max-width:700px;\r\n  animation:fadeUp 1s ease;\r\n}\r\n.hero-content h1{\r\n  font-size:clamp(4rem,7vw,7rem);\r\n  line-height:.95;\r\n  font-weight:900;\r\n  letter-spacing:-1px;\r\n  margin-bottom:35px;\r\n  color:#93000b;\r\n  text-shadow:\r\n    0 10px 40px rgba(255,255,255,.95);\r\n}\r\n.hero-content p{\r\n  max-width:620px;\r\n  font-size:1.7rem;\r\n  line-height:2;\r\n  color:#3a3a3a;\r\n  margin-bottom:45px;\r\n  font-weight:450;\r\n  text-shadow:\r\n    0 5px 30px rgba(255,255,255,.95);\r\n}\r\n/* =====================================================\r\nBUTTONS\r\n===================================================== */\r\n.hero-buttons{\r\n  display:flex;\r\n  gap:20px;\r\n  flex-wrap:wrap;\r\n}\r\n.btn{\r\n  padding:18px 34px;\r\n  border-radius:18px;\r\n  font-weight:700;\r\n  transition:.4s ease;\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:12px;\r\n  font-size:1rem;\r\n}\r\n.btn-primary{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n  box-shadow:\r\n    0 15px 35px rgba(147,0,11,.25);\r\n}\r\n.btn-primary:hover{\r\n  transform:translateY(-4px);\r\n}\r\n.btn-secondary{\r\n  background:\r\n    #fbecec;\r\n  border:\r\n    1px solid rgba(147,0,11,.15);\r\n  color:#93000b;\r\n  backdrop-filter:blur(10px);\r\n  box-shadow:\r\n    0 10px 25px rgba(0,0,0,.05);\r\n}\r\n.btn-secondary:hover{\r\n  background:white;\r\n}\r\n/* =====================================================\r\nSECTION\r\n===================================================== */\r\n.section{\r\n  padding:120px 0;\r\n}\r\n.section-title{\r\n  text-align:center;\r\n  margin-bottom:70px;\r\n}\r\n.section-title span{\r\n  color:#93000b;\r\n  font-weight:800;\r\n  letter-spacing:1px;\r\n  text-transform:uppercase;\r\n  font-size:.82rem;\r\n}\r\n.section-title h2{\r\n  font-size:clamp(2.8rem,5vw,4rem);\r\n  margin-top:16px;\r\n  color:#3a3a3a;\r\n  font-weight:900;\r\n}\r\n.section-title p{\r\n  max-width:760px;\r\n  margin:auto;\r\n  margin-top:24px;\r\n  line-height:1.9;\r\n  color:#6b6b6b;\r\n  font-size:1.5rem;\r\n}\r\n/* =====================================================\r\nTIMELINE\r\n===================================================== */\r\n.timeline-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(280px,1fr));\r\n  gap:28px;\r\n}\r\n.timeline-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:30px;\r\n  padding:35px;\r\n  transition:.4s ease;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n}\r\n.timeline-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n  box-shadow:\r\n    0 20px 40px rgba(147,0,11,.12);\r\n}\r\n.timeline-card h3{\r\n  font-size:2rem;\r\n  color:#93000b;\r\n  margin-bottom:18px;\r\n  font-weight:900;\r\n}\r\n.timeline-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.card-btn{\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:10px;\r\n  color:#93000b;\r\n  font-weight:700;\r\n}\r\n/* =====================================================\r\nDOCUMENTS\r\n===================================================== */\r\n.docs-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(320px,1fr));\r\n  gap:28px;\r\n}\r\n.doc-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(147,0,11,.12);\r\n  border-radius:28px;\r\n  padding:35px;\r\n  box-shadow:\r\n    0 10px 30px rgba(147,0,11,.05);\r\n  transition:.4s ease;\r\n}\r\n.doc-card:hover{\r\n  transform:translateY(-8px);\r\n  border-color:#93000b;\r\n}\r\n.doc-icon{\r\n  width:85px;\r\n  height:85px;\r\n  border-radius:24px;\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      rgba(147,0,11,.10),\r\n      rgba(147,0,11,.18)\r\n    );\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  margin-bottom:24px;\r\n  font-size:1.2rem;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.doc-card h4{\r\n  font-size:1.4rem;\r\n  margin-bottom:14px;\r\n  color:#3a3a3a;\r\n}\r\n.doc-card p{\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.doc-actions{\r\n  display:flex;\r\n  gap:14px;\r\n}\r\n.doc-btn{\r\n  flex:1;\r\n  text-align:center;\r\n  padding:14px;\r\n  border-radius:14px;\r\n  font-weight:700;\r\n  transition:.3s ease;\r\n}\r\n.view-btn{\r\n  background:#fbecec;\r\n  color:#93000b;\r\n}\r\n.download-btn{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #93000b,\r\n      #6e0008\r\n    );\r\n  color:white;\r\n}\r\n.doc-btn:hover{\r\n  transform:translateY(-2px);\r\n}\r\n/* =====================================================\r\nFOOTER\r\n===================================================== */\r\nfooter{\r\n  padding:80px 0;\r\n  border-top:\r\n    1px solid rgba(147,0,11,.12);\r\n  margin-top:100px;\r\n}\r\n.footer-content{\r\n  display:flex;\r\n  justify-content:space-between;\r\n  gap:60px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-brand h3{\r\n  font-size:2rem;\r\n  margin-bottom:20px;\r\n  font-weight:900;\r\n  color:#93000b;\r\n}\r\n.footer-brand p{\r\n  max-width:500px;\r\n  color:#6b6b6b;\r\n  line-height:1.9;\r\n}\r\n.footer-links{\r\n  display:flex;\r\n  gap:80px;\r\n  flex-wrap:wrap;\r\n}\r\n.footer-links h4{\r\n  margin-bottom:18px;\r\n  color:#3a3a3a;\r\n}\r\n.footer-links a{\r\n  display:block;\r\n  margin-bottom:14px;\r\n  color:#6b6b6b;\r\n  transition:.3s ease;\r\n}\r\n.footer-links a:hover{\r\n  color:#93000b;\r\n}\r\n/* =====================================================\r\nANIMATIONS\r\n===================================================== */\r\n@keyframes fadeUp{\r\n  from{\r\n    opacity:0;\r\n    transform:translateY(50px);\r\n  }\r\n  to{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n}\r\n/* =====================================================\r\nRESPONSIVE\r\n===================================================== */\r\n@media(max-width:980px){\r\n  .hero{\r\n    min-height:auto;\r\n    padding:120px 0 100px;\r\n  }\r\n  .hero-content h1{\r\n    font-size:4rem;\r\n  }\r\n  .hero-overlay{\r\n    background:\r\n      linear-gradient(\r\n        180deg,\r\n        rgba(255,255,255,.95),\r\n        rgba(255,255,255,.80)\r\n      );\r\n  }\r\n}\r\n@media(max-width:680px){\r\n  .hero-content h1{\r\n    font-size:3rem;\r\n    letter-spacing:-2px;\r\n  }\r\n  .hero-content p{\r\n    font-size:1rem;\r\n  }\r\n  .hero-buttons{\r\n    flex-direction:column;\r\n  }\r\n  .btn{\r\n    width:100%;\r\n    justify-content:center;\r\n  }\r\n}\r\n</style><!-- =====================================================\r\nHERO\r\n===================================================== --><section class="hero"><!-- IMAGE --><div class="hero-bg"><!-- CAMBIA ESTA IMAGEN --><img src="/sites/default/files/2026-05/RENDICION7%20-%20MESAS%20DE%20TRABAJO.jpg" alt="" width="3196" height="1788"></div><!-- OVERLAY --><div class="hero-overlay">&nbsp;</div><!-- DECORATION --><div class="hero-decoration">&nbsp;</div><!-- CONTENT --><div class="container"><div class="hero-content"><h1>Transparencia y Rendición de Cuentas</h1><p>Acceda de forma clara, organizada y pública a los procesos de rendición de cuentas de la Universidad Nacional de Loja.</p><div class="hero-buttons"><a class="btn btn-primary" href="#procesos">Explorar procesos → </a><a class="btn btn-secondary" href="/sites/default/files/2026-03/INFORME%20RENDICION%20CUENTAS%20UNL%202025_VP.pdf" title="Rendición de cuentas 2025">Informe 2025&nbsp;</a></div></div></div></section><!-- =====================================================\r\nTIMELINE\r\n===================================================== --><section class="section" id="procesos"><div class="container"><div class="section-title"><p><span>Histórico institucional&nbsp;</span></p><h2>Procesos de Rendición</h2><p>Consulte los procesos institucionales organizados por año y acceda rápidamente a la documentación pública.<br>&nbsp;</p></div><div class="timeline-grid"><div class="timeline-card"><h3>2025</h3><p>Rendición de cuentas 2025</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2025" title="Rendición de cuentas 2025">Ver más →</a></p></div><div class="timeline-card"><h3>2024</h3><p>Rendición de cuentas 2024</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2024" title="Rendición de cuentas 2024">Ver más →</a></p></div><div class="timeline-card"><h3>2023</h3><p>Rendición de cuentas 2023</p><p><a class="card-btn" href="http://172.190.19.169/rendicion_cuentas/2023" title="Rendición de cuentas 2023">Ver más →</a></p></div><div class="timeline-card"><h3>2022</h3><p>Rendición de cuentas 2022</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2022" title="Rendición de cuentas 202 ">Ver más →</a></p></div><div class="timeline-card"><h3>2021</h3><p>Rendición de cuentas 2021</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2021" title="Rendición de cuentas 2021">Ver más →</a></p></div><div class="timeline-card"><h3>2020</h3><p>Rendición de cuentas 2020</p><p><a class="card-btn" href="https://unl.edu.ec/rendicion_cuentas/2020" title="Ren