0%,\r\n      rgba(255,255,255,.92) 28%,\r\n      rgba(255,255,255,.70) 48%,\r\n      rgba(255,255,255,.20) 70%,\r\n      rgba(255,255,255,.05) 100%\r\n    );\r\n}\r\n/* =====================================================\r\nDECORATION\r\n===================================================== */\r\n.hero-decoration{\r\n  position:absolute;\r\n  left:-200px;\r\n  bottom:-220px;\r\n  width:600px;\r\n  height:600px;\r\n  border-radius:50%;\r\n  background:\r\n    radial-gradient(\r\n      circle,\r\n      rgba(11,35,65,.06),\r\n      transparent 70%\r\n    );\r\n  z-index:2;\r\n}\r\n/* =====================================================\r\nCONTENT\r\n===================================================== */\r\n.hero-content{\r\n  position:relative;\r\n  z-index:5;\r\n  max-width:700px;\r\n  animation:fadeUp 1s ease;\r\n}\r\n.hero-content h1{\r\n  font-size:clamp(4rem,7vw,7rem);\r\n  line-height:.95;\r\n  font-weight:900;\r\n  letter-spacing:-1px;\r\n  margin-bottom:35px;\r\n  color:#0b2341;\r\n  text-shadow:\r\n    0 10px 40px rgba(255,255,255,.95);\r\n}\r\n.hero-content p{\r\n  max-width:620px;\r\n  font-size:1.7rem;\r\n  line-height:2;\r\n  color:#44536d;\r\n  margin-bottom:45px;\r\n  font-weight:450;\r\n  text-shadow:\r\n    0 5px 30px rgba(255,255,255,.95);\r\n}\r\n/* =====================================================\r\nBUTTONS\r\n===================================================== */\r\n.hero-buttons{\r\n  display:flex;\r\n  gap:20px;\r\n  flex-wrap:wrap;\r\n}\r\n.btn{\r\n  padding:18px 34px;\r\n  border-radius:18px;\r\n  font-weight:700;\r\n  transition:.4s ease;\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:12px;\r\n  font-size:1rem;\r\n}\r\n.btn-primary{\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      #0b2341,\r\n      #17365d\r\n    );\r\n  color:white;\r\n  box-shadow:\r\n    0 15px 35px rgba(11,35,65,.25);\r\n}\r\n.btn-primary:hover{\r\n  transform:translateY(-4px);\r\n}\r\n.btn-secondary{\r\n  background:\r\n    rgba(255,255,255,.92);\r\n  border:\r\n    1px solid rgba(11,35,65,.08);\r\n  color:#0b2341;\r\n  backdrop-filter:blur(10px);\r\n  box-shadow:\r\n    0 10px 25px rgba(0,0,0,.05);\r\n}\r\n.btn-secondary:hover{\r\n  background:white;\r\n}\r\n/* =====================================================\r\nFLOATING STATS\r\n===================================================== */\r\n.hero-stats{\r\n  position:absolute;\r\n  right:70px;\r\n  bottom:70px;\r\n  z-index:6;\r\n  display:flex;\r\n  gap:20px;\r\n  flex-wrap:wrap;\r\n}\r\n.stat-box{\r\n  min-width:220px;\r\n  background:\r\n    rgba(255,255,255,.92);\r\n  border:\r\n    1px solid rgba(11,35,65,.06);\r\n  backdrop-filter:blur(14px);\r\n  border-radius:26px;\r\n  padding:24px 28px;\r\n  box-shadow:\r\n    0 20px 40px rgba(11,35,65,.10);\r\n  animation:fadeUp 1.2s ease;\r\n}\r\n.stat-box h3{\r\n  font-size:3rem;\r\n  color:#0b2341;\r\n  margin-bottom:8px;\r\n  font-weight:900;\r\n}\r\n.stat-box p{\r\n  color:#5d6b84;\r\n  font-size:1rem;\r\n  line-height:1.5;\r\n}\r\n/* =====================================================\r\nSECTION\r\n===================================================== */\r\n.section{\r\n  padding:120px 0;\r\n}\r\n.section-title{\r\n  text-align:center;\r\n  margin-bottom:70px;\r\n}\r\n.section-title span{\r\n  color:#17365d;\r\n  font-weight:800;\r\n  letter-spacing:1px;\r\n  text-transform:uppercase;\r\n  font-size:.82rem;\r\n}\r\n.section-title h2{\r\n  font-size:clamp(2.8rem,5vw,4rem);\r\n  margin-top:16px;\r\n  color:#0b2341;\r\n  font-weight:900;\r\n}\r\n.section-title p{\r\n  max-width:760px;\r\n  margin:auto;\r\n  margin-top:24px;\r\n  line-height:1.9;\r\n  color:#5d6b84;\r\n  font-size:1.5rem;\r\n}\r\n/* =====================================================\r\nTIMELINE\r\n===================================================== */\r\n.timeline-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(280px,1fr));\r\n  gap:28px;\r\n}\r\n.timeline-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(11,35,65,.08);\r\n  border-radius:30px;\r\n  padding:35px;\r\n  transition:.4s ease;\r\n  box-shadow:\r\n    0 10px 30px rgba(11,35,65,.05);\r\n}\r\n.timeline-card:hover{\r\n  transform:translateY(-8px);\r\n  box-shadow:\r\n    0 20px 40px rgba(11,35,65,.08);\r\n}\r\n.timeline-card h3{\r\n  font-size:2rem;\r\n  color:#0b2341;\r\n  margin-bottom:18px;\r\n  font-weight:900;\r\n}\r\n.timeline-card p{\r\n  color:#5d6b84;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.card-btn{\r\n  display:inline-flex;\r\n  align-items:center;\r\n  gap:10px;\r\n  color:#0b2341;\r\n  font-weight:700;\r\n}\r\n/* =====================================================\r\nDOCUMENTS\r\n===================================================== */\r\n.docs-grid{\r\n  display:grid;\r\n  grid-template-columns:\r\n    repeat(auto-fit,minmax(320px,1fr));\r\n  gap:28px;\r\n}\r\n.doc-card{\r\n  background:#ffffff;\r\n  border:\r\n    1px solid rgba(11,35,65,.08);\r\n  border-radius:28px;\r\n  padding:35px;\r\n  box-shadow:\r\n    0 10px 30px rgba(11,35,65,.05);\r\n  transition:.4s ease;\r\n}\r\n.doc-card:hover{\r\n  transform:translateY(-8px);\r\n}\r\n.doc-icon{\r\n  width:85px;\r\n  height:85px;\r\n  border-radius:24px;\r\n  background:\r\n    linear-gradient(\r\n      135deg,\r\n      rgba(11,35,65,.08),\r\n      rgba(23,54,93,.12)\r\n    );\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  margin-bottom:24px;\r\n  font-size:1.2rem;\r\n  font-weight:900;\r\n  color:#0b2341;\r\n}\r\n.doc-card h4{\r\n  font-size:1.4rem;\r\n  margin-bottom:14px;\r\n  color:#0b2341;\r\n}\r\n.doc-card p{\r\n  color:#5d6b84;\r\n  line-height:1.9;\r\n  margin-bottom:28px;\r\n}\r\n.doc-actions{\r\n  display:flex;\r\n  gap:14px;\r\n}\r\n.doc-btn{\r\n  flex:1;\r\n  text-align:center;\r\n  padding:14px;\r\n  border-radius:14px;\r\n  font-weight:700;\r\n  transition:.3s ease;\r\n}\r\n.view-btn{\r\n  background:#f5f7fb;\r\n  color:#0b2341;\r\n}\r\n.download