t/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf">Junta&nbsp;10</a></td></tr><tr><td colspan="1" rowspan="2"><h4>&nbsp;</h4><h4><strong>Masculino</strong></h4></td><td><p>&nbsp;</p><p>&nbsp;</p><p><span>&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf">Junta 1</a></p></td><td><p>&nbsp;</p><p>&nbsp;</p><p><span>&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf">Junta 2</a></p></td><td><p>&nbsp;</p><p>&nbsp;</p><p><span>&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf">Junta&nbsp;3</a></p></td><td><p>&nbsp;</p><p>&nbsp;</p><p><span>&nbsp;&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf">Junta&nbsp;4</a></p></td><td><p>&nbsp;</p><p>&nbsp;</p><p><span>&nbsp;&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf">Junta&nbsp;5</a></p></td></tr><tr><td><span>&nbsp;&nbsp;&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf">Junta&nbsp;6</a></td><td><span>&nbsp;&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf">Junta&nbsp;7</a></td><td><span>&nbsp;&nbsp;&nbsp; </span><img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf">Junta&nbsp;8</a></td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td colspan="5" rowspan="1"><h5 class="text-align-center">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<img src="/sites/default/files/inline-images/referendum_17785896.png" data-entity-uuid="123c0ae9-c259-45d8-9f33-5e356199a020" data-entity-type="file" alt="imagen 1" width="28" height="28"> <a href="https://unl.edu.ec/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf">Unidad de Educación a Distancia y en Línea</a>&nbsp;</h5></td><td>&nbsp;</td></tr></tbody></table><p>&nbsp;</p><p class="text-align-justify">&nbsp;</p><p>Según el art. 39 de&nbsp;<a href="https://unl.edu.ec/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a href="https://unl.edu.ec/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf">ausentismo de sufragio justificado.</a></p><p>&nbsp;</p><h3><a href="https://unl.edu.ec/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></h3><p>&nbsp;</p><p>&nbsp;</p><p>@import url('https://fonts.googleapis.com/css2?family=Inter&amp;display=swap');</p>	formato_texto_redactores
