;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20SERVIDORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Servidores</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20DOCENTES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Docentes</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20TRABAJADORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es" title="NOMINA TRABAJADORES ELECCIONES 2025"><strong>Trabajadores</strong></a></div></div><div style="display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin:0 auto 30px;max-width:1100px;"><img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/25d79dfe-702e-4c29-bca4-77657026f428.jpeg" data-entity-uuid="0f6643a9-395d-4d1a-bb2a-bac678cf50ea" data-entity-type="file" alt="Convocatoria " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Nu%CC%81mero%20de%20lectores%20habilitados%20.jpeg" data-entity-uuid="fdef90e7-6601-457b-bbd7-50ae88133d58" data-entity-type="file" alt="Número de electores " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-13%20at%208.20.14%20AM.jpeg" data-entity-uuid="db406c56-281a-4ec4-ad18-a903476ecd6d" data-entity-