c4-ad18-a903476ecd6d" data-entity-type="file" alt="NOMINA ELECTORES " width="339" height="425"><p class="text-align-center">&nbsp;</p></td></tr><tr><td style="width:312px;"><img src="/sites/default/files/inline-images/bc65fe31-6867-4b47-a8e6-b5ad32fe4c2a.jpeg" data-align="center" data-entity-uuid="ca784f4d-fef5-4585-9eb8-bf386075d29e" data-entity-type="file" alt="Recintos electores " width="302" height="378"><p class="text-align-center">&nbsp;</p></td><td style="width:353px;"><img src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM%20%281%29.jpeg" data-align="center" data-entity-uuid="d9da27ae-6b54-42b6-99d0-798d59dea348" data-entity-type="file" alt="Comunicado elecciones 1" width="311" height="390"><p class="text-align-center">&nbsp;</p></td><td style="width:399px;"><img src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM.jpg" data-align="center" data-entity-uuid="da728bf1-c7f0-42f8-b18f-7090e4e0d7f6" data-entity-type="file" alt="Comunicado elecciones 2" width="315" height="394"><p class="text-align-center">&nbsp;</p></td></tr><tr><td style="width:312px;"><img src="/sites/default/files/inline-images/Imagen%20de%20WhatsApp%202025-07-10%20a%20las%2018.43.01_469b6939_0.jpg" data-align="center" data-entity-uuid="dac4d600-5bc1-41fb-b079-81930eab9856" data-entity-type="file" alt="Invitación" width="306" height="383"></td><td style="width:353px;"><img src="/sites/default/files/inline-images/elecciones.jpg" data-align="center" data-entity-uuid="11183b91-890d-4094-90bb-5a79b6f408df" data-entity-type="file" alt="comunicado elecciones 3" width="302" height="378"></td><td style="width:399px;">&nbsp;</td></tr></tbody></table><p class="text-align-center">&nbsp;</p><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>Modalidad de sufragio&nbsp;</strong></p><p>•&nbsp;&nbsp; &nbsp;Presencial, con juntas receptoras del voto por estamento.</p><p>•&nbsp;&nbsp; &nbsp;Electrónico remoto, si así lo dispone el Tribunal Electoral General.</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>Cronograma&nbsp;</strong></p><div class="row m-auto text-center"><div class="text-align-center" style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.15);display:inline-block;margin:10px;min-width:275px;padding:12px 20px;vertical-align:middle;"><a style="color:#93000b;text-decoration:none;" href="https://unl.edu.ec/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>Descarga</strong></a></div></div></div><table class="table" style="width:100%;" border="0" cellpadding="5" cellspacing="5"><tbody><tr><td><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>¿Quiénes deben votar?</strong></p><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;">&nbsp;</p><p><meta charset="UTF-8">&nbsp;&nbsp;&nbsp;&nbsp;•&nbsp;&nbsp; &nbsp;Docentes titulares<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Estudiantes regulares (a partir del tercer ciclo o su equivalente)<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Servidores administrativos y trabajadores titulares</p></div></td><td class="text-align-center">&nbsp;</td><td><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>¿Dón