ont-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_09-signed.pdf"><strong>Junta 9</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf"><strong>Junta 10</strong></a></div><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Masculino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a></div><p class="text-align-center" style="margin:0;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;padding:8px 18px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf"><strong>Unidad de Educación a Distancia y en Línea</strong></a></p></div></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>Según el art. 39 de&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf" title="Reglamento elecciones ">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a style="color:#93000b;" href="/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf" title="ausentismo de sufragio ">ausentismo de sufragio justificado.</a></p></div><p>&nbsp;</p><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf" hreflang="es"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></div><div style="margin:20px auto;max-width:800px;"><div style="border-radius:8px;height:0;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/gTP4tCSS3vU?si=0AaIwB-UVhbLFaVA" title="YouTube video player"></iframe></div></div><p>&nbsp;</p>	full_html
texto_libre	0	163	2120	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p style="margin:0;">La Universidad Nacional de Loja (UNL) respeta la privacidad de las personas que visitan este sitio web y trata sus datos personales conforme a la Ley Orgánica de Protección de Datos Personales (LOPDP) del Ecuador. Este documento explica qué información recopilamos, con qué fines y cómo puedes ejercer tus derechos.</p><p style="color:#5d6b84;font-size:0.9em;margin:10px 0 0;">Última actualización: [completar fecha de publicación]</p></div><h2 style="color:#93000b;margin-top:30px;">1. Responsable del tratamiento</h2><p>El responsable del tratamiento de los datos personales recopilados a través de este sitio web es la <strong>Universidad Nacional de Loja</strong>.</p><ul><li data-list-item-id="e26b9adbba14d4001bdd3cc2757b9d5bb"><strong>Dirección:</strong> Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li><li data-list-item-id="e49075f84cfd06143132f912e47b8c952"><strong>Teléfono:</strong> <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e138e08cf909cdfb6d06c66d35b20b831"><strong>Correo electrónico:</strong> <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li></ul><h2 style="color:#93000b;margin-top:30px;">2. ¿Qué datos recopilamos?</h2><p>Al navegar por nuestro sitio, según los servicios que aceptes en el gestor de cookies, podemos recopilar:</p><ul><li data-list-item-id="e85991ea23bb10028c1631e03ae8860f7">Un identificador de sesión anónimo, para que el sitio funcione correctamente mientras navegas (por ejemplo, para recordar tus preferencias de cookies).</li><li data-list-item-id="e75a783ad3ad827da3b55cfd13235a1c0">Datos de navegación con fines estadísticos (páginas visitadas, tiempo de permanencia, ubicación aproximada por IP), si aceptas el servicio de analítica.</li><li data-list-item-id="e465b7689a72a456e39152260990a2a2a">Datos que se generan al reproducir contenido incrustado de terceros, como videos de YouTube, si decides activar ese contenido.</li></ul><p>No recopilamos datos sensibles (salud, creencias religiosas, orientación sexual, afiliación política, etc.) a través de este sitio.</p><h2 style="color:#93000b;margin-top:30px;">3. Finalidades del tratamiento</h2><p>Usamos los datos recopilados únicamente para los siguientes fines, agrupados de la misma forma en que puedes gestionarlos desde el panel de cookies:</p><ul><li data-list-item-id="e78ac199d5c4d7e6f8ee703b11252840c"><strong>Funcional:</strong> imprescindible para que el sitio funcione correctamente (por ejemplo, recordar el consentimiento de cookies que diste). No se puede desactivar.</li><li data-list-item-id="e2125b9a9a8e13498d78a7325ac093759"><strong>Analítica:</strong> nos ayuda a entender cómo se usa el sitio (páginas más visitadas, errores, etc.) para mejorarlo. Es opcional.</li><li data-list-item-id="eb3056b31a79621e5f480c0469ad5ba83"><strong>Contenido externo incrustado:</strong> permite mostrar contenido de plataformas externas (como videos de YouTube) directamente en nuestras páginas. Es opcional.</li></ul><h2 style="color:#93000b;margin-top:30px;">4. Servicios de terceros que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Servicio</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Más información</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">Klaro (gestor de consentimiento)</td><td style="border-bottom:1px solid #e2e6ea;">Funcional — guarda tus preferencias de cookies en el navegador.</td><td style="border-bottom:1px solid #e2e6ea;">—</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">Google Analytics</td><td style="border-bottom:1px solid #e2e6ea;">Analítica — estadísticas de uso del sitio de forma agregada.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">YouTube</td><td style="border-bottom:1px solid #e2e6ea;">Contenido externo incrustado — reproducción de videos institucionales.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr></tbody></table><h2 style="color:#93000b;margin-top:30px;">5. Cookies que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Cookie</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Duración aproximada</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">SESS / SSESS</td><td style="border-bottom:1px solid #e2e6ea;">Identifica tu sesión mientras navegas por el sitio.</td><td style="border-bottom:1px solid #e2e6ea;">Se elimina al cerrar el navegador.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">klaro</td><td style="border-bottom:1px solid #e2e6ea;">Recuerda las preferencias de cookies que elegiste.</td><td style="border-bottom:1px solid #e2e6ea;">180 días.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">_ga, _gid</td><td style="border-bottom:1px solid #e2e6ea;">Distinguen usuarios de forma anónima para estadísticas (Google Analytics).</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 2 años (_ga) / 24 horas (_gid).</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">IDE</td><td style="border-bottom:1px solid #e2e6ea;">Cookie de Google asociada a servicios integrados.</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 1 año.</td></tr></tbody></table><p style="color:#5d6b84;font-size:0.9em;">Las cookies de Analítica y Contenido externo solo se instalan si das tu consentimiento explícito a través del panel de cookies.</p><h2 style="color:#93000b;margin-top:30px;">6. Tus derechos</h2><p>De acuerdo con la LOPDP, como titular de tus datos personales puedes ejercer en cualquier momento los siguientes derechos:</p><ul><li data-list-item-id="e0f547e17d229e068a9e72412ccf2dd23"><strong>Acceso:</strong> conocer qué datos tuyos tratamos.</li><li data-list-item-id="efc0e8d009bcb3b368e29ead5391d06fa"><strong>Rectificación:</strong> corregir datos inexactos o incompletos.</li><li data-list-item-id="e5c8046ee1896939686eb5e26bbe0bc7d"><strong>Eliminación:</strong> solicitar que borremos tus datos cuando ya no sean necesarios.</li><li data-list-item-id="e7c430682fb6b05f9eba8add9113428ba"><strong>Oposición:</strong> oponerte al tratamiento de tus datos para fines específicos, como la analítica.</li><li data-list-item-id="e7212ec8eab56a3e65810dead58222db8"><strong>Revocar tu consentimiento:</strong> en cualquier momento, volviendo a abrir el panel de preferencias de cookies (enlace "Personalizar" en el aviso de cookies) y desactivando los servicios opcionales.</li></ul><p>Para ejercer cualquiera de estos derechos, puedes escribirnos a <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a>.</p><h2 style="color:#93000b;margin-top:30px;">7. Cambios a esta política</h2><p>Podemos actualizar este documento cuando cambien los servicios o cookies que utilizamos. Te recomendamos revisarlo periódicamente. Cuando el cambio sea significativo, el gestor de cookies volverá a solicitarte tu consentimiento.</p><h2 style="color:#93000b;margin-top:30px;">8. Contacto</h2><p>Si tienes preguntas sobre esta política o sobre el tratamiento de tus datos personales, contáctanos:</p><ul><li data-list-item-id="e043df4eb5d15f3dd7f906eec22a40406">Correo: <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li><li data-list-item-id="e794018110558ec86d974be3a220c7d13">Teléfono: <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e726314536bc2df4682915336b2b7aad9">Dirección: Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li></ul>	full_html
texto_libre	0	162	2263	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>&nbsp;</p><p><meta charset="UTF-8"></p><p>La Universidad Nacional de Loja se prepara para elegir a los nuevos representantes de su Órgano Colegiado Superior (OCS). según el&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2020-01/ESTATUTO%20ORGANICO%206-11-2019%2C%20VALIDADO%20POR%20EL%20CES.PDF">Estatuto de la institución</a>.</p><p class="text-align-center"><strong>&nbsp;¿Qué se elige?</strong></p><ul><li data-list-item-id="e856832c2f275ebb6075ccb71e448d338">Representantes al Órgano Colegiado Superior (OCS)</li><li data-list-item-id="e32911e0890787c694bacda1d08ed1b12">8 docentes titulares (con dos alternos cada uno)</li><li data-list-item-id="e764c8aa879e39659c598bdc40a10f9a4">2 estudiantes (con dos alternos)</li><li data-list-item-id="e55fd81512c14f695539b27bd02776ae8">&nbsp;1 servidor/a o trabajador/a (con dos alternos)</li></ul></div><p>&nbsp;</p><img style="border-radius:8px;display:block;margin:0 auto;max-width:100%;" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-12%20at%201.05.08%20PM.jpeg" data-align="center" data-entity-uuid="bd514ad1-4b7f-40cc-848a-42936eee8e74" data-entity-type="file" alt="Banner 3" width="1126" height="393"><p>&nbsp;</p><h2 class="text-align-center" style="color:#93000b;margin:30px 0 20px;">Nómina de candidatos por estamento</h2><div style="display:grid;gap:18px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin:0 auto 30px;max-width:1100px;"><div style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);padding:20px;text-align:center;"><p style="font-size:1.1em;margin:0 0 12px;"><strong style="color:#93000b;">Estudiantes</strong></p><ul style="list-style:none;margin:0;padding:0;text-align:left;"><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e4b4dc31692a04320ac4422eacc5c4c16"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_farnr-signed.pdf">Facultad Agropecuaria y de Recursos Naturales Renovables</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e207228d80a8ceeea0a33cd2ae7b9e9a6"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_feac-signed.pdf">Facultad de la Educación el Arte y la Comunicación</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e62166deee237905b0e6e6639d0b07d53"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_feirnnr-signed.pdf">Facultad de la Energía, las Industrias y los Recursos Naturales no Renovables</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="ef2722fc82f3ddc9658afacdcfd76dd2f"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_fjsa-signed.pdf">Facultad Jurídica, Social y Administrativa</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e56d6fc8f3dd27a6ac19ac1cf9336b746"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_fsh-signed.pdf">Facultad de la Salud Humana</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="ea5d1a7c94ec3a03f01780e399d7c6cfb"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_ued-signed.pdf">Unidad de Educación a Distancia y en Línea</a></li></ul></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20SERVIDORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Servidores</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20DOCENTES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Docentes</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20TRABAJADORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es" title="NOMINA TRABAJADORES ELECCIONES 2025"><strong>Trabajadores</strong></a></div></div><div style="display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin:0 auto 30px;max-width:1100px;"><img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/25d79dfe-702e-4c29-bca4-77657026f428.jpeg" data-entity-uuid="0f6643a9-395d-4d1a-bb2a-bac678cf50ea" data-entity-type="file" alt="Convocatoria " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Nu%CC%81mero%20de%20lectores%20habilitados%20.jpeg" data-entity-uuid="fdef90e7-6601-457b-bbd7-50ae88133d58" data-entity-type="file" alt="Número de electores " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-13%20at%208.20.14%20AM.jpeg" data-entity-uuid="db406c56-281a-4ec4-ad18-a903476ecd6d" data-entity-type="file" alt="NOMINA ELECTORES " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/bc65fe31-6867-4b47-a8e6-b5ad32fe4c2a.jpeg" data-entity-uuid="ca784f4d-fef5-4585-9eb8-bf386075d29e" data-entity-type="file" alt="Recintos electores " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM%20%281%29.jpeg" data-entity-uuid="d9da27ae-6b54-42b6-99d0-798d59dea348" data-entity-type="file" alt="Comunicado elecciones 1" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM.jpg" data-entity-uuid="da728bf1-c7f0-42f8-b18f-7090e4e0d7f6" data-entity-type="file" alt="Comunicado elecciones 2" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Imagen%20de%20WhatsApp%202025-07-10%20a%20las%2018.43.01_469b6939_0.jpg" data-entity-uuid="dac4d600-5bc1-41fb-b079-81930eab9856" data-entity-type="file" alt="Invitación" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/elecciones.jpg" data-entity-uuid="11183b91-890d-4094-90bb-5a79b6f408df" data-entity-type="file" alt="comunicado elecciones 3" width="100%" height="100%"></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>Modalidad de sufragio&nbsp;</strong></p><p>•&nbsp;&nbsp; &nbsp;Presencial, con juntas receptoras del voto por estamento.</p><p>•&nbsp;&nbsp; &nbsp;Electrónico remoto, si así lo dispone el Tribunal Electoral General.</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 12px;"><strong>Cronograma&nbsp;</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>Descarga</strong></a></p></div><div style="display:flex;flex-wrap:wrap;gap:16px;margin:20px auto;max-width:1100px;"><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0 0 10px;"><strong>¿Quiénes deben votar?</strong></p><p>&nbsp;&nbsp;&nbsp;&nbsp;•&nbsp;&nbsp; &nbsp;Docentes titulares<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Estudiantes regulares (a partir del tercer ciclo o su equivalente)<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Servidores administrativos y trabajadores titulares</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 14px;"><strong>¿Dónde votar?</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="https://lugarvotacion.unl.edu.ec/" hreflang="es" rel="noopener noreferer" target="_blank" title="Conoce tu lugar de votación"><strong>Conoce tu lugar de votación</strong></a></p></div></div><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>NOMINA DE CANDIDATOS POR EL MOVIMIENTO ACADÉMICO POLÍTICO TRANSFORMACIÓN UNIVERSITARIA.</strong></a></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:24px;"><h1 class="text-align-center" style="color:#93000b;margin:0 0 24px;">Padrón Electoral</h1><div style="display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-bottom:30px;"><a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20SERVIDORES%20CON%20NOMBRAMIENTO%20DEFINITIVO.pdf"><strong>Servidores</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20DOCENTES.pdf"><strong>Docentes</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20TRABAJADORES%20CON%20CONTRATO%20INDEFINIDO.pdf"><strong>Trabajadores</strong></a></div><div style="background-color:#FFFFFF;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.06);margin:0 auto;max-width:900px;padding:24px;"><h3 class="text-align-center" style="color:#93000b;margin:0 0 20px;">Estudiantes</h3><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Femenino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_09-signed.pdf"><strong>Junta 9</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf"><strong>Junta 10</strong></a></div><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Masculino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a></div><p class="text-align-center" style="margin:0;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;padding:8px 18px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf"><strong>Unidad de Educación a Distancia y en Línea</strong></a></p></div></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>Según el art. 39 de&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf" title="Reglamento elecciones ">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a style="color:#93000b;" href="/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf" title="ausentismo de sufragio ">ausentismo de sufragio justificado.</a></p></div><p>&nbsp;</p><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf" hreflang="es"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></div><div style="margin:20px auto;max-width:800px;"><div style="border-radius:8px;height:0;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/gTP4tCSS3vU?si=0AaIwB-UVhbLFaVA" title="YouTube video player"></iframe></div></div><p>&nbsp;</p>	full_html
texto_libre	0	163	2121	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p style="margin:0;">La Universidad Nacional de Loja (UNL) respeta la privacidad de las personas que visitan este sitio web y trata sus datos personales conforme a la Ley Orgánica de Protección de Datos Personales (LOPDP) del Ecuador. Este documento explica qué información recopilamos, con qué fines y cómo puedes ejercer tus derechos.</p><p style="color:#5d6b84;font-size:0.9em;margin:10px 0 0;">Última actualización: [completar fecha de publicación]</p></div><h2 style="color:#93000b;margin-top:30px;">1. Responsable del tratamiento</h2><p>El responsable del tratamiento de los datos personales recopilados a través de este sitio web es la <strong>Universidad Nacional de Loja</strong>.</p><ul><li data-list-item-id="e26b9adbba14d4001bdd3cc2757b9d5bb"><strong>Dirección:</strong> Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li><li data-list-item-id="e49075f84cfd06143132f912e47b8c952"><strong>Teléfono:</strong> <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e138e08cf909cdfb6d06c66d35b20b831"><strong>Correo electrónico:</strong> <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li></ul><h2 style="color:#93000b;margin-top:30px;">2. ¿Qué datos recopilamos?</h2><p>Al navegar por nuestro sitio, según los servicios que aceptes en el gestor de cookies, podemos recopilar:</p><ul><li data-list-item-id="e85991ea23bb10028c1631e03ae8860f7">Un identificador de sesión anónimo, para que el sitio funcione correctamente mientras navegas (por ejemplo, para recordar tus preferencias de cookies).</li><li data-list-item-id="e75a783ad3ad827da3b55cfd13235a1c0">Datos de navegación con fines estadísticos (páginas visitadas, tiempo de permanencia, ubicación aproximada por IP), si aceptas el servicio de analítica.</li><li data-list-item-id="e465b7689a72a456e39152260990a2a2a">Datos que se generan al reproducir contenido incrustado de terceros, como videos de YouTube, si decides activar ese contenido.</li></ul><p>No recopilamos datos sensibles (salud, creencias religiosas, orientación sexual, afiliación política, etc.) a través de este sitio.</p><h2 style="color:#93000b;margin-top:30px;">3. Finalidades del tratamiento</h2><p>Usamos los datos recopilados únicamente para los siguientes fines, agrupados de la misma forma en que puedes gestionarlos desde el panel de cookies:</p><ul><li data-list-item-id="e78ac199d5c4d7e6f8ee703b11252840c"><strong>Funcional:</strong> imprescindible para que el sitio funcione correctamente (por ejemplo, recordar el consentimiento de cookies que diste). No se puede desactivar.</li><li data-list-item-id="e2125b9a9a8e13498d78a7325ac093759"><strong>Analítica:</strong> nos ayuda a entender cómo se usa el sitio (páginas más visitadas, errores, etc.) para mejorarlo. Es opcional.</li><li data-list-item-id="eb3056b31a79621e5f480c0469ad5ba83"><strong>Contenido externo incrustado:</strong> permite mostrar contenido de plataformas externas (como videos de YouTube) directamente en nuestras páginas. Es opcional.</li></ul><h2 style="color:#93000b;margin-top:30px;">4. Servicios de terceros que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Servicio</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Más información</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">Klaro (gestor de consentimiento)</td><td style="border-bottom:1px solid #e2e6ea;">Funcional — guarda tus preferencias de cookies en el navegador.</td><td style="border-bottom:1px solid #e2e6ea;">—</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">Google Analytics</td><td style="border-bottom:1px solid #e2e6ea;">Analítica — estadísticas de uso del sitio de forma agregada.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">YouTube</td><td style="border-bottom:1px solid #e2e6ea;">Contenido externo incrustado — reproducción de videos institucionales.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr></tbody></table><h2 style="color:#93000b;margin-top:30px;">5. Cookies que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Cookie</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Duración aproximada</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">SESS / SSESS</td><td style="border-bottom:1px solid #e2e6ea;">Identifica tu sesión mientras navegas por el sitio.</td><td style="border-bottom:1px solid #e2e6ea;">Se elimina al cerrar el navegador.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">klaro</td><td style="border-bottom:1px solid #e2e6ea;">Recuerda las preferencias de cookies que elegiste.</td><td style="border-bottom:1px solid #e2e6ea;">180 días.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">_ga, _gid</td><td style="border-bottom:1px solid #e2e6ea;">Distinguen usuarios de forma anónima para estadísticas (Google Analytics).</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 2 años (_ga) / 24 horas (_gid).</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">IDE</td><td style="border-bottom:1px solid #e2e6ea;">Cookie de Google asociada a servicios integrados.</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 1 año.</td></tr></tbody></table><p style="color:#5d6b84;font-size:0.9em;">Las cookies de Analítica y Contenido externo solo se instalan si das tu consentimiento explícito a través del panel de cookies.</p><h2 style="color:#93000b;margin-top:30px;">6. Tus derechos</h2><p>De acuerdo con la LOPDP, como titular de tus datos personales puedes ejercer en cualquier momento los siguientes derechos:</p><ul><li data-list-item-id="e0f547e17d229e068a9e72412ccf2dd23"><strong>Acceso:</strong> conocer qué datos tuyos tratamos.</li><li data-list-item-id="efc0e8d009bcb3b368e29ead5391d06fa"><strong>Rectificación:</strong> corregir datos inexactos o incompletos.</li><li data-list-item-id="e5c8046ee1896939686eb5e26bbe0bc7d"><strong>Eliminación:</strong> solicitar que borremos tus datos cuando ya no sean necesarios.</li><li data-list-item-id="e7c430682fb6b05f9eba8add9113428ba"><strong>Oposición:</strong> oponerte al tratamiento de tus datos para fines específicos, como la analítica.</li><li data-list-item-id="e7212ec8eab56a3e65810dead58222db8"><strong>Revocar tu consentimiento:</strong> en cualquier momento, volviendo a abrir el panel de preferencias de cookies (enlace "Personalizar" en el aviso de cookies) y desactivando los servicios opcionales.</li></ul><p>Para ejercer cualquiera de estos derechos, puedes escribirnos a <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a>.</p><h2 style="color:#93000b;margin-top:30px;">7. Cambios a esta política</h2><p>Podemos actualizar este documento cuando cambien los servicios o cookies que utilizamos. Te recomendamos revisarlo periódicamente. Cuando el cambio sea significativo, el gestor de cookies volverá a solicitarte tu consentimiento.</p><h2 style="color:#93000b;margin-top:30px;">8. Contacto</h2><p>Si tienes preguntas sobre esta política o sobre el tratamiento de tus datos personales, contáctanos:</p><ul><li data-list-item-id="e043df4eb5d15f3dd7f906eec22a40406">Correo: <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li><li data-list-item-id="e794018110558ec86d974be3a220c7d13">Teléfono: <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e726314536bc2df4682915336b2b7aad9">Dirección: Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li></ul>	full_html
texto_libre	0	162	2265	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>&nbsp;</p><p><meta charset="UTF-8"></p><p>La Universidad Nacional de Loja se prepara para elegir a los nuevos representantes de su Órgano Colegiado Superior (OCS). según el&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2020-01/ESTATUTO%20ORGANICO%206-11-2019%2C%20VALIDADO%20POR%20EL%20CES.PDF">Estatuto de la institución</a>.</p><p class="text-align-center"><strong>&nbsp;¿Qué se elige?</strong></p><ul><li data-list-item-id="e856832c2f275ebb6075ccb71e448d338">Representantes al Órgano Colegiado Superior (OCS)</li><li data-list-item-id="e32911e0890787c694bacda1d08ed1b12">8 docentes titulares (con dos alternos cada uno)</li><li data-list-item-id="e764c8aa879e39659c598bdc40a10f9a4">2 estudiantes (con dos alternos)</li><li data-list-item-id="e55fd81512c14f695539b27bd02776ae8">&nbsp;1 servidor/a o trabajador/a (con dos alternos)</li></ul></div><p>&nbsp;</p><img style="border-radius:8px;display:block;margin:0 auto;max-width:100%;" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-12%20at%201.05.08%20PM.jpeg" data-align="center" data-entity-uuid="bd514ad1-4b7f-40cc-848a-42936eee8e74" data-entity-type="file" alt="Banner 3" width="1126" height="393"><p>&nbsp;</p><h2 class="text-align-center" style="color:#93000b;margin:30px 0 20px;">Nómina de candidatos por estamento</h2><div style="display:grid;gap:18px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin:0 auto 30px;max-width:1100px;"><div style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);padding:20px;text-align:center;"><p style="font-size:1.1em;margin:0 0 12px;"><strong style="color:#93000b;">Estudiantes</strong></p><ul style="list-style:none;margin:0;padding:0;text-align:left;"><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e4b4dc31692a04320ac4422eacc5c4c16"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_farnr-signed.pdf">Facultad Agropecuaria y de Recursos Naturales Renovables</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e207228d80a8ceeea0a33cd2ae7b9e9a6"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_feac-signed.pdf">Facultad de la Educación el Arte y la Comunicación</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e62166deee237905b0e6e6639d0b07d53"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_feirnnr-signed.pdf">Facultad de la Energía, las Industrias y los Recursos Naturales no Renovables</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="ef2722fc82f3ddc9658afacdcfd76dd2f"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_fjsa-signed.pdf">Facultad Jurídica, Social y Administrativa</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e56d6fc8f3dd27a6ac19ac1cf9336b746"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_fsh-signed.pdf">Facultad de la Salud Humana</a></li><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="ea5d1a7c94ec3a03f01780e399d7c6cfb"><a style="color:#93000b;text-decoration:none;" href="/sites/default/files/2025-06/_lista_certificada_estudiantes_elecciones_2025_-_ued-signed.pdf">Unidad de Educación a Distancia y en Línea</a></li></ul></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20SERVIDORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Servidores</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20DOCENTES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Docentes</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20TRABAJADORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es" title="NOMINA TRABAJADORES ELECCIONES 2025"><strong>Trabajadores</strong></a></div></div><div style="display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin:0 auto 30px;max-width:1100px;"><img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/25d79dfe-702e-4c29-bca4-77657026f428.jpeg" data-entity-uuid="0f6643a9-395d-4d1a-bb2a-bac678cf50ea" data-entity-type="file" alt="Convocatoria " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Nu%CC%81mero%20de%20lectores%20habilitados%20.jpeg" data-entity-uuid="fdef90e7-6601-457b-bbd7-50ae88133d58" data-entity-type="file" alt="Número de electores " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-13%20at%208.20.14%20AM.jpeg" data-entity-uuid="db406c56-281a-4ec4-ad18-a903476ecd6d" data-entity-type="file" alt="NOMINA ELECTORES " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/bc65fe31-6867-4b47-a8e6-b5ad32fe4c2a.jpeg" data-entity-uuid="ca784f4d-fef5-4585-9eb8-bf386075d29e" data-entity-type="file" alt="Recintos electores " width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM%20%281%29.jpeg" data-entity-uuid="d9da27ae-6b54-42b6-99d0-798d59dea348" data-entity-type="file" alt="Comunicado elecciones 1" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM.jpg" data-entity-uuid="da728bf1-c7f0-42f8-b18f-7090e4e0d7f6" data-entity-type="file" alt="Comunicado elecciones 2" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Imagen%20de%20WhatsApp%202025-07-10%20a%20las%2018.43.01_469b6939_0.jpg" data-entity-uuid="dac4d600-5bc1-41fb-b079-81930eab9856" data-entity-type="file" alt="Invitación" width="100%" height="100%"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/elecciones.jpg" data-entity-uuid="11183b91-890d-4094-90bb-5a79b6f408df" data-entity-type="file" alt="comunicado elecciones 3" width="100%" height="100%"></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>Modalidad de sufragio&nbsp;</strong></p><p>•&nbsp;&nbsp; &nbsp;Presencial, con juntas receptoras del voto por estamento.</p><p>•&nbsp;&nbsp; &nbsp;Electrónico remoto, si así lo dispone el Tribunal Electoral General.</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 12px;"><strong>Cronograma&nbsp;</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>Descarga</strong></a></p></div><div style="display:flex;flex-wrap:wrap;gap:16px;margin:20px auto;max-width:1100px;"><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0 0 10px;"><strong>¿Quiénes deben votar?</strong></p><p>&nbsp;&nbsp;&nbsp;&nbsp;•&nbsp;&nbsp; &nbsp;Docentes titulares<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Estudiantes regulares (a partir del tercer ciclo o su equivalente)<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Servidores administrativos y trabajadores titulares</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 14px;"><strong>¿Dónde votar?</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="https://lugarvotacion.unl.edu.ec/" hreflang="es" rel="noopener noreferer" target="_blank" title="Conoce tu lugar de votación"><strong>Conoce tu lugar de votación</strong></a></p></div></div><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>NOMINA DE CANDIDATOS POR EL MOVIMIENTO ACADÉMICO POLÍTICO TRANSFORMACIÓN UNIVERSITARIA.</strong></a></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:24px;"><h1 class="text-align-center" style="color:#93000b;margin:0 0 24px;">Padrón Electoral</h1><div style="display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-bottom:30px;"><a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20SERVIDORES%20CON%20NOMBRAMIENTO%20DEFINITIVO.pdf"><strong>Servidores</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20DOCENTES.pdf"><strong>Docentes</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20TRABAJADORES%20CON%20CONTRATO%20INDEFINIDO.pdf"><strong>Trabajadores</strong></a></div><div style="background-color:#FFFFFF;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.06);margin:0 auto;max-width:900px;padding:24px;"><h3 class="text-align-center" style="color:#93000b;margin:0 0 20px;">Estudiantes</h3><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Femenino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_09-signed.pdf"><strong>Junta 9</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf"><strong>Junta 10</strong></a></div><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Masculino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a></div><p class="text-align-center" style="margin:0;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;padding:8px 18px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf"><strong>Unidad de Educación a Distancia y en Línea</strong></a></p></div></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>Según el art. 39 de&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf" title="Reglamento elecciones ">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a style="color:#93000b;" href="/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf" title="ausentismo de sufragio ">ausentismo de sufragio justificado.</a></p></div><p>&nbsp;</p><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf" hreflang="es"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></div><div style="margin:20px auto;max-width:800px;"><div style="border-radius:8px;height:0;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/gTP4tCSS3vU?si=0AaIwB-UVhbLFaVA" title="YouTube video player"></iframe></div></div><p>&nbsp;</p>	full_html
texto_libre	0	163	2122	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p style="margin:0;">La Universidad Nacional de Loja (UNL) respeta la privacidad de las personas que visitan este sitio web y trata sus datos personales conforme a la Ley Orgánica de Protección de Datos Personales (LOPDP) del Ecuador. Este documento explica qué información recopilamos, con qué fines y cómo puedes ejercer tus derechos.</p><p style="color:#5d6b84;font-size:0.9em;margin:10px 0 0;">Última actualización: 21 de Septiembre de 2026</p></div><h2 style="color:#93000b;margin-top:30px;">1. Responsable del tratamiento</h2><p>El responsable del tratamiento de los datos personales recopilados a través de este sitio web es la <strong>Universidad Nacional de Loja</strong>.</p><ul><li data-list-item-id="e26b9adbba14d4001bdd3cc2757b9d5bb"><strong>Dirección:</strong> Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li><li data-list-item-id="e49075f84cfd06143132f912e47b8c952"><strong>Teléfono:</strong> <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e138e08cf909cdfb6d06c66d35b20b831"><strong>Correo electrónico:</strong> <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li></ul><h2 style="color:#93000b;margin-top:30px;">2. ¿Qué datos recopilamos?</h2><p>Al navegar por nuestro sitio, según los servicios que aceptes en el gestor de cookies, podemos recopilar:</p><ul><li data-list-item-id="e85991ea23bb10028c1631e03ae8860f7">Un identificador de sesión anónimo, para que el sitio funcione correctamente mientras navegas (por ejemplo, para recordar tus preferencias de cookies).</li><li data-list-item-id="e75a783ad3ad827da3b55cfd13235a1c0">Datos de navegación con fines estadísticos (páginas visitadas, tiempo de permanencia, ubicación aproximada por IP), si aceptas el servicio de analítica.</li><li data-list-item-id="e465b7689a72a456e39152260990a2a2a">Datos que se generan al reproducir contenido incrustado de terceros, como videos de YouTube, si decides activar ese contenido.</li></ul><p>No recopilamos datos sensibles (salud, creencias religiosas, orientación sexual, afiliación política, etc.) a través de este sitio.</p><h2 style="color:#93000b;margin-top:30px;">3. Finalidades del tratamiento</h2><p>Usamos los datos recopilados únicamente para los siguientes fines, agrupados de la misma forma en que puedes gestionarlos desde el panel de cookies:</p><ul><li data-list-item-id="e78ac199d5c4d7e6f8ee703b11252840c"><strong>Funcional:</strong> imprescindible para que el sitio funcione correctamente (por ejemplo, recordar el consentimiento de cookies que diste). No se puede desactivar.</li><li data-list-item-id="e2125b9a9a8e13498d78a7325ac093759"><strong>Analítica:</strong> nos ayuda a entender cómo se usa el sitio (páginas más visitadas, errores, etc.) para mejorarlo. Es opcional.</li><li data-list-item-id="eb3056b31a79621e5f480c0469ad5ba83"><strong>Contenido externo incrustado:</strong> permite mostrar contenido de plataformas externas (como videos de YouTube) directamente en nuestras páginas. Es opcional.</li></ul><h2 style="color:#93000b;margin-top:30px;">4. Servicios de terceros que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Servicio</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Más información</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">Klaro (gestor de consentimiento)</td><td style="border-bottom:1px solid #e2e6ea;">Funcional — guarda tus preferencias de cookies en el navegador.</td><td style="border-bottom:1px solid #e2e6ea;">—</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">Google Analytics</td><td style="border-bottom:1px solid #e2e6ea;">Analítica — estadísticas de uso del sitio de forma agregada.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">YouTube</td><td style="border-bottom:1px solid #e2e6ea;">Contenido externo incrustado — reproducción de videos institucionales.</td><td style="border-bottom:1px solid #e2e6ea;"><a style="color:#93000b;" href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Política de privacidad de Google</a></td></tr></tbody></table><h2 style="color:#93000b;margin-top:30px;">5. Cookies que utilizamos</h2><table class="table" style="border-collapse:collapse;width:100%;" border="0" cellpadding="8" cellspacing="0"><thead><tr style="background-color:#f1f3f5;"><th style="border-bottom:2px solid #93000b;">Cookie</th><th style="border-bottom:2px solid #93000b;">Finalidad</th><th style="border-bottom:2px solid #93000b;">Duración aproximada</th></tr></thead><tbody><tr><td style="border-bottom:1px solid #e2e6ea;">SESS / SSESS</td><td style="border-bottom:1px solid #e2e6ea;">Identifica tu sesión mientras navegas por el sitio.</td><td style="border-bottom:1px solid #e2e6ea;">Se elimina al cerrar el navegador.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">klaro</td><td style="border-bottom:1px solid #e2e6ea;">Recuerda las preferencias de cookies que elegiste.</td><td style="border-bottom:1px solid #e2e6ea;">180 días.</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">_ga, _gid</td><td style="border-bottom:1px solid #e2e6ea;">Distinguen usuarios de forma anónima para estadísticas (Google Analytics).</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 2 años (_ga) / 24 horas (_gid).</td></tr><tr><td style="border-bottom:1px solid #e2e6ea;">IDE</td><td style="border-bottom:1px solid #e2e6ea;">Cookie de Google asociada a servicios integrados.</td><td style="border-bottom:1px solid #e2e6ea;">Hasta 1 año.</td></tr></tbody></table><p style="color:#5d6b84;font-size:0.9em;">Las cookies de Analítica y Contenido externo solo se instalan si das tu consentimiento explícito a través del panel de cookies.</p><h2 style="color:#93000b;margin-top:30px;">6. Tus derechos</h2><p>De acuerdo con la LOPDP, como titular de tus datos personales puedes ejercer en cualquier momento los siguientes derechos:</p><ul><li data-list-item-id="e0f547e17d229e068a9e72412ccf2dd23"><strong>Acceso:</strong> conocer qué datos tuyos tratamos.</li><li data-list-item-id="efc0e8d009bcb3b368e29ead5391d06fa"><strong>Rectificación:</strong> corregir datos inexactos o incompletos.</li><li data-list-item-id="e5c8046ee1896939686eb5e26bbe0bc7d"><strong>Eliminación:</strong> solicitar que borremos tus datos cuando ya no sean necesarios.</li><li data-list-item-id="e7c430682fb6b05f9eba8add9113428ba"><strong>Oposición:</strong> oponerte al tratamiento de tus datos para fines específicos, como la analítica.</li><li data-list-item-id="e7212ec8eab56a3e65810dead58222db8"><strong>Revocar tu consentimiento:</strong> en cualquier momento, volviendo a abrir el panel de preferencias de cookies (enlace "Personalizar" en el aviso de cookies) y desactivando los servicios opcionales.</li></ul><p>Para ejercer cualquiera de estos derechos, puedes escribirnos a <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a>.</p><h2 style="color:#93000b;margin-top:30px;">7. Cambios a esta política</h2><p>Podemos actualizar este documento cuando cambien los servicios o cookies que utilizamos. Te recomendamos revisarlo periódicamente. Cuando el cambio sea significativo, el gestor de cookies volverá a solicitarte tu consentimiento.</p><h2 style="color:#93000b;margin-top:30px;">8. Contacto</h2><p>Si tienes preguntas sobre esta política o sobre el tratamiento de tus datos personales, contáctanos:</p><ul><li data-list-item-id="e043df4eb5d15f3dd7f906eec22a40406">Correo: <a style="color:#93000b;" href="mailto:comunicacion@unl.edu.ec">comunicacion@unl.edu.ec</a></li><li data-list-item-id="e794018110558ec86d974be3a220c7d13">Teléfono: <a style="color:#93000b;" href="tel:072593550">07 259 3550</a></li><li data-list-item-id="e726314536bc2df4682915336b2b7aad9">Dirección: Av. Pío Jaramillo Alvarado y Reinaldo Espinosa, Ciudad Universitaria Guillermo Falconí, Loja, Ecuador.</li></ul>	full_html
texto_libre	0	162	2267	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>&nbsp;</p><p><meta charset="UTF-8"></p><p>La Universidad Nacional de Loja se prepara para elegir a los nuevos representantes de su Órgano Colegiado Superior (OCS). según el&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2020-01/ESTATUTO%20ORGANICO%206-11-2019%2C%20VALIDADO%20POR%20EL%20CES.PDF">Estatuto de la institución</a>.</p><p class="text-align-center"><strong>&nbsp;¿Qué se elige?</strong></p><ul><li data-list-item-id="e856832c2f275ebb6075ccb71e448d338">Representantes al Órgano Colegiado Superior (OCS)</li><li data-list-item-id="e32911e0890787c694bacda1d08ed1b12">8 docentes titulares (con dos alternos cada uno)</li><li data-list-item-id="e764c8aa879e39659c598bdc40a10f9a4">2 estudiantes (con dos alternos)</li><li data-list-item-id="e55fd81512c14f695539b27bd02776ae8">&nbsp;1 servidor/a o trabajador/a (con dos alternos)</li></ul></div><p>&nbsp;</p><img style="border-radius:8px;display:block;margin:0 auto;max-width:100%;" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-12%20at%201.05.08%20PM.jpeg" data-align="center" data-entity-uuid="bd514ad1-4b7f-40cc-848a-42936eee8e74" data-entity-type="file" alt="Banner 3" width="1126" height="393"><p>&nbsp;</p><h2 class="text-align-center" style="color:#93000b;margin:30px 0 20px;">Nómina de candidatos por estamento</h2><div style="display:grid;gap:18px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin:0 auto 30px;max-width:1100px;"><div style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);padding:20px;text-align:center;"><p style="font-size:1.1em;margin:0 0 12px;"><strong style="color:#93000b;">Estudiantes</strong></p><ul style="list-style:none;margin:0;padding:0;text-align:left;"><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e4b4dc3169