ont-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_09-signed.pdf"><strong>Junta 9</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_FEMENINO_JUNTA_10-signed.pdf"><strong>Junta 10</strong></a></div><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Masculino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_01-signed.pdf"><strong>Junta 1</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_02-signed.pdf"><strong>Junta 2</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_03-signed.pdf"><strong>Junta 3</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_04-signed.pdf"><strong>Junta 4</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_05-signed.pdf"><strong>Junta 5</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_06-signed.pdf"><strong>Junta 6</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_07-signed.pdf"><strong>Junta 7</strong></a> <a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size:0.95em;padding:8px 16px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_PRESENCIAL_MASCULINO_JUNTA_08-signed.pdf"><strong>Junta 8</strong></a></div><p class="text-align-center" style="margin:0;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;padding:8px 18px;text-decoration:none;" href="/sites/default/files/2025-06/_PADRON_ELECTORAL_2025_UED-signed.pdf"><strong>Unidad de Educación a Distancia y en Línea</strong></a></p></div></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>Según el art. 39 de&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2021-06/REGLAMENTO%20DE%20ELECCIONES%20%20ORGANO%20COLEGIADO%20SUPERIOR.%20aprobado%20%2828-06-2021%29.docx-signed-signed-signed.pdf" title="Reglamento elecciones ">Reglamento de Elecciones</a>, siguiendo el debido proceso, se aplicarán las sanciones señaladas en la Ley Orgánica de Educación Superior, las previstas en el Estatuto Orgánico de la Universidad; las establecidas en la Ley Orgánica de Servicio Público, y, Código del Trabajo. Los estudiantes que no integren la Junta Receptora del Voto y que no justifiquen su inasistencia al sufragio, serán sancionados con una multa equivalente al cinco por ciento (5 %) de un salario básico vigente del trabajador en general.</p><p>Conoce aquí los requisitos en caso de&nbsp;<a style="color:#93000b;" href="/sites/default/files/2025-07/JUSTIFICACION%20DE%20ESTUDIANTES%20QUE%20NO%20VOTARON.pdf" title="ausentismo de sufragio ">ausentismo de sufragio justificado.</a></p></div><p>&nbsp;</p><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/2025-07/INSTRUCTIVO%20-%20CERTIFICACION-signed-signed-signed.pdf" hreflang="es"><strong>Instructivo para realizar el Voto Electrónico Remoto</strong></a></div><div style="margin:20px auto;max-width:800px;"><div style="border-radius:8px;height:0;overflow:hidden;padding-bottom:56.25%;position:relative;"><iframe style="height:100%;left:0;position:absolute;top:0;width:100%;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen="" frameborder="0" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube.com/embed/gTP4tCSS3vU?si=0AaIwB-UVhbLFaVA" title="YouTube video player"></iframe></div></div><p>&nbsp;</p>	full_html
texto_libre	0	162	2160	es	0	<div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p>&nbsp;</p><p><meta charset="UTF-8"></p><p>La Universidad Nacional de Loja se prepara para elegir a los nuevos representantes de su Órgano Colegiado Superior (OCS). según el&nbsp;<a style="color:#93000b;" href="/sites/default/files/archivo/2020-01/ESTATUTO%20ORGANICO%206-11-2019%2C%20VALIDADO%20POR%20EL%20CES.PDF">Estatuto de la institución</a>.</p><p class="text-align-center"><strong>&nbsp;¿Qué se elige?</strong></p><ul><li data-list-item-id="e856832c2f275ebb6075ccb71e448d338">Representantes al Órgano Colegiado Superior (OCS)</li><li data-list-item-id="e32911e0890787c694bacda1d08ed1b12">8 docentes titulares (con dos alternos cada uno)</li><li data-list-item-id="e764c8aa879e39659c598bdc40a10f9a4">2 estudiantes (con dos alternos)</li><li data-list-item-id="e55fd81512c14f695539b27bd02776ae8">&nbsp;1 servidor/a o trabajador/a (con dos alternos)</li></ul></div><p>&nbsp;</p><img style="border-radius:8px;display:block;margin:0 auto;max-width:100%;" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-12%20at%201.05.08%20PM.jpeg" data-align="center" data-entity-uuid="bd514ad1-4b7f-40cc-848a-42936eee8e74" data-entity-type="file" alt="Banner 3" width="1126" height="392"><p>&nbsp;</p><h2 class="text-align-center" style="color:#93000b;margin:30px 0 20px;">Nómina de candidatos por estamento</h2><div style="display:grid;gap:18px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin:0 auto 30px;max-width:1100px;"><div style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);padding:20px;text-align:center;"><p style="font-size:1.1em;margin:0 0 12px;"><strong style="color:#93000b;">Estudiantes</strong></p><ul style="list-style:none;margin:0;padding:0;text-align:left;"><li style="border-top:1px solid #e2e6ea;padding:8px 0;" data-list-item-id="e4b4dc3169