;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20SERVIDORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Servidores</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20DOCENTES%20ELECCIONES%20OCS-signed.pdf" hreflang="es"><strong>Docentes</strong></a></div><div class="text-align-center" style="align-items:center;background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);display:flex;justify-content:center;padding:20px;"><a style="color:#93000b;font-size:1.1em;text-decoration:none;" href="/sites/default/files/2025-06/NOMINA%20TRABAJADORES%20ELECCIONES%20OCS-signed.pdf" hreflang="es" title="NOMINA TRABAJADORES ELECCIONES 2025"><strong>Trabajadores</strong></a></div></div><div style="display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin:0 auto 30px;max-width:1100px;"><img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/25d79dfe-702e-4c29-bca4-77657026f428.jpeg" data-entity-uuid="0f6643a9-395d-4d1a-bb2a-bac678cf50ea" data-entity-type="file" alt="Convocatoria " width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Nu%CC%81mero%20de%20lectores%20habilitados%20.jpeg" data-entity-uuid="fdef90e7-6601-457b-bbd7-50ae88133d58" data-entity-type="file" alt="Número de electores " width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-06-13%20at%208.20.14%20AM.jpeg" data-entity-uuid="db406c56-281a-4ec4-ad18-a903476ecd6d" data-entity-type="file" alt="NOMINA ELECTORES " width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/bc65fe31-6867-4b47-a8e6-b5ad32fe4c2a.jpeg" data-entity-uuid="ca784f4d-fef5-4585-9eb8-bf386075d29e" data-entity-type="file" alt="Recintos electores " width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM%20%281%29.jpeg" data-entity-uuid="d9da27ae-6b54-42b6-99d0-798d59dea348" data-entity-type="file" alt="Comunicado elecciones 1" width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/WhatsApp%20Image%202025-07-10%20at%2012.08.13%20PM.jpg" data-entity-uuid="da728bf1-c7f0-42f8-b18f-7090e4e0d7f6" data-entity-type="file" alt="Comunicado elecciones 2" width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/Imagen%20de%20WhatsApp%202025-07-10%20a%20las%2018.43.01_469b6939_0.jpg" data-entity-uuid="dac4d600-5bc1-41fb-b079-81930eab9856" data-entity-type="file" alt="Invitación" width="100%" height="NaN"> <img style="border-radius:10px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);" src="/sites/default/files/inline-images/elecciones.jpg" data-entity-uuid="11183b91-890d-4094-90bb-5a79b6f408df" data-entity-type="file" alt="comunicado elecciones 3" width="100%" height="NaN"></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0;"><strong>Modalidad de sufragio&nbsp;</strong></p><p>•&nbsp;&nbsp; &nbsp;Presencial, con juntas receptoras del voto por estamento.</p><p>•&nbsp;&nbsp; &nbsp;Electrónico remoto, si así lo dispone el Tribunal Electoral General.</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 12px;"><strong>Cronograma&nbsp;</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>Descarga</strong></a></p></div><div style="display:flex;flex-wrap:wrap;gap:16px;margin:20px auto;max-width:1100px;"><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;"><p class="text-align-center" style="color:#93000b;font-size:18px;margin:0 0 10px;"><strong>¿Quiénes deben votar?</strong></p><p>&nbsp;&nbsp;&nbsp;&nbsp;•&nbsp;&nbsp; &nbsp;Docentes titulares<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Estudiantes regulares (a partir del tercer ciclo o su equivalente)<br>&nbsp;&nbsp; &nbsp;•&nbsp;&nbsp; &nbsp;Servidores administrativos y trabajadores titulares</p></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;flex:1 1 320px;font-family:Arial, sans-serif;margin-top:10px;padding:20px;text-align:center;"><p style="color:#93000b;font-size:18px;margin:0 0 14px;"><strong>¿Dónde votar?</strong></p><p><a style="background-color:#93000b;border-radius:8px;color:#FFFFFF;display:inline-block;padding:10px 24px;text-decoration:none;" href="https://lugarvotacion.unl.edu.ec/" hreflang="es" rel="noopener noreferer" target="_blank" title="Conoce tu lugar de votación"><strong>Conoce tu lugar de votación</strong></a></p></div></div><div class="text-align-center" style="margin:20px auto;"><a style="background-color:#f1f3f5;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.1);color:#93000b;display:inline-block;max-width:100%;padding:14px 24px;text-decoration:none;" href="/sites/default/files/archivo/2025-05/Cronograma%20para%20elecciones%20%20OCS%202025%20OFICIAL-signed-signed.pdf" hreflang="es"><strong>NOMINA DE CANDIDATOS POR EL MOVIMIENTO ACADÉMICO POLÍTICO TRANSFORMACIÓN UNIVERSITARIA.</strong></a></div><div style="background-color:#fbecec;border-left:5px solid #93000b;border-radius:8px;font-family:Arial, sans-serif;margin-top:10px;padding:24px;"><h1 class="text-align-center" style="color:#93000b;margin:0 0 24px;">Padrón Electoral</h1><div style="display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-bottom:30px;"><a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20SERVIDORES%20CON%20NOMBRAMIENTO%20DEFINITIVO.pdf"><strong>Servidores</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20DOCENTES.pdf"><strong>Docentes</strong></a> <a style="align-items:center;background-color:#93000b;border-radius:30px;color:#FFFFFF;display:inline-flex;gap:8px;padding:10px 22px;text-decoration:none;" href="/sites/default/files/2025-06/PADRON%20ELECTORAL%20TRABAJADORES%20CON%20CONTRATO%20INDEFINIDO.pdf"><strong>Trabajadores</strong></a></div><div style="background-color:#FFFFFF;border-radius:12px;box-shadow:0px 4px 12px rgba(0,0,0,0.06);margin:0 auto;max-width:900px;padding:24px;"><h3 class="text-align-center" style="color:#93000b;margin:0 0 20px;">Estudiantes</h3><p class="text-align-center" style="color:#3a3a3a;margin:0 0 10px;"><strong>Femenino</strong></p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:24px;"><a style="background-color:#fbecec;border-radius:20px;color:#93000b;display:inline-block;font-size